/* -- js/Input/BaseInputHandler.js -- */
class BaseInputHandler {
    constructor(options = {}) {
        // Component that owns this input handler
        this.owner = options.owner;
        
        // Element to attach events to
        this.element = options.element || document;

        // Input state
        this.inputState = {
            // Mouse position in page coordinates
            mousePosX: 0,
            mousePosY: 0,
            
            // Scroll tracking
            lastScrollX: window.scrollX,
            lastScrollY: window.scrollY,
            
            // Mouse state
            isMousePressed: false,
            pressStartTime: 0,

            // Activity tracking
            lastMovementTime: Date.now(),
            isActive: true
        };

        // Keyboard shortcut configuration
        this.shortcuts = options.shortcuts || {};

        // Bind methods
        this.boundMethods = {
            keydown: this.handleKeyDown.bind(this),
            click: this.handleClick.bind(this),
            mousedown: this.handleMouseDown.bind(this),
            mouseup: this.handleMouseUp.bind(this),
            mousemove: this.handleMouseMove.bind(this),
            touchstart: this.handleTouchStart.bind(this),
            touchmove: this.handleTouchMove.bind(this),
            touchend: this.handleTouchEnd.bind(this),
            contextmenu: this.handleContextMenu.bind(this),
            scroll: this.handleScroll.bind(this),
            drag: this.handleDrag.bind(this)
        };
    }

    init() {
        this.addEventListeners();
    }

    addEventListeners() {
        // Mouse events
        document.addEventListener('click', this.boundMethods.click);
        document.addEventListener('mousedown', this.boundMethods.mousedown);
        document.addEventListener('mouseup', this.boundMethods.mouseup);
        document.addEventListener('mousemove', this.boundMethods.mousemove);
        document.addEventListener('contextmenu', this.boundMethods.contextmenu);
        document.addEventListener('drag', this.boundMethods.drag);

        // Touch events
        document.addEventListener('touchstart', this.boundMethods.touchstart, { passive: true });
        document.addEventListener('touchmove', this.boundMethods.touchmove, { passive: true });
        document.addEventListener('touchend', this.boundMethods.touchend);

        // Keyboard events
        document.addEventListener('keydown', this.boundMethods.keydown);

        // Scroll events
        window.addEventListener('scroll', this.boundMethods.scroll);
    }

    handleKeyDown(event) {
        if (event.target.tagName === 'INPUT' || 
            event.target.tagName === 'TEXTAREA' || 
            event.target.isContentEditable) {
            return;
        }

        const key = event.key.toLowerCase();
        if (this.shortcuts[key]) {
            event.preventDefault();
            this.shortcuts[key](event);
        }
    }

    handleClick(event) {
        this.setLastActive();
    }

    handleMouseDown(event) {
        this.inputState.isMousePressed = true;
        this.inputState.pressStartTime = Date.now();
        this.updateMousePosition(event);
        this.setLastActive();
    }

    handleMouseUp(event) {
        if (this.getPressDuration() > 0) {
            this.inputState.isMousePressed = false;
            this.inputState.pressStartTime = 0;
        }
        this.updateMousePosition(event);
        this.setLastActive();
    }

    handleMouseMove(event) {
        this.updateMousePosition(event);
        this.setLastActive();
    }

    handleDrag(event) {
        this.updateMousePosition(event);
        this.setLastActive();
    }

    handleTouchStart(event) {
        const touch = event.touches[0];
        this.updateMousePosition(touch);
        this.setLastActive();
    }

    handleTouchMove(event) {
        const touch = event.touches[0];
        this.updateMousePosition(touch);
        this.setLastActive();
    }

    handleTouchEnd(event) {
        this.setLastActive();
    }

    handleContextMenu(event) {
        // event.preventDefault();
        //return false;
    }

    handleScroll(event) {
        // Update mouse position based on scroll
        this.inputState.mousePosX += window.scrollX - this.inputState.lastScrollX;
        this.inputState.mousePosY += window.scrollY - this.inputState.lastScrollY;
        
        // Update last scroll position
        this.inputState.lastScrollX = window.scrollX;
        this.inputState.lastScrollY = window.scrollY;
        
        this.setLastActive();
    }

    updateMousePosition(event) {
        const clientX = event.touches ? event.touches[0].clientX : event.clientX;
        const clientY = event.touches ? event.touches[0].clientY : event.clientY;

        this.inputState.mousePosX = clientX + document.body.scrollLeft;
        this.inputState.mousePosY = clientY + document.body.scrollTop;
    }

    getPressDuration() {
        if (this.inputState.isMousePressed) {
            return Date.now() - this.inputState.pressStartTime;
        }
        return 0;
    }

    setLastActive() {
        this.inputState.lastMovementTime = Date.now();
        this.inputState.isActive = true;
    }

    checkInactive(inactiveTimeout) {
        const currentTime = Date.now();
        if (currentTime - this.inputState.lastMovementTime >= inactiveTimeout) {
            if (this.inputState.isActive) {
                this.inputState.isActive = false;
                return true;
            }
        } else if (!this.inputState.isActive) {
            this.inputState.isActive = true;
            return true;
        }
        return false;
    }

    dispose() {
        Object.entries(this.boundMethods).forEach(([event, handler]) => {
            if (event === 'scroll') {
                window.removeEventListener(event, handler);
            } else {
                document.removeEventListener(event, handler);
            }
        });
    }

    // Public getters for input state
    getMousePosition() {
        return {
            x: this.inputState.mousePosX,
            y: this.inputState.mousePosY
        };
    }

    isPressed() {
        return this.inputState.isMousePressed;
    }

    isUserActive() {
        return this.inputState.isActive;
    }
};
/* -- js/Input/BaseDragHandler.js -- */
class DragHandler {
    constructor(options = {}) {
        // Element to attach drag handlers to
        this.element = options.element;
        
        // Parent component/manager that owns this handler
        this.parent = options.parent;
        
        // Drag validation callback
        this.canDrag = options.canDrag || (() => true);

        // Pointer-down validation callback (for region-based hit testing)
        this.canStart = options.canStart || (() => true);
        
        // Drag update callback
        this.onDragUpdate = options.onDragUpdate || (() => {});
        
        // Drag start callback
        this.onDragStart = options.onDragStart || (() => {});
        
        // Drag end callback
        this.onDragEnd = options.onDragEnd || (() => {});

        this.inputSystem = InputSystem.getInstance();

        // State tracking
        this.isDragging = false;
        this.initialTouchPos = { x: 0, y: 0 };
        this.lastTouchPos = { x: 0, y: 0 };
        this.dragVelocity = { x: 0, y: 0 };
        this.dragStartTime = 0;
        
        // Configuration
        this.config = {
            dragThreshold: options.dragThreshold || 10, // Minimum pixels moved to start drag
            inertiaDeceleration: options.inertiaDeceleration || 0.95, // Deceleration factor for inertia
            maxInertiaSpeed: options.maxInertiaSpeed || 20, // Maximum inertia speed
            touchTimeout: options.touchTimeout || 300, // ms to distinguish tap from drag
            preventScrollThreshold: options.preventScrollThreshold || 10 // Pixels moved before preventing scroll
        };

        // Touch tracking
        this.touchId = null;
        this.preventScroll = false;
        this.moveThreshold = false;
        
        // Performance optimization
        this.rafId = null;
        this.boundHandleStart = this.handleStart.bind(this);
        this.boundHandleMove = this.handleMove.bind(this);
        this.boundHandleEnd = this.handleEnd.bind(this);
        this.boundHandleVisibility = this.handleVisibility.bind(this);

        this.initializeEventListeners();
    }

    initializeEventListeners() {
        if (!this.element) return;

        // Mouse events
        this.element.addEventListener('mousedown', this.boundHandleStart, { passive: false });

        // Touch events
        this.element.addEventListener('touchstart', this.boundHandleStart, { passive: false });
        
        // Add touch-action CSS for better mobile scrolling
        this.element.style.touchAction = 'none';
    }

    handleStart = (event) => {
        // Check if dragging is allowed
        if (!this.canDrag()) return;

        const pos = this.getEventPosition(event);
        if (!pos) return;

        if (!this.canStart(event, pos)) return;

        // Map-object drags listen globally and may overlap a Myte's much larger
        // sprite hitbox. Claim this press before either handler can move so only
        // the entity the user actually pressed is picked up.
        if (!this.inputSystem.claimDrag(this)) return;

        event.preventDefault();

        // Store initial touch/click position
        this.initialTouchPos = { ...pos };
        this.lastTouchPos = { ...pos };
        this.dragStartTime = Date.now();
        this.moveThreshold = false;
        this.preventScroll = false;

        // Store touch identifier for multi-touch support
        if (event.type === 'touchstart') {
            this.touchId = event.touches[0].identifier;
        }

        // Add drag listeners
        window.addEventListener('mousemove', this.boundHandleMove);
        window.addEventListener('touchmove', this.boundHandleMove, { passive: false });
        window.addEventListener('mouseup', this.boundHandleEnd);
        window.addEventListener('touchend', this.boundHandleEnd);
        window.addEventListener('touchcancel', this.boundHandleEnd);
        document.addEventListener('visibilitychange', this.boundHandleVisibility);

        // Initialize drag state
        this.initializeDrag(event, pos);
    }

    initializeDrag(event, position) {
        this.isDragging = true;
        this.onDragStart({ event, position });
    }

    getEventPosition(event) {
        if (event.touches) {
            const touch = event.type === 'touchend'
                ? event.changedTouches[0]
                : event.touches[0];
            return { x: touch.clientX, y: touch.clientY };
        }
        return { x: event.clientX, y: event.clientY };
    }

    updateDragPosition = () => {
        this.rafId = null;
        
        // Calculate new position
        const position = {
            x: this.lastTouchPos.x + window.scrollX,
            y: this.lastTouchPos.y + window.scrollY,
            velocity: this.dragVelocity
        };

        // Call the update callback
        this.onDragUpdate(position);
    }

    handleMove = (event) => {
        if (!this.isDragging) return;

        const pos = this.getEventPosition(event);
        if (!pos || (event.type === 'touchmove' && !this.isCorrectTouch(event))) return;

        // Check if we should prevent scrolling
        if (!this.moveThreshold) {
            const deltaX = Math.abs(pos.x - this.initialTouchPos.x);
            const deltaY = Math.abs(pos.y - this.initialTouchPos.y);
            
            if (deltaX > this.config.preventScrollThreshold || 
                deltaY > this.config.preventScrollThreshold) {
                this.moveThreshold = true;
                this.preventScroll = deltaX > deltaY;
            }
        }

        // Only prevent default for touch events
        if (this.preventScroll && event.type === 'touchmove') {
            event.preventDefault();
        }

        // Calculate velocity
        const now = Date.now();
        const dt = now - this.dragStartTime;
        this.dragVelocity = {
            x: (pos.x - this.lastTouchPos.x) / dt,
            y: (pos.y - this.lastTouchPos.y) / dt
        };

        // Update positions
        this.lastTouchPos = pos;
        this.dragStartTime = now;

        // Use RequestAnimationFrame for smooth updates
        if (!this.rafId) {
            this.rafId = requestAnimationFrame(this.updateDragPosition);
        }
    }

    handleEnd = (event) => {
        if (!this.isDragging) return;
        if (event.type === 'touchend' && !this.isCorrectTouch(event)) return;

        this.finalizeDrag();
        this.cleanup();
    }

    handleVisibility = () => {
        if (document.hidden && this.isDragging) {
            this.finalizeDrag();
            this.cleanup();
        }
    }

    isCorrectTouch(event) {
        const touches = event.type === 'touchend' ? event.changedTouches : event.touches;
        for (let i = 0; i < touches.length; i++) {
            if (touches[i].identifier === this.touchId) return true;
        }
        return false;
    }

    finalizeDrag() {
        this.isDragging = false;
        this.onDragEnd();
    }

    cleanup() {
        // Remove event listeners
        window.removeEventListener('mousemove', this.boundHandleMove);
        window.removeEventListener('touchmove', this.boundHandleMove);
        window.removeEventListener('mouseup', this.boundHandleEnd);
        window.removeEventListener('touchend', this.boundHandleEnd);
        window.removeEventListener('touchcancel', this.boundHandleEnd);
        document.removeEventListener('visibilitychange', this.boundHandleVisibility);

        // Cancel any pending animation frame
        if (this.rafId) {
            cancelAnimationFrame(this.rafId);
            this.rafId = null;
        }

        // Reset state
        this.isDragging = false;
        this.touchId = null;
        this.preventScroll = false;
        this.moveThreshold = false;
        this.inputSystem.releaseDrag(this);
    }

    dispose() {
        this.cleanup();
        if (this.element) {
            this.element.removeEventListener('mousedown', this.boundHandleStart);
            this.element.removeEventListener('touchstart', this.boundHandleStart);
            this.element.style.touchAction = '';
        }
    }
}
