/* -- js/Engine/ResourceManager.js -- */
class ResourceManager {
    static MAX_LOAD_ATTEMPTS = 2;
    static RETRY_DELAY_MS = 150;
    static PLACEHOLDER_SPRITE_DATA_URI = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';

    constructor() {
        this.sprites = new Map();
        this.pendingLoads = new Map();
    }

    loadSprite(id, url) {
        if (this.sprites.has(id)) return Promise.resolve(this.sprites.get(id));
        if (this.pendingLoads.has(id)) return this.pendingLoads.get(id);

        const loadPromise = this._loadSpriteWithRetry(id, url)
            .then(img => {
                this.sprites.set(id, img);
                return img;
            })
            .finally(() => this.pendingLoads.delete(id));

        this.pendingLoads.set(id, loadPromise);
        return loadPromise;
    }

    getSprite(id) {
        return this.sprites.get(id);
    }

    isResourceLoaded(id) {
        return this.sprites.has(id);
    }

    async _loadSpriteWithRetry(id, url) {
        for (let attempt = 1; attempt <= ResourceManager.MAX_LOAD_ATTEMPTS; attempt++) {
            const requestUrl = attempt === 1 ? url : this._appendCacheBust(url, attempt);
            try {
                return await this._loadImage(requestUrl);
            } catch (error) {
                if (attempt === ResourceManager.MAX_LOAD_ATTEMPTS) {
                    console.warn(`Failed to load sprite: ${id} from ${url}. Using placeholder.`, error);
                    return this._createPlaceholderSprite(id, url);
                }
                console.warn(`Retrying sprite load: ${id} from ${url} (attempt ${attempt + 1})`, error);
                await this._delay(ResourceManager.RETRY_DELAY_MS);
            }
        }
        return this._createPlaceholderSprite(id, url);
    }

    _loadImage(url) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error(`Unable to load ${url}`));
            img.src = url;
        });
    }

    _createPlaceholderSprite(id, sourceUrl) {
        return new Promise((resolve) => {
            const img = new Image();
            img.dataset.resourceId = id;
            img.dataset.resourceFallback = 'true';
            img.dataset.resourceSource = sourceUrl;
            img.onload = () => resolve(img);
            img.src = ResourceManager.PLACEHOLDER_SPRITE_DATA_URI;
        });
    }

    _appendCacheBust(url, attempt) {
        const separator = url.includes('?') ? '&' : '?';
        return `${url}${separator}retry=${attempt}&ts=${Date.now()}`;
    }

    _delay(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }
}
;
/* -- js/Engine/Audio/AudioCategoryRules.js -- */
const AudioCategoryRules = {
	resolve(id, preset = null) {
		const resolvedPreset = preset || {};
		if (resolvedPreset.category) {
			return resolvedPreset.category;
		}

		switch (resolvedPreset.type) {
			case "music":
				return "music";
			case "ambient":
				return "ambient";
			case "ui":
				return "ui";
			default:
				break;
		}

		if (String(id || '').startsWith('myte_')) return 'entities';
		if (String(id || '').startsWith('footstep_')) return 'footsteps';
		if (['obj_fountain', 'obj_lantern'].some(prefix => String(id || '').startsWith(prefix))) return 'machines';
		if (String(id || '').startsWith('obj_')) return 'world';
		return 'sfx';
	},

	// The mute switch that owns each category. Everything answers to
	// `soundEnabled` first — that is what makes it the master — and then to the
	// one switch beside its own slider.
	MUTE_FLAGS: Object.freeze({
		master: 'soundEnabled',
		music: 'musicEnabled',
		ambient: 'ambientEnabled',
		sfx: 'sfxEnabled',
		footsteps: 'footstepsEnabled',
		ui: 'uiEnabled'
	}),

	isEnabled(soundManager, category) {
		if (!soundManager.soundEnabled) return false;
		switch (category) {
			case 'music':
				return soundManager.musicEnabled;
			case 'ambient':
				return soundManager.ambientEnabled;
			case 'ui':
				return soundManager.uiEnabled;
			// Footsteps are mixed through the SFX bus, so silencing effects
			// silences them too — the switch beside the Footsteps slider only
			// narrows that further.
			case 'footsteps':
				return soundManager.sfxEnabled && soundManager.footstepsEnabled;
			default:
				return soundManager.sfxEnabled;
		}
	},

	getVolume(soundManager, category) {
		switch (category) {
			case 'music':
				return soundManager.volume.music;
			case 'ambient':
				return soundManager.volume.ambient;
			case 'ui':
				return soundManager.volume.ui;
			case 'footsteps':
				return soundManager.volume.sfx * soundManager.volume.footsteps;
			case 'entities':
			case 'machines':
			case 'notifications':
			case 'world':
			case 'sfx':
			default:
				return soundManager.volume.sfx;
		}
	}
};
;
/* -- js/Engine/Audio/AudioScheduleProfiles.js -- */
const AudioScheduleProfiles = {
	// Each profile defines ambient layers and music for a location type.
	// ambientBase  — always playing in this location
	// ambientDay   — added during daytime hours (7–17)
	// ambientNight — added during night hours (19–4)
	// music*       — music IDs keyed by time window, see getMusicForHour.
	//                One track per part of the day: morning / noon / evening /
	//                night, each named for the window it belongs to.
	_profiles: {
		outside: {
			ambientBase:  ['env_wind'],
			ambientDay:   ['env_birds'],
			ambientNight: ['env_cricket'],
			musicMorning: 'music_morning',
			musicDay:     'music_noon',
			musicEvening: 'music_evening',
			musicNight:   'music_night',
			musicDefault: 'music_evening'
		},
		inside: {
			ambientBase:  ['env_indoor_cozy'],
			ambientDay:   [],
			ambientNight: [],
			musicMorning: 'music_morning',
			musicDay:     'music_noon',
			musicEvening: 'music_evening',
			musicNight:   'music_night',
			musicDefault: 'music_evening'
		}
	},

	_getProfile(location) {
		return this._profiles[location] || this._profiles.outside;
	},

	/**
	 * Four windows, one per part of the day.
	 *
	 * A day is five real minutes, so an in-game hour is ~12.5 real seconds and
	 * these are shorter than they look. The two long stretches get the two long
	 * loops and the two transitions get the two short ones, so every track is
	 * heard several times over rather than cut off part-way:
	 *
	 *   05-08  morning   3h ≈ 38s   music_morning
	 *   08-17  noon      9h ≈ 112s  music_noon
	 *   17-20  evening   3h ≈ 38s   music_evening
	 *   20-05  night     9h ≈ 112s  music_night
	 *
	 * Each track's melody and pad loop at coprime lengths and drift apart, so
	 * what you actually hear takes minutes to come round — the loop length in
	 * bars is not the length of the experience. See SoundManager._resolveLoopEnd.
	 *
	 * The evening piece was `music_main`, the fallback for whatever the other
	 * windows left over, which is why it never seemed to play. It has its own
	 * window now, and the unknown-hour fallback stays pointed at it.
	 */
	getMusicForHour(hour, location = 'outside') {
		const p = this._getProfile(location);
		if (!Number.isFinite(hour)) return p.musicDefault;
		if (hour >= 5  && hour < 8)  return p.musicMorning;
		if (hour >= 8  && hour < 17) return p.musicDay;
		if (hour >= 17 && hour < 20) return p.musicEvening;
		return p.musicNight;
	},

	getAmbientForHour(hour, location = 'outside') {
		const p = this._getProfile(location);
		const tracks = [...p.ambientBase];
		if (Number.isFinite(hour)) {
			if (hour >= 7 && hour <= 17) tracks.push(...p.ambientDay);
			if (hour >= 19 || hour <= 4) tracks.push(...p.ambientNight);
		}
		return tracks;
	}
};
;
