class GameTime {
	constructor() {
		if (GameTime.instance) {
			return GameTime.instance;
		}
		GameTime.instance = this;

		// Core time tracking
		this.totalElapsedSeconds = 0;
		this.isPaused = false;
		this.timeScale = 1;

		// Configuration
		this.config = {
			dayDurationInMinutes: SiteConfig.time.dayDurationInMinutes,
			daysPerSeason: SiteConfig.time.daysPerSeason,
			displayMinuteStep: SiteConfig.time.displayMinuteStep,
			// The shape of the year and the week is world tuning, not clock
			// mechanics — SiteConfig owns it and the calendar reads the same
			// lists, so there is one answer to "how long is a season?".
			seasons: [...SiteConfig.time.seasons],
			daysOfTheWeek: [...SiteConfig.time.daysOfTheWeek],

			// Natural day/night cycle times (in hours)
			naturalCycle: {
				dawn: { hour: 5, minute: 0 },
				sunrise: { hour: 6, minute: 0 },
				noon: { hour: 12, minute: 0 },
				sunset: { hour: 18, minute: 0 },
				dusk: { hour: 19, minute: 0 },
				midnight: { hour: 0, minute: 0 }
			},

			// Time periods array - easier to maintain
			timePeriods: [
				{ name: 'deep_night', start: { hour: 22, minute: 0 }, end: { hour: 23, minute: 30 } },
				{ name: 'midnight', start: { hour: 23, minute: 30 }, end: { hour: 0, minute: 30 } },
				{ name: 'dead_of_night', start: { hour: 0, minute: 30 }, end: { hour: 2, minute: 0 } },
				{ name: 'witching_hour', start: { hour: 2, minute: 0 }, end: { hour: 3, minute: 0 } },
				{ name: 'night_watch', start: { hour: 3, minute: 0 }, end: { hour: 4, minute: 0 } },
				{ name: 'late_night', start: { hour: 4, minute: 0 }, end: { hour: 4, minute: 30 } },
				{ name: 'predawn', start: { hour: 4, minute: 30 }, end: { hour: 5, minute: 30 } },
				{ name: 'dawn', start: { hour: 5, minute: 30 }, end: { hour: 6, minute: 30 } },
				{ name: 'sunrise', start: { hour: 6, minute: 30 }, end: { hour: 7, minute: 30 } },
				{ name: 'aurora_hour', start: { hour: 7, minute: 30 }, end: { hour: 9, minute: 0 } },
				{ name: 'morning', start: { hour: 9, minute: 0 }, end: { hour: 12, minute: 0 } },
				{ name: 'midday', start: { hour: 12, minute: 0 }, end: { hour: 15, minute: 0 } },
				{ name: 'afternoon', start: { hour: 15, minute: 0 }, end: { hour: 17, minute: 0 } },
				{ name: 'evening', start: { hour: 17, minute: 0 }, end: { hour: 18, minute: 0 } },
				{ name: 'magic_hour', start: { hour: 18, minute: 0 }, end: { hour: 19, minute: 0 } },
				{ name: 'sunset', start: { hour: 19, minute: 0 }, end: { hour: 19, minute: 30 } },
				{ name: 'dusk', start: { hour: 19, minute: 30 }, end: { hour: 20, minute: 30 } },
				{ name: 'gloaming', start: { hour: 20, minute: 30 }, end: { hour: 21, minute: 30 } },
				{ name: 'nightfall', start: { hour: 21, minute: 30 }, end: { hour: 22, minute: 0 } }
			],

			// Moon configuration
			moonPhases: {
				daysPerPhase: 3.5,
				phases: ['new', 'waxingCrescent', 'firstQuarter', 'waxingGibbous',
					'full', 'waningGibbous', 'lastQuarter', 'waningCrescent'],
				phaseEffects: {
					new: { lightBonus: 0, growthMultiplier: 0.8 },
					waxingCrescent: { lightBonus: 0.2, growthMultiplier: 0.9 },
					firstQuarter: { lightBonus: 0.3, growthMultiplier: 1.0 },
					waxingGibbous: { lightBonus: 0.4, growthMultiplier: 1.1 },
					full: { lightBonus: 0.5, growthMultiplier: 1.2 },
					waningGibbous: { lightBonus: 0.4, growthMultiplier: 1.1 },
					lastQuarter: { lightBonus: 0.3, growthMultiplier: 1.0 },
					waningCrescent: { lightBonus: 0.2, growthMultiplier: 0.9 }
				}
			}
		};

		// Event handling
		this.subscribers = {
			minute: new Set(),
			hour: new Set(),
			day: new Set(),
			season: new Set(),
			year: new Set(),
			dayNight: new Set(),
			light: new Set(),
			moonPhase: new Set(),
			timeSkip: new Set()
		};

		const initialDate = SiteConfig.time.initialDate || {
			year: 1,
			season: 'spring',
			day: 1,
			hour: 8,
			minute: 0
		};

		this.setDateTime(
			initialDate.year,
			initialDate.season,
			initialDate.day,
			initialDate.hour,
			initialDate.minute
		);

		this.lastMinute = this.getCurrentMinute();
		this.lastHour = this.getCurrentHour();
		this.lastDay = this.getCurrentDay();
		this.lastSeason = this.getCurrentSeason();
		this.lastYear = this.getCurrentYear();
		this.lastTimeOfDay = this.getTimeOfDay();
		this.lastLightLevel = this.getLightLevel();
		this.lastMoonPhase = this.getMoonPhase();
		this._notifyAccum = 0;
	}

	// Helper methods for common calculations
	_timeToMinutes(hour, minute) {
		return hour * 60 + minute;
	}

	_getTotalGameDays() {
		return Math.floor(this.getCurrentGameMinutes() / (24 * 60));
	}

	_getGameMinuteToRealSecondsRatio() {
		return (this.config.dayDurationInMinutes * 60) / (24 * 60);
	}

	// Time getters
	getCurrentGameMinutes() {
		const gameMinuteToRealSeconds = this._getGameMinuteToRealSecondsRatio();
		const realToGameScalingFactor = 1 / gameMinuteToRealSeconds;
		return Math.floor(this.totalElapsedSeconds * realToGameScalingFactor);
	}

	getCurrentMinute() {
		return this.getCurrentGameMinutes() % 60;
	}

	getCurrentHour() {
		return Math.floor(this.getCurrentGameMinutes() / 60) % 24;
	}

	getCurrentDay() {
		return Math.floor(this.getCurrentGameMinutes() / (60 * 24)) % this.config.daysPerSeason;
	}

	getCurrentDayOfWeek() {
		return this.getDayOfWeekForTotalDays(this._getTotalGameDays());
	}

	// ── Date arithmetic for dates other than today ───────────────────────────
	//
	// The calendar needs to know what any date is, not just the one the clock is
	// standing on. Every "when is that?" question in the game goes through these
	// so the panel can never drift from the clock.

	getDaysPerYear() {
		return this.config.daysPerSeason * this.config.seasons.length;
	}

	// Days elapsed since the dawn of year 1 for a (year, season, day) date, with
	// `day` 1-based the way the UI counts it. This is the same number
	// `_getTotalGameDays()` returns for today, which is what makes the two
	// comparable.
	getTotalDaysFor(year, season, day) {
		const seasonIndex = typeof season === 'number'
			? season
			: this.config.seasons.indexOf(String(season).toLowerCase());
		if (seasonIndex < 0) return NaN;

		return (Number(year) - 1) * this.getDaysPerYear() +
			seasonIndex * this.config.daysPerSeason +
			(Number(day) - 1);
	}

	getDayOfWeekForTotalDays(totalDays) {
		const week = this.config.daysOfTheWeek;
		return week[((totalDays % week.length) + week.length) % week.length];
	}

	getDayOfWeekFor(year, season, day) {
		return this.getDayOfWeekForTotalDays(this.getTotalDaysFor(year, season, day));
	}

	// Today as a plain date object — the anchor the calendar pages away from.
	getCurrentDate() {
		return {
			year: this.getCurrentYear(),
			season: this.getCurrentSeason(),
			day: this.getCurrentDay() + 1
		};
	}

	// Step a (year, season) pair forward or back by whole seasons, which is the
	// only way the calendar moves. Years roll over on their own.
	offsetSeason(year, season, offset = 0) {
		const seasons = this.config.seasons;
		const index = seasons.indexOf(String(season).toLowerCase());
		if (index < 0) return { year, season };

		const absolute = (Number(year) - 1) * seasons.length + index + Math.trunc(offset);
		return {
			year: Math.floor(absolute / seasons.length) + 1,
			season: seasons[((absolute % seasons.length) + seasons.length) % seasons.length]
		};
	}

	// How many whole seasons separate two (year, season) pairs — positive when
	// the second is later. The calendar uses it to clamp its own paging.
	getSeasonDistance(fromYear, fromSeason, toYear, toSeason) {
		const seasons = this.config.seasons;
		const from = (Number(fromYear) - 1) * seasons.length + seasons.indexOf(String(fromSeason).toLowerCase());
		const to = (Number(toYear) - 1) * seasons.length + seasons.indexOf(String(toSeason).toLowerCase());
		return to - from;
	}

	getCurrentSeason() {
		const totalDays = this._getTotalGameDays();
		const seasonIndex = Math.floor(totalDays / this.config.daysPerSeason) % this.config.seasons.length;
		return this.config.seasons[seasonIndex];
	}

	getCurrentYear() {
		const totalDays = this._getTotalGameDays();
		return Math.floor(totalDays / (this.config.daysPerSeason * this.config.seasons.length)) + 1;
	}

	// Moon-related methods
	getMoonPhase() {
		const totalDays = this._getTotalGameDays();
		const cycleLength = this.config.moonPhases.daysPerPhase * this.config.moonPhases.phases.length;
		const phaseIndex = Math.floor((totalDays % cycleLength) / this.config.moonPhases.daysPerPhase);
		return this.config.moonPhases.phases[phaseIndex];
	}

	getMoonIllumination() {
		const phase = this.getMoonPhase();
		const effects = this.config.moonPhases.phaseEffects[phase];
		return effects ? effects.lightBonus : 0;
	}

	getMoonGrowthMultiplier() {
		const phase = this.getMoonPhase();
		const effects = this.config.moonPhases.phaseEffects[phase];
		return effects ? effects.growthMultiplier : 1;
	}

	// Time of day and light calculations
	getTimeOfDay() {
		const currentMinutes = this._timeToMinutes(this.getCurrentHour(), this.getCurrentMinute());

		const isBetween = (time, start, end) => {
			const startMins = this._timeToMinutes(start.hour, start.minute);
			const endMins = this._timeToMinutes(end.hour, end.minute);

			if (startMins <= endMins) {
				return time >= startMins && time < endMins;
			} else {
				// Handle overnight period (e.g., 22:00 - 03:00)
				return time >= startMins || time < endMins;
			}
		};

		const period = this.config.timePeriods.find(period =>
			isBetween(currentMinutes, period.start, period.end)
		);

		return period ? period.name : 'night';
	}

	getLightLevel() {
		const hour = this.getCurrentHour();
		const minute = this.getCurrentMinute();

		// Calculate base daylight
		let baseLight = this.calculateDaylightLevel(hour, minute);

		// Add moonlight at night
		if (baseLight === 0) {
			const moonPhase = this.getMoonPhase();
			const moonEffect = this.config.moonPhases.phaseEffects[moonPhase];
			baseLight = moonEffect ? moonEffect.lightBonus : 0;
		}

		return Math.min(1, Math.max(0, baseLight));
	}

	calculateDaylightLevel(hour, minute) {
		const currentMinutes = this._timeToMinutes(hour, minute);
		const cycle = this.config.naturalCycle;

		const times = Object.entries(cycle).reduce((acc, [key, value]) => {
			acc[key] = this._timeToMinutes(value.hour, value.minute);
			return acc;
		}, {});

		if (currentMinutes < times.dawn) return 0;
		if (currentMinutes < times.sunrise) {
			return (currentMinutes - times.dawn) / (times.sunrise - times.dawn) * 0.3;
		}
		if (currentMinutes < times.noon) {
			return 0.3 + (currentMinutes - times.sunrise) / (times.noon - times.sunrise) * 0.7;
		}
		if (currentMinutes < times.sunset) {
			return 1 - (currentMinutes - times.noon) / (times.sunset - times.noon) * 0.7;
		}
		if (currentMinutes < times.dusk) {
			return 0.3 - (currentMinutes - times.sunset) / (times.dusk - times.sunset) * 0.3;
		}
		return 0;
	}

	// Formatting methods
	getFormattedTime() {
		const hour = this.getCurrentHour();
		const minuteStep = Utility.clamp(Math.round(Number(this.config.displayMinuteStep) || 1), 1, 60);
		const minute = Math.floor(this.getCurrentMinute() / minuteStep) * minuteStep;

		const display12hour = true;
		let displayHour = display12hour ? (hour % 12 || 12) : hour;
		let period = display12hour ? (hour >= 12 ? 'PM' : 'AM') : '';
		let hourString = `${displayHour}:${minute.toString().padStart(2, '0')} ${period}`.trim();

		return hourString;
	}

	getFormattedDate() {
		const dayOfWeek = this.getCurrentDayOfWeek();
		const day = this.getCurrentDay() + 1;
		const season = this.getCurrentSeason();
		const year = this.getCurrentYear();

		return `${dayOfWeek}, day ${day} of ${season}, year ${year}`;
	}

	getTimeData() {
		return {
			minute: this.getCurrentMinute(),
			hour: this.getCurrentHour(),
			day: this.getCurrentDay() + 1,
			dayOfWeek: this.getCurrentDayOfWeek(),
			season: this.getCurrentSeason(),
			year: this.getCurrentYear(),
			timeOfDay: this.getTimeOfDay(),
			lightLevel: this.getLightLevel(),
			moonPhase: this.getMoonPhase(),
			moonIllumination: this.getMoonIllumination(),
			moonGrowthMultiplier: this.getMoonGrowthMultiplier(),
			formattedTime: this.getFormattedTime(),
			formattedDate: this.getFormattedDate(),
			seasonProgress: this.getCurrentDay() / this.config.daysPerSeason,
			dayProgress: (this.getCurrentHour() * 60 + this.getCurrentMinute()) / (24 * 60),
			totalDays: this._getTotalGameDays(),
			totalElapsedSeconds: this.totalElapsedSeconds,
			timeScale: this.timeScale,
			isPaused: this.isPaused
		};
	}

	// Event handling methods
	subscribe(event, callback) {
		if (this.subscribers[event]) {
			this.subscribers[event].add(callback);
			if (event !== 'timeSkip') {
				callback(this.getTimeData());
			}
		}
	}

	unsubscribe(event, callback) {
		if (this.subscribers[event]) {
			this.subscribers[event].delete(callback);
		}
	}

	checkAndNotifyChanges() {
		const currentMinute = this.getCurrentMinute();
		const currentHour = this.getCurrentHour();
		const currentDay = this.getCurrentDay();
		const currentSeason = this.getCurrentSeason();
		const currentYear = this.getCurrentYear();
		const currentTimeOfDay = this.getTimeOfDay();
		const currentLightLevel = this.getLightLevel();
		const currentMoonPhase = this.getMoonPhase();

		if (currentMinute !== this.lastMinute) {
			this.notifySubscribers('minute');
			this.lastMinute = currentMinute;
		}

		if (currentHour !== this.lastHour) {
			this.notifySubscribers('hour');
			this.lastHour = currentHour;
		}

		if (currentDay !== this.lastDay) {
			this.notifySubscribers('day');
			this.lastDay = currentDay;
		}

		if (currentSeason !== this.lastSeason) {
			this.notifySubscribers('season');
			this.lastSeason = currentSeason;
		}

		if (currentYear !== this.lastYear) {
			this.notifySubscribers('year');
			this.lastYear = currentYear;
		}

		if (currentTimeOfDay !== this.lastTimeOfDay) {
			this.notifySubscribers('dayNight');
			this.lastTimeOfDay = currentTimeOfDay;
		}

		if (Math.abs(currentLightLevel - this.lastLightLevel) >= 0.05) {
			this.notifySubscribers('light');
			this.lastLightLevel = currentLightLevel;
		}

		if (currentMoonPhase !== this.lastMoonPhase) {
			this.notifySubscribers('moonPhase');
			this.lastMoonPhase = currentMoonPhase;
		}
	}

	notifySubscribers(event) {
		const timeData = this.getTimeData();
		this.subscribers[event]?.forEach(callback => callback(timeData));
	}

	_notifyTimeSkip(realMs) {
		if (realMs <= 0) return;
		this.subscribers.timeSkip?.forEach(cb => cb(realMs));
	}

	// Time control methods
	update(deltaTime) {
		if (this.isPaused) return;

		this.totalElapsedSeconds += (deltaTime / 1000) * this.timeScale;

		this._notifyAccum += deltaTime;
		if (this._notifyAccum >= 250) {
			this._notifyAccum = 0;
			this.checkAndNotifyChanges();
		}
	}

	tickUpdate(deltaTime) {
		this.update(deltaTime);
	}

	pause() {
		this.isPaused = true;
	}

	resume() {
		this.isPaused = false;
	}

	setTimeScale(scale = 1) {
		this.timeScale = Math.min(32, Math.max(0, Number(scale) || 0));
		return this.timeScale;
	}

	// Set specific time
	setTime(hour, minute = 0) {
		if (hour < 0 || hour > 23) throw new Error('Invalid hour');
		if (minute < 0 || minute > 59) throw new Error('Invalid minute');

		const currentYear = this.getCurrentYear();
		const currentSeason = this.getCurrentSeason();
		const currentDay = this.getCurrentDay() + 1;

		const before = this.totalElapsedSeconds;
		this.setDateTime(currentYear, currentSeason, currentDay, hour, minute);
		this._notifyTimeSkip((this.totalElapsedSeconds - before) * 1000);
	}

	// Set specific date and time
	setDateTime(year, season, day, hour = 0, minute = 0) {
		// Validate inputs
		if (year < 1) throw new Error('Year must be 1 or greater');
		const targetSeason = this.config.seasons.indexOf(season.toLowerCase());
		if (targetSeason === -1) throw new Error('Invalid season');
		if (day < 1 || day > this.config.daysPerSeason) throw new Error('Invalid day');
		if (hour < 0 || hour > 23) throw new Error('Invalid hour');
		if (minute < 0 || minute > 59) throw new Error('Invalid minute');

		// Calculate total game minutes first (same way we read them)
		const yearMinutes = (year - 1) * this.config.seasons.length * this.config.daysPerSeason * 60 * 24;
		const seasonMinutes = targetSeason * this.config.daysPerSeason * 60 * 24;
		const dayMinutes = (day - 1) * 60 * 24;
		const hourMinutes = hour * 60;
		const totalGameMinutes = yearMinutes + seasonMinutes + dayMinutes + hourMinutes + minute;

		// Convert game minutes back to real seconds: 1 game-min = dayDurationInMinutes/24 real seconds
		this.totalElapsedSeconds = totalGameMinutes * this._getGameMinuteToRealSecondsRatio();

		this.checkAndNotifyChanges();
	}


	// Skip forward by a specific amount
	skipTime(hours = 0, minutes = 0) {
		const totalMinutes = hours * 60 + minutes;
		const secondsPerGameMinute = this._getGameMinuteToRealSecondsRatio();
		const realMs = totalMinutes * secondsPerGameMinute * 1000;
		this.totalElapsedSeconds += totalMinutes * secondsPerGameMinute;
		this.checkAndNotifyChanges();
		this._notifyTimeSkip(realMs);
	}

	skipDays(days) {
		if (days < 0) throw new Error('Cannot skip negative days');

		const currentYear = this.getCurrentYear();
		const currentSeason = this.getCurrentSeason();
		const currentDay = this.getCurrentDay() + 1;
		const currentHour = this.getCurrentHour();
		const currentMinute = this.getCurrentMinute();

		let newDay = currentDay + days;
		let newSeason = currentSeason;
		let newYear = currentYear;

		while (newDay > this.config.daysPerSeason) {
			newDay -= this.config.daysPerSeason;
			const seasonIndex = (this.config.seasons.indexOf(newSeason) + 1) % this.config.seasons.length;
			newSeason = this.config.seasons[seasonIndex];
			if (seasonIndex === 0) {
				newYear++;
			}
		}

		const before = this.totalElapsedSeconds;
		this.setDateTime(newYear, newSeason, newDay, currentHour, currentMinute);
		this._notifyTimeSkip((this.totalElapsedSeconds - before) * 1000);
	}

	skipToNextDay() {
		const currentYear = this.getCurrentYear();
		const currentSeason = this.getCurrentSeason();
		const currentDay = this.getCurrentDay() + 1;

		let nextDay = currentDay + 1;
		let nextSeason = currentSeason;
		let nextYear = currentYear;

		if (nextDay > this.config.daysPerSeason) {
			nextDay = 1;
			const seasonIndex = (this.config.seasons.indexOf(nextSeason) + 1) % this.config.seasons.length;
			nextSeason = this.config.seasons[seasonIndex];
			if (seasonIndex === 0) {
				nextYear++;
			}
		}

		const before = this.totalElapsedSeconds;
		this.setDateTime(nextYear, nextSeason, nextDay, 0, 0);
		this._notifyTimeSkip((this.totalElapsedSeconds - before) * 1000);
	}

	// Change how long a day takes in real-time minutes
	setDayDuration(realMinutes) {
		// Store current game time
		const currentGameMinutes = this.getCurrentGameMinutes();

		// Update configuration
		this.config.dayDurationInMinutes = realMinutes;

		// Recalculate totalElapsedSeconds to maintain game time
		const newSecondsPerGameMinute = this._getGameMinuteToRealSecondsRatio();
		this.totalElapsedSeconds = currentGameMinutes * newSecondsPerGameMinute;

		this.checkAndNotifyChanges();
	}

	dispose() {
		Object.values(this.subscribers).forEach(subscribers => subscribers.clear());
		GameTime.instance = null;
	}
}
;
/* -- js/Engine/GameModeManager.js -- */
/**
 * GameModeManager — the Play / Build split.
 *
 * Build mode freezes the simulation and hands the map to the player. Nothing
 * here toggles visibility directly: the mode is written to
 * `document.body.dataset.gameMode` and the container wrapper, and CSS drives
 * every show/hide from there. JS only owns the things CSS cannot — the pause,
 * the camera, the wall presentation, and the save on the way out.
 */
const GAME_MODES = Object.freeze({ PLAY: 'play', BUILD: 'build' });

class GameModeManager {
    constructor(container) {
        this.container = container;
        this.mode = GAME_MODES.PLAY;
        this._restore = null;
        this._seenTutorial = false;
        // Debug's "Build Anywhere". Off by default even with the debug overlay
        // on, so the policies themselves stay testable.
        this.buildAnywhere = false;
    }

    get config() {
        return SiteConfig.buildMode;
    }

    get ui() {
        return this.container?.ui || null;
    }

    isBuild() {
        return this.mode === GAME_MODES.BUILD;
    }

    isPlay() {
        return this.mode === GAME_MODES.PLAY;
    }

    /**
     * Whether the current map lets the player build at all.
     *
     * A map's own `buildPolicy` property wins. Failing that the player's home
     * map is 'full' and everything else is 'none' — the home default lives in
     * code rather than only in House.tmx because browsers cache .tmx files
     * outside debug mode, so a client holding an older copy of the map would
     * otherwise find its own house permanently unbuildable.
     */
    getPolicy(gameMap = this.container?.gameMap) {
        // The single point every rule reads — BuildRules.policy comes through
        // here — so overriding it opens both the way into the mode and every
        // per-cell check, rather than letting you enter a mode that then
        // refuses everything.
        if (this.buildAnywhere) return 'full';
        const declared = gameMap?.properties?.buildPolicy;
        if (this.config.policies.includes(declared)) return declared;
        return this.isHomeMap(gameMap) ? 'full' : this.config.defaultPolicy;
    }

    /**
     * Lets the build tools onto maps that would refuse them. A dev switch: the
     * edits it permits are saved like any other, so it is off unless asked for.
     */
    setBuildAnywhere(flag) {
        const next = flag === true;
        if (this.buildAnywhere === next) return next;
        this.buildAnywhere = next;
        // Turning it off under your own feet leaves you building on a map that
        // no longer allows it.
        if (!next && this.isBuild() && !this.canBuildHere()) this.setMode(GAME_MODES.PLAY);
        this.container?.eventManager?.emit(EVENTS.BUILD_POLICY_CHANGED, {
            buildAnywhere: next,
            policy: this.getPolicy()
        });
        return next;
    }

    // The player's house, and only that. A myte's `homeMapId` is where it
    // sleeps, which for a visiting myte can be any map in the world — using it
    // here would quietly open the whole world to building.
    isHomeMap(gameMap = this.container?.gameMap) {
        return !!gameMap?.id && gameMap.id === SiteConfig.world.defaultMap;
    }

    canBuildHere(gameMap = this.container?.gameMap) {
        return this.getPolicy(gameMap) !== 'none';
    }

    toggle() {
        return this.setMode(this.isBuild() ? GAME_MODES.PLAY : GAME_MODES.BUILD);
    }

    setMode(mode) {
        if (mode !== GAME_MODES.BUILD && mode !== GAME_MODES.PLAY) return false;
        if (mode === this.mode) return false;

        if (mode === GAME_MODES.BUILD && !this.canBuildHere()) {
            this.ui?.showMessage?.("You can't build here.", 'warning', 'Build Mode');
            return false;
        }

        const previous = this.mode;
        this.mode = mode;
        this.applyModeState();

        if (mode === GAME_MODES.BUILD) this.enterBuild();
        else this.leaveBuild();

        this.container?.eventManager?.emit(EVENTS.GAME_MODE_CHANGED, { mode, previous });
        return true;
    }

    applyModeState() {
        document.body.dataset.gameMode = this.mode;
        this.container?.containerWrapper?.setAttribute('data-game-mode', this.mode);
    }

    /**
     * Re-run the entry side effects after a map change. The mode itself is not
     * map state, but everything it overrides — camera, walls, lighting — belongs
     * to the map that was just torn down.
     */
    handleMapChanged() {
        this.container?.buildHistory?.clear();
        if (!this.isBuild()) return;
        if (!this.canBuildHere()) {
            this.setMode(GAME_MODES.PLAY);
            return;
        }
        this._restore = null;
        this.applyEnvironment();
    }

    // The tool swap itself is ToolManager's, driven by GAME_MODE_CHANGED, so
    // there is one place that decides which tools a mode owns.
    enterBuild() {
        this.ui?.setSelected?.(null);
        this.container?.buildHistory?.clear();

        this._restore = {
            followMode: this.container?.camera?.followMode ?? null,
            zoom: this.container?.camera?.zoomLevel ?? null
        };

        this.setSimulationPaused(true);
        this.applyEnvironment();
        this.playSound(this.config.sounds.modeEnter);
        this.setModeMusic(this.config.sounds.music);
        this.showTutorial();
    }

    leaveBuild() {
        const gameMap = this.container?.gameMap;

        this.ui?.wallBuildPanel?.cancelDrag?.();
        this.ui?.fenceBuildPanel?.cancelDrag?.();
        this.container?.inventory?.cancelPlacement?.();
        this.ui?.wallBuildPanel?.close?.();
        this.ui?.fenceBuildPanel?.close?.();
        this.ui?.surfaceCustomizePanel?.close?.();
        this.container?.buildHistory?.clear();

        this.clearEnvironment();
        this.setSimulationPaused(false);
        this.setModeMusic(null);

        if (this._restore) {
            // Eased, like the way in. Entry glides to the build framing and
            // exit used to cut straight back, so the two halves of the same
            // trip did not match.
            if (Number.isFinite(this._restore.zoom)) this.container?.camera?.zoomTo?.(this._restore.zoom, { immediate: false });
            if (Number.isFinite(this._restore.followMode)) this.container?.camera?.setMode?.(this._restore.followMode);
            this._restore = null;
        }

        this.reflowStrandedMytes();
        if (gameMap) {
            this.container?.worldState?.captureMap?.(gameMap);
            this.container?.core?.user?._scheduleSave?.();
        }
        this.playSound(this.config.sounds.modeExit);
    }

    // ── Entry environment (camera, walls, lighting) ───────────────────────────

    applyEnvironment() {
        const camera = this.container?.camera;
        camera?.setMode?.(this.config.cameraFollowMode);
        if (Number.isFinite(this.config.entryZoom)) camera?.zoomTo?.(this.config.entryZoom, { immediate: false });

        this.container?.gameMap?.wallBuilder?.setBuildPresentation?.(
            this.container.buildPresentation || this.config.defaultPresentation
        );
        this.setNeutralLighting(this.config.neutralLighting === true);
    }

    clearEnvironment() {
        this.container?.gameMap?.wallBuilder?.clearBuildPresentation?.();
        this.setNeutralLighting(false);
    }

    setNeutralLighting(flag) {
        const environment = this.container?.gameMap?.environmentManager;
        if (!environment || environment.lightingOverride === flag) return;
        environment.lightingOverride = flag;
        environment.refreshDisplaySettings?.();
    }

    // ── Simulation pause ──────────────────────────────────────────────────────

    setSimulationPaused(flag) {
        this.container?.core?.setSimulationPaused?.(flag);
        if (flag) this.container?.core?.gameTime?.pause?.();
        else this.container?.core?.gameTime?.resume?.();
    }

    // ── Aftermath ─────────────────────────────────────────────────────────────

    /**
     * Walls raised during a build session can strand a myte on a cell that is
     * no longer walkable. Nudge each one to the nearest cell it can stand on,
     * and warn about rooms that ended up with no way in.
     */
    reflowStrandedMytes() {
        const gridSystem = this.container?.gameMap?.gridSystem;
        if (!gridSystem?.findNearestValidPositionForEntity) return;

        let moved = 0;
        for (const myte of this.container.mytes || []) {
            if (!myte.isActive) continue;
            const cell = gridSystem.worldToGrid(myte.posX, myte.posY);
            if (gridSystem.grid?.[cell.x]?.[cell.y]?.walkable !== false) continue;
            const safe = gridSystem.findNearestValidPositionForEntity(myte, myte.posX, myte.posY, 16);
            if (!safe) continue;
            myte.setPosition?.(safe.x, safe.y, this.container.settings?.limitMap);
            myte.setTarget?.(safe.x, safe.y);
            moved += 1;
        }

        if (moved > 0) {
            this.ui?.showMessage?.(
                moved === 1 ? 'A Myte was moved clear of a new wall.' : `${moved} Mytes were moved clear of new walls.`,
                'info',
                'Build Mode'
            );
        }
    }

    showTutorial() {
        if (this._seenTutorial || this.ui?.settingsPanel?.settings?.gameplay?.tutorials === false) return;
        this._seenTutorial = true;
        this.ui?.showMessage?.(
            'Time is paused while you build. 1 moves furniture, 2 builds walls, 3 paints rooms, 4 paints surfaces. Ctrl+Z undoes.',
            'info',
            'Build Mode'
        );
    }

    playSound(soundId) {
        if (soundId) this.container?.core?.soundManager?.playWhenReady?.(soundId);
    }

    setModeMusic(musicId) {
        this.container?.core?.soundManager?.setModeMusic?.(musicId ?? null);
    }

    dispose() {
        this.container = null;
    }
}
