/* -- js/Engine/BuildHistory.js -- */
/**
 * BuildHistory — undo/redo for a build session.
 *
 * A command stack, not snapshots: wall edits, surface paints and object moves
 * all have cheap inverses, and every inverse goes back through the same commit
 * plumbing the original edit used, so persistence, room recomputation and the
 * WALL_GEOMETRY_CHANGED listeners never see a silent mutation.
 *
 * The stack is session-scoped. It is cleared on entering and leaving build mode
 * and on map change — undoing across a map boundary would target geometry the
 * world state has already recaptured.
 */
class BuildHistory {
    constructor(container) {
        this.container = container;
        this.undoStack = [];
        this.redoStack = [];
        this.limit = SiteConfig.buildMode.historyLimit;
        this._applying = false;
    }

    get canUndo() {
        return this.undoStack.length > 0;
    }

    get canRedo() {
        return this.redoStack.length > 0;
    }

    peekUndoLabel() {
        return this.undoStack[this.undoStack.length - 1]?.label ?? null;
    }

    peekRedoLabel() {
        return this.redoStack[this.redoStack.length - 1]?.label ?? null;
    }

    /**
     * Record a completed edit. `command` is `{ label, undo(), redo() }` — the
     * edit itself has already happened, so redo() is what replays it.
     */
    push(command) {
        // A command pushed while undo/redo is running is that operation's own
        // echo, not a new edit.
        if (this._applying || !command?.undo || !command?.redo) return false;
        if (!this.container?.gameMode?.isBuild()) return false;

        this.undoStack.push(command);
        if (this.undoStack.length > this.limit) this.undoStack.shift();
        this.redoStack.length = 0;
        this.emitChanged();
        return true;
    }

    undo() {
        return this._run(this.undoStack, this.redoStack, 'undo', 'Undid');
    }

    redo() {
        return this._run(this.redoStack, this.undoStack, 'redo', 'Redid');
    }

    _run(from, to, method, verb) {
        const command = from.pop();
        if (!command) return false;

        this._applying = true;
        try {
            command[method]();
        } catch (error) {
            console.error('[BuildHistory] command failed:', error);
            this._applying = false;
            this.clear();
            return false;
        }
        this._applying = false;

        to.push(command);
        this.commit();
        this.emitChanged();
        this.container?.core?.soundManager?.playWhenReady?.(SiteConfig.buildMode.sounds.history);
        if (command.label) {
            this.container?.ui?.showMessage?.(`${verb}: ${command.label}`, 'info', 'Build Mode');
        }
        return true;
    }

    // Every path that changes the map persists the same way.
    commit() {
        const gameMap = this.container?.gameMap;
        if (!gameMap) return;
        this.container?.worldState?.captureMap?.(gameMap);
        this.container?.core?.user?._scheduleSave?.();
    }

    clear() {
        if (this.undoStack.length === 0 && this.redoStack.length === 0) return;
        this.undoStack.length = 0;
        this.redoStack.length = 0;
        this.emitChanged();
    }

    emitChanged() {
        this.container?.eventManager?.emit(EVENTS.BUILD_HISTORY_CHANGED, {
            canUndo: this.canUndo,
            canRedo: this.canRedo,
            undoLabel: this.peekUndoLabel(),
            redoLabel: this.peekRedoLabel()
        });
    }

    dispose() {
        this.undoStack.length = 0;
        this.redoStack.length = 0;
        this.container = null;
    }
}
;
/* -- js/Engine/SpriteAnimator.js -- */
class SpriteAnimator {
    // frames: array of [col, row] | [col, row, durationMs] | plain column index (single-row sheet)
    // options: { fps, frameDuration, loop, speedScale }
    //   fps / frameDuration: base rate. frameDuration (ms) takes priority over fps if both provided.
    //   Per-frame durationMs embedded in frame data always wins over the base rate.
    //   speedScale: >1 = faster, <1 = slower. Applied to every frame interval.
    constructor(frames = [], options = {}) {
        this._frames = frames;
        this._loop = options.loop ?? true;
        this._speedScale = Math.max(0.01, options.speedScale ?? 1);
        this._baseInterval = options.frameDuration != null
            ? options.frameDuration
            : 1000 / (options.fps ?? SiteConfig.myte.defaultAnimationFPS);
        this._frameIndex = 0;
        this._elapsed = 0;
        this._complete = false;
    }

    get frameIndex() { return this._frameIndex; }
    get frameCount() { return this._frames.length; }
    get isComplete() { return this._complete; }
    get currentFrame() { return this._frames[this._frameIndex] ?? null; }

    // Switch to a new sequence and reset. options: { fps, frameDuration, loop }
    setFrames(frames, options = {}) {
        this._frames = frames;
        if (options.fps != null) this._baseInterval = 1000 / options.fps;
        if (options.frameDuration != null) this._baseInterval = options.frameDuration;
        if (options.loop != null) this._loop = options.loop;
        this.reset();
        // Non-looping animations with no frames can't display anything — complete immediately
        // so sticky states and isTransitioning locks don't wait forever.
        // Single-frame (length === 1) non-looping animations are intentional (e.g. turn
        // transitions); let update() time them out normally so they display for a full interval.
        if (!this._loop && this._frames.length === 0) {
            this._complete = true;
        }
    }

    setSpeedScale(scale) {
        this._speedScale = Math.max(0.01, scale);
    }

    reset() {
        this._frameIndex = 0;
        this._elapsed = 0;
        this._complete = false;
    }

    _getFrameInterval() {
        const frame = this._frames[this._frameIndex];
        const perFrame = Array.isArray(frame) && frame[2] != null ? frame[2] : null;
        return (perFrame ?? this._baseInterval) / this._speedScale;
    }

    // Advance by deltaTime ms.
    // Returns true when the frame index changes, or on the tick a non-looping animation completes.
    // After returning true, check isComplete to distinguish completion from a normal frame advance.
    update(deltaTime) {
        if (this._complete || this._frames.length === 0) return false;

        // Single-frame non-looping: hold the frame for one interval then complete.
        if (this._frames.length === 1 && !this._loop) {
            this._elapsed += deltaTime;
            if (this._elapsed >= this._getFrameInterval()) {
                this._complete = true;
                return true;
            }
            return false;
        }

        this._elapsed += deltaTime;
        const interval = this._getFrameInterval();
        if (this._elapsed < interval) return false;

        this._elapsed -= interval;
        if (this._elapsed >= interval) this._elapsed = 0; // clamp runaway catch-up

        const next = this._frameIndex + 1;
        if (next >= this._frames.length) {
            if (this._loop) {
                this._frameIndex = 0;
            } else {
                this._complete = true; // hold on last frame
            }
        } else {
            this._frameIndex = next;
        }
        return true;
    }

    // CSS background-position string for the current frame.
    getBackgroundPosition(frameW, frameH = frameW, scale = 1) {
        const frame = this._frames[this._frameIndex];
        if (frame == null) return '0px 0px';
        const col = Array.isArray(frame) ? frame[0] : frame;
        const row = Array.isArray(frame) ? (frame[1] ?? 0) : 0;
        return `${-col * frameW * scale}px ${-row * frameH * scale}px`;
    }
}
;
/* -- js/Effects/Particles/ParticleMath.js -- */
// Thin aliases over the shared Utility helpers — kept so particle code reads
// in its own vocabulary, but with a single implementation underneath.
class ParticleMath {
    static FRAME_MS = 1000 / 60;

    static clamp(value, min, max) {
        return Utility.clamp(value, min, max);
    }

    static lerp(start, end, amount) {
        return Utility.lerp(start, end, amount);
    }

    static inverseLerp(start, end, value) {
        return Utility.inverseLerp(start, end, value);
    }

    static wrap(value, min, max) {
        return Utility.wrap(value, min, max);
    }
}
