/* -- js/Input/DragComponent.js -- */
class DragComponent extends InputComponent {

	getDefaultOptions() {
		return {
			...super.getDefaultOptions(),
			dragThreshold: 5,                // Minimum pixels moved to start drag
			dragTimeThreshold: 100,          // Minimum time in ms before a drag starts
			preventDefaultsForDrag: true,    // Whether to prevent default touch behavior during drag
			autoActivate: false,             // Whether to start dragging automatically on mousedown/touch
			inertia: false,                  // Whether to enable inertia after drag
			inertiaDeceleration: 0.95,       // Deceleration factor for inertia
			maxInertiaSpeed: 20,             // Maximum inertia speed
			limitToElement: null,            // Element to limit dragging within
			limitToViewport: false,          // Whether to limit dragging within viewport
			touchAction: 'none',             // CSS touch-action property during drag
			dragOriginX: 0.5,                // Origin point for drag (0.5 = center)
			dragOriginY: 0.5,                // Origin point for drag (0.5 = center)
			velocityWindow: 100,             // ms of position history used to compute throw velocity on release

			// Callbacks
			canDrag: null,                   // Function to check if dragging is allowed
			onDragStart: null,               // Called when drag starts
			onDragMove: null,                // Called during drag
			onDragEnd: null                  // Called when drag ends
		};
	}

	initialize() {
		super.initialize();

		// Dragging state
		this.isDragging = false;
		this.dragStartPosition = { x: 0, y: 0 };
		this.currentPosition = { x: 0, y: 0 };
		this.dragStartTime = 0;
		this.lastPosition = { x: 0, y: 0 };
		this.velocity = { x: 0, y: 0 };
		this.positionHistory = [];
		this.touchId = null;
		this.mouseDownReceived = false; // Track if mousedown was received
		this.grabOffset = { x: 0, y: 0 };

		// For inertia animation
		this.inertiaAnimationId = null;

		// Debug: Add window-level handler for mouseup to ensure we catch all mouseup events
		window.addEventListener('mouseup', this.windowMouseUpHandler);
		window.addEventListener('touchend', this.windowTouchEndHandler);
	}

	/**
	 * Global handler for mouseup to ensure we catch all mouseup events
	 */
	windowMouseUpHandler = (event) => {
		if (this.isDragging) {
			this.handleEnd({
				position: {
					x: event.pageX || 0,
					y: event.pageY || 0,
					clientX: event.clientX || 0,
					clientY: event.clientY || 0
				},
				originalEvent: event
			});
		}
	};

	/**
	 * Global handler for touchend to ensure we catch all touch end events
	 */
	windowTouchEndHandler = (event) => {
		if (this.isDragging && event.changedTouches) {
			for (let i = 0; i < event.changedTouches.length; i++) {
				const touch = event.changedTouches[i];
				if (touch.identifier === this.touchId) {
					this.handleEnd({
						position: {
							x: touch.pageX || 0,
							y: touch.pageY || 0,
							clientX: touch.clientX || 0,
							clientY: touch.clientY || 0
						},
						touchId: touch.identifier,
						originalEvent: event
					});
					break;
				}
			}
		}
	};

	/**
	 * Set up event subscriptions
	 */
	setupSubscriptions() {
		// Mouse events
		this.subscribe('mouse.down', this.handleStart);
		this.subscribe('mouse.move', this.handleMove);
		this.subscribe('mouse.up', this.handleEnd);

		// Touch events
		this.subscribe('touch.start', this.handleStart);
		this.subscribe('touch.move', this.handleMove);
		this.subscribe('touch.end', this.handleEnd);
	}

	/**
	 * Handle drag start (mousedown/touchstart)
	 */
	handleStart = (event) => {
		// Check if we can drag
		if (this.options.canDrag && !this.options.canDrag(event)) {
			return;
		}

		// Not on this element, or not on the world at all — see claimsPress.
		if (!this.claimsPress(event)) return;

		// Store starting information
		this.dragStartPosition = { ...event.position };
		this.currentPosition = { ...event.position };
		this.lastPosition = { ...event.position };
		this.dragStartTime = Date.now();
		this.velocity = { x: 0, y: 0 };
		this.mouseDownReceived = true; // Flag that we received mousedown

		// For touch events, store the touch identifier
		if (event.touchId !== undefined) {
			this.touchId = event.touchId;
		} else {
			this.touchId = null;
		}

		// If auto-activate is enabled, start dragging immediately
		if (this.options.autoActivate) {
			this.startDrag(event);
		}
	}

	/**
	 * Handle drag move
	 */
	handleMove = (event) => {
		if (!this.active) return;

		// If we haven't received a mousedown yet, ignore move events
		if (!this.mouseDownReceived) {
			return;
		}

		// If we haven't started dragging yet, check if we should
		if (!this.isDragging) {
			// For touch events, make sure it's the right touch
			if (event.touchId !== undefined && event.touchId !== this.touchId) {
				return;
			}

			// Check if we've moved enough to start dragging
			const deltaX = event.position.x - this.dragStartPosition.x;
			const deltaY = event.position.y - this.dragStartPosition.y;
			const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
			const timeElapsed = Date.now() - this.dragStartTime;

			// Start dragging if we've moved enough and enough time has passed
			if (distance >= this.options.dragThreshold &&
				timeElapsed >= this.options.dragTimeThreshold) {
				this.startDrag(event);
			}

			// If we're not dragging yet, don't continue processing the move
			if (!this.isDragging) {
				return;
			}
		}

		// For touch events, make sure it's the right touch
		if (event.touchId !== undefined && event.touchId !== this.touchId) {
			return;
		}

		// Calculate velocity
		const now = Date.now();
		const dt = (now - this.dragStartTime) / 1000; // in seconds

		if (dt > 0) {
			this.velocity = {
				x: (event.position.x - this.currentPosition.x) / dt,
				y: (event.position.y - this.currentPosition.y) / dt
			};
		}

		// Store current position
		this.lastPosition = { ...this.currentPosition };
		this.currentPosition = { ...event.position };
		this.dragStartTime = now;

		// Track position history for throw velocity
		this.positionHistory.push({ x: event.position.x, y: event.position.y, t: now });
		const cutoff = now - this.options.velocityWindow;
		while (this.positionHistory.length > 1 && this.positionHistory[0].t < cutoff) {
			this.positionHistory.shift();
		}

		// Apply movement constraints
		const constrainedPosition = this.constrainPosition(this.currentPosition);

		// Call move callback
		if (this.options.onDragMove) {
			this.options.onDragMove({
				originalEvent: event.originalEvent,
				position: constrainedPosition,
				startPosition: this.dragStartPosition,
				delta: {
					x: constrainedPosition.x - this.dragStartPosition.x,
					y: constrainedPosition.y - this.dragStartPosition.y
				},
				velocity: this.velocity
			});
		}

	}

	/**
	 * Handle drag end
	 */
	handleEnd = (event) => {
		if (!this.active) return;


		// Reset mousedown tracking regardless of whether we were dragging
		this.mouseDownReceived = false;

		// If we weren't dragging, nothing else to do
		if (!this.isDragging) return;

		// For touch events, make sure it's the right touch
		if (event.touchId !== undefined && event.touchId !== this.touchId) {
			return;
		}

		// Apply movement constraints
		const constrainedPosition = this.constrainPosition(this.currentPosition);

		// Call end callback
		if (this.options.onDragEnd) {
			this.options.onDragEnd({
				originalEvent: event.originalEvent,
				position: constrainedPosition,
				startPosition: this.dragStartPosition,
				delta: {
					x: constrainedPosition.x - this.dragStartPosition.x,
					y: constrainedPosition.y - this.dragStartPosition.y
				},
				velocity: this._computeThrowVelocity()
			});
		}
		this.positionHistory = [];

		// Reset state
		this.isDragging = false;
		this.touchId = null;
		this.inputSystem.releaseDrag(this);

		// Reset element style if we modified it
		if (this.element && this.options.touchAction) {
			this.element.style.touchAction = '';
		}

		// Start inertia if enabled
		if (this.options.inertia) {
			this.startInertia();
		}
	}

	/**
	 * Start the drag operation
	 */
	startDrag(event) {
		// Only one entity may drag at a time per press cycle
		if (!this.inputSystem.claimDrag(this)) return;

		this.isDragging = true;
		this.positionHistory = [];

		// Set touch-action CSS for better touch handling
		if (this.element && this.options.touchAction) {
			this.element.style.touchAction = this.options.touchAction;
		}

		// Apply drag origin offset
		if (this.element) {
			const rect = this.element.getBoundingClientRect();
			const startClientX = this.dragStartPosition.clientX ?? event.position.clientX;
			const startClientY = this.dragStartPosition.clientY ?? event.position.clientY;
			this.grabOffset = {
				x: startClientX - rect.left,
				y: startClientY - rect.top
			};
			this.dragOffset = {
				x: this.grabOffset.x - (rect.width * this.options.dragOriginX),
				y: this.grabOffset.y - (rect.height * this.options.dragOriginY)
			};
		} else {
			this.grabOffset = { x: 0, y: 0 };
			this.dragOffset = { x: 0, y: 0 };
		}

		// Call start callback
		if (this.options.onDragStart) {
			this.options.onDragStart({
				originalEvent: event.originalEvent,
				position: this.dragStartPosition,
				offset: this.dragOffset,
				grabOffset: this.grabOffset
			});
		}
	}

	/**
	 * Constrain a position to limits if set
	 * @param {Object} position Position to constrain
	 * @returns {Object} Constrained position
	 */
	constrainPosition(position) {
		// Create a copy of the position
		const constrained = { ...position };

		// Apply limit to element
		if (this.options.limitToElement && this.element) {
			const rect = this.options.limitToElement.getBoundingClientRect();
			const elemRect = this.element.getBoundingClientRect();

			constrained.x = Math.max(
				rect.left + this.dragOffset.x,
				Math.min(rect.right - elemRect.width + this.dragOffset.x, constrained.x)
			);

			constrained.y = Math.max(
				rect.top + this.dragOffset.y,
				Math.min(rect.bottom - elemRect.height + this.dragOffset.y, constrained.y)
			);
		}

		// Apply limit to viewport
		if (this.options.limitToViewport && this.element) {
			const elemRect = this.element.getBoundingClientRect();

			constrained.x = Math.max(
				this.dragOffset.x,
				Math.min(window.innerWidth - elemRect.width + this.dragOffset.x, constrained.x)
			);

			constrained.y = Math.max(
				this.dragOffset.y,
				Math.min(window.innerHeight - elemRect.height + this.dragOffset.y, constrained.y)
			);
		}

		return constrained;
	}

	/**
	 * Start inertia animation
	 */
	startInertia() {
		if (!this.options.inertia) return;

		// Cancel any existing inertia
		this.cancelInertia();

		// Limit initial velocity
		const speed = Math.sqrt(
			this.velocity.x * this.velocity.x +
			this.velocity.y * this.velocity.y
		);

		if (speed <= 0) return;

		if (speed > this.options.maxInertiaSpeed) {
			const scale = this.options.maxInertiaSpeed / speed;
			this.velocity.x *= scale;
			this.velocity.y *= scale;
		}

		// Start animation
		this.inertiaAnimationId = requestAnimationFrame(this.updateInertia);
	}

	/**
	 * Update inertia animation
	 */
	updateInertia = () => {
		// Calculate new position
		const newPosition = {
			x: this.currentPosition.x + this.velocity.x,
			y: this.currentPosition.y + this.velocity.y
		};

		// Apply constraints
		const constrainedPosition = this.constrainPosition(newPosition);

		// Update current position
		this.currentPosition = constrainedPosition;

		// Call move callback
		if (this.options.onDragMove) {
			this.options.onDragMove({
				position: constrainedPosition,
				startPosition: this.dragStartPosition,
				delta: {
					x: constrainedPosition.x - this.dragStartPosition.x,
					y: constrainedPosition.y - this.dragStartPosition.y
				},
				velocity: this.velocity,
				inertia: true
			});
		}

		// Apply deceleration
		this.velocity.x *= this.options.inertiaDeceleration;
		this.velocity.y *= this.options.inertiaDeceleration;

		// Stop if velocity is very low
		const speed = Math.sqrt(
			this.velocity.x * this.velocity.x +
			this.velocity.y * this.velocity.y
		);

		if (speed < 0.1) {
			this.cancelInertia();

			// Call end callback
			if (this.options.onDragEnd) {
				this.options.onDragEnd({
					position: constrainedPosition,
					startPosition: this.dragStartPosition,
					delta: {
						x: constrainedPosition.x - this.dragStartPosition.x,
						y: constrainedPosition.y - this.dragStartPosition.y
					},
					velocity: { x: 0, y: 0 },
					inertia: true
				});
			}

			return;
		}

		// Continue animation
		this.inertiaAnimationId = requestAnimationFrame(this.updateInertia);
	}

	/**
	 * Cancel inertia animation
	 */
	cancelInertia() {
		if (this.inertiaAnimationId) {
			cancelAnimationFrame(this.inertiaAnimationId);
			this.inertiaAnimationId = null;
		}
	}

	/**
	 * Manually start a drag operation at the current mouse position
	 */
	startDragAtCurrentPosition() {
		const mousePos = this.inputSystem.getMousePosition();
		this.startDragAtPosition(mousePos);
	}

	/**
	 * Manually start a drag operation at an explicit screen position
	 * @param {Object} position Position object with x/y and optional clientX/clientY
	 */
	startDragAtPosition(position = {}) {
		const normalizedPosition = {
			x: position.x ?? position.clientX ?? 0,
			y: position.y ?? position.clientY ?? 0,
			clientX: position.clientX ?? position.x ?? 0,
			clientY: position.clientY ?? position.y ?? 0
		};
		this.handleStart({
			position: normalizedPosition,
			originalEvent: null
		});
		this.startDrag({
			position: normalizedPosition,
			originalEvent: null
		});
	}

	/**
	 * Stop the current drag operation (can be called externally)
	 */
	stopDrag() {
		if (this.isDragging) {
			const mousePos = this.inputSystem.getMousePosition();
			this.handleEnd({
				position: mousePos,
				originalEvent: null
			});
		}
	}

	/**
	 * Compute throw velocity from recent position history.
	 * Uses the oldest sample within velocityWindow ms to get a stable average,
	 * avoiding the stale-last-frame problem when the user releases mid-movement.
	 */
	_computeThrowVelocity() {
		const history = this.positionHistory;
		if (history.length < 2) return { ...this.velocity };
		const oldest = history[0];
		const newest = history[history.length - 1];
		const dt = (newest.t - oldest.t) / 1000;
		if (dt <= 0) return { ...this.velocity };
		return {
			x: (newest.x - oldest.x) / dt,
			y: (newest.y - oldest.y) / dt
		};
	}

	/**
	 * Clean up resources
	 */
	dispose() {
		this.cancelInertia();

		// Remove global handlers
		window.removeEventListener('mouseup', this.windowMouseUpHandler);
		window.removeEventListener('touchend', this.windowTouchEndHandler);

		// Reset element style if needed
		if (this.element && this.options.touchAction) {
			this.element.style.touchAction = '';
		}

		super.dispose();
	}
}
;
/* -- js/Input/RubbingComponent.js -- */

/**
 * Component to handle rubbing/petting gestures
 */
class RubbingComponent extends InputComponent {
  /**
   * Get default options for this component
   * @returns {Object} Default options
   */
  getDefaultOptions() {
    const rubbing = SiteConfig.interaction.rubbing;
    return {
      ...super.getDefaultOptions(),
      minRubs: rubbing.minRubs,                       // Minimum rubs needed for a valid interaction
      maxRubs: rubbing.maxRubsObject,                 // Maximum effective rubs
      rubbingThreshold: rubbing.rubbingThreshold,     // Minimum velocity for a valid rub
      minTimeBetweenRubs: rubbing.minTimeBetweenRubs, // Cooldown between rub sessions (ms)
      directionThreshold: rubbing.directionThreshold, // Pixels needed to determine direction
      hapticEnabled: true,       // Whether to use haptic feedback
      hapticDuration: rubbing.hapticDuration,         // Duration of haptic feedback (ms)

      // Callbacks
      onRubProgress: null,       // Called during rubbing with progress
      onRubComplete: null,       // Called when rubbing sequence completes
      onRubOverdone: null,       // Called when rubbing too much
      onRubStart: null,          // Called when rubbing starts
      canRub: null               // Function to check if rubbing is allowed
    };
  }
  
  /**
   * Initialize the component
   */
  initialize() {
    super.initialize();
    
    // Rubbing state
    this.isRubbing = false;
    this.lastRubTime = 0;
    this.rubCounter = 0;
    this.totalRubDistance = 0;
    this.lastPosition = { x: 0, y: 0 };
    this.lastTimestamp = 0;
    this.lastRubDirection = null;
    this.consecutiveSameDirection = 0;
    this.touchId = null;
    
    // Add touch-action CSS style
    if (this.element) {
      this.originalTouchAction = this.element.style.touchAction;
    }
  }
  
  /**
   * Set up event subscriptions
   */
  setupSubscriptions() {
    // Mouse events
    this.subscribe('mouse.down', this.handleStart);
    this.subscribe('mouse.move', this.handleMove);
    this.subscribe('mouse.up', this.handleEnd);
    
    // Touch events
    this.subscribe('touch.start', this.handleStart);
    this.subscribe('touch.move', this.handleMove);
    this.subscribe('touch.end', this.handleEnd);
  }
  
  /**
   * Handle start of interaction
   * @param {Object} event Input system event
   */
  handleStart = (event) => {
    
    // Check if rubbing is allowed
    if (this.options.canRub && !this.options.canRub(event)) {
      return;
    }
    
    // Don't start if we're in cooldown
    if (!this.canRub()) {
      return;
    }
    
    // For touch events, store the touch ID
    if (event.touchId !== undefined) {
      this.touchId = event.touchId;
    } else {
      this.touchId = null;
    }
    
    // Not on this element, or not on the world at all — see claimsPress.
    if (!this.claimsPress(event)) return;

    // Set touch-action to none for smoother rubbing on touch devices
    if (this.element) this.element.style.touchAction = 'none';
    
    // Initialize rubbing state
    this.isRubbing = true;
    this.lastPosition = { ...event.position };
    this.lastTimestamp = Date.now();
    this.totalRubDistance = 0;
    this.rubCounter = 0;
    this.lastRubDirection = null;
    this.consecutiveSameDirection = 0;
    
    // Call start callback
    if (this.options.onRubStart) {
      this.options.onRubStart({
        position: event.position,
        isTouchEvent: event.isTouchEvent
      });
    }
  }
  
  /**
   * Handle movement during rubbing
   * @param {Object} event Input system event
   */
  handleMove = (event) => {
    if (!this.active || !this.isRubbing) return;
    
    // For touch events, check if it's the right touch
    if (event.touchId !== undefined && event.touchId !== this.touchId) {
      return;
    }
    
    // Calculate movement
    const deltaX = event.position.x - this.lastPosition.x;
    const deltaY = event.position.y - this.lastPosition.y;
    const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    const deltaTime = Date.now() - this.lastTimestamp;
    const velocity = deltaTime > 0 ? distance / deltaTime : 0;
    
    // Determine rub direction
    if (distance > this.options.directionThreshold) {
      const direction = Math.abs(deltaX) > Math.abs(deltaY)
        ? (deltaX > 0 ? 'right' : 'left')
        : (deltaY > 0 ? 'down' : 'up');
      
      if (direction === this.lastRubDirection) {
        this.consecutiveSameDirection++;
      } else {
        this.lastRubDirection = direction;
        this.consecutiveSameDirection = 1;
      }
    }
    
    // Check if this is a valid rubbing motion
    if (velocity > this.options.rubbingThreshold) {
      this.totalRubDistance += distance;
      
      // Count as a rub if we've moved enough in the same direction
      if (this.consecutiveSameDirection >= 2) {
        this.rubCounter++;
        this.consecutiveSameDirection = 0;
        
        // Provide haptic feedback
        if (this.options.hapticEnabled) {
          this.provideHapticFeedback();
        }
        
        // Call progress callback
        if (this.options.onRubProgress) {
          this.options.onRubProgress({
            count: this.rubCounter,
            distance: this.totalRubDistance,
            isOverdone: this.rubCounter > this.options.maxRubs,
            direction: this.lastRubDirection
          });
        }
      }
    }
    
    // Update state
    this.lastPosition = { ...event.position };
    this.lastTimestamp = Date.now();
  }
  
  /**
   * Handle end of rubbing
   * @param {Object} event Input system event
   */
  handleEnd = (event) => {
    if (!this.active || !this.isRubbing) return;
    
    // For touch events, check if it's the right touch
    if (event.touchId !== undefined && event.touchId !== this.touchId) {
      return;
    }
    
    // Reset element style
    if (this.element) {
      this.element.style.touchAction = this.originalTouchAction || '';
    }
    
    // If we had valid rubs, start the cooldown
    if (this.rubCounter >= this.options.minRubs) {
      this.lastRubTime = Date.now();
      
      if (this.rubCounter <= this.options.maxRubs) {
        // Good number of rubs
        if (this.options.onRubComplete) {
          this.options.onRubComplete({
            count: this.rubCounter,
            distance: this.totalRubDistance,
            direction: this.lastRubDirection
          });
        }
      } else {
        // Too much rubbing
        if (this.options.onRubOverdone) {
          this.options.onRubOverdone({
            count: this.rubCounter,
            distance: this.totalRubDistance,
            direction: this.lastRubDirection
          });
        }
      }
    }
    
    // Reset state
    this.isRubbing = false;
    this.touchId = null;
  }
  
  /**
   * Provide haptic feedback
   */
  provideHapticFeedback() {
    if ('vibrate' in navigator) {
      navigator.vibrate(this.options.hapticDuration);
    }
  }
  
  /**
   * Check if rubbing is allowed based on cooldown
   * @returns {boolean}
   */
  canRub() {
    return Date.now() - this.lastRubTime >= this.options.minTimeBetweenRubs;
  }
  
  /**
   * Get time remaining until rubbing is allowed again
   * @returns {number} Time in milliseconds
   */
  getCooldownTimeRemaining() {
    const elapsed = Date.now() - this.lastRubTime;
    const remaining = this.options.minTimeBetweenRubs - elapsed;
    return Math.max(0, remaining);
  }
  
  /**
   * Clean up resources
   */
  dispose() {
    // Reset element style if needed
    if (this.element) {
      this.element.style.touchAction = this.originalTouchAction || '';
    }
    
    super.dispose();
  }
}
;
/* -- js/User/MyteRosterSchema.js -- */
// Single source of truth for the Myte save/roster schema.
// ContainerManager (restore/normalize) and User (save) both go through these
// helpers, so field names, defaults, and clamping rules live in one place.
class MyteRosterSchema {

    static createStarterRoster(existingRoster = []) {
        const starters = SiteConfig.myte.starterRoster || [];
        const candidates = Array.isArray(existingRoster) ? existingRoster : [];
        const usedCandidates = new Set();

        return starters.map((starter, index) => {
            const candidateIndex = candidates.findIndex((entry, candidateIndex) =>
                !usedCandidates.has(candidateIndex) &&
                MyteDefinitionRegistry.normalizeSpeciesId?.(entry?.species || entry?.speciesId) === starter.species
            );
            const candidate = candidateIndex >= 0 ? candidates[candidateIndex] : {};
            if (candidateIndex >= 0) usedCandidates.add(candidateIndex);

            return this.normalizeEntry({
                ...candidate,
                ...starter,
                stats: candidate?.stats,
                isActive: false
            }, index);
        });
    }

    static statDefaults() {
        const initial = SiteConfig.myte.initialStats;
        return {
            health:     initial.health,
            energy:     initial.energy,
            fun:        initial.fun,
            social:     initial.social,
            satiety:    initial.satiety,
            comfort:    initial.comfort,
            confidence: initial.confidence
        };
    }

    // Normalize a raw roster entry (saved data, DOM extraction, or fallback)
    // into the canonical shape ContainerManager.setupMytes consumes.
    static normalizeEntry(entry = {}, index = 0) {
        const species = MyteDefinitionRegistry.normalizeSpeciesId?.(entry.species || entry.speciesId || 'snail') || 'snail';
        const name = String(entry.name || entry.displayName || `Myte ${index + 1}`).trim() || `Myte ${index + 1}`;
        const slotId = String(entry.slotId || `myte-slot-${index + 1}`);
        const slotLabel = String(entry.slotLabel || `${name}'s Slot`).trim() || `${name}'s Slot`;
        const starter = SiteConfig.myte.starterRoster?.find(candidate =>
            String(candidate.id) === String(entry.id || index + 1) ||
            candidate.slotId === slotId
        );
        const homeMapId = String(entry.homeMapId || starter?.homeMapId || SiteConfig.world.defaultMap);
        const stats = entry.stats || {};
        const defaults = this.statDefaults();
        const slotX = Number.isFinite(Number(entry.slotX)) ? Number(entry.slotX) : 0;
        const slotY = Number.isFinite(Number(entry.slotY)) ? Number(entry.slotY) : 0;
        // Home slots can be dragged in Build mode, so a stored position is a
        // decision somebody made, whether it came from the authored markup or
        // from a save. Without a position the map's spawn layout places it.
        const hasExplicitSlotPosition = entry.hasSlotPosition === true ||
            (entry.hasSlotPosition == null && (slotX !== 0 || slotY !== 0));
        const num = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;

        const id = String(entry.id || index + 1);
        // A birthday is save data, not content: whatever the save holds wins,
        // and CalendarRegistry derives a stable one for a myte that has none so
        // an existing roster is not left blank.
        const birthday = CalendarRegistry.resolveBirthday({
            id,
            name,
            birthday: entry.birthday ?? starter?.birthday
        });

        return {
            id,
            name,
            species,
            slotId,
            slotLabel,
            homeMapId,
            birthday,
            slotX,
            slotY,
            hasSlotPosition: hasExplicitSlotPosition,
            isActive: entry.isActive === true,
            goal: entry.goal ?? DEFAULT_MODE,
            followGoal: entry.followGoal ?? DEFAULT_FOLLOW_MODE,
            autonomyGoal: entry.autonomyGoal ?? DEFAULT_AUTONOMY_MODE,
            posX: Number.isFinite(Number(entry.posX)) ? Number(entry.posX) : null,
            posY: Number.isFinite(Number(entry.posY)) ? Number(entry.posY) : null,
            stats: {
                health:     num(stats.health, defaults.health),
                energy:     num(stats.energy, defaults.energy),
                fun:        num(stats.fun, defaults.fun),
                social:     num(stats.social, defaults.social),
                satiety:    num(stats.satiety ?? stats.hunger, defaults.satiety),
                comfort:    num(stats.comfort, defaults.comfort),
                confidence: num(stats.confidence, defaults.confidence)
            }
        };
    }

    // Serialize a live Myte into the save shape.
    static serializeMyte(myte, index = 0) {
        const defaults = this.statDefaults();
        return {
            id: myte.id,
            name: myte.name,
            species: myte.species,
            posX: myte.posX,
            posY: myte.posY,
            // The slot is the model, so the save reads from it rather than
            // scraping the label out of the DOM it happens to be drawn with.
            ...(myte.homeSlot?.serialize() ?? {
                slotId: `myte-slot-${index + 1}`,
                slotLabel: `${myte.name}'s Slot`,
                homeMapId: SiteConfig.world.defaultMap,
                slotX: 0,
                slotY: 0,
                hasSlotPosition: false
            }),
            birthday: myte.birthday ?? null,
            isActive: !!myte.isActive,
            goal: myte.goal ?? null,
            followGoal: myte.followGoal ?? null,
            autonomyGoal: myte.autonomyGoal ?? null,
            stats: {
                health:     myte.stats?.health     ?? defaults.health,
                energy:     myte.stats?.energy     ?? defaults.energy,
                fun:        myte.stats?.fun        ?? defaults.fun,
                social:     myte.stats?.social     ?? defaults.social,
                satiety:    myte.stats?.satiety    ?? defaults.satiety,
                comfort:    myte.stats?.comfort    ?? defaults.comfort,
                confidence: myte.stats?.confidence ?? defaults.confidence,
                speed:      myte.stats?.speed      ?? 1,
                level:      myte.stats?.level      ?? 1,
                experience: myte.stats?.experience ?? 0,
                traits: myte.stats?.traits ? { ...myte.stats.traits } : undefined,
            },
        };
    }

    // Apply a normalized roster entry to a live Myte (name, display labels, stats).
    static applyToMyte(myte, rosterEntry = {}) {
        if (!myte?.stats || !rosterEntry) {
            return;
        }

        myte.name = rosterEntry.name || myte.name;
        myte.homeSlot?.applyRosterEntry(rosterEntry);
        myte.birthday = rosterEntry.birthday ?? CalendarRegistry.resolveBirthday(rosterEntry);
        myte.element.dataset.myteName = myte.name;
        myte.element.dataset.myteHomeMap = myte.homeMapId;
        if (myte.elements.wrapper) {
            myte.elements.wrapper.dataset.myteHomeMap = myte.homeMapId;
        }
        myte.duplicate?.setAttribute?.('data-myte-name', myte.name);

        const displayNameElements = [
            myte.element.querySelector('.name-wrapper .name'),
            myte.duplicate?.querySelector?.('.name-wrapper .name'),
            myte.elements.wrapper?.querySelector?.('.myte-home-label .name')
        ].filter(Boolean);
        displayNameElements.forEach((element, index) => {
            element.textContent = index === 2
                ? (rosterEntry.slotLabel || `${myte.name}'s Slot`)
                : myte.name;
        });

        const stats = rosterEntry.stats || {};
        myte.stats.health = Math.max(myte.stats.minHealth, Math.min(myte.stats.maxHealth, stats.health ?? myte.stats.health));
        myte.stats.energy = Math.max(myte.stats.minEnergy, Math.min(myte.stats.maxEnergy, stats.energy ?? myte.stats.energy));
        if (stats.fun     != null) myte.stats.fun    = Math.max(myte.stats.minFun,    Math.min(myte.stats.maxFun,    stats.fun));
        if (stats.social  != null) myte.stats.social = Math.max(myte.stats.minSocial, Math.min(myte.stats.maxSocial, stats.social));
        const savedSatiety = stats.satiety ?? stats.hunger;
        if (savedSatiety != null) myte.stats.satiety = Math.max(myte.stats.minSatiety, Math.min(myte.stats.maxSatiety, savedSatiety));
        myte.stats.comfort    = Math.max(myte.stats.minComfort,    Math.min(myte.stats.maxComfort,    stats.comfort    ?? myte.stats.comfort));
        // Migrate old 0–100 confidence saves to new 0–1 scale
        const savedConfidence = stats.confidence != null && stats.confidence > 1
            ? stats.confidence / 100
            : stats.confidence;
        myte.stats.confidence = Math.max(myte.stats.minConfidence, Math.min(myte.stats.maxConfidence, savedConfidence ?? myte.stats.confidence));

        // Restore progression and personality traits from the canonical save schema.
        if (stats.speed != null) myte.stats.speed = stats.speed;
        if (stats.level != null) myte.stats.level = stats.level;
        if (stats.experience != null) myte.stats.experience = stats.experience;
        if (stats.traits && typeof stats.traits === 'object') {
            myte.stats.traits = { ...myte.stats.traits, ...stats.traits };
        }

        myte.stats.updateBatteryDisplay?.();
    }
}
;
/* -- js/User/User.js -- */
const USER_DATA_VERSION = 5;
const USER_DEFAULT_PREFERENCES = Object.freeze({
    soundEnabled: true,
    musicEnabled: true,
    ambientEnabled: true,
    sfxEnabled: true,
    uiEnabled: true,
    footstepsEnabled: true,
    spatialAudioEnabled: true,
    masterVolume: 1,
    sfxVolume: 0.82,
    footstepsVolume: 0.72,
    musicVolume: 0.28,
    uiVolume: 0.72,
    ambientVolume: 0.42,
    cameraMode: 'follow',
    containerLimit: true,
    theme: 'light',
    graphicsQuality: 'medium',
    effectsEnabled: true,
    animationsEnabled: true,
    timeOfDayOverlayEnabled: true,
    lightingEnabled: false,
    lightingDitherEnabled: true,
    weatherEffectsEnabled: true,
    tutorialsEnabled: true,
    interactionHintsEnabled: true,
    // The explanatory notes inside panels. Separate from interactionHints,
    // which is the world's own tooltips: one is the interface explaining
    // itself, the other is the game pointing at things.
    panelHintsEnabled: true,
    autoSaveEnabled: true,
    notificationsEnabled: true,
    // Set once the first-run hints have been shown, so returning players are not
    // re-onboarded. Turning `tutorialsEnabled` back on resets this (SettingsPanel).
    hasSeenIntro: false
});

class User {
    constructor(core) {
        this.core = core;
        
        // Basic user info
        this.username = null;
        this.userId = null;
        this.lastLogin = null;
        this.dateCreated = null;
		this.lastSavedAt = null;
		this.returnSummary = null;

        // Reference to ContainerManager's inventory instance
        this.inventory = null;
        this.items = [];

        // Game state
        this.activeMytes = [];
        this.savedMytes = [];   // serialized myte state restored on load
        this.currentMapId = null;
        this.worldState = { version: 1, maps: {} };

        // User preferences
        this.preferences = User.getDefaultPreferences();

        // Statistics
        this.stats = {
            totalPlayTime: 0,
            mytesHatched: 0,
            itemsCollected: 0,
            achievementsUnlocked: 0
        };

        // Achievement tracking
        this.achievements = new Map();

        // Currency/Resources
        this.currency = {
            coins: 0,
            gems: 0
        };
        this._saveTimer = null;
        this._lastPlayTimeSaveAt = 0;
    }

    // Connect to existing inventory instance
    setInventory(inventoryInstance) {
        this.inventory = inventoryInstance;
    }

    trackMytes(mytes = []) {
        this.activeMytes = Array.isArray(mytes) ? [...mytes] : [];
    }

    getStorageKey(userId = this.userId) {
        if (!userId) return null;
        return this.core?.getUserStorageKey?.(userId) ?? `user_${userId}`;
    }

    serializeUserData() {
		this.lastSavedAt = new Date().toISOString();
        this.core?.getFirstContainer?.()?.worldState?.captureMap?.(this.core.getFirstContainer().gameMap);
        const trackedMytes = Array.isArray(this.activeMytes) ? this.activeMytes : [];
        const inventoryData = (this.inventory?.items ?? this.items).map(item => ({
                name: item.name,
                quantity: item.quantity,
                type: item.type,
                variant: item.variant,
                description: item.description || ''
            }));

        return {
            data_version: USER_DATA_VERSION,
            username: this.username,
            userId: this.userId,
            lastLogin: this.lastLogin,
            dateCreated: this.dateCreated,
			lastSavedAt: this.lastSavedAt,
            currentMapId: this.currentMapId,
            worldState: this.worldState,
            inventory: inventoryData,
            mytes: trackedMytes.map((myte, index) => MyteRosterSchema.serializeMyte(myte, index)),
            preferences: this.preferences,
            stats: this.stats,
            achievements: Array.from(this.achievements.entries()),
            currency: this.currency
        };
    }

    applyUserData(userData = {}) {
        this.username = userData.username ?? this.username;
        this.userId = userData.userId ?? this.userId;
        this.lastLogin = userData.lastLogin ? new Date(userData.lastLogin) : this.lastLogin;
        this.dateCreated = userData.dateCreated ? new Date(userData.dateCreated) : this.dateCreated;
		this.lastSavedAt = userData.lastSavedAt ?? this.lastSavedAt;
        this.currentMapId = userData.currentMapId ?? this.currentMapId;
        this.worldState = userData.worldState?.version === 1
            ? Utility.deepClone(userData.worldState)
            : { version: 1, maps: {} };

        if (Array.isArray(userData.mytes)) {
            this.savedMytes = userData.mytes.map(m => ({ ...m }));
        }

        if (userData.preferences) {
            this.preferences = User.normalizePreferences({
                ...this.preferences,
                ...userData.preferences
            });
        }

        if (userData.stats) {
            this.stats = {
                ...this.stats,
                ...userData.stats
            };
        }
        this._lastPlayTimeSaveAt = this.stats.totalPlayTime;

        if (userData.achievements) {
            this.achievements = new Map(userData.achievements);
        }

        if (userData.currency) {
            this.currency = {
                ...this.currency,
                ...userData.currency
            };
        }

        if (Array.isArray(userData.inventory)) {
            this.items = userData.inventory.map(item => ({ ...item }));
        }

        this.syncInventoryFromItems();
    }

    syncInventoryFromItems() {
        // loadItems is the one reload path: it clears state + DOM and
        // normalizes through the registry, so names and sprites survive the
        // round-trip. Duplicating it here is where items used to lose their
        // display name on import.
        this.inventory?.loadItems(this.items);
    }

    _migrateUserData(data) {
        const version = data?.data_version ?? 0;
        if (version === USER_DATA_VERSION) return data;

        let migrated = { ...data };

        if (version < 1) {
            // v0 → v1: data_version field added; all other fields are compatible
            migrated.data_version = 1;
        }

        if (migrated.data_version < 2) {
            if (migrated.userId === 'default') {
                migrated.mytes = MyteRosterSchema.createStarterRoster(migrated.mytes);
            }
            migrated.data_version = 2;
        }

        if (migrated.data_version < 3) {
            migrated.worldState = { version: 1, maps: {} };
            migrated.data_version = 3;
        }

		if (migrated.data_version < 4) {
			migrated.lastSavedAt = null;
			migrated.data_version = 4;
		}

		// v4 → v5: night lighting now ships off. Existing saves carry the old
		// default explicitly, so without this the new default reaches nobody
		// who has played before.
		if (migrated.data_version < 5) {
			if (migrated.preferences) migrated.preferences.lightingEnabled = false;
			migrated.data_version = 5;
		}

        if (migrated.data_version === USER_DATA_VERSION) {
            Utility.logDebug(`[User] Migrated save data from v${version} to v${USER_DATA_VERSION}.`);
            return migrated;
        }

        console.warn(`[User] Save data v${version} could not be migrated to v${USER_DATA_VERSION}, resetting.`);
        return null;
    }

    loadUserDataFromStorage(userId = this.userId) {
        const storageKey = this.getStorageKey(userId);
        if (!storageKey) return false;

        const savedData = localStorage.getItem(storageKey);
        if (!savedData) return false;

        let parsed;
        try {
            parsed = JSON.parse(savedData);
        } catch (e) {
            // Never delete a corrupt save outright — for a pet game that is the
            // player's only copy of their Mytes. Quarantine it, try the rolling
            // backup, and say what happened.
            console.warn('[User] Corrupted save data.', e);
            this._quarantineCorruptSave(storageKey, savedData);

            const recovered = this._loadBackup(storageKey);
            if (recovered) {
                this.core?.toastManager?.warning?.(
                    'Your save was damaged, so the previous backup was loaded instead. Recent progress may be missing.',
                    'Save Recovered'
                );
                const migratedBackup = this._migrateUserData(recovered);
                if (migratedBackup) {
					this.captureReturnSummary(migratedBackup);
                    this.applyUserData(migratedBackup);
                    return true;
                }
            }

            this.core?.toastManager?.error?.(
                'Your save could not be read and no backup was available. A copy of the damaged data was kept.',
                'Save Unreadable'
            );
            return false;
        }

        const migrated = this._migrateUserData(parsed);
        if (!migrated) return false;

		this.captureReturnSummary(migrated);
        this.applyUserData(migrated);
        return true;
    }

	captureReturnSummary(userData) {
		this.returnSummary = null;
		const savedAt = Date.parse(userData?.lastSavedAt);
		if (!Number.isFinite(savedAt)) return;

		const awayMs = Math.max(0, Date.now() - savedAt);
		if (awayMs < SiteConfig.ui.welcomeBack.minAwayMs) return;
		this.returnSummary = { awayMs };
	}

    _backupKey(storageKey) { return `${storageKey}.bak`; }
    _corruptKey(storageKey) { return `${storageKey}.corrupt`; }

    // Keep the damaged blob under a separate key so it can be inspected or
    // hand-recovered later. Best effort: if even this write fails, we are out of
    // storage and there is nothing useful left to do.
    _quarantineCorruptSave(storageKey, rawData) {
        try {
            localStorage.setItem(this._corruptKey(storageKey), rawData);
        } catch (error) {
            console.warn('[User] Could not quarantine corrupt save:', error);
        }
    }

    _loadBackup(storageKey) {
        try {
            const backup = localStorage.getItem(this._backupKey(storageKey));
            return backup ? JSON.parse(backup) : null;
        } catch (error) {
            console.warn('[User] Backup save is unreadable too:', error);
            return null;
        }
    }

    /**
     * Serialize the current user to a portable JSON string — the export half of
     * export/import, and a useful bug-report attachment.
     */
    exportUserData() {
        return JSON.stringify({
            exportedAt: new Date().toISOString(),
            userId: this.userId,
            data: this.serializeUserData()
        }, null, 2);
    }

    /**
     * Replace the current save from an exported blob.
     *
     * Accepts both the wrapped export shape and a bare save, so a file pulled
     * straight out of localStorage also works.
     *
     * @returns {{ ok: boolean, error?: string }}
     */
    importUserData(json) {
        let parsed;
        try {
            parsed = typeof json === 'string' ? JSON.parse(json) : json;
        } catch (error) {
            return { ok: false, error: 'That file is not valid JSON.' };
        }

        const payload = parsed?.data ?? parsed;
        if (!payload || typeof payload !== 'object') {
            return { ok: false, error: 'That file does not contain save data.' };
        }

        const migrated = this._migrateUserData(payload);
        if (!migrated) {
            return { ok: false, error: 'That save is from an unsupported version.' };
        }

        // Snapshot what is about to be replaced, so an accidental import of the
        // wrong file is recoverable.
        const storageKey = this.getStorageKey();
        if (storageKey) {
            const current = localStorage.getItem(storageKey);
            if (current) {
                try {
                    localStorage.setItem(this._backupKey(storageKey), current);
                } catch (error) {
                    console.warn('[User] Could not back up before import:', error);
                }
            }
        }

        this.applyUserData(migrated);
        this.saveUserData();
        return { ok: true };
    }

    // User authentication and profile methods
    login(username, userId) {
        this.username = username;
        this.userId = userId;
        this.lastLogin = new Date();
        this.dateCreated ??= new Date();
        this.loadUserData();
    }

    // Currency management
    setCurrency(type, total) {
        if (!Object.prototype.hasOwnProperty.call(this.currency, type)) return false;

        const nextTotal = Math.max(0, Math.round(Number(total) || 0));
        const previousTotal = this.currency[type];
        const delta = nextTotal - previousTotal;
        if (delta === 0) return true;

        this.currency[type] = nextTotal;
        this._scheduleSave();
        this._emitCurrencyChanged(type, delta);
        return true;
    }

    addCurrency(type, amount) {
        if (!Object.prototype.hasOwnProperty.call(this.currency, type)) return false;
        return this.setCurrency(type, this.currency[type] + Number(amount || 0));
    }

    spendCurrency(type, amount) {
        if (!Object.prototype.hasOwnProperty.call(this.currency, type)) return false;
        const cost = Math.max(0, Number(amount) || 0);
        if (this.currency[type] < cost) return false;
        return this.setCurrency(type, this.currency[type] - cost);
    }

    _emitCurrencyChanged(type, delta) {
        this.core?.eventManager?.emit(EVENTS.USER_CURRENCY_CHANGED, {
            type,
            delta,
            total: this.currency[type]
        });
    }

    // Preference management
    setPreference(key, value) {
        if (this.preferences.hasOwnProperty(key)) {
            this.preferences[key] = value;
            this._scheduleSave();
            return true;
        }
        return false;
    }

    // Load data from JSON file
    async loadUserDataFromFile(fileName) {
        try {
            const response = await fetch(fileName); // Perform the fetch
            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
            
            const responseText = await response.text(); // Extract the response text
            const userData = JSON.parse(responseText); // Parse it as JSON
            Utility.logDebug('[User] Loaded user data from file:', userData);

            this.applyUserData(userData);

            return true;
        } catch (error) {

            const inferredPath = new URL(fileName, window.location.href).href;
            Utility.logDebug('Attempting to load file from:', inferredPath);
            console.error('Error reading file:', fileName);
            console.error('Error loading user data:', error);

            return false;
        }
    }

    applyAudioSettings(soundManager) {
        if (!soundManager) return;
        const p = this.preferences;
        soundManager.soundEnabled     = p.soundEnabled;
        soundManager.musicEnabled     = p.musicEnabled;
        soundManager.ambientEnabled   = p.ambientEnabled ?? true;
        soundManager.sfxEnabled       = p.sfxEnabled ?? true;
        soundManager.uiEnabled        = p.uiEnabled ?? true;
        soundManager.footstepsEnabled = p.footstepsEnabled;
        soundManager.spatialAudioEnabled = p.spatialAudioEnabled ?? true;
        soundManager.volume.master  = p.masterVolume;
        soundManager.volume.sfx     = p.sfxVolume;
        soundManager.volume.footsteps = p.footstepsVolume;
        soundManager.volume.music   = p.musicVolume;
        soundManager.volume.ui      = p.uiVolume;
        soundManager.volume.ambient = p.ambientVolume;
    }

    resetAudioPreferences() {
        const defaults = User.getDefaultPreferences();
        [
            'soundEnabled',
            'musicEnabled',
            'ambientEnabled',
            'sfxEnabled',
            'uiEnabled',
            'footstepsEnabled',
            'spatialAudioEnabled',
            'masterVolume',
            'sfxVolume',
            'footstepsVolume',
            'musicVolume',
            'uiVolume',
            'ambientVolume'
        ].forEach((key) => {
            this.preferences[key] = defaults[key];
        });
        this._scheduleSave();
        return { ...defaults };
    }

    static getDefaultPreferences() {
        return { ...USER_DEFAULT_PREFERENCES };
    }

    static normalizePreferences(rawPreferences = {}) {
        return {
            ...USER_DEFAULT_PREFERENCES,
            ...(rawPreferences || {})
        };
    }

    // Data persistence
    saveUserData() {
        if (!this.userId) return;

        const storageKey = this.getStorageKey();
        if (!storageKey) return;

        try {
            const serialized = JSON.stringify(this.serializeUserData());

            // Roll the last known-good save into a backup before overwriting, so a
            // corrupt or partial write is recoverable rather than terminal. Only
            // promote a previous value that actually parses — otherwise a bad save
            // would overwrite a good backup.
            const previous = localStorage.getItem(storageKey);
            if (previous && previous !== serialized) {
                try {
                    JSON.parse(previous);
                    localStorage.setItem(this._backupKey(storageKey), previous);
                } catch {
                    // Previous value was already damaged — leave the older backup be.
                }
            }

            localStorage.setItem(storageKey, serialized);

            const lastUserIdKey = this.core?.config?.userData?.lastUserIdKey;
            if (lastUserIdKey) {
                localStorage.setItem(lastUserIdKey, this.userId);
            }
        } catch (error) {
            console.error('[User] Failed to save user data:', error);
            this.core?.toastManager?.warning?.(
                'Could not save - storage full or unavailable',
                'Warning'
            );
        }
    }

    // Debounced save — use this for frequent mutations (myte add/remove, currency, prefs).
    // Flushes at most once per 2 seconds; logout/unload calls saveUserData() directly.
    _scheduleSave() {
        if (this.preferences.autoSaveEnabled === false) return;
        if (this._saveTimer) return;
        this._saveTimer = setTimeout(() => {
            this._saveTimer = null;
            this.saveUserData();
        }, 2000);
    }

    loadUserData() {
        return this.loadUserDataFromStorage(this.userId);
    }

    // Analytics and tracking
    updatePlayTime(deltaTime) {
        this.stats.totalPlayTime += deltaTime;
        if (this.stats.totalPlayTime - this._lastPlayTimeSaveAt >= 300000) {
            this._lastPlayTimeSaveAt = this.stats.totalPlayTime;
            this.saveUserData();
        }
    }

    getPlayTimeStats() {
        return {
            totalHours: Math.floor(this.stats.totalPlayTime / 3600000),
            totalMinutes: Math.floor((this.stats.totalPlayTime % 3600000) / 60000)
        };
    }
}
