/* -- js/Engine/Entity.js -- */

// Shared entity capabilities and pathfinding mixin.
// Apply to any class with: applyEntityMixin(MyClass)
// Both Myte and NpcMapObject use this so the logic lives in one place.

const EntityDefaults = {
	capabilities() {
		return {
			canSwim: false,
			followsPaths: true,
			canOpenDoors: false,
			canWade: true,
			fireResistance: false
		};
	},

	pathfindingOptions() {
		return {};
	}
};

const EntityMethods = {

	// ── Region membership ─────────────────────────────────────────────────────
	// Backed by RegionManager (js/Map/Regions/). Room membership is recomputed
	// only when the entity crosses a grid cell; zone membership is written by
	// Zone itself, because its thresholds are intersection-ratio based and a
	// centre-point test cannot reproduce them.

	getRegionManager() {
		return this.gameMap?.regionManager ??
			this.parent?.gameMap?.regionManager ??
			this.container?.gameMap?.regionManager ??
			null;
	},

	getAttachmentSystem() {
		return this.container?.attachments ??
			this.parent?.attachments ??
			this.gameMap?.parent?.attachments ??
			this.parent?.gameMap?.parent?.attachments ??
			null;
	},

	get currentRooms() {
		const parent = this.getAttachmentSystem()?.getAttachment(this)?.parent;
		if (parent) return parent.currentRooms ?? [];
		return this.getRegionManager()?.getMembership(this, 'room') ?? [];
	},

	// Innermost room wins when volumes overlap: the smaller area is the more
	// specific answer (a nook inside a hall reads as the nook).
	get currentRoom() {
		const rooms = this.currentRooms;
		if (rooms.length <= 1) return rooms[0] ?? null;
		return rooms.reduce((best, room) =>
			(room.bounds.width * room.bounds.height) < (best.bounds.width * best.bounds.height) ? room : best
		);
	},

	get currentRoomId() {
		return this.currentRoom?.id ?? null;
	},

	get currentZones() {
		return this.getRegionManager()?.getMembership(this, 'zone') ?? [];
	},

	get currentZoneIds() {
		return this.currentZones.map(region => region.id);
	},

	// Per-map `location` is the fallback; a room refines it. This is the whole
	// "is this entity sheltered" question — one expression, no new system.
	get isIndoors() {
		const room = this.currentRoom;
		if (room) return room.properties?.indoor !== false;
		const location = String(this.gameMap?.location ?? this.parent?.gameMap?.location ?? '').toLowerCase();
		return location === 'inside' || location === 'interior' || location === 'house';
	},

	resolveDepthOffsetValue(depthLine, depthOffset, colliderBottom, sizeHeight) {
		const resolveExplicitDepth = value => {
			if (value === null || value === undefined ||
				(typeof value === 'string' && value.trim() === '')) {
				return null;
			}

			const numericValue = Number(value);
			return Number.isFinite(numericValue) ? numericValue : null;
		};

		const resolvedDepthLine = resolveExplicitDepth(depthLine);
		if (resolvedDepthLine !== null) {
			return resolvedDepthLine;
		}

		const resolvedDepthOffset = resolveExplicitDepth(depthOffset);
		if (resolvedDepthOffset !== null) {
			return resolvedDepthOffset;
		}

		const resolvedColliderBottom = Number(colliderBottom);
		if (Number.isFinite(resolvedColliderBottom) && resolvedColliderBottom > 0) {
			return resolvedColliderBottom;
		}

		return Number.isFinite(sizeHeight) ? sizeHeight : 0;
	},

	getSortYValue(y, fallbackY, depthOffset) {
		const resolvedY = Number.isFinite(y) ? y : fallbackY;
		const resolvedDepthOffset = Number.isFinite(depthOffset) ? depthOffset : 0;
		return resolvedY + resolvedDepthOffset;
	},

	writeSortY(element, sortY) {
		if (!element || !Number.isFinite(sortY)) return;
		element.dataset.sortY = `${Math.round(sortY * 100) / 100}`;
	},

	// Returns the map's shared AStarPathfinder. All pathfinding goes through
	// one instance per map — no per-entity copies needed.
	get pathfinder() {
		return this.parent?.gameMap?.gridSystem?.pathfinder ?? null;
	},

	normalizeRegionId(regionId = 'collider') {
		switch (String(regionId || '').trim().toLowerCase()) {
			case 'interaction': return 'interaction';
			case 'select': return 'select';
			case 'hit': return 'hit';
			case 'pickup': return 'pickup';
			case 'collider':
			default: return 'collider';
		}
	},

	getHitRect() {
		return this.getRegionRect('hit') || this.getRegionRect('collider');
	},

	getCenterPoint(regionId = 'collider') {
		const rect = this.getRegionRect?.(regionId) || this.getRegionRect?.('collider');
		if (rect) {
			return {
				x: rect.left + (rect.width / 2),
				y: rect.top + (rect.height / 2)
			};
		}
		return {
			x: this.posX + (this.collider?.offsetX ?? 0) + ((this.collider?.width ?? this.size?.width ?? 0) / 2),
			y: this.posY + (this.collider?.offsetY ?? 0) + ((this.collider?.height ?? this.size?.height ?? 0) / 2)
		};
	},

	// Returns true when this entity is allowed to auto-open the given collider.
	// axis: 'x' | 'y' | undefined — when provided, doors must be perpendicular to the movement axis.
	// E/W doors (tall, vertical) block X movement; N/S doors (wide, horizontal) block Y movement.
	canAutoOpenCollider(collider, axis) {
		const dbg = window._doorDebug;
		if (!collider || !this.capabilities?.canOpenDoors) {
			if (dbg && collider && ['DOOR','GATE'].includes(collider.type)) Utility.logDebug(`[canAutoOpenCollider] FAIL: canOpenDoors=${this.capabilities?.canOpenDoors}`);
			return false;
		}
		if (!['DOOR', 'GATE'].includes(collider.type)) return false;
		if (typeof collider.open !== 'function' || collider.isOpen) {
			if (dbg) Utility.logDebug(`[canAutoOpenCollider] FAIL: isOpen=${collider.isOpen} hasOpen=${typeof collider.open === 'function'}`);
			return false;
		}

		if (axis && collider.facingDirection) {
			const verticalDoors = ['E', 'W']; // tall doors — block X movement
			const horizontalDoors = ['N', 'S']; // wide doors — block Y movement
			if (axis === 'x' && !verticalDoors.includes(collider.facingDirection)) {
				if (dbg) Utility.logDebug(`[canAutoOpenCollider] FAIL: axis=x but door facing=${collider.facingDirection} (need E/W)`);
				return false;
			}
			if (axis === 'y' && !horizontalDoors.includes(collider.facingDirection)) {
				if (dbg) Utility.logDebug(`[canAutoOpenCollider] FAIL: axis=y but door facing=${collider.facingDirection} (need N/S)`);
				return false;
			}
		}

		if (typeof collider.canAutoOpenFor === 'function' && !collider.canAutoOpenFor(this, axis)) {
			return false;
		}

		return true;
	},

	// Tries to open the collider. Returns true if the door was opened.
	tryOpenCollider(collider, axis) {
		if (!this.canAutoOpenCollider(collider, axis)) return false;
		return collider.open({
			triggeredBy: 'auto',
			actor: this,
			axis
		}) !== false;
	},

	// Euclidean distance to another entity (posX / posY duck-typed).
	getDistanceTo(other) {
		if (!other) return Infinity;
		return Math.hypot(this.posX - other.posX, this.posY - other.posY);
	},

	// Euclidean distance to an arbitrary world point.
	getDistanceToPoint(x, y) {
		return Math.hypot(this.posX - x, this.posY - y);
	}

};

function applyEntityMixin(cls) {
	Object.defineProperties(cls.prototype, Object.getOwnPropertyDescriptors(EntityMethods));
}
;
/* -- js/Engine/WorldRegistry.js -- */
// WorldRegistry — the single index of every simulated thing in the world.
//
// STATUS: IMPLEMENTED (Fable, 2026-07-05 — the T3 kernel). WorldQuery (T4)
// builds on this. API is frozen; changes need Fable sign-off.
//
// ── Contract ────────────────────────────────────────────────────────────────
// Registered entities must satisfy the entity duck-type
// (docs/ARCHITECTURE_AUDIT_2026-07.md §Proposed Entity Model): id, type,
// posX/posY/posZ, size, getRegionRect(), getCenterPoint(), capabilities.
//
// Identity: raw ids are NOT globally unique across kinds (Tiled object ids and
// myte roster ids can both be "3"), so the registry key is
// entity.worldId = "<kind>:<id>", stamped on add(). byId() takes a worldId.
// Serialization of cross-entity references always uses worldId.
//
// Ownership & lifetime:
//   - ONE registry per ContainerManager (spans map transitions; Mytes persist
//     across maps, map objects re-register on every map load).
//   - add() callers: GameMap.add (kind 'object'), GameMap.addDroppedItem
//     (kind 'item'), ContainerManager myte construction (kind 'myte').
//   - remove() callers: GameMap.removeInactiveObjects sweep, dropped-item
//     collection, GameMap.dispose, ContainerManager.dispose. remove() is the
//     future despawn hook for EntityRelationships.clearAllFor and
//     AttachmentSystem.detachAllChildren (T5/T6).
//
// Grid interplay (implemented in GameMapGrid):
//   - contributesToWalkability === false → indexed in cells for spatial
//     queries, but never affects cell walkability or collider lists
//     (mytes, dropped items).
//   - excludeFromCulling === true → never enters GridSystem.activeObjects
//     (mytes: ContainerManager owns their update/visibility).

const WORLD_ENTITY_KINDS = Object.freeze({
	MYTE: 'myte',
	OBJECT: 'object',
	ITEM: 'item'
});

class WorldRegistry {
	static _nextAnonId = 1;
	static _nextScopeId = 1;

	constructor(container) {
		this.container = container;
		this._byId = new Map();     // worldId → entity
		this._byKind = new Map();   // kind → Set<entity>
	}

	getScopedOwnerId(entity, kind) {
		if (!entity || kind === WORLD_ENTITY_KINDS.MYTE) {
			return null;
		}

		const owner = entity.gameMap || entity.parent || null;
		if (!owner) {
			return null;
		}

		if (!owner._worldRegistryScopeId) {
			owner._worldRegistryScopeId = `scope_${WorldRegistry._nextScopeId++}`;
		}

		return owner._worldRegistryScopeId;
	}

	// Registers an entity under the given kind. Stamps entity.kind and
	// entity.worldId. Assigns a fallback id when the entity has none.
	// Throws on unknown kind or duplicate registration.
	add(entity, kind) {
		if (!entity) {
			throw new Error('[WorldRegistry] add() requires an entity');
		}
		if (!Object.values(WORLD_ENTITY_KINDS).includes(kind)) {
			throw new Error(`[WorldRegistry] Unknown entity kind "${kind}"`);
		}

		if (entity.id === undefined || entity.id === null || entity.id === '') {
			entity.id = `anon_${WorldRegistry._nextAnonId++}`;
		}

		const scopedOwnerId = this.getScopedOwnerId(entity, kind);
		const typeToken = kind === WORLD_ENTITY_KINDS.OBJECT && entity.type
			? `:${String(entity.type).toLowerCase()}`
			: '';
		const baseWorldId = scopedOwnerId
			? `${kind}:${scopedOwnerId}${typeToken}:${entity.id}`
			: `${kind}:${entity.id}`;
		let worldId = baseWorldId;
		let existing = this._byId.get(worldId);
		if (existing === entity) {
			throw new Error(`[WorldRegistry] Entity already registered: ${worldId}`);
		}
		if (existing) {
			if (kind === WORLD_ENTITY_KINDS.MYTE) {
				throw new Error(`[WorldRegistry] Duplicate world id: ${worldId}`);
			}

			let suffix = 2;
			while (this._byId.has(worldId)) {
				worldId = `${baseWorldId}:${suffix++}`;
			}
		}

		entity.kind = kind;
		entity.worldId = worldId;
		this._byId.set(worldId, entity);

		let kindSet = this._byKind.get(kind);
		if (!kindSet) {
			kindSet = new Set();
			this._byKind.set(kind, kindSet);
		}
		kindSet.add(entity);
		return entity;
	}

	// Removes an entity. Idempotent — unknown/already-removed entities are a
	// no-op. THE despawn path: clears the entity's attachments and relationships
	// so no other code path has to remember to.
	remove(entity) {
		if (!entity?.worldId) return false;
		if (this._byId.get(entity.worldId) !== entity) return false;

		this.container?.attachments?.detachAllChildren?.(entity);
		this.container?.attachments?.detach?.(entity);
		this.container?.relationships?.clearAllFor?.(entity);

		this._byId.delete(entity.worldId);
		this._byKind.get(entity.kind)?.delete(entity);
		return true;
	}

	byId(worldId) {
		if (worldId === undefined || worldId === null) return null;
		return this._byId.get(String(worldId)) ?? null;
	}

	// Iterable over entities, optionally one kind. Mutation during iteration
	// is NOT supported — snapshot ([...registry.all()]) before adding/removing.
	all(kind = null) {
		if (kind === null) return this._byId.values();
		return this._byKind.get(kind) ?? [];
	}

	count(kind = null) {
		if (kind === null) return this._byId.size;
		return this._byKind.get(kind)?.size ?? 0;
	}

	// For the invariant sweeper: per-kind counts must match the population
	// arrays (container.mytes / gameMap.objects / gameMap.droppedItems).
	stats() {
		const byKind = {};
		for (const kind of Object.values(WORLD_ENTITY_KINDS)) {
			byKind[kind] = this.count(kind);
		}
		return { total: this._byId.size, ...byKind };
	}
}
;
/* -- js/Engine/WorldQuery.js -- */
// WorldQuery — the single spatial/capability query facade.
//
// STATUS: IMPLEMENTED (Fable, 2026-07-05). Call-site migration is task T4 —
// nothing calls this yet, so behavior parity is verified per call site as each
// caller flips over. API frozen; changes need Fable sign-off.
//
// Replaces (T4): MyteAI.getNearbyObjects/getNearbyMytes/getNearbyDroppedItems,
// NpcMapObject._detectTargets, Myte._syncCompanionBuffs scan,
// Myte.getRandomNearbyObject, BirdMapObject.findTarget's broad phase.
//
// ── Semantics (pinned to preserve current behavior exactly) ────────────────
// Broad phase: mytes + objects come from gridSystem.getObjectsInArea over a
// square padded by (radius + WorldQuery.BROAD_PHASE_PAD) — the pad preserves
// MyteAI's collider-inset guarantee. Dropped items are NOT grid-indexed
// (deliberate — the list is tiny) and come from the registry. Virtual tile
// colliders returned by getObjectsInArea have no worldId and are dropped.
//
// Narrow phase distance, measureFrom:
//   'pos'    (default) — hypot(entity.posX - x, entity.posY - y), matching
//              Entity.getDistanceTo / today's MyteAI predicates.
//   'center' — sprite center (posX + size.width/2), matching
//              GameMap.getObjectsInRadius.
//
// Liveness (activeOnly, default true) mirrors today's per-kind predicates:
//   myte   → isActive === true          (MyteAI.getNearbyMytes)
//   item   → active && !collected       (MyteAI.getNearbyDroppedItems)
//   object → active truthy              (MyteAI.getNearbyObjects)

class WorldQuery {
	static BROAD_PHASE_PAD = 64;

	constructor(registry, gameMap) {
		this.registry = registry;
		this.gameMap = gameMap;
	}

	_normalizeKinds(kind) {
		if (kind === null || kind === undefined) {
			return Object.values(WORLD_ENTITY_KINDS);
		}
		return Array.isArray(kind) ? kind : [kind];
	}

	_isAlive(entity) {
		switch (entity.kind) {
			case WORLD_ENTITY_KINDS.MYTE: return entity.isActive === true;
			case WORLD_ENTITY_KINDS.ITEM: return !!entity.active && !entity.collected;
			default: return !!entity.active;
		}
	}

	_distanceTo(entity, x, y, measureFrom) {
		if (measureFrom === 'center') {
			const cx = entity.posX + ((entity.size?.width ?? 0) / 2);
			const cy = entity.posY + ((entity.size?.height ?? 0) / 2);
			return Math.hypot(cx - x, cy - y);
		}
		return Math.hypot(entity.posX - x, entity.posY - y);
	}

	// Broad-phase candidates for the requested kinds. Deduped Set.
	_collectCandidates(x, y, radius, kinds) {
		const candidates = new Set();
		const gridSystem = this.gameMap?.gridSystem;
		const wantsGridKinds = kinds.includes(WORLD_ENTITY_KINDS.MYTE) ||
			kinds.includes(WORLD_ENTITY_KINDS.OBJECT);

		if (gridSystem && wantsGridKinds) {
			const pad = radius + WorldQuery.BROAD_PHASE_PAD;
			for (const entity of gridSystem.getObjectsInArea(x - pad, y - pad, pad * 2, pad * 2)) {
				// Virtual tile colliders and anything unregistered have no worldId.
				if (entity.worldId) candidates.add(entity);
			}
		} else if (!gridSystem && this.registry && wantsGridKinds) {
			for (const kind of kinds) {
				if (kind === WORLD_ENTITY_KINDS.ITEM) continue;
				for (const entity of this.registry.all(kind)) candidates.add(entity);
			}
		}

		if (kinds.includes(WORLD_ENTITY_KINDS.ITEM) && this.registry) {
			for (const entity of this.registry.all(WORLD_ENTITY_KINDS.ITEM)) candidates.add(entity);
		}

		return candidates;
	}

	findNearby(options = {}) {
		const {
			x, y, radius,
			kind = null,
			capability = null,
			filter = null,
			exclude = null,
			measureFrom = 'pos',
			activeOnly = true,
			excludeDragging = true,
			finitePositionsOnly = true,
			sortByDistance = true,
			limit = Infinity
		} = options;

		if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(radius)) {
			throw new Error('[WorldQuery] findNearby requires finite x, y, radius');
		}

		const kinds = this._normalizeKinds(kind);
		const excludeSet = exclude
			? new Set(Array.isArray(exclude) ? exclude : [exclude])
			: null;

		const results = [];
		for (const entity of this._collectCandidates(x, y, radius, kinds)) {
			if (!kinds.includes(entity.kind)) continue;
			if (excludeSet?.has(entity)) continue;
			if (activeOnly && !this._isAlive(entity)) continue;
			if (excludeDragging && entity.isDragging === true) continue;
			if (finitePositionsOnly &&
				(!Number.isFinite(entity.posX) || !Number.isFinite(entity.posY))) continue;
			if (capability && !entity.capabilities?.[capability]) continue;

			const distance = this._distanceTo(entity, x, y, measureFrom);
			if (distance > radius) continue;
			if (filter && !filter(entity)) continue;

			results.push({ entity, distance });
		}

		if (sortByDistance) {
			results.sort((a, b) => a.distance - b.distance);
		}

		const capped = limit === Infinity ? results : results.slice(0, limit);
		return capped.map(entry => entry.entity);
	}

	nearest(options = {}) {
		const matches = this.findNearby({
			...options,
			sortByDistance: true,
			limit: 1
		});
		return matches[0] ?? null;
	}

	// Registry-wide capability lookup (no spatial bound). Use sparingly; if a
	// call site turns hot, add a capability index inside WorldRegistry rather
	// than caching at the caller.
	findByCapability(capability, kind = null) {
		if (!capability || !this.registry) return [];
		const results = [];
		for (const k of this._normalizeKinds(kind)) {
			for (const entity of this.registry.all(k)) {
				if (entity.capabilities?.[capability] && this._isAlive(entity)) {
					results.push(entity);
				}
			}
		}
		return results;
	}
}
;
/* -- js/Engine/EntityRelationships.js -- */
// EntityRelationships — central registry of semantic entity↔entity relations.
//
// STATUS: IMPLEMENTED (Fable, 2026-07-05). Call-site migration is task T5 —
// nothing sets relations yet; the carry/aggro/rest façades flip over in T5.
// API frozen; changes need Fable sign-off.
//
// ── Design (per audit §Entity Relationship Model) ──────────────────────────
// - Relations live HERE, not as fields on entities. Runtime uses direct object
//   references; worldIds appear only in serialize().
// - set() writes forward and inverse atomically; clear() removes both.
// - Exclusivity: setting an exclusive relation auto-clears the previous pair
//   (callers that want to forbid replacement check has() first, as today's
//   canPerform guards already do). inverseExclusive guards the other side
//   (an item can have only one carrier).
// - Spatial payload (sockets, offsets) lives in AttachmentSystem; attach()/
//   detach() write the matching semantic relation here. 'occupying'/'carrying'/
//   'riding' flow through AttachmentSystem; 'targeting'/'following' are set
//   directly.
// - WorldRegistry.remove() calls clearAllFor() — the single despawn path.
//   Each cleared pair emits 'relationship:cleared' on the core EventManager so
//   dependent actions can interrupt.
//
// DECISION (audit Q7): pendingPickup stays a plain flag; it is NOT a relation.

const RELATION_TYPES = Object.freeze({
	carrying:  Object.freeze({ inverse: 'carriedBy',  exclusive: true, inverseExclusive: true  }),
	occupying: Object.freeze({ inverse: 'occupiedBy', exclusive: false, inverseExclusive: true  }),
	riding:    Object.freeze({ inverse: 'riddenBy',   exclusive: false, inverseExclusive: true  }),
	targeting: Object.freeze({ inverse: 'targetedBy', exclusive: true, inverseExclusive: false }),
	following: Object.freeze({ inverse: 'followedBy', exclusive: true, inverseExclusive: false })
});

// name → { forwardType, isForward } for both directions.
const RELATION_NAMES = (() => {
	const names = {};
	for (const [type, def] of Object.entries(RELATION_TYPES)) {
		names[type] = { forwardType: type, isForward: true };
		names[def.inverse] = { forwardType: type, isForward: false };
	}
	return Object.freeze(names);
})();

class EntityRelationships {
	constructor(registry) {
		this.registry = registry;
		// forwardType → Map<entityA, Set<entityB>> (forward direction only;
		// inverse lookups walk the same maps via _inverseLookup).
		this._forward = new Map();
		for (const type of Object.keys(RELATION_TYPES)) {
			this._forward.set(type, new Map());
		}
	}

	_emitCleared(type, a, b) {
		this.registry?.container?.core?.eventManager?.emit?.(EVENTS.RELATIONSHIP_CLEARED, {
			type, a, b
		});
	}

	// Establishes type between a → b (and inverse b → a).
	set(type, a, b) {
		const def = RELATION_TYPES[type];
		if (!def) throw new Error(`[EntityRelationships] Unknown relation type "${type}"`);
		if (!a || !b) throw new Error(`[EntityRelationships] set(${type}) requires two entities`);
		if (a === b) throw new Error(`[EntityRelationships] set(${type}) — entity cannot relate to itself`);

		const typeMap = this._forward.get(type);

		if (def.exclusive) {
			// a may hold only one forward relation of this type.
			const existing = typeMap.get(a);
			if (existing) {
				for (const prev of [...existing]) {
					if (prev !== b) this.clear(type, a, prev);
				}
			}
		}

		if (def.inverseExclusive) {
			// b may be the target of only one relation of this type.
			for (const [holder, targets] of typeMap) {
				if (holder !== a && targets.has(b)) {
					this.clear(type, holder, b);
				}
			}
		}

		let targets = typeMap.get(a);
		if (!targets) {
			targets = new Set();
			typeMap.set(a, targets);
		}
		targets.add(b);
		return true;
	}

	// Clears a → b (and its inverse). With b omitted, clears all of a's
	// forward relations of this type. Idempotent; returns count cleared.
	clear(type, a, b = null) {
		const def = RELATION_TYPES[type];
		if (!def) throw new Error(`[EntityRelationships] Unknown relation type "${type}"`);
		const typeMap = this._forward.get(type);
		const targets = typeMap.get(a);
		if (!targets) return 0;

		let cleared = 0;
		const toClear = b ? (targets.has(b) ? [b] : []) : [...targets];
		for (const target of toClear) {
			targets.delete(target);
			cleared++;
			this._emitCleared(type, a, target);
		}
		if (targets.size === 0) typeMap.delete(a);
		return cleared;
	}

	_inverseLookup(forwardType, entity) {
		const holders = [];
		for (const [holder, targets] of this._forward.get(forwardType)) {
			if (targets.has(entity)) holders.push(holder);
		}
		return holders;
	}

	// Lookup by relation name — forward ('carrying') or inverse ('carriedBy').
	// Exclusive directions return entity|null; multi-valued return an array.
	get(name, entity) {
		const resolved = RELATION_NAMES[name];
		if (!resolved) throw new Error(`[EntityRelationships] Unknown relation name "${name}"`);
		const def = RELATION_TYPES[resolved.forwardType];

		if (resolved.isForward) {
			const targets = this._forward.get(resolved.forwardType).get(entity);
			if (def.exclusive) {
				return targets?.values().next().value ?? null;
			}
			return targets ? [...targets] : [];
		}

		const holders = this._inverseLookup(resolved.forwardType, entity);
		if (def.inverseExclusive) {
			return holders[0] ?? null;
		}
		return holders;
	}

	has(name, a, b = null) {
		const value = this.get(name, a);
		if (value === null) return false;
		if (Array.isArray(value)) {
			return b ? value.includes(b) : value.length > 0;
		}
		return b ? value === b : true;
	}

	// THE despawn hook — called from WorldRegistry.remove(). Clears every
	// relation (both directions) involving the entity.
	clearAllFor(entity) {
		if (!entity) return 0;
		let cleared = 0;
		for (const type of Object.keys(RELATION_TYPES)) {
			cleared += this.clear(type, entity);
			for (const holder of this._inverseLookup(type, entity)) {
				cleared += this.clear(type, holder, entity);
			}
		}
		return cleared;
	}

	// Forward relations only (inverses are re-derived), by worldId.
	serialize() {
		const pairs = [];
		for (const [type, typeMap] of this._forward) {
			for (const [a, targets] of typeMap) {
				for (const b of targets) {
					if (a.worldId && b.worldId) {
						pairs.push({ type, a: a.worldId, b: b.worldId });
					}
				}
			}
		}
		return pairs;
	}

	// Resolves worldIds via the registry; silently drops pairs whose entities
	// no longer exist.
	restore(pairs = []) {
		let restored = 0;
		for (const pair of pairs) {
			const a = this.registry?.byId(pair.a);
			const b = this.registry?.byId(pair.b);
			if (a && b && RELATION_TYPES[pair.type]) {
				this.set(pair.type, a, b);
				restored++;
			}
		}
		return restored;
	}

	// All relations involving an entity, for the invariant sweeper and the
	// selection sidebar.
	debugRelationsFor(entity) {
		const rows = [];
		for (const type of Object.keys(RELATION_TYPES)) {
			const targets = this._forward.get(type).get(entity);
			if (targets) {
				for (const b of targets) rows.push({ type, direction: 'forward', other: b });
			}
			for (const holder of this._inverseLookup(type, entity)) {
				rows.push({ type, direction: 'inverse', other: holder });
			}
		}
		return rows;
	}
}
;
/* -- js/Engine/AttachmentSystem.js -- */
// SocketSet + AttachmentSystem — spatial parent/child: sockets, surfaces,
// occupancy, and the single per-frame transform-propagation pass.
//
// STATUS: INTERFACE SKELETON (audit task T6, docs/ARCHITECTURE_AUDIT_2026-07.md
// §Attachment and Socket Architecture; socket data schema in docs/SOCKET_SCHEMA.md).
// The API below is FROZEN — implement the bodies, do not change signatures or
// semantics without Fable sign-off. Methods throw until implemented.
//
// DECISIONS (closing audit soft points):
//   - ActionSlotLedger is ABSORBED: SocketSet replaces it entirely (occupancy
//     keys by socketId, not actionId). No compat layer — pre-release, data
//     migrates destructively (T6b).
//   - Update order: ContainerManager updates mytes → GameMap.update runs
//     object updates → AttachmentSystem.update() runs LAST, before
//     MapRenderer.flush. Attached children therefore never lag their parent.
//   - Actions choreograph (approach/settle/dismount, stat effects); the
//     attachment owns world position while attached. Bob and similar idle
//     motion write attachment.localOffset, never entity.posX/posY directly.

// One furniture/mount/wall face's socket collection. Constructed by
// MapObject (and later Myte, for hold/accessory anchors) from the entity's
// `sockets` config (see docs/SOCKET_SCHEMA.md for the data format).
class SocketSet {
	constructor(owner, socketsConfig) {
		this.owner = owner;
		this.socketsConfig = socketsConfig && typeof socketsConfig === 'object' ? socketsConfig : {};
		this._occupants = new Map();
		this._surfaceIntervals = new Map();
	}

	_getFacing() {
		const configuredFacing = this.owner?.getConfig?.('facingDirection', null);
		return configuredFacing ?? this.owner?.facingDirection ?? this.owner?.direction ?? 'S';
	}

	_matchesCandidate(socket, candidate) {
		const accepts = Array.isArray(socket.accepts) && socket.accepts.length > 0
			? socket.accepts
			: ['myte'];
		const kind = candidate?.kind ?? (candidate?.constructor?.name === 'Myte' ? 'myte' : 'object');
		return accepts.includes(kind) || accepts.some(capability => candidate?.capabilities?.[capability]);
	}

	_claim(socketId, candidate) {
		if (!this.hasCapacity(socketId, candidate)) return false;
		let occupants = this._occupants.get(socketId);
		if (!occupants) {
			occupants = new Set();
			this._occupants.set(socketId, occupants);
		}
		occupants.add(candidate);
		return true;
	}

	_release(socketId, candidate) {
		const occupants = this._occupants.get(socketId);
		if (!occupants || !occupants.delete(candidate)) return false;
		if (occupants.size === 0) this._occupants.delete(socketId);
		this.releaseSurfaceInterval(socketId, candidate);
		return true;
	}

	reserveSurfaceInterval(socketId, candidate, u0, u1) {
		const socket = this.get(socketId);
		if (!socket || socket.kind !== 'surface') return false;
		const start = Math.min(Number(u0), Number(u1));
		const end = Math.max(Number(u0), Number(u1));
		if (!Number.isFinite(start) || !Number.isFinite(end) || start === end) return false;
		let intervals = this._surfaceIntervals.get(socketId);
		if (!intervals) {
			intervals = [];
			this._surfaceIntervals.set(socketId, intervals);
		}
		if (intervals.some(entry => entry.candidate !== candidate && start < entry.u1 && end > entry.u0)) {
			return false;
		}
		for (let index = intervals.length - 1; index >= 0; index--) {
			if (intervals[index].candidate === candidate) intervals.splice(index, 1);
		}
		intervals.push({ candidate, u0: start, u1: end });
		return true;
	}

	releaseSurfaceInterval(socketId, candidate) {
		const intervals = this._surfaceIntervals.get(socketId);
		if (!intervals) return false;
		const next = intervals.filter(entry => entry.candidate !== candidate);
		if (next.length === intervals.length) return false;
		if (next.length > 0) this._surfaceIntervals.set(socketId, next);
		else this._surfaceIntervals.delete(socketId);
		return true;
	}

	surfaceIntervals(socketId) {
		return (this._surfaceIntervals.get(socketId) || []).map(entry => ({
			candidate: entry.candidate,
			u0: entry.u0,
			u1: entry.u1
		}));
	}

	// Resolved socket definition for the owner's CURRENT facing (byFacing
	// applied), or null. Resolved shape:
	// { id, kind: 'seat'|'sleep'|'hold'|'surface'|'mount',
	//   position|area, facing, accepts, capacity, approach, zBias, collision }
	get(socketId) {
		const socket = this.socketsConfig?.[socketId];
		if (!socket || typeof socket !== 'object') return null;

		const override = socket.byFacing?.[this._getFacing()];
		if (override === null) return null;
		const resolved = Utility.deepMerge({}, socket);
		delete resolved.byFacing;
		if (override && typeof override === 'object') {
			Object.assign(resolved, Utility.deepMerge(resolved, override));
		}
		return {
			id: socketId,
			kind: resolved.kind,
			accepts: ['myte'],
			capacity: 1,
			zBias: 2,
			collision: 'disabled',
			...resolved
		};
	}

	// All resolved sockets, optionally filtered by kind.
	list(kind = null) {
		return Object.keys(this.socketsConfig)
			.map(socketId => this.get(socketId))
			.filter(socket => socket && (!kind || socket.kind === kind));
	}

	// World-space anchor for a socket. For 'surface' kind, surfacePoint {u,v}
	// (0..1 within the area) is required. Accounts for owner position, size,
	// and facing. Pure — no side effects; safe for AI scoring and approach
	// planning (replaces SurfaceSlotAction.getSurfaceRestPosition math).
	resolveWorldPosition(socketId, surfacePoint = null) {
		const socket = this.get(socketId);
		if (!socket) return null;

		const ownerX = Number(this.owner?.posX);
		const ownerY = Number(this.owner?.posY);
		const width = Number(this.owner?.size?.width);
		const height = Number(this.owner?.size?.height);
		if (![ownerX, ownerY, width, height].every(Number.isFinite)) return null;

		if (socket.kind === 'surface') {
			const point = surfacePoint && typeof surfacePoint === 'object' ? surfacePoint : null;
			if (!point || !Array.isArray(socket.area?.xFactor) || !Array.isArray(socket.area?.yFactor)) return null;
			const rawU = Number(point.u);
			const surfaceLength = Math.max(1, Number(socket.surfaceLength) || width);
			const u = socket.uMode === 'distance'
				? Utility.clamp(rawU / surfaceLength, 0, 1)
				: Utility.clamp(rawU, 0, 1);
			const v = Utility.clamp(Number(point.v), 0, 1);
			const [minX, maxX] = socket.area.xFactor;
			const [minY, maxY] = socket.area.yFactor;
			return {
				x: ownerX + width * (Number(minX) + ((Number(maxX) - Number(minX)) * u)),
				y: ownerY + height * (Number(minY) + ((Number(maxY) - Number(minY)) * v))
			};
		}

		const position = socket.position;
		if (!position || typeof position !== 'object') return null;
		return {
			x: ownerX + width * (Number(position.xFactor) || 0) + (Number(position.offsetX) || 0),
			y: ownerY + height * (Number(position.yFactor) || 0) + (Number(position.offsetY) || 0)
		};
	}

	// Occupancy (replaces ActionSlotLedger). Occupants are entities.
	occupantsOf(socketId) {
		return [...(this._occupants.get(socketId) ?? [])];
	}

	hasCapacity(socketId, candidate = null) {
		const socket = this.get(socketId);
		if (!socket || (candidate && !this._matchesCandidate(socket, candidate))) return false;
		const occupants = this._occupants.get(socketId) ?? new Set();
		return occupants.has(candidate) || occupants.size < Math.max(1, Number(socket.capacity) || 1);
	}

	// Sockets with room for `candidate` (accepts + capacity checks), for AI
	// slot selection (replaces getAvailableActionSlots).
	availableFor(candidate, kind = null) {
		return this.list(kind).filter(socket =>
			this._matchesCandidate(socket, candidate) && this.hasCapacity(socket.id, candidate)
		);
	}
}

class AttachmentSystem {
	constructor(registry, relationships) {
		this.registry = registry;
		this.relationships = relationships;
		this._byChild = new Map();
		this._childrenByParent = new Map();
	}

	_getRelationType(socket) {
		if (socket.kind === 'hold') return 'carrying';
		if (socket.kind === 'mount') return 'riding';
		return 'occupying';
	}

	_setChildPosition(child, x, y) {
		if (!Number.isFinite(x) || !Number.isFinite(y)) return;
		const previousX = child.posX;
		const previousY = child.posY;
		child.setPosition?.(x, y);
		child.setTarget?.(x, y);
		child.setSpritePosition?.(x, y);
		if (child.renderState) {
			child.renderState.posX = x;
			child.renderState.posY = y;
			child.renderState.dirty = true;
		}
		if (Math.abs((previousX ?? x) - x) >= 1 || Math.abs((previousY ?? y) - y) >= 1) {
			child.gameMap?.gridSystem?.updateObjectPosition?.(child, previousX, previousY);
		}
	}

	_getParentSortY(parent) {
		if (!parent) return 0;
		const sortY = parent.getSortY?.();
		if (Number.isFinite(sortY)) return sortY;
		return Number(parent?.posY) || 0;
	}

	_getParentRenderZIndex(parent) {
		if (!parent) return 0;

		const directZIndex = parent.getRenderZIndex?.();
		if (Number.isFinite(directZIndex)) return directZIndex;

		const rendererZIndex = parent.renderer?.getZIndex?.(parent.posY);
		if (Number.isFinite(rendererZIndex)) return rendererZIndex;

		const mapDepthZIndex = parent.parent?.getDepthZIndex?.(
			this._getParentSortY(parent),
			parent.getDepthPriority?.() ?? 0
		);
		return Number.isFinite(mapDepthZIndex) ? mapDepthZIndex : 0;
	}

	_wouldCreateCycle(parent, child) {
		for (let current = parent; current; current = this._byChild.get(current)?.parent) {
			if (current === child) return true;
		}
		return false;
	}

	// Attaches child to parent at a socket. Claims capacity, writes the
	// semantic relation ('occupying' for seat/sleep/surface, 'carrying' for
	// hold, 'riding' for mount), stores the child's pre-attach position,
	// applies the socket's collision mode, and rejects cycles (walks the
	// parent chain). Returns the Attachment record or null on refusal.
	//
	// options: { surfacePoint {u,v}, localOffset {x,y}, inheritFacing, mode:
	//   'rigid'|'anim', zBias, collision: 'disabled'|'inherit' } — all
	//   defaulted from the socket definition.
	attach(parent, child, socketId, options = {}) {
		if (!parent || !child || parent === child || this._wouldCreateCycle(parent, child)) return null;
		const sockets = parent.sockets;
		const socket = sockets?.get?.(socketId);
		if (!socket || !sockets.hasCapacity(socketId, child)) return null;

		const existing = this.getAttachment(child);
		if (existing && (existing.parent !== parent || existing.socketId !== socketId)) {
			this.detach(child);
		}
		if (!sockets._claim(socketId, child)) return null;
		if (socket.kind === 'surface') {
			const surfaceLength = Math.max(1, Number(socket.surfaceLength) || Number(parent.size?.width) || 1);
			const center = Number(options.surfacePoint?.u ?? 0.5);
			const centerDistance = socket.uMode === 'distance' ? center : center * surfaceLength;
			const halfWidth = Math.max(0.5, Number(options.surfaceWidth ?? child.size?.width ?? 1) / 2);
			const interval = options.surfaceInterval || {
				u0: centerDistance - halfWidth,
				u1: centerDistance + halfWidth
			};
			if (!sockets.reserveSurfaceInterval(socketId, child, interval.u0, interval.u1)) {
				sockets._release(socketId, child);
				return null;
			}
		}

		const attachment = existing ?? {
			parent,
			child,
			socketId,
			previousPosition: { x: child.posX, y: child.posY },
			previousCollision: child.checkForCollisions
		};
		Object.assign(attachment, {
			parent,
			child,
			socketId,
			surfacePoint: options.surfacePoint ?? attachment.surfacePoint ?? null,
			localOffset: { x: 0, y: 0, ...(options.localOffset ?? attachment.localOffset) },
			inheritFacing: options.inheritFacing ?? attachment.inheritFacing ?? true,
			mode: options.mode ?? attachment.mode ?? 'rigid',
			zBias: options.zBias ?? socket.zBias ?? 2,
			collision: options.collision ?? socket.collision ?? 'disabled',
			relationType: this._getRelationType(socket)
		});

		if (attachment.collision === 'disabled') child.checkForCollisions = false;
		this._byChild.set(child, attachment);
		let children = this._childrenByParent.get(parent);
		if (!children) {
			children = new Set();
			this._childrenByParent.set(parent, children);
		}
		children.add(child);
		this.relationships?.set?.(attachment.relationType, parent, child);
		// An attached child derives room membership from its spatial parent. Remove
		// its stale independent room record so reverse occupant sets cannot claim it
		// is still in the room where it was picked up or seated.
		child.getRegionManager?.()?.forget?.(child, ['room']);
		return attachment;
	}

	// Detaches child: releases capacity, clears the semantic relation,
	// restores collision, places the child at options.exitPosition (or its
	// socket's exit, or nearest valid cell), optionally seeds child velocity
	// from the parent's last frame delta (options.inheritVelocity).
	detach(child, options = {}) {
		const attachment = this._byChild.get(child);
		if (!attachment) return false;

		attachment.parent?.sockets?._release?.(attachment.socketId, child);
		this.relationships?.clear?.(attachment.relationType, attachment.parent, child);
		if (attachment.collision === 'disabled') {
			child.checkForCollisions = attachment.previousCollision;
		}

		this._byChild.delete(child);
		const siblings = this._childrenByParent.get(attachment.parent);
		siblings?.delete(child);
		if (siblings?.size === 0) this._childrenByParent.delete(attachment.parent);

		const exit = options.exitPosition;
		if (exit && Number.isFinite(exit.x) && Number.isFinite(exit.y)) {
			this._setChildPosition(child, exit.x, exit.y);
		}
		// Detachment restores independent room membership immediately; callers do
		// not have to wait for the next cell crossing or simulation frame.
		child.getRegionManager?.()?.updateMembership?.(child, {
			layers: ['room'],
			force: true
		});
		child._attachmentRenderZIndex = null;
		return true;
	}

	// THE parent-despawn hook — called from WorldRegistry.remove(parent).
	// Detaches every child to the nearest valid position. One code path for
	// audit scenario 11.
	detachAllChildren(parent, options = {}) {
		let detached = 0;
		for (const child of [...(this._childrenByParent.get(parent) ?? [])]) {
			if (this.detach(child, options)) detached++;
		}
		return detached;
	}

	getAttachment(child) {
		return this._byChild.get(child) ?? null;
	}

	childrenOf(parent) {
		return [...(this._childrenByParent.get(parent) ?? [])];
	}

	// The single per-frame pass (see update-order decision above): for every
	// attachment, child world pos = parent pos + socket anchor (+ localOffset);
	// facing applied if inheritFacing; renderState marked dirty; child sortY =
	// parent sortY + zBias. 'anim'-mode attachments (settle/dismount tweens
	// driven by actions) are skipped here — the action owns the tween, then
	// flips mode to 'rigid'.
	update() {
		for (const attachment of this._byChild.values()) {
			if (attachment.mode !== 'rigid') continue;
			const socket = attachment.parent?.sockets?.get?.(attachment.socketId);
			const anchor = attachment.parent?.sockets?.resolveWorldPosition?.(
				attachment.socketId,
				attachment.surfacePoint
			);
			if (!socket || !anchor) continue;
			const childWidth = Number(attachment.child?.size?.width) || 0;
			const childHeight = Number(attachment.child?.size?.height) || 0;
			const isHeldItem = socket.kind === 'hold' && attachment.child?.kind !== 'myte';
			const childAnchorX = 0.5;
			const childAnchorY = isHeldItem ? 1 : 0.5;
			this._setChildPosition(
				attachment.child,
				anchor.x - (childWidth * childAnchorX) + (attachment.localOffset?.x ?? 0),
				anchor.y - (childHeight * childAnchorY) + (attachment.localOffset?.y ?? 0)
			);
			if (attachment.inheritFacing && socket.facing) {
				attachment.child.setDirection?.(socket.facing);
			}
			const parentSortY = this._getParentSortY(attachment.parent);
			const parentZ = this._getParentRenderZIndex(attachment.parent);
			attachment.child._attachmentRenderZIndex = parentZ + attachment.zBias;
			if (attachment.child.renderState) {
				attachment.child.renderState.sortY = parentSortY + attachment.zBias;
				attachment.child.renderState.zIndex = attachment.child._attachmentRenderZIndex;
				attachment.child.renderState.dirty = true;
			}
			attachment.child.renderer?.setZIndex?.(attachment.child.posY);
		}
	}

	// [{ parentId, childId, socketId, surfacePoint, localOffset }] — restore()
	// resolves ids, re-claims capacity, drops unresolvable records placing the
	// child at its own saved position.
	serialize() {
		return [...this._byChild.values()]
			.filter(attachment => attachment.parent?.worldId && attachment.child?.worldId)
			.map(attachment => ({
				parentId: attachment.parent.worldId,
				childId: attachment.child.worldId,
				socketId: attachment.socketId,
				surfacePoint: attachment.surfacePoint,
				localOffset: { ...attachment.localOffset }
			}));
	}

	restore(records) {
		let restored = 0;
		for (const record of records ?? []) {
			const parent = this.registry?.byId?.(record.parentId);
			const child = this.registry?.byId?.(record.childId);
			if (parent && child && this.attach(parent, child, record.socketId, record)) restored++;
		}
		return restored;
	}
}
