// Show affection toward another Myte (one-sided emote, no sync needed)
class ShowAffectionAction extends MyteAction {
    static metadata = { id: 'show_affection' };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, { ...ShowAffectionAction.metadata.defaultOptions, duration: ShowAffectionAction.metadata.defaultDuration, ...options });
    }

    start() {
        super.start();
        this.myte.queue.addExpression(this.expressionType, this.expressionDuration, this.expressionRepeat);
    }

    update(deltaTime = 0) {
        this.currentDuration -= deltaTime;
        return this.currentDuration <= 0;
    }
}

class PairedSocialAction extends PositionableAction {
    static receiverActionId = null;

    static canPerform(selected, active) {
        return selected instanceof Myte && selected !== active &&
            !active?.queue?.isCarrying?.() && !selected.queue?.isCarrying?.() &&
            !selected.queue?.isBeingCarried?.() && (selected.queue?.count?.() ?? 0) === 0;
    }

    static getRequiredOptions(selected) {
        return { target: selected };
    }

    constructor(myte, options = {}) {
        super(myte, { ...options, duration: options.duration ?? this.constructor.metadata.defaultDuration });
        this.sync = options.sync ?? new ActionSync();
        this.partnerSide = options.partnerSide ?? null;
        this.phase = 'approach';
        this._signalled = false;
        this._refused = false;
    }

    start() {
        super.start();
        if (!(this.target instanceof Myte)) {
            this._refuse();
            return;
        }

        if (!this.partnerSide && !this.constructor.isReceiver && !PairedSocialAction.canPerform(this.target, this.myte)) {
            this._refuse();
            return;
        }

        this.partnerSide ??= this._resolveApproachSide();
        this._setApproachTarget();

        if (!this.constructor.isReceiver) {
            this.target.queue.addToFront(this.constructor.receiverActionId, {
                target: this.myte,
                sync: this.sync,
                partnerSide: this._oppositeSide(this.partnerSide),
                expressionType: this.expressionType,
                expressionDuration: this.expressionDuration,
                expressionRepeat: this.expressionRepeat,
                duration: this.duration
            });
        }
    }

    _refuse() {
        this._refused = true;
        this._interrupted = true;
        this.myte.queue.addExpression('cry', 400, 1);
    }

    _resolveApproachSide() {
        const targetRect = this.getTargetRect(this.target, 'interaction');
        const myteRect = this.myte.getRect();
        return this.getClosestSideHorizontal(targetRect, myteRect) ?? 'left';
    }

    _oppositeSide(side) {
        return ({ left: 'right', right: 'left', top: 'bottom', bottom: 'top' })[side] ?? 'right';
    }

    _setApproachTarget() {
        const targetRect = this.getTargetRect(this.target, 'interaction');
        const myteRect = this.myte.getRect();
        if (!targetRect || !myteRect) return;
        const point = this.calculatePosition(myteRect, targetRect, this.partnerSide, {
            gap: this.socialGap ?? 8,
            align: 'center'
        });
        this.myte.setTarget(point.x, point.y);
    }

    _faceTarget() {
        const dx = this.target.posX - this.myte.posX;
        const dy = this.target.posY - this.myte.posY;
        this.myte.setDirection(Math.abs(dx) > Math.abs(dy)
            ? (dx > 0 ? DIRECTION.EAST : DIRECTION.WEST)
            : (dy > 0 ? DIRECTION.SOUTH : DIRECTION.NORTH));
    }

    _signalReady() {
        if (this._signalled) return;
        this._signalled = true;
        this._faceTarget();
        this.sync.signal(this);
        this.sync.onReady(() => {
            this.phase = 'perform';
            this.currentDuration = this.duration;
            this.myte.queue.addExpression(this.expressionType, this.expressionDuration, this.expressionRepeat);
        });
    }

    update(deltaTime = 0) {
        if (this._refused || !this.target?.isActive) return true;
        if (this.phase === 'approach') {
            if (!this.myte.isAtTarget()) {
                this.myte.moveTowardsTarget();
                return false;
            }
            this._signalReady();
            return false;
        }
        if (this.phase !== 'perform') return false;
        this.currentDuration -= deltaTime;
        return this.currentDuration <= 0;
    }
}

class PairedSocialReceiveAction extends PairedSocialAction {
    static isReceiver = true;
    static canPerform() { return false; }
}

class GreetAction extends PairedSocialAction {
    static metadata = { id: 'greet' };
    static receiverActionId = 'greet_receive';
}

class GreetReceiveAction extends PairedSocialReceiveAction {
    static metadata = { id: 'greet_receive', hideFromQueue: true };
}

class KissAction extends PairedSocialAction {
    static metadata = { id: 'kiss' };
    static receiverActionId = 'kiss_receive';
}

class KissReceiveAction extends PairedSocialReceiveAction {
    static metadata = { id: 'kiss_receive', hideFromQueue: true };
}

class HighFiveAction extends PairedSocialAction {
    static metadata = { id: 'high_five' };
    static receiverActionId = 'high_five_receive';
}

class HighFiveReceiveAction extends PairedSocialReceiveAction {
    static metadata = { id: 'high_five_receive', hideFromQueue: true };
}

// Stand near another Myte and loosely follow their position.
class WatchAction extends PositionableAction {
    static metadata = { id: 'watch' };

    static canPerform(selected, active) {
        return selected instanceof Myte && selected !== active && !active?.queue.isCarrying();
    }

    static getRequiredOptions(selected, active) {
        return { target: selected };
    }

    constructor(myte, options) {
        super(myte, { ...WatchAction.metadata.defaultOptions, duration: WatchAction.metadata.defaultDuration, ...options });
    }

    start() {
        super.start();
    }

    update(deltaTime = 0) {
        if (!this.target) return true;

        const targetRect = this.getTargetRect(this.target, 'interaction');
        const myteRect = this.myte.getRect();
        const horizontal = this.getClosestSideHorizontal(targetRect, myteRect);
        const watchPos = this.calculatePosition(myteRect, targetRect, horizontal, { gap: -5, align: 'bottom-edge' });

        this.myte.setTarget(watchPos.x, watchPos.y);
        this.myte.moveTowardsTarget();

        this.currentDuration -= deltaTime;
        return this.currentDuration <= 0;
    }
}

// Play tag - chaser/runner role switches on catch.
class PlayTagAction extends PositionableAction {
    static metadata = { id: 'play_tag' };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, { ...PlayTagAction.metadata.defaultOptions, duration: PlayTagAction.metadata.defaultDuration, ...options });
    }

    update(deltaTime = 0) {
        const target = this.target;
        if (!target) return true;

        const dx = target.posX - this.myte.posX;
        const dy = target.posY - this.myte.posY;
        const distance = Math.hypot(dx, dy);

        if (this.isIt) {
            this.myte.setTarget(target.posX, target.posY);
            this.myte.moveTowardsTarget();

            if (distance < this.catchDistance) {
                this.isIt = false;
                target.queue.add('play_tag', {
                    target: this.myte,
                    isIt: true,
                    duration: this.currentDuration
                });
                return true;
            }
        } else {
            const angle = Math.atan2(dy, dx) + Math.PI;
            this.myte.setTarget(
                this.myte.posX + Math.cos(angle) * this.runDistance,
                this.myte.posY + Math.sin(angle) * this.runDistance
            );
            this.myte.moveTowardsTarget();
        }

        this.currentDuration -= deltaTime;
        return this.currentDuration <= 0;
    }
}

// Chase another Myte — move toward them at speed; complete when close enough
class ChaseAction extends PositionableAction {
    static metadata = { id: 'chase' };

    static canPerform(selected, active) {
        return selected instanceof Myte && selected !== active && !active?.queue.isCarrying();
    }

    static getRequiredOptions(selected) {
        return { target: selected };
    }

    constructor(myte, options) {
        super(myte, { ...ChaseAction.metadata.defaultOptions, duration: ChaseAction.metadata.defaultDuration, ...options });
    }

    update(deltaTime = 0) {
        if (!this.target) return true;

        const dist = Math.hypot(this.target.posX - this.myte.posX, this.target.posY - this.myte.posY);

        if (dist < this.catchDistance) {
            this.myte.queue.addExpression('excited', 400, 2);
            return true;
        }

        this.myte.setTarget(this.target.posX, this.target.posY);
        this.myte.moveTowardsTarget();
        this.currentDuration -= deltaTime;
        return this.currentDuration <= 0;
    }
}

// Approach any target and show an expression on arrival
class EmoteAtAction extends GoToObjectAction {
    static metadata = { id: 'emote_at' };

    static canPerform(selected, active) {
        return active && selected instanceof Myte && selected !== active && !active?.queue.isCarrying();
    }

    static getRequiredOptions(selected) {
        return { target: selected };
    }

    complete() {
        this.faceTarget();
        super.complete();
        this.myte.queue.addExpression(this.expressionType, this.expressionDuration, this.expressionRepeat);
        this.myte.queue.addIdle(600);
    }
}

// Approach another Myte and transfer the held item to them
class GiveItemAction extends GoToObjectAction {
    static metadata = { id: 'give_item' };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               active?.queue?.isCarryingItem?.();
    }

    static getRequiredOptions(selected) {
        return { target: selected };
    }

    complete() {
        this.faceTarget();
        super.complete();
        const item = this.myte.queue.getHeldItem?.();
        if (!item || item.carrier !== this.myte) return;

        // Drop item at the recipient's feet and let them pick it up
        item.drop?.(0, 0);
        item.setPosition?.(this.target.posX, this.target.posY);
        item.setSpritePosition?.(this.target.posX, this.target.posY);
        this.target.queue.add('pickup_item', { target: item });
        this.myte.queue.addExpression('heart', 300, 1);
    }
}

const FetchStates = {
    PICKUP: 'pickup',
    THROW: 'throw',
    CHASE: 'chase',
    RETURN: 'return'
};

// Play fetch with a throwable object.
class PlayFetchAction extends MyteAction {
    static metadata = { id: 'play_fetch' };

    static canPerform(selected, active) {
        return active &&
               selected instanceof MapObject &&
               selected.type?.toUpperCase?.() === 'BALL' &&
               !active.queue.isCarrying();
    }

    static getRequiredOptions(selected) {
        return { target: selected, throwable: selected };
    }

    constructor(myte, options) {
        super(myte, { ...PlayFetchAction.metadata.defaultOptions, ...options });
        this.throwPosition = null;
        this.throwTarget = null;
        this.throwProgress = 0;
        this.completedTrips = 0;
        // Fetch walks the map like any other errand: a chest between the myte
        // and the ball has to be walked around, not into. Raw steering could
        // only push into it, so every leg drives a nested A* move instead.
        this.moveAction = null;
        this._moveDestination = null;
    }

    start() {
        super.start();
        this.myte.queue.addExpression(this.expressionType, this.expressionDuration);
    }

    update() {
        switch (this.fetchState) {
            case FetchStates.PICKUP: return this._handlePickup();
            case FetchStates.THROW: return this._handleThrow();
            case FetchStates.CHASE: return this._handleChase();
            case FetchStates.RETURN: return this._handleReturn();
            default: return true;
        }
    }

    interrupt() {
        super.interrupt();
        this._stopMoving();
    }

    complete() {
        this._stopMoving();
        return super.complete();
    }

    cancel() {
        this._stopMoving();
        super.cancel?.();
    }

    // ── Pathed movement ──────────────────────────────────────────────────────

    _stopMoving() {
        this.moveAction?.cancel?.();
        this.moveAction = null;
        this._moveDestination = null;
    }

    // Drives a nested A* move towards (x, y), replanning when the destination
    // drifts (the ball rolls, the myte is carried elsewhere). Returns true once
    // the path is exhausted — arrived, or as close as the map allows.
    _moveTowards(x, y, replanDistance = 24) {
        const drifted = this._moveDestination &&
            Math.hypot(this._moveDestination.x - x, this._moveDestination.y - y) > replanDistance;

        if (!this.moveAction || drifted) {
            this.moveAction?.cancel?.();
            this.moveAction = new AStarMoveAction(this.myte, {
                target: { x, y },
                pathfindingOptions: { exactEndMode: 'if-reachable' }
            });
            this.moveAction.start();
            this._moveDestination = { x, y };
        }

        if (this.moveAction.update()) {
            this.moveAction = null;
            this._moveDestination = null;
            return true;
        }

        return false;
    }

    // Picks a throw destination the myte can actually run to. A random point can
    // land inside a wall or on the far side of one, which used to strand the
    // ball; candidates are tested against the pathfinder and the throw shortens
    // until one lands somewhere reachable.
    _pickThrowTarget(from) {
        const pathfinder = this.myte?.pathfinder;
        const attempts = 8;

        for (let attempt = 0; attempt < attempts; attempt++) {
            const angle = Math.random() * Math.PI * 2;
            // Later attempts throw shorter, so a myte boxed into a small room
            // still finds somewhere to put the ball.
            const reach = this.maxThrowDistance * (1 - (attempt / attempts));
            const candidate = {
                x: from.x + Math.cos(angle) * reach,
                y: from.y + Math.sin(angle) * reach
            };

            if (!pathfinder) return candidate;

            const path = pathfinder.findPath(
                this.myte, from.x, from.y, candidate.x, candidate.y,
                { ...this.myte.pathfindingOptions, exactEndMode: 'if-reachable' }
            );
            if (!path?.length) continue;

            const end = path[path.length - 1];
            if (Math.hypot(end.x - candidate.x, end.y - candidate.y) <= this.catchDistance * 2) {
                return candidate;
            }
        }

        // Nothing reachable — drop the ball where the myte is standing rather
        // than throwing it somewhere it can never be retrieved from.
        return { x: from.x, y: from.y };
    }

    _handlePickup() {
        if (!this.throwable) return true;

        const dx = this.throwable.posX - this.myte.posX;
        const dy = this.throwable.posY - this.myte.posY;

        if (Math.hypot(dx, dy) > this.pickupDistance) {
            // Path exhausted without reaching the ball means it is walled off;
            // ending the action lets the queue move on instead of shoving.
            if (this._moveTowards(this.throwable.posX, this.throwable.posY, this.pickupDistance)) {
                return Math.hypot(
                    this.throwable.posX - this.myte.posX,
                    this.throwable.posY - this.myte.posY
                ) > this.pickupDistance;
            }
            return false;
        }

        this._stopMoving();
        this.throwPosition = { x: this.myte.posX, y: this.myte.posY };
        this.throwTarget = this._pickThrowTarget(this.throwPosition);
        this.throwProgress = 0;
        this.fetchState = FetchStates.THROW;
        return false;
    }

    _handleThrow() {
        this.throwProgress += this.throwStrength / 100;

        if (this.throwProgress >= 1) {
            this.fetchState = FetchStates.CHASE;
            return false;
        }

        const t = this.throwProgress;
        const x = this.throwPosition.x + (this.throwTarget.x - this.throwPosition.x) * t;
        const y = this.throwPosition.y + (this.throwTarget.y - this.throwPosition.y) * t
                - Math.sin(t * Math.PI) * this.arcHeight;

        if (this.throwable) {
            this.throwable.setPosition(x, y);
            this.throwable.setSpritePosition(x, y);
        }

        return false;
    }

    _handleChase() {
        if (!this.throwable) return true;

        const arrived = this._moveTowards(this.throwTarget.x, this.throwTarget.y, this.catchDistance);
        const reached = Math.hypot(
            this.myte.posX - this.throwTarget.x,
            this.myte.posY - this.throwTarget.y
        ) < this.catchDistance;

        if (reached || arrived) {
            this._stopMoving();
            this.myte.queue.addExpression('excited', 500);
            this.fetchState = FetchStates.RETURN;
        }

        return false;
    }

    _handleReturn() {
        const arrived = this._moveTowards(this.throwPosition.x, this.throwPosition.y, this.catchDistance);

        if (this.throwable) {
            this.throwable.setPosition(this.myte.posX, this.myte.posY - 20);
            this.throwable.setSpritePosition(this.myte.posX, this.myte.posY - 20);
        }

        if (arrived || this.myte.isAtTarget()) {
            this._stopMoving();
            this.completedTrips++;

            if (this.throwable) {
                this.throwable.setPosition(this.throwPosition.x, this.throwPosition.y);
                this.throwable.setSpritePosition(this.throwPosition.x, this.throwPosition.y);
            }

            if (this.completedTrips >= this.roundTrips) {
                return true;
            }

            this.throwProgress = 0;
            this.throwTarget = this._pickThrowTarget(this.throwPosition);
            this.fetchState = FetchStates.THROW;
        }

        return false;
    }
}
;
/* -- js/Myte/Queue/Actions/StateActions.js -- */
// Perform a happy dance - moves in small steps around a base position.
class DanceAction extends MyteAction {
    static metadata = { id: 'dance' };

    static canPerform(selected, active) {
        return selected === active && !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, {
            ...DanceAction.metadata.defaultOptions,
            duration: options.duration || DanceAction.metadata.defaultDuration,
            ...options
        });
        this.danceSteps = [
            { x: 0, y: -20 },
            { x: 20, y: 0 },
            { x: 0, y: 20 },
            { x: -20, y: 0 }
        ];
        this.currentStep = 0;
        this.stepTimer = this.stepDuration;
    }

    start() {
        super.start();
        this.baseX = this.myte.posX;
        this.baseY = this.myte.posY;
    }

    update() {
        this.stepTimer -= 16;

        if (this.stepTimer <= 0) {
            this.currentStep = (this.currentStep + 1) % this.danceSteps.length;
            this.stepTimer = this.stepDuration;
            const step = this.danceSteps[this.currentStep];
            this.myte.setTarget(this.baseX + step.x, this.baseY + step.y);
        }

        this.myte.moveTowardsTarget();
        this.currentDuration--;
        return this.currentDuration <= 0;
    }
}

// Deep sleep with bobbing animation.
class SleepAction extends MyteAction {
    static metadata = { id: 'sleep' };

    static canPerform(selected, active) {
        return selected === active && !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, {
            ...SleepAction.metadata.defaultOptions,
            duration: options.duration || SleepAction.metadata.defaultDuration,
            ...options
        });
        this.bobPhase = 0;
        this.zTimer = this.zInterval;
        this.startY = myte.posY;
    }

    start() {
        super.start();
        this.myte.queue.addExpression('sleep', 1000);
    }

    update() {
        this.bobPhase += 0.05;
        const newY = this.startY + Math.sin(this.bobPhase) * this.bobHeight;
        this.myte.setPosition(null, newY);
        this.myte.setSpritePosition(null, newY);

        this.zTimer -= 16;
        if (this.zTimer <= 0) {
            this.zTimer = this.zInterval;
        }

        this.currentDuration--;
        return this.currentDuration <= 0;
    }
}

// Quick nap with gentle floating.
class SimpleSleepAction extends MyteAction {
    static metadata = { id: 'simple_sleep' };

    static canPerform(selected, active) {
        return selected === active && !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, {
            ...SimpleSleepAction.metadata.defaultOptions,
            duration: options.duration || SimpleSleepAction.metadata.defaultDuration,
            ...options
        });
        this._zPosition = 0;
        this._zSpeed = this.zSpeed;
    }

    start() {
        super.start();
        this.baseY = this.myte.posY;
        this.myte.queue.addExpression('sleep', 500, 10);
    }

    update() {
        this._zPosition += this._zSpeed;
        if (this._zPosition > 1 || this._zPosition < 0) {
            this._zSpeed = -this._zSpeed;
        }

        this.myte.setPosition(null, this.baseY - (Math.sin(this._zPosition * Math.PI) * 10));
        this.currentDuration--;
        return this.currentDuration <= 0;
    }
}

// Spin in place by cycling through directions.
class SpinAction extends MyteAction {
    static metadata = { id: 'spin' };

    static canPerform(selected, active) {
        return selected === active && !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, {
            ...SpinAction.metadata.defaultOptions,
            duration: options.duration || SpinAction.metadata.defaultDuration,
            ...options
        });
        this.directions = [DIRECTION.NORTH, DIRECTION.EAST, DIRECTION.SOUTH, DIRECTION.WEST];
        this.dirIndex = 0;
        this.frameTimer = this.frameDelay;
    }

    start() {
        super.start();
    }

update() {
    const progress = 1 - (this.currentDuration / this.duration);

    // Exponential acceleration/deceleration
    // Adjust these to control the curve feel
    const accelExponent = 2.5;
    const decelExponent = 2.0;

    let speedCurve;

    if (progress < 0.5) {
        // Accelerate
        const t = progress / 0.5;
        speedCurve = Math.pow(t, accelExponent);
    } else {
        // Decelerate
        const t = (progress - 0.5) / 0.5;
        speedCurve = 1 - Math.pow(t, decelExponent);
    }

    // Speed control
    // Smaller delay = faster spinning
    const maxDelay = 12; // slowest speed
    const minDelay = 4;  // fastest speed

    const currentFrameDelay =
        maxDelay - ((maxDelay - minDelay) * speedCurve);

    this.frameTimer--;

    if (this.frameTimer <= 0) {
        this.dirIndex = (this.dirIndex + 1) % this.directions.length;

        this.frameTimer = currentFrameDelay;

        this.myte.setDirection(this.directions[this.dirIndex]);
    }

    this.currentDuration--;
    return this.currentDuration <= 0;
}
}
;
/* -- js/Myte/Queue/Actions/CarryActions.js -- */
function getCarryOffset() {
    return SiteConfig.myte.carryOffset ?? 45;
}

function setCarryRelation(carrier, target) {
    carrier?.container?.relationships?.set?.('carrying', carrier, target);
}

function clearCarryRelation(carrier, target = null) {
    const relationships = carrier?.container?.relationships;
    if (!relationships) return;

    if (target) {
        relationships.clear('carrying', carrier, target);
        return;
    }

    relationships.clear('carrying', carrier);
}

// Pickup animation — lifts target Myte toward the carrier over a fixed duration
class CarryPickupAction extends MyteAction {
    static metadata = { id: 'carry_pickup' };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               !selected.queue.isBeingCarried() &&
               !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, options);
        this.startPosition = { x: this.target.posX, y: this.target.posY };
    }

    start() {
        super.start();
        setCarryRelation(this.myte, this.target);
    }

    update(deltaTime = 0) {
        if (this.currentDuration === -1) {
            this.currentDuration = this.duration;
        }

        this.currentDuration = Math.max(0, this.currentDuration - deltaTime);
        const progress      = 1 - (this.currentDuration / this.duration);
        const easedProgress = 1 - Math.pow(1 - progress, 3);
        const carryOffset = getCarryOffset();

        const currentPos = {
            x: this.startPosition.x + (this.myte.posX - this.startPosition.x) * easedProgress,
            y: this.startPosition.y + ((this.myte.posY - carryOffset) - this.startPosition.y) * easedProgress
        };

        this.target.setPosition(currentPos.x, currentPos.y);
        this.target.setSpritePosition(currentPos.x, currentPos.y);

        if (this.currentDuration <= 0) {
            this.myte.queue.add('carry', { target: this.target, duration: -1 });
            this.target.queue.interrupt('being_carried', { carrierMyte: this.myte, duration: -1 });
        }

        return this.currentDuration <= 0;
    }

    interrupt() {
        super.interrupt();
        clearCarryRelation(this.myte, this.target);
    }
}

// Carry — the carrier follows the mouse while keeping the target overhead
class CarryAction extends MyteAction {
    static metadata = { id: 'carry' };

    static canPerform(selected, active) {
        return active?.queue.isCarryingMyte?.();
    }

	start() {
		super.start();
		this._attachment = this.myte.container?.attachments?.attach?.(
			this.myte,
			this.target,
			'carry.myte'
		) ?? null;
		if (!this._attachment) {
			setCarryRelation(this.myte, this.target);
		}
	}

	interrupt() {
		super.interrupt();
		if (this._attachment) {
			this.myte.container?.attachments?.detach?.(this.target);
			this._attachment = null;
		} else {
			clearCarryRelation(this.myte, this.target);
		}
	}

	update() {
        this.myte.updateTargetToFollowMouse();
        this.myte.moveTowardsTarget();

        return false;
    }
}

// Being carried — passive state on the carried Myte
class BeingCarriedAction extends MyteAction {
    static metadata = { id: 'being_carried', hideFromQueue: true };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               !selected.queue.isBeingCarried() &&
               !active?.queue.isCarrying();
    }

    update() {
        return false;
    }
}

// Putdown animation — lowers the carried Myte to the ground
class CarryPutdownAction extends MyteAction {
    static metadata = { id: 'carry_putdown' };

    static canPerform(selected, active) {
        return active?.queue.isCarryingMyte?.();
    }

    constructor(myte, options) {
        super(myte, options);
        this.startPosition = { x: this.target.posX, y: this.target.posY };
    }

    start() {
        super.start();
        setCarryRelation(this.myte, this.target);
    }

    update(deltaTime = 0) {
        if (this.currentDuration === -1) {
            this.currentDuration = this.duration;
        }

        this.currentDuration = Math.max(0, this.currentDuration - deltaTime);
        const progress      = 1 - (this.currentDuration / this.duration);
        const easedProgress = 1 - Math.pow(1 - progress, 3);
        const carryOffset = getCarryOffset();

        const currentPos = {
            x: this.startPosition.x + (this.myte.posX - this.startPosition.x) * easedProgress,
            y: this.startPosition.y + ((this.myte.posY + carryOffset) - this.startPosition.y) * easedProgress
        };

        this.target.setPosition(currentPos.x, currentPos.y);
        this.target.setSpritePosition(currentPos.x, currentPos.y);
        if (this.currentDuration <= 0) {
            clearCarryRelation(this.myte, this.target);
            this.target.queue.clear();
        }

        return this.currentDuration <= 0;
    }

    interrupt() {
        super.interrupt();
        clearCarryRelation(this.myte, this.target);
    }
}

class PickupItemAction extends MyteAction {
    static metadata = { id: 'pickup_item' };

    static canPerform(selected, active) {
        return active &&
               selected instanceof MapObject &&
               selected.getConfig?.('canPickUp', false) &&
               !selected.isPickedUp &&
               !active.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, options);
        this.target = options.target ?? null;
        this.approachAction = null;
        this.maxReplans = 4;
        this.replanCount = 0;
        this.lastTargetPosition = null;
        this.lastReplanAt = 0;
        this.startedAt = 0;
        this.lastDistance = Infinity;
        this.lastProgressAt = 0;
        this.maxPickupDurationMs = 8000;
        this.maxStallDurationMs = 2000;
    }

    start() {
        super.start();
        this.startedAt = SimClock.now();
        this.lastProgressAt = this.startedAt;
        this.lastDistance = this._getDistanceToTarget();
        if (this.target) {
            this.target.pendingPickup = true;
            this.lastTargetPosition = { x: this.target.posX, y: this.target.posY };
        }
    }

    update() {
        if (!this.target?.active) return true;
        if (this.target.isPickedUp && this.target.carrier !== this.myte) return true;
        if (!this.target.canBePickedUpBy?.(this.myte)) {
            this.target.pendingPickup = false;
            return true;
        }

        const now = SimClock.now();
        const distance = this._getDistanceToTarget();
        if (distance + 4 < this.lastDistance) {
            this.lastDistance = distance;
            this.lastProgressAt = now;
        } else if (Number.isFinite(distance)) {
            this.lastDistance = Math.min(this.lastDistance, distance);
        }

        if (this.target.isInPickupRange?.(this.myte)) {
            this.target.pendingPickup = false;
            if (this.target.pickup?.(this.myte)) {
                this.myte.queue.add('hold_item', { target: this.target });
            }
            return true;
        }

        if (now - this.startedAt >= this.maxPickupDurationMs) {
            this.target.pendingPickup = false;
            return true;
        }

        if (now - this.lastProgressAt >= this.maxStallDurationMs) {
            if (this.replanCount >= this.maxReplans) {
                this.target.pendingPickup = false;
                return true;
            }
            this._createApproachAction();
            this.lastProgressAt = now;
        }

        if (!this.approachAction || this._shouldReplan()) {
            if (this.replanCount >= this.maxReplans) {
                this.target.pendingPickup = false;
                return true;
            }

            this._createApproachAction();
        }

        if (!this.approachAction) {
            this.target.pendingPickup = false;
            return true;
        }

        const approachComplete = this.approachAction.update();
        if (approachComplete && !this.target.isInPickupRange?.(this.myte)) {
            this._createApproachAction();
        }

        return false;
    }

    interrupt() {
        super.interrupt();
        if (this.target?.carrier !== this.myte) {
            this.target.pendingPickup = false;
        }
    }

    complete() {
        super.complete();
        if (this.target?.carrier !== this.myte) {
            this.target.pendingPickup = false;
        }
    }

    _createApproachAction() {
        this.approachAction = new GoToObjectAction(this.myte, {
            target: this.target,
            approachConfig: 'center'
        });
        this.approachAction.start();
        this.replanCount++;
        this.lastReplanAt = SimClock.now();
        this.lastTargetPosition = this.target ? { x: this.target.posX, y: this.target.posY } : null;
    }

    _shouldReplan() {
        if (!this.target || !this.lastTargetPosition) {
            return false;
        }

        const now = SimClock.now();
        if (now - this.lastReplanAt < 150) {
            return false;
        }

        const movedDistance = Math.hypot(
            this.target.posX - this.lastTargetPosition.x,
            this.target.posY - this.lastTargetPosition.y
        );

        return movedDistance >= 16;
    }

    _getDistanceToTarget() {
        if (!this.target) {
            return Infinity;
        }

        const targetCenter = this.target.getPickupTargetPoint?.(this.myte) ||
            this.target.getCenterPoint?.() || {
            x: this.target.posX + ((this.target.size?.width ?? 0) / 2),
            y: this.target.posY + ((this.target.size?.height ?? 0) / 2)
        };
        const myteCenter = this.myte.getCenterPoint?.('collider') || {
            x: this.myte.posX + (this.myte.collider?.offsetX ?? 0) + ((this.myte.collider?.width ?? this.myte.size.width) / 2),
            y: this.myte.posY + (this.myte.collider?.offsetY ?? 0) + ((this.myte.collider?.height ?? this.myte.size.height) / 2)
        };

        return Math.hypot(targetCenter.x - myteCenter.x, targetCenter.y - myteCenter.y);
    }
}

class HoldItemAction extends MyteAction {
    static metadata = { id: 'hold_item' };

    static canPerform() {
        return false;
    }

    constructor(myte, options) {
        super(myte, options);
        this.target = options.target ?? null;
    }

    start() {
        super.start();
        if (this.target && this.target.carrier !== this.myte && this.target.isInPickupRange?.(this.myte)) {
            this.target.pickup?.(this.myte);
        }
    }

    update() {
        if (!this.target || this.target.carrier !== this.myte) return true;
        this.myte.updateTargetToFollowMouse();
        this.myte.moveTowardsTarget();
        return false;
    }

    interrupt() {
        super.interrupt();
        this._dropItem();
    }

    complete() {
        super.complete();
        this._dropItem();
    }

    _dropItem() {
        if (!this.target || this.target.carrier !== this.myte) return;
        const dx = this.myte.targetX - this.myte.posX;
        const dy = this.myte.targetY - this.myte.posY;
        const dist = Math.hypot(dx, dy);
        const spd = 3;
        this.target.drop?.(
            dist > 1 ? (dx / dist) * spd : 0,
            dist > 1 ? (dy / dist) * spd : 0
        );
    }
}

class DropItemAction extends MyteAction {
    static metadata = { id: 'drop_item' };

    static canPerform(selected, active) {
        const heldItem = active?.queue?.getHeldItem?.() || null;
        return !!heldItem && (selected === active || selected === heldItem);
    }

    static getRequiredOptions(selected, active) {
        return { target: active?.queue?.getHeldItem?.() || null };
    }

    start() {
        super.start();
        if (!this.target || this.target.carrier !== this.myte) {
            return;
        }

        const dx = this.myte.targetX - this.myte.posX;
        const dy = this.myte.targetY - this.myte.posY;
        const dist = Math.hypot(dx, dy);
        const spd = 3;
        this.target.drop?.(
            dist > 1 ? (dx / dist) * spd : 0,
            dist > 1 ? (dy / dist) * spd : 0
        );
    }

    update() {
        return true;
    }
}
;
/* -- js/Myte/Queue/Actions/ReactiveActions.js -- */
// Flee from a scary object or Myte
class RunAwayAction extends MyteAction {
    static metadata = { id: 'run_away' };

    static canPerform(selected, active) {
        return selected instanceof Myte &&
               selected !== active &&
               !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, { ...RunAwayAction.metadata.defaultOptions, ...options });
    }

    update() {
        const target = this.target;
        if (!target) return true;

        const dx       = target.posX - this.myte.posX;
        const dy       = target.posY - this.myte.posY;
        const distance = Math.hypot(dx, dy);

        if (distance < this.panicDistance) {
            const angle    = Math.atan2(dy, dx) + Math.PI;
            const clamped = this.myte.parent.clampEntityPosition(
                this.myte,
                this.myte.posX + Math.cos(angle) * this.runDistance,
                this.myte.posY + Math.sin(angle) * this.runDistance
            );

            this.myte.setTarget(clamped.x, clamped.y);

            if (Math.random() < 0.02) {
                this.myte.queue.addExpression('panic', 200);
            }
        }

        this.myte.moveTowardsTarget();

        if (this.duration > 0) {
            this.currentDuration--;
            return this.currentDuration <= 0;
        }

        return false;
    }
}

// Hide behind an object from something scary — occasionally peeks out.
// Not user-triggered; queued internally by AI when the Myte is scared.
// Requires options: { hideTarget: MapObject, scaryObject: MapObject|Myte }
class HideAction extends MyteAction {
    static metadata = { id: 'hide' };

    static canPerform() { return false; }

    constructor(myte, options) {
        super(myte, {
            ...HideAction.metadata.defaultOptions,
            duration: options.duration || HideAction.metadata.defaultDuration,
            ...options
        });
        this.peekTimer  = this.peekInterval;
        this.isPeeking  = false;
    }

    start() {
        super.start();
    }

    update() {
        const hideTarget   = this.hideTarget;
        const scaryObject  = this.scaryObject;
        if (!hideTarget || !scaryObject) return true;

        const dx    = hideTarget.posX - scaryObject.posX;
        const dy    = hideTarget.posY - scaryObject.posY;
        const angle = Math.atan2(dy, dx);

        this.myte.setTarget(
            hideTarget.posX + Math.cos(angle) * 30,
            hideTarget.posY + Math.sin(angle) * 30
        );
        this.myte.moveTowardsTarget();

        this.peekTimer -= 16;
        if (this.peekTimer <= 0) {
            this.isPeeking = !this.isPeeking;
            this.peekTimer = this.peekInterval;
            if (this.isPeeking) {
                this.myte.queue.addExpression('peek', 500);
            }
        }

        this.currentDuration--;
        return this.currentDuration <= 0;
    }
}

// Run away from a MapObject (animals, scary objects, etc.)
class RunFromAction extends MyteAction {
    static metadata = { id: 'run_from' };

    static canPerform(selected, active) {
        return selected instanceof MapObject &&
               selected.getConfig?.('scary', false) === true &&
               !active?.queue.isCarrying();
    }

    constructor(myte, options) {
        super(myte, { ...RunFromAction.metadata.defaultOptions, ...options });
    }

    update() {
        const target = this.target;
        if (!target) return true;

        const dx = target.posX - this.myte.posX;
        const dy = target.posY - this.myte.posY;
        const distance = Math.hypot(dx, dy);

        if (distance < this.panicDistance) {
            const angle = Math.atan2(dy, dx) + Math.PI;
            const clamped = this.myte.parent.clampEntityPosition(
                this.myte,
                this.myte.posX + Math.cos(angle) * this.runDistance,
                this.myte.posY + Math.sin(angle) * this.runDistance
            );
            this.myte.setTarget(clamped.x, clamped.y);

            if (Math.random() < 0.02) {
                this.myte.queue.addExpression('panic', 200);
            }
        }

        this.myte.moveTowardsTarget();
        this.currentDuration--;
        return this.currentDuration <= 0;
    }
}
