/* -- js/Map/GameMapLoader.js -- */
// GameMapLoader with improved error handling
class GameMapLoader {
    constructor(core) {
        this.core = core;
        this.maps = new Map();
        this.currentMap = null;
        this.mapDisplayNames = new Map();
        this.mapDisplayNamePromises = new Map();
        Utility.logDebug(`[GameMapLoader] Initialized`);
    }

    normalizeMapId(mapId) {
        return String(mapId || '').replace(/\.tmx$/i, '');
    }

    humanizeMapId(mapId) {
        const normalized = this.normalizeMapId(mapId);
        return normalized
            .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
            .replace(/[_-]+/g, ' ')
            .trim() || 'Unknown';
    }

    getCachedMapDisplayName(mapId) {
        const normalized = this.normalizeMapId(mapId);
        return this.mapDisplayNames.get(normalized) || null;
    }

    async getMapDisplayName(mapId) {
        const normalized = this.normalizeMapId(mapId);
        if (!normalized) {
            return 'Unknown';
        }

        const cached = this.getCachedMapDisplayName(normalized);
        if (cached) {
            return cached;
        }

        if (this.mapDisplayNamePromises.has(normalized)) {
            return this.mapDisplayNamePromises.get(normalized);
        }

        const promise = (async () => {
            const fallback = this.humanizeMapId(normalized);
            const paths = [
                `data/maps/${normalized}.tmx`,
                `data/spritesheets/${normalized}.tmx`,
                `assets/maps/${normalized}.tmx`,
                `${normalized}.tmx`
            ];

            for (const path of paths) {
                try {
                    const response = await fetch(path);
                    if (!response.ok) continue;

                    const xml = new DOMParser().parseFromString(await response.text(), 'text/xml');
                    const propertyNode = xml.querySelector('map > properties > property[name="displayName"]');
                    const displayName = propertyNode?.getAttribute('value')?.trim();

                    if (displayName) {
                        this.mapDisplayNames.set(normalized, displayName);
                        return displayName;
                    }

                    // The file was found but declares no map-level displayName — a
                    // content choice, not a missing file. Stop probing here: the
                    // remaining candidate paths are legacy locations that no longer
                    // exist, and walking them only emits console 404s.
                    return fallback;
                } catch (error) {
                    Utility.warnDebug(`[GameMapLoader] Could not resolve display name for ${normalized} from ${path}:`, error);
                }
            }

            return fallback;
        })();

        this.mapDisplayNamePromises.set(normalized, promise);

        try {
            const displayName = await promise;
            if (displayName) {
                this.mapDisplayNames.set(normalized, displayName);
            }
            return displayName || this.humanizeMapId(normalized);
        } finally {
            this.mapDisplayNamePromises.delete(normalized);
        }
    }

    getRandomTransitionTip() {
        const tips = [
            'You can long-press a queue badge in the top-left to cancel it.',
            'Free-roaming mytes can be tapped again to bring them back into follow mode.',
            'Dragging a myte onto its slot sends it home.',
            'Different maps can have their own zones for resting, wandering, and social behavior.',
            'Double-click the map to queue an A* move for your active myte.',
            'With no active myte, double-click a portal to open its destination.'
        ];

        return Utility.randomChoice(tips);
    }

    updateTransitionOverlay(progress, message = null) {
        const loadingManager = this.core?.loadingManager;
        if (!loadingManager) return;

        loadingManager.setManualProgress(progress);

        if (message) {
            loadingManager.setMessage(message);
        }
    }

    // Optional initialization method
    async init() {
        Utility.logDebug(`[GameMapLoader] Init called`);
        return true;
    }

    // Update the loadMap method in GameMapLoader.js to pass the isInitialLoad flag
    async loadMap(mapId, container, options = {}) {
        let map = null;
        try {
            Utility.logDebug(`[GameMapLoader] Loading map: ${mapId}`);

            // Check if container is valid
            if (!container) {
                throw new Error('Container is null or undefined');
            }

            if (!container.canvas) {
                throw new Error('Container canvas is null or undefined');
            }

            // Create map instance
            Utility.logDebug(`[GameMapLoader] Creating new GameMap instance`);
            map = new GameMap(container);

            // Initialize with TMX file, passing along initialization options
            Utility.logDebug(`[GameMapLoader] Initializing map with id: ${mapId}`);
            await map.initialize(mapId, {
                isInitialLoad: options.isInitialLoad || false,
                allowFallback: options.allowFallback === true
            });
            container.worldState?.restoreMap?.(map);

            this.currentMap = map;
            if (map?.displayName) {
                this.mapDisplayNames.set(this.normalizeMapId(mapId), map.displayName);
            }
            Utility.logDebug(`[GameMapLoader] Map ${mapId} loaded successfully`);
            return map;
        } catch (error) {
            map?.dispose?.();
            throw error;
        }
    }

    async loadMapWithTransition(mapId, container, options = {}) {
        const previousMap = this.currentMap ?? container?.gameMap ?? null;

        try {
            container?.worldState?.captureMap?.(previousMap);
            const map = await this.loadMap(mapId, container, {
                isInitialLoad: options.isInitialLoad || false,
                allowFallback: options.allowFallback === true
            });

            if (previousMap) {
                previousMap.dispose();
            }

            this.currentMap = map;
            return map;
        } catch (error) {
            this.currentMap = previousMap;
            throw error;
        }
    }
}
;
/* -- js/Map/WorldState.js -- */
class WorldState {
    static VERSION = 1;

    constructor(container, user) {
        this.container = container;
        this.user = user;
        if (user && user.worldState?.version !== WorldState.VERSION) {
            user.worldState = WorldState.emptyPayload();
        }
    }

    static emptyPayload() {
        return { version: WorldState.VERSION, maps: {} };
    }

    get payload() {
        if (!this.user.worldState || this.user.worldState.version !== WorldState.VERSION) {
            this.user.worldState = WorldState.emptyPayload();
        }
        return this.user.worldState;
    }

    captureMap(map) {
        if (!map?.id) return null;
        const objects = map.objects
            .filter(object => typeof object.serializeState === 'function')
            .map(object => ({
                id: String(object.id),
                type: object.type,
                variant: object.variant,
                posX: object.posX,
                posY: object.posY,
                state: object.serializeState()
            }));
        const droppedItems = map.droppedItems
            .filter(item => item.active && !item.collected)
            .map(item => item.serializeState());
        const walls = map.wallBuilder?.serializeState?.() ?? null;
        const terrain = map.terrainBuilder?.serializeState?.() ?? null;
        const roomCells = map.roomAssignments?.serializeState?.() ?? null;
        // Both merged onto what was already stored, never replacing it.
        // Auto-detected rooms are rebuilt from scratch on every wall change, so
        // while a removed wall has two rooms merged into one the second room
        // does not exist to be captured — pruning it here would throw its finish
        // and its name away, and undoing the wall would bring the room back
        // bare. Stale ids cost nothing: restoreRooms skips any room that is not
        // on the map.
        const rooms = map.regionManager?.all('room') || [];
        const floors = Object.assign({}, this.payload.maps[map.id]?.floors,
            Object.fromEntries(rooms
                .filter(room =>
                    (room.properties?.floorFinishId ?? null) !==
                    (room.properties?.authoredFloorFinishId ?? null)
                )
                .map(room => [room.id, room.properties?.floorFinishId ?? null])));
        const roomWalls = Object.assign({}, this.payload.maps[map.id]?.roomWalls,
            Object.fromEntries(rooms
                .filter(room => (room.properties?.wallFinishId ?? null) !==
                    (room.properties?.authoredWallFinishId ?? null))
                .map(room => [room.id, room.properties?.wallFinishId ?? null])));
        const roomEdits = Object.assign({}, this.payload.maps[map.id]?.roomEdits,
            Object.fromEntries(rooms
                .filter(room =>
                    typeof room.properties?.playerName === 'string' ||
                    typeof room.properties?.roomType === 'string' ||
                    Object.hasOwn(room.properties ?? {}, 'buildingName'))
                .map(room => [room.id, {
                    name: room.properties.playerName ?? null,
                    type: room.properties.roomType ?? null,
                    buildingName: room.properties.buildingName ?? null
                }])));
        const snapshot = { mapId: map.id, objects, droppedItems, walls, terrain, roomCells, floors, roomWalls, roomEdits, savedAt: Date.now() };
        this.payload.maps[map.id] = snapshot;
        return snapshot;
    }

    restoreMap(map) {
        const snapshot = this.payload.maps[map?.id];
        if (!snapshot) return false;

        for (const record of snapshot.objects ?? []) {
            let object = map.getObjectById(record.id);
            if (!object && record.type && record.variant) {
                object = map.addObject(record.type, record.variant, record.posX, record.posY, {
                    id: record.id,
                    _worldStateRestored: true
                });
            }
            object?.restoreState?.(record.state ?? {});
        }

        for (const data of snapshot.droppedItems ?? []) {
            const item = map.addDroppedItem(data.type, data.variant, data.posX, data.posY);
            item.restoreState(data);
        }
        // Before the walls: restoring walls kicks the room detector, and a
        // detector that runs without the player's own rooms merges them back
        // together and then hands restoreRooms ids that no longer exist.
        if (map.roomAssignments) {
            map.roomAssignments.restoreState(snapshot.roomCells ?? {}, { emit: false });
        }
        if (snapshot.walls && map.wallBuilder) {
            map.wallBuilder.restoreState(snapshot.walls);
        }
        // After the walls: painted ground writes cell walkability, and a wall
        // restored on top of it has the final say about what can be walked on.
        if (snapshot.terrain && map.terrainBuilder) {
            map.terrainBuilder.restoreState(snapshot.terrain);
        }
        this.restoreRooms(map, snapshot);
        return true;
    }

    /**
     * Re-applies everything the player has done to a room — its finish and the
     * name they gave it. Called on load and again every time the room set is
     * recomputed, since auto-detected rooms are rebuilt rather than edited.
     */
    restoreRooms(map, snapshot = this.payload.maps[map?.id]) {
        if (!snapshot || !map?.regionManager) return false;
        let restored = false;

        for (const [roomId, finishId] of Object.entries(snapshot.floors ?? {})) {
            if (!map.regionManager.get('room', roomId) || !map.floorBuilder) continue;
            map.floorBuilder.setRoomFinish(roomId, finishId);
            restored = true;
        }

        let restoredWallFinish = false;
        for (const [roomId, finishId] of Object.entries(snapshot.roomWalls ?? {})) {
            const room = map.regionManager.get('room', roomId);
            if (!room || !map.wallBuilder) continue;
            // Restoring is not repainting. setRoomWallFinish deliberately drops
            // that room's per-face accents because a new coat supersedes them;
            // running it after every topology rebuild erased accents that had
            // just travelled with a moved wall.
            room.properties = { ...room.properties, wallFinishId: finishId || null };
            restoredWallFinish = true;
            restored = true;
        }
        if (restoredWallFinish) map.wallBuilder.refreshRoomFaces();

        for (const [roomId, edit] of Object.entries(snapshot.roomEdits ?? {})) {
            const room = map.regionManager.get('room', roomId);
            if (!room) continue;
            room.properties = {
                ...room.properties,
                playerName: edit.name ?? null,
                roomType: edit.type ?? room.properties.roomType ?? null,
                buildingName: edit.buildingName ?? null,
                displayName: edit.name ?? room.properties.authoredDisplayName ?? room.properties.displayName
            };
            restored = true;
        }

        return restored;
    }
}
;
/* -- js/Map/WorldGraph.js -- */
// ─────────────────────────────────────────────────────────────────────────────
// WorldGraph — how the maps of the world connect to each other.
//
// A map file describes itself completely: its `region` and `worldX`/`worldY`
// place it on the world map, its Portal objects say what it connects to, and its
// Spawn objects say where a traveller arrives. So the graph is *discovered*
// rather than declared — start at the default map, read its portals, follow them
// into their targets, and repeat. Adding a connected map to the world is a
// matter of dropping the .tmx in and pointing a portal at it.
//
// There is no world manifest to keep in step: a map is part of the world when
// something opens onto it, which is the same rule the player experiences. A map
// nothing links to is not in the world graph — it can still be loaded directly,
// it just isn't anywhere yet. Portals are treated as bidirectional when both
// sides declare each other, and one-way otherwise.
//
// A map may also name a `parentMap`, which says the place it describes sits
// inside another one — a house standing in a yard rather than beside it. That
// is a statement about the chart, not the simulation: the two maps are still
// separate maps joined by a portal, and travel between them is the same walk it
// always was. It only changes where the world map draws them, and it makes the
// child's worldX/worldY local to its parent, so an interior gets its own little
// grid instead of having to find a free square in the overworld.
//
// Distance is hop count — the number of map transitions a traveller makes —
// which is what "is this myte too far away to walk over?" actually means.
//
// Each map's geometry comes out of the same .tmx pass: map size, portal centres,
// spawn points. That is what lets a journey be measured in the ground a
// traveller actually has to cover — the walk from the portal it came in by to
// the portal it is leaving through — rather than a flat per-map timer, and it
// works for maps that are not loaded, which is most of them.
// ─────────────────────────────────────────────────────────────────────────────

class WorldGraph {
    static nodes = new Map();
    static edges = new Map();
    static geometry = new Map();
    static preloaded = false;
    static preloadPromise = null;
    static discoverPromise = null;

    static normalizeId(mapId) {
        return String(mapId || '').replace(/\.tmx$/i, '');
    }

    static async preload() {
        if (this.preloaded) return true;
        if (this.preloadPromise) return this.preloadPromise;

        this.preloadPromise = (async () => {
            await this.discover();
            this.preloaded = true;
            return true;
        })();

        return this.preloadPromise;
    }

    // Walk out from the starting maps through every portal, reading each map file
    // once. Whatever a portal points at becomes part of the world, so long as the
    // file is really there — a typo in a targetMap leaves an edge to nowhere
    // rather than inventing a map.
    static async discover(startingMaps = [SiteConfig.world.defaultMap]) {
        if (this.discoverPromise) return this.discoverPromise;
        this.discoverPromise = this._discover(startingMaps);
        try {
            return await this.discoverPromise;
        } finally {
            this.discoverPromise = null;
        }
    }

    static async _discover(startingMaps) {
        const nodes = new Map();
        const edges = new Map();
        const geometryByMap = new Map();

        const seeds = startingMaps.map(id => this.normalizeId(id)).filter(Boolean);
        const pending = [...new Set(seeds)];
        const visited = new Set(pending);

        while (pending.length > 0) {
            // One frontier at a time, so sibling maps are read in parallel.
            const frontier = await Promise.all(
                pending.splice(0).map(async id => [id, await this._readMapGeometry(id)])
            );

            frontier.forEach(([mapId, geometry]) => {
                if (!geometry) {
                    visited.delete(mapId);
                    return;
                }

                geometryByMap.set(mapId, geometry);
                nodes.set(mapId, Object.freeze({
                    id: mapId,
                    region: geometry.region,
                    displayName: geometry.displayName,
                    layout: geometry.layout,
                    parentMap: geometry.parentMap,
                    pointsOfInterest: geometry.pointsOfInterest
                }));
                edges.set(mapId, new Map());

                geometry.portals.forEach(portal => {
                    if (visited.has(portal.targetMap)) return;
                    visited.add(portal.targetMap);
                    pending.push(portal.targetMap);
                });
            });
        }

        // Edges last: a portal only counts once the map it points at is known.
        geometryByMap.forEach((geometry, mapId) => {
            geometry.portals.forEach(portal => {
                if (!nodes.has(portal.targetMap)) return;
                edges.get(mapId).set(portal.targetMap, portal);
            });
        });

        this.nodes = nodes;
        this.edges = edges;
        this.geometry = geometryByMap;
        this._pruneParents();
    }

    // A parentMap is only worth keeping if the parent is really in the world and
    // the chain above it ends somewhere. Anything else — a typo, a parent left
    // behind by a deleted portal, two maps naming each other — drops back to a
    // root, so every map is still charted exactly once.
    static _pruneParents() {
        this.nodes.forEach((node, mapId) => {
            if (!node.parentMap) return;

            let parent = node.parentMap;
            const seen = new Set([mapId]);
            while (parent && this.nodes.has(parent) && !seen.has(parent)) {
                seen.add(parent);
                parent = this.nodes.get(parent).parentMap;
            }
            if (!parent) return;

            Utility.warnDebug(`[WorldGraph] ${mapId} cannot nest inside "${node.parentMap}"; charting it as a root.`);
            this.nodes.set(mapId, Object.freeze({ ...node, parentMap: null }));
        });
    }

    static _emptyGeometry() {
        return Object.freeze({
            width: 0,
            height: 0,
            region: 'world',
            displayName: '',
            layout: Object.freeze({ x: 0, y: 0 }),
            parentMap: null,
            portals: Object.freeze([]),
            pointsOfInterest: Object.freeze([]),
            spawns: new Map()
        });
    }

    // Everything the world needs to know about a map, straight from the map: how
    // big it is, where it sits on the world map, what it connects to and where a
    // traveller arrives. Returns null when there is no such map file, which is
    // how a portal pointing at nothing is told apart from an empty map.
    static async _readMapGeometry(mapId) {
        try {
            const response = await fetch(`${AppConfig.content.mapsPath}/${mapId}.tmx`);
            if (!response.ok) return null;

            const xml = new DOMParser().parseFromString(await response.text(), 'text/xml');
            const number = (node, attribute) => Number(node?.getAttribute(attribute)) || 0;
            const mapNode = xml.querySelector('map');
            if (!mapNode || xml.querySelector('parsererror')) return null;

            // The map's own <properties>, walked as direct children rather than
            // queried: a selector would happily reach down into an object's
            // properties instead, and `:scope` is unreliable across XML parsers.
            const mapProperties = new Map();
            [...mapNode.children]
                .filter(child => child.tagName === 'properties')
                .forEach(properties => {
                    [...properties.children].forEach(property => {
                        mapProperties.set(property.getAttribute('name'), property.getAttribute('value'));
                    });
                });
            const mapProperty = key => mapProperties.get(key) ?? null;

            const portals = [];
            const pointsOfInterest = [];
            const spawns = new Map();

            [...xml.querySelectorAll('objectgroup > object')].forEach(node => {
                const name = node.getAttribute('name');
                const property = key => node.querySelector(`property[name="${key}"]`)?.getAttribute('value') || null;
                const shopId = property('shopId');
                if (shopId) {
                    pointsOfInterest.push(Object.freeze({ type: 'shop', id: shopId }));
                }

                if (name !== 'Portal' && name !== 'Spawn') return;

                const center = Object.freeze({
                    x: number(node, 'x') + number(node, 'width') / 2,
                    y: number(node, 'y') + number(node, 'height') / 2
                });

                if (name === 'Spawn') {
                    spawns.set(property('type') || 'default', center);
                    return;
                }

                const targetMap = this.normalizeId(property('targetMap'));
                if (!targetMap) return;

                portals.push(Object.freeze({
                    portalId: property('portalId'),
                    targetMap,
                    targetPortalId: property('targetPortalId'),
                    center
                }));
            });

            return Object.freeze({
                width: number(mapNode, 'width') * number(mapNode, 'tilewidth'),
                height: number(mapNode, 'height') * number(mapNode, 'tileheight'),
                region: mapProperty('region') || 'world',
                displayName: mapProperty('displayName') || mapProperty('name') || '',
                parentMap: this.normalizeId(mapProperty('parentMap')) || null,
                layout: Object.freeze({
                    x: Number(mapProperty('worldX')) || 0,
                    y: Number(mapProperty('worldY')) || 0
                }),
                portals: Object.freeze(portals),
                pointsOfInterest: Object.freeze(pointsOfInterest),
                spawns
            });
        } catch (error) {
            Utility.warnDebug(`[WorldGraph] Could not read geometry for ${mapId}:`, error);
            return null;
        }
    }

    static getGeometry(mapId) {
        return this.geometry.get(this.normalizeId(mapId)) ?? this._emptyGeometry();
    }

    // The portal on `mapId` that leads to `targetMapId`, as the map file knows
    // it — available whether or not that map is the one currently loaded.
    static getPortalTo(mapId, targetMapId) {
        return this.edges.get(this.normalizeId(mapId))?.get(this.normalizeId(targetMapId)) ?? null;
    }

    // Where a traveller stands when it arrives on `mapId` from `fromMapId`: the
    // portal facing back the way it came, or the spawn point when it is starting
    // out rather than arriving.
    static getEntryPoint(mapId, fromMapId = null) {
        const geometry = this.getGeometry(mapId);
        const back = fromMapId ? this.getPortalTo(mapId, fromMapId) : null;
        return back?.center
            ?? geometry.spawns.get('myte')
            ?? geometry.spawns.get('default')
            ?? { x: geometry.width / 2, y: geometry.height / 2 };
    }

    // How far a traveller walks to cross `mapId` on its way from `fromMapId` to
    // `toMapId`, in map pixels. Straight-line: obstacles make the real path
    // longer, but this is a schedule, not a simulation.
    static getCrossingDistance(mapId, fromMapId, toMapId) {
        const entry = this.getEntryPoint(mapId, fromMapId);
        const exit = this.getPortalTo(mapId, toMapId)?.center;
        if (!exit) return 0;
        return Math.hypot(exit.x - entry.x, exit.y - entry.y);
    }

    static getMaps() {
        return [...this.nodes.values()];
    }

    static getMap(mapId) {
        return this.nodes.get(this.normalizeId(mapId)) || null;
    }

    // The maps that sit inside this one, in their own layout order. Passing null
    // asks for the roots — the maps that sit inside nothing — so the same call
    // walks the chart from the top down.
    static getChildren(mapId = null) {
        const parent = mapId === null ? null : this.normalizeId(mapId);
        return this.getMaps()
            .filter(map => (map.parentMap ?? null) === parent)
            .sort((a, b) => (a.layout.y - b.layout.y) || (a.layout.x - b.layout.x));
    }

    // Whether two maps share a layout space, which is the only case where their
    // worldX/worldY can be compared at all: a child's coordinates are its
    // parent's, not the world's.
    static areSiblings(mapIdA, mapIdB) {
        const a = this.getMap(mapIdA);
        const b = this.getMap(mapIdB);
        return !!a && !!b && (a.parentMap ?? null) === (b.parentMap ?? null);
    }

    // Every edge as a flat list, for a world-map view to draw lines from.
    static getConnections() {
        const connections = [];
        this.edges.forEach((targets, fromMapId) => {
            targets.forEach((portal, toMapId) => {
                connections.push({
                    from: fromMapId,
                    to: toMapId,
                    portalId: portal.portalId,
                    // A link is two-way only when the far side also points back.
                    bidirectional: this.edges.get(toMapId)?.has(fromMapId) ?? false
                });
            });
        });
        return connections;
    }

    static getNeighbors(mapId) {
        return [...(this.edges.get(this.normalizeId(mapId))?.keys() ?? [])];
    }

    // Shortest sequence of maps from `fromMapId` to `toMapId`, inclusive of both.
    // Returns null when the two are not connected. Breadth-first: every edge is
    // one transition, so the first path found is the shortest.
    static getRoute(fromMapId, toMapId) {
        const from = this.normalizeId(fromMapId);
        const to = this.normalizeId(toMapId);
        if (!this.nodes.has(from) || !this.nodes.has(to)) return null;
        if (from === to) return [from];

        const cameFrom = new Map([[from, null]]);
        const queue = [from];

        while (queue.length > 0) {
            const current = queue.shift();

            for (const neighbor of this.getNeighbors(current)) {
                if (cameFrom.has(neighbor)) continue;
                cameFrom.set(neighbor, current);

                if (neighbor === to) {
                    const route = [];
                    for (let step = to; step !== null; step = cameFrom.get(step)) {
                        route.unshift(step);
                    }
                    return route;
                }

                queue.push(neighbor);
            }
        }

        return null;
    }

    // Number of map transitions between two maps, or Infinity when unreachable.
    static getDistance(fromMapId, toMapId) {
        const route = this.getRoute(fromMapId, toMapId);
        return route ? route.length - 1 : Infinity;
    }

    static areConnected(fromMapId, toMapId) {
        return Number.isFinite(this.getDistance(fromMapId, toMapId));
    }
}
;
/* -- js/Map/Regions/SpatialRegion.js -- */
// ─────────────────────────────────────────────────────────────────────────────
// SpatialRegion — one geometry primitive for every "area of the map" concept.
//
// Before this, three parallel representations existed: Zone (rect only, buffs),
// environment.rooms (rect + optional polygon, lighting only), and an ad-hoc
// terrain-tile proximity scan for water. Rooms would have been a fourth.
//
// A region owns GEOMETRY and an opaque `properties` payload. It owns no
// behaviour: what a region *means* lives in whichever system consumes its layer
// (Zone applies buffs, MapEnvironmentManager applies lighting). That separation
// is what keeps this from becoming a vague god-object.
// ─────────────────────────────────────────────────────────────────────────────
class SpatialRegion {
    /**
     * @param {object} data
     *   id         unique within its layer
     *   layer      'zone' | 'room' | 'trigger' | 'lighting-opening'
     *   shape      { kind: 'rect', bounds }
     *            | { kind: 'polygon', points, bounds? }
     *            | { kind: 'tilemask', cells, cellSize, bounds? }
     *   properties layer-specific payload, untouched by this class
     */
    constructor(data = {}) {
        this.id = data.id;
        this.layer = data.layer ?? 'zone';
        this.properties = data.properties ?? {};
        this.shape = SpatialRegion.normalizeShape(data.shape);
        this.bounds = this.shape.bounds;
        this.source = data.source ?? null;
    }

    static normalizeShape(shape) {
        if (!shape) return { kind: 'rect', bounds: { x: 0, y: 0, width: 0, height: 0 } };

        if (shape.kind === 'polygon') {
            const points = shape.points ?? [];
            return { kind: 'polygon', points, bounds: shape.bounds ?? SpatialRegion.boundsOfPoints(points) };
        }

        if (shape.kind === 'tilemask') {
            const cellSize = shape.cellSize ?? 32;
            // Store as a Set of packed cell keys so `contains` is O(1).
            const cells = shape.cells instanceof Set
                ? shape.cells
                : new Set((shape.cells ?? []).map(c => (Array.isArray(c) ? `${c[0]},${c[1]}` : `${c.x},${c.y}`)));
            return {
                kind: 'tilemask',
                cells,
                cellSize,
                bounds: shape.bounds ?? SpatialRegion.boundsOfCells(cells, cellSize)
            };
        }

        return { kind: 'rect', bounds: shape.bounds ?? shape };
    }

    static boundsOfPoints(points) {
        if (!points?.length) return { x: 0, y: 0, width: 0, height: 0 };
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const p of points) {
            minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
            minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
        }
        return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
    }

    static boundsOfCells(cells, cellSize) {
        if (!cells?.size) return { x: 0, y: 0, width: 0, height: 0 };
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (const key of cells) {
            const [cx, cy] = key.split(',').map(Number);
            minX = Math.min(minX, cx); maxX = Math.max(maxX, cx);
            minY = Math.min(minY, cy); maxY = Math.max(maxY, cy);
        }
        return {
            x: minX * cellSize,
            y: minY * cellSize,
            width: (maxX - minX + 1) * cellSize,
            height: (maxY - minY + 1) * cellSize
        };
    }

    /**
     * Roughly how much ground this covers, in cells.
     *
     * Only ever used to rank overlapping regions against each other, which is
     * why a bounding-box estimate is good enough for rect and polygon: a region
     * walled off inside another is contained by both, and "the smaller one" is
     * the one the player means.
     */
    areaInCells(cellSize = this.shape.cellSize ?? 32) {
        if (this.shape.kind === 'tilemask') return this.shape.cells.size;
        const size = cellSize || 32;
        return (this.bounds.width * this.bounds.height) / (size * size);
    }

    // Bounds test first — cheap rejection before any polygon/tilemask work.
    boundsContain(x, y) {
        const b = this.bounds;
        return x >= b.x && x <= b.x + b.width && y >= b.y && y <= b.y + b.height;
    }

    contains(x, y) {
        if (!this.boundsContain(x, y)) return false;

        if (this.shape.kind === 'rect') return true;

        if (this.shape.kind === 'tilemask') {
            const cs = this.shape.cellSize;
            return this.shape.cells.has(`${Math.floor(x / cs)},${Math.floor(y / cs)}`);
        }

        // Polygon: even-odd ray cast. Handles concave shapes (L-shaped rooms).
        const pts = this.shape.points;
        let inside = false;
        for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
            const xi = pts[i].x, yi = pts[i].y;
            const xj = pts[j].x, yj = pts[j].y;
            const intersects = ((yi > y) !== (yj > y)) &&
                (x < ((xj - xi) * (y - yi)) / ((yj - yi) || Number.EPSILON) + xi);
            if (intersects) inside = !inside;
        }
        return inside;
    }

    /**
     * Fraction of `rect` that lies inside this region.
     *
     * Rect regions get the exact analytic answer (identical to the pre-existing
     * `RectUtils.getIntersectionRatio`, which Zone thresholds depend on — this
     * must not drift). Non-rect shapes sample instead, since there is no cheap
     * exact answer for arbitrary polygons.
     */
    intersectionRatio(rect) {
        if (this.shape.kind === 'rect') {
            return RectUtils.getIntersectionRatio(rect, this.bounds);
        }

        const samples = 5;
        let hits = 0;
        for (let i = 0; i < samples; i++) {
            for (let j = 0; j < samples; j++) {
                const x = rect.x + (rect.width * ((i + 0.5) / samples));
                const y = rect.y + (rect.height * ((j + 0.5) / samples));
                if (this.contains(x, y)) hits++;
            }
        }
        return hits / (samples * samples);
    }

    getCenterPoint() {
        const b = this.bounds;
        return { x: b.x + (b.width / 2), y: b.y + (b.height / 2) };
    }
}
;
/* -- js/Map/Regions/RegionManager.js -- */
// ─────────────────────────────────────────────────────────────────────────────
// RegionManager — the one place that answers "which areas is this entity in?"
//
// Layers are independent and unhierarchical on purpose: a zone may sit inside a
// room, and a zone may straddle two rooms. No containment tree is enforced.
//
// Membership is cached per entity and recomputed only when the entity crosses a
// grid cell, not every frame. Reverse occupant sets are maintained so a region
// can list who is inside it for free — something the old per-frame Zone scan
// could not do.
// ─────────────────────────────────────────────────────────────────────────────
class RegionManager {
    constructor(map, { cellSize = 32 } = {}) {
        this.map = map;
        this.cellSize = cellSize;
        this.regions = new Map();               // regionKey -> SpatialRegion
        this.byLayer = new Map();               // layer -> Set<SpatialRegion>
        this.occupants = new Map();             // regionKey -> Set<entity>
        this._membership = new Map();           // entity -> { cellKey, byLayer: Map<layer, Set<regionKey>> }
    }

    static key(layer, id) {
        return `${layer}:${id}`;
    }

    add(region) {
        if (!region) return null;
        const key = RegionManager.key(region.layer, region.id);
        this.regions.set(key, region);
        if (!this.byLayer.has(region.layer)) this.byLayer.set(region.layer, new Set());
        this.byLayer.get(region.layer).add(region);
        this.occupants.set(key, new Set());
        return region;
    }

    remove(region) {
        if (!region) return;
        const key = RegionManager.key(region.layer, region.id);
        this.regions.delete(key);
        this.byLayer.get(region.layer)?.delete(region);
        this.occupants.delete(key);
    }

    get(layer, id) {
        return this.regions.get(RegionManager.key(layer, id)) ?? null;
    }

    all(layer = null) {
        if (layer === null) return [...this.regions.values()];
        return [...(this.byLayer.get(layer) ?? [])];
    }

    /**
     * Regions containing a point. Bounds-first broad phase; with a few dozen
     * regions per map a linear scan over bounds is cheaper than maintaining a
     * spatial index. Add a cell index only if region counts grow materially.
     */
    regionsAt(x, y, layer = null) {
        const pool = layer === null ? this.regions.values() : (this.byLayer.get(layer) ?? []);
        const found = [];
        for (const region of pool) {
            if (region.contains(x, y)) found.push(region);
        }
        return found;
    }

    /**
     * The smallest region covering a point on a layer.
     *
     * Regions nest — a room walled off inside another sits inside its parent's
     * bounds, so the first match is the outer one and the inner one would be
     * unreachable. Everything that asks "which room is this?" wants the
     * innermost answer.
     */
    innermostAt(x, y, layer = null, cellSize = undefined) {
        return this.regionsAt(x, y, layer).reduce((smallest, region) =>
            !smallest || region.areaInCells(cellSize) < smallest.areaInCells(cellSize)
                ? region
                : smallest,
            null);
    }

    getOccupants(region) {
        if (!region) return [];
        return [...(this.occupants.get(RegionManager.key(region.layer, region.id)) ?? [])];
    }

    /**
     * Directly record occupancy, for consumers that decide membership by their own
     * rule rather than the default point test. Zone uses this: its thresholds are
     * intersection-ratio based (touching / halfway / fully), which a centre-point
     * test cannot reproduce, and its effects must stay per-frame so that per-ms
     * stat accumulation keeps its existing cadence.
     */
    setOccupant(region, entity, inside) {
        if (!region || !entity) return;
        const key = RegionManager.key(region.layer, region.id);
        const set = this.occupants.get(key);
        if (!set) return;

        if (inside) set.add(entity);
        else set.delete(entity);

        // Mirror into the entity's membership record so `getMembership` answers the
        // same thing whichever path wrote it — consumer-driven (here) or the
        // default point test in updateMembership.
        let record = this._membership.get(entity);
        if (!record) {
            record = { cellKey: null, byLayer: new Map() };
            this._membership.set(entity, record);
        }
        let layerKeys = record.byLayer.get(region.layer);
        if (!layerKeys) {
            layerKeys = new Set();
            record.byLayer.set(region.layer, layerKeys);
        }
        if (inside) layerKeys.add(key);
        else layerKeys.delete(key);
    }

    _cellKeyFor(entity) {
        const cs = this.cellSize;
        return `${Math.floor(entity.posX / cs)},${Math.floor(entity.posY / cs)}`;
    }

    /**
     * Recompute an entity's membership if it has crossed a grid cell.
     *
     * @param {object} entity
     * @param {object} options
     *   layers  which layers to evaluate (default: all)
     *   test    (region, entity) => boolean — lets a consumer impose its own
     *           containment rule (Zone's intersection thresholds, for example)
     *           instead of the default centre-point test
     *   force   recompute even without a cell crossing
     * @returns {{ entered: SpatialRegion[], exited: SpatialRegion[], changed: boolean }}
     */
    updateMembership(entity, { layers = null, test = null, force = false } = {}) {
        const cellKey = this._cellKeyFor(entity);
        let record = this._membership.get(entity);

        if (!record) {
            record = { cellKey: null, byLayer: new Map() };
            this._membership.set(entity, record);
        } else if (!force && record.cellKey === cellKey) {
            return { entered: [], exited: [], changed: false };
        }

        record.cellKey = cellKey;
        const targetLayers = layers ?? [...this.byLayer.keys()];
        const entered = [];
        const exited = [];

        for (const layer of targetLayers) {
            const previous = record.byLayer.get(layer) ?? new Set();
            const current = new Set();

            for (const region of this.byLayer.get(layer) ?? []) {
                const inside = test
                    ? test(region, entity)
                    : region.contains(entity.posX, entity.posY);
                if (!inside) continue;

                const key = RegionManager.key(region.layer, region.id);
                current.add(key);
                if (!previous.has(key)) {
                    entered.push(region);
                    this.occupants.get(key)?.add(entity);
                }
            }

            for (const key of previous) {
                if (current.has(key)) continue;
                const region = this.regions.get(key);
                if (region) exited.push(region);
                this.occupants.get(key)?.delete(entity);
            }

            record.byLayer.set(layer, current);
        }

        return { entered, exited, changed: entered.length > 0 || exited.length > 0 };
    }

    getMembership(entity, layer) {
        const keys = this._membership.get(entity)?.byLayer.get(layer);
        if (!keys) return [];
        return [...keys].map(key => this.regions.get(key)).filter(Boolean);
    }

    // Single cleanup path — called from despawn alongside the other registries.
    forget(entity, layers = null) {
        const record = this._membership.get(entity);
        if (!record) return;

        const targetLayers = layers === null ? [...record.byLayer.keys()] : layers;
        for (const layer of targetLayers) {
            const keys = record.byLayer.get(layer);
            if (!keys) continue;
            for (const key of keys) this.occupants.get(key)?.delete(entity);
            record.byLayer.delete(layer);
        }

        if (layers === null || record.byLayer.size === 0) {
            this._membership.delete(entity);
        }
    }

    clear() {
        this.regions.clear();
        this.byLayer.clear();
        this.occupants.clear();
        this._membership.clear();
    }
}
