        if (SiteConfig.wallSystem?.extendCanvasForWallHeight !== true) return;
        const cells = [...(this.wallBuilder?.cells?.values?.() || [])];
        if (!cells.length) return;
        const cellSize = this.gridSystem?.config?.cellSize || this.mapData?.tileHeight || 32;
