/* -- js/Map/MapObjects/MapObjectBases.js -- */
const withDirectional = (BaseClass) => class extends BaseClass {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        const direction = options.direction || config.direction || 'S';
        const processedConfig = MapObject.processDirectionConfig(config, direction);
        super(parent, type, variant, posX, posY, processedConfig, options);
        this.facingDirection = processedConfig.facingDirection || direction;
    }

    getBaseCssClass() {
        return null;
    }

    applyDirectionalVisuals(element) {
        const baseClass = this.getBaseCssClass();
        if (baseClass) {
            element.classList.add(baseClass);
        }

        element.classList.add(`facing-${this.facingDirection.toLowerCase()}`);

        const spriteElement = element.querySelector('.sprite');
        const transformStyle = this.getConfig('transformStyle', '');
        if (spriteElement && transformStyle) {
            spriteElement.style.transform = transformStyle;
        }

        if (this.getConfig('debug', false)) {
            const interactionRegion = this.getLocalRegionRect?.('interaction');
            if (!interactionRegion) {
                return element;
            }
            const interactiveZone = document.createElement('div');
            interactiveZone.classList.add('interactive-zone', 'debug-visible');
            interactiveZone.style.width = `${interactionRegion.width}px`;
            interactiveZone.style.height = `${interactionRegion.height}px`;
            interactiveZone.style.left = `${interactionRegion.x}px`;
            interactiveZone.style.top = `${interactionRegion.y}px`;
            element.appendChild(interactiveZone);
        }

        return element;
    }

    render(container, parent) {
        const element = super.render(container, parent);
        return this.applyDirectionalVisuals(element);
    }
};

class DirectionalMapObject extends withDirectional(MapObject) {}

// Uses withAnimation directly rather than the named AnimatedMapObject class,
// removing one level from the inheritance chain.
class DirectionalAnimatedMapObject extends withDirectional(withAnimation(MapObject)) {}

class InteractiveMapObject extends withAnimation(MapObject) {
    getInteractionActor() {
        return this.activeMyte;
    }

    shouldSelectOnPress() {
        return true;
    }

    getApproachActionId() {
        return 'go_to_object';
    }

    // 'side'     — stop at the nearest horizontal side (default)
    // 'adjacent' — stop just outside, no overlap (flowers, fountains)
    // 'center'   — walk into the center (portals)
    // 'front'    — face directly toward the object (doors, NPCs)
    getApproachConfig() {
        return this.getConfig('approachConfig', null);
    }

    getApproachMode() {
        return 'side';
    }

    enqueueApproach(myte, onComplete = null, options = {}) {
        if (!myte?.queue) return false;

        const payload = {
            target: this,
            ...options
        };
        if (onComplete) {
            payload.onComplete = onComplete;
        }

        myte.queue.add(this.getApproachActionId(), payload);
        return true;
    }

    runInteractionWhenInRange(action, myte = this.getInteractionActor(), options = {}) {
        if (!myte || typeof action !== 'function') return false;

        if (this.shouldSelectOnPress()) {
            this.selectInUi();
        }

        const {
            interactionRadius = this.getInteractionRadius(),
            queueIfOutOfRange = true,
            allowUnlimitedRange = interactionRadius === -1,
            queueVerb = null,
            userInitiated = false,
            postActionIdleDuration = 0
        } = options;
        const resolvedQueueVerb = queueVerb || (userInitiated ? this.getBestInteractionAction?.(myte)?.label ?? null : null);

        const wrappedAction = (m) => {
            action(m);
            if (postActionIdleDuration > 0) {
                m.queue?.addIdle(postActionIdleDuration);
            }
        };

        if (allowUnlimitedRange || this.isInInteractionRange(myte, interactionRadius)) {
            wrappedAction(myte);
            return true;
        }

        if (!queueIfOutOfRange) return false;
        return this.enqueueApproach(myte, () => wrappedAction(myte), {
            queueVerb: resolvedQueueVerb,
            userInitiated
        });
    }
}

class StatefulMapObject extends InteractiveMapObject {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);
        this.state = options.initialState ?? this.getDefaultState();
    }

    getDefaultState() {
        return this.getDefaultVisualState('default');
    }

    getStateAttributeName() {
        return 'data-state';
    }

    getAnimationSequence(state) {
        return [state, state];
    }

    updateElementState(value = this.state) {
        if (!this.element) return;
        this.element.setAttribute(this.getStateAttributeName(), value);
    }

    transitionToState(nextState, options = {}) {
        const {
            beforeChange,
            afterChange
        } = options;

        if (typeof beforeChange === 'function') {
            beforeChange(nextState, this.state);
        }

        this.state = nextState;
        this.updateElementState();

        const [firstAnim, secondAnim] = this.getAnimationSequence(nextState);
        this.playAnimation(firstAnim, () => {
            this.playAnimation(secondAnim);
            if (typeof afterChange === 'function') {
                afterChange(nextState);
            }
        });
    }

    render(container, parent) {
        const element = super.render(container, parent);
        this.updateElementState();
        return element;
    }
}

class ToggleableMapObject extends StatefulMapObject {
    getEnabledState() {
        return 'on';
    }

    getDisabledState() {
        return 'off';
    }

    isEnabled() {
        return this.state === this.getEnabledState();
    }

    getAnimationSequence(state) {
        if (state === this.getEnabledState()) {
            return ['turnOn', 'idle'];
        }

        if (state === this.getDisabledState()) {
            return ['turnOff', 'off'];
        }

        return super.getAnimationSequence(state);
    }

    toggleState(options = {}) {
        const nextState = this.isEnabled()
            ? this.getDisabledState()
            : this.getEnabledState();

        const soundType = nextState === this.getEnabledState() ? 'on' : 'off';
        const { beforeChange, ...restOptions } = options;

        this.transitionToState(nextState, {
            ...restOptions,
            beforeChange: (...args) => {
                this.playConfiguredSound(soundType);
                if (typeof beforeChange === 'function') {
                    beforeChange(...args);
                }
            }
        });
        return nextState;
    }
}

class MultiStateMapObject extends StatefulMapObject {
    getDefaultState() {
        return this.getDefaultVisualState(super.getDefaultState());
    }

    getStateClassNames() {
        return [];
    }

    updateElementState(value = this.state) {
        if (!this.element) return;

        const stateClasses = this.getStateClassNames();
        if (stateClasses.length) {
            this.element.classList.remove(...stateClasses);
        }

        this.element.classList.add(value);
    }

    playStateTransition(transitionState, finalState, options = {}) {
        const {
            beforeChange,
            afterChange,
            transitionAnimation = transitionState,
            finalAnimation = finalState
        } = options;

        if (typeof beforeChange === 'function') {
            beforeChange(finalState, this.state, transitionState);
        }

        this.state = transitionState;
        this.updateElementState();

        this.playAnimation(transitionAnimation, () => {
            this.state = finalState;
            this.updateElementState();
            this.playAnimation(finalAnimation);

            if (typeof afterChange === 'function') {
                afterChange(finalState, transitionState);
            }
        });

        return true;
    }
}

class OpenableMapObject extends DirectionalAnimatedMapObject {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);
        this.isOpen = options.isOpen ?? this.getDefaultVisualState('closed') === 'open';
        this.isAnimating = false;
        this.updateCollisionState();
    }

    getToggleEventName() {
        return null;
    }

    getToggleStateClassMap() {
        return {
            open: 'open',
            closed: 'closed'
        };
    }

    getOpenAnimationName() {
        return 'opening';
    }

    getCloseAnimationName() {
        return 'closing';
    }

    getOpenLoopAnimationName() {
        return 'open';
    }

    getClosedLoopAnimationName() {
        return 'closed';
    }

    refreshGridOccupancy() {
        if (!this.gameMap?.gridSystem) return;
        this.gameMap.gridSystem.removeObject(this);
        this.gameMap.gridSystem.addObject(this);
    }

    updateCollisionState() {
        this.config.physics.walkable = this.isOpen;
        this.config.physics.collision = !this.isOpen;
        this.refreshGridOccupancy();
        this.applyOpenStateClasses();
    }

    applyOpenStateClasses() {
        if (!this.element) return;

        const { open, closed } = this.getToggleStateClassMap();
        this.element.classList.toggle(open, this.isOpen);
        this.element.classList.toggle(closed, !this.isOpen);
    }

    emitToggleEvent(state) {
        const eventName = this.getToggleEventName();
        if (!this.gameMap?.eventManager) return;

        this.gameMap.eventManager.emit(EVENTS.WORLD_ACTION_AVAILABILITY_CHANGED, {
            object: this,
            state
        });
        if (!eventName) return;

        this.gameMap.eventManager.emit(eventName, {
            object: this,
            state,
            position: { x: this.posX, y: this.posY }
        });
    }

    onOpened(_context = {}) {}

    onClosed(_context = {}) {}

    onOpenStateChanged(_context = {}) {}

    open(openContext = {}) {
        if (this.isOpen || this.isAnimating) return false;

        this.isAnimating = true;
        this.playConfiguredSound('open');
        this.playAnimation(this.getOpenAnimationName(), () => {
            this.isOpen = true;
            this.isAnimating = false;
            this.updateCollisionState();
            this.onOpened(openContext);

            const loopAnimation = this.getOpenLoopAnimationName();
            if (this.hasAnimation(loopAnimation)) {
                this.playAnimation(loopAnimation);
            }

            this.emitToggleEvent('open');
            this.onOpenStateChanged(openContext);
        });

        return true;
    }

    close(closeContext = {}) {
        if (!this.isOpen || this.isAnimating) return false;

        this.isAnimating = true;
        this.playConfiguredSound('close');
        this.playAnimation(this.getCloseAnimationName(), () => {
            this.isOpen = false;
            this.isAnimating = false;
            this.updateCollisionState();
            this.onClosed(closeContext);

            const loopAnimation = this.getClosedLoopAnimationName();
            if (this.hasAnimation(loopAnimation)) {
                this.playAnimation(loopAnimation);
            }

            this.emitToggleEvent('closed');
            this.onOpenStateChanged(closeContext);
        });

        return true;
    }

    toggle(toggleContext = {}) {
        return this.isOpen ? this.close(toggleContext) : this.open(toggleContext);
    }

    press(interactor) {
        if (this.isAnimating) return false;
        this.toggle();
        super.press(interactor);
        return true;
    }

    render(container, parent) {
        const element = super.render(container, parent);
        this.applyOpenStateClasses();
        return element;
    }
}

// Mixin for objects that emit a passive aura affecting nearby mytes.
// Subclasses override isAuraActive(), getAuraExpression(), getAuraExpressionChance().
// Config keys read from types.json: aura.radius, aura.checkInterval, auraBuffId, auraBuffDefinition.
const withAura = (BaseClass) => class extends BaseClass {
    constructor(...args) {
        super(...args);
        this._auraAccumulator = 0;
        this._auraInterval = this.getConfig('aura.checkInterval', SiteConfig.objects.aura.proximityInterval);
    }

    getAuraRadius() {
        return this.getConfig('aura.radius', SiteConfig.objects.aura.defaultRadius);
    }

    getBuffContextKey() {
        return `${this.type.toLowerCase()}:${this.id ?? `${this.posX},${this.posY}`}:aura`;
    }

    // Return false to deactivate the aura without removing the buff.
    isAuraActive() {
        return typeof this.isEnabled === 'function' ? this.isEnabled() : true;
    }

    // Return an expression id to occasionally emit while a myte is in range, or null for none.
    getAuraExpression() {
        return null;
    }

    getAuraExpressionChance() {
        return 0;
    }

    syncAuraBuff(myte, active) {
        myte?.buffs?.syncContextBuff?.(
            this.getBuffContextKey(),
            this.getConfig('auraBuffDefinition', null) ?? this.getConfig('auraBuffId', null),
            {
                active,
                source: 'aura',
                payload: { objectType: this.type, objectId: this.id }
            }
        );
    }

    checkNearbyMytes() {
        const mytes = this.mytes;
        if (!mytes.length) return;

        const auraActive = this.isAuraActive();
        const radius = this.getAuraRadius();
        const expression = this.getAuraExpression();
        const expressionChance = expression ? this.getAuraExpressionChance() : 0;

        mytes.forEach(myte => {
            if (!myte?.isActive) {
                this.syncAuraBuff(myte, false);
                return;
            }

            const inRange = auraActive && this.getDistanceTo(myte) <= radius;
            this.syncAuraBuff(myte, inRange);

            if (inRange && expression && Math.random() < expressionChance) {
                myte.queue.addExpression(expression);
            }
        });
    }

    tickUpdate(tickDelta) {
        super.tickUpdate(tickDelta);
        this._auraAccumulator += tickDelta;
        if (this._auraAccumulator >= this._auraInterval) {
            this._auraAccumulator = 0;
            this.checkNearbyMytes();
        }
    }
};

const withConnectable = (BaseClass) => class extends BaseClass {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);
        this.connectedObjectIds = new Set();

        if (this.getConfig('autoConnect', true)) {
            this.connectToNearbyObjects();
        }
    }

    getConnectableTypes() {
        return ['FENCE', 'GATE'];
    }

    getConnectionRadius() {
        return this.getConfig('connectionRadius', 40);
    }

    canConnectTo(object) {
        return object &&
            object !== this &&
            this.getConnectableTypes().includes(object.type) &&
            object.active;
    }

    getNearbyConnectableObjects() {
        if (!this.gameMap) return [];
        return this.gameMap.getObjectsInRadius(this.posX, this.posY, this.getConnectionRadius())
            .filter(obj => this.canConnectTo(obj));
    }

    connectToObject(object) {
        if (!this.canConnectTo(object)) return false;
        this.connectedObjectIds.add(object.id);
        object.addConnectedObject?.(this.id);
        return true;
    }

    connectToNearbyObjects() {
        this.getNearbyConnectableObjects().forEach(obj => this.connectToObject(obj));
    }

    addConnectedObject(objectId) {
        this.connectedObjectIds.add(objectId);
    }

    removeConnectedObject(objectId) {
        this.connectedObjectIds.delete(objectId);
    }

    disconnectFromConnectedObjects() {
        if (!this.gameMap) return;

        this.connectedObjectIds.forEach(objectId => {
            const object = this.gameMap.getObjectById?.(objectId);
            object?.removeConnectedObject?.(this.id);
        });
    }

    remove() {
        this.disconnectFromConnectedObjects();
        super.remove();
    }
};

class LinkedOpenableMapObject extends withConnectable(OpenableMapObject) {
    getConnectableTypes() {
        return ['FENCE'];
    }
}

// ── withItemDrops ─────────────────────────────────────────────────────────────
// Mixin for objects that spawn DroppedMapItem instances (plants, chests, trees).
// Moved out of MapObject so only declaring classes carry the ~200-line weight.
// Apply: class Foo extends withItemDrops(BaseClass) { ... }
const withItemDrops = (Base) => class extends Base {
    getFrontDropSpawnPoint({ distance = 18, verticalLift = 0 } = {}) {
        const rect = this.getColliderRectFor(this) ?? {
            left: this.posX,
            top: this.posY,
            right: this.posX + this.size.width,
            bottom: this.posY + this.size.height,
            width: this.size.width,
            height: this.size.height
        };
        const facing = this.getFacingVector();
        const centerX = rect.left + (rect.width / 2);
        const centerY = rect.top + (rect.height / 2);
        const halfDepth = facing.x !== 0 ? (rect.width / 2) : (rect.height / 2);
        const frontOffset = halfDepth + distance;
        return {
            x: centerX + (facing.x * frontOffset),
            y: centerY + (facing.y * frontOffset) - verticalLift
        };
    }

    getDefaultItemPopOutMotionOptions() {
        return {
            distance: 0,
            verticalLift: 8,
            forwardTravelDistance: 226,
            forwardSpeed: null,
            forwardVariance: 4,
            spreadDistance: 8,
            spreadSpeed: 0.5,
            spreadIndex: 0,
            spreadCount: 1,
            lateralSpeed: 0.18,
            lateralSpawnDistance: 2,
            lateralBias: null,
            verticalSpeed: 8.2,
            verticalVariance: 2.1,
            airDrag: 0.92
        };
    }

    getItemPopOutSpreadBias(index = 0, count = 1) {
        const resolvedCount = Math.max(1, Math.round(Number(count) || 1));
        if (resolvedCount <= 1) return 0;
        const resolvedIndex = Utility.clamp(Math.round(Number(index) || 0), 0, resolvedCount - 1);
        const midpoint = (resolvedCount - 1) / 2;
        return (resolvedIndex - midpoint) / Math.max(midpoint, 0.5);
    }

    getItemPopOutMotion({
        distance, verticalLift, forwardTravelDistance, forwardSpeed, forwardVariance,
        spreadDistance, spreadSpeed, spreadIndex, spreadCount, lateralSpeed,
        lateralSpawnDistance, lateralBias = null, verticalSpeed, verticalVariance, airDrag
    } = {}) {
        const defaults = this.getDefaultItemPopOutMotionOptions();
        const forward = this.getFacingVector();
        const lateral = { x: -forward.y, y: forward.x };
        const resolvedDistance = Number.isFinite(Number(distance)) ? Number(distance) : defaults.distance;
        const resolvedVerticalLift = Number.isFinite(Number(verticalLift)) ? Number(verticalLift) : defaults.verticalLift;
        const resolvedForwardTravelDistance = Number.isFinite(Number(forwardTravelDistance)) ? Number(forwardTravelDistance) : defaults.forwardTravelDistance;
        const resolvedForwardVariance = Number.isFinite(Number(forwardVariance)) ? Number(forwardVariance) : defaults.forwardVariance;
        const resolvedSpreadDistance = Number.isFinite(Number(spreadDistance)) ? Number(spreadDistance)
            : (Number.isFinite(Number(lateralSpawnDistance)) ? Number(lateralSpawnDistance) : defaults.spreadDistance);
        const resolvedSpreadSpeed = Number.isFinite(Number(spreadSpeed)) ? Number(spreadSpeed)
            : (Number.isFinite(Number(lateralSpeed)) ? Number(lateralSpeed) : defaults.spreadSpeed);
        const resolvedSpreadIndex = Number.isFinite(Number(spreadIndex)) ? Number(spreadIndex) : defaults.spreadIndex;
        const resolvedSpreadCount = Number.isFinite(Number(spreadCount)) ? Number(spreadCount) : defaults.spreadCount;
        const bias = lateralBias !== null && lateralBias !== undefined && Number.isFinite(Number(lateralBias))
            ? Utility.clamp(Number(lateralBias), -1, 1)
            : this.getItemPopOutSpreadBias(resolvedSpreadIndex, resolvedSpreadCount);
        const resolvedVerticalSpeed = Number.isFinite(Number(verticalSpeed)) ? Number(verticalSpeed) : defaults.verticalSpeed;
        const resolvedVerticalVariance = Number.isFinite(Number(verticalVariance)) ? Number(verticalVariance) : defaults.verticalVariance;
        const resolvedAirDrag = Number.isFinite(Number(airDrag)) ? Utility.clamp(Number(airDrag), 0, 0.999) : defaults.airDrag;
        const spawnPoint = this.getFrontDropSpawnPoint({ distance: resolvedDistance, verticalLift: resolvedVerticalLift });
        const effectiveGravity = 0.5;
        const estimatedAirborneFrames = Math.max(1, Math.round(((resolvedVerticalSpeed + (resolvedVerticalVariance * 0.5)) * 2) / effectiveGravity));
        const dragDistanceFactor = resolvedAirDrag > 0 && resolvedAirDrag < 0.999
            ? (1 - Math.pow(resolvedAirDrag, estimatedAirborneFrames)) / (1 - resolvedAirDrag)
            : estimatedAirborneFrames;
        const derivedForwardSpeed = resolvedForwardTravelDistance / Math.max(dragDistanceFactor, 0.001);
        const resolvedForwardSpeed = Number.isFinite(Number(forwardSpeed)) ? Number(forwardSpeed)
            : (Number.isFinite(Number(defaults.forwardSpeed)) ? Number(defaults.forwardSpeed) : derivedForwardSpeed);
        const forwardMagnitude = resolvedForwardSpeed + (Math.random() * resolvedForwardVariance);

        // Fan spread: half-angle grows with item count so a single item flies straight.
        const fanHalfAngleDeg = resolvedSpreadCount > 1 ? Math.min(60, 15 + (resolvedSpreadCount - 1) * 15) : 0;
        const fanAngleRad = bias * fanHalfAngleDeg * (Math.PI / 180);
        const cos_a = Math.cos(fanAngleRad);
        const sin_a = Math.sin(fanAngleRad);
        const rotatedX = forward.x * cos_a - forward.y * sin_a;
        const rotatedY = forward.x * sin_a + forward.y * cos_a;

        return {
            spawnX: spawnPoint.x + (lateral.x * bias * resolvedSpreadDistance),
            spawnY: spawnPoint.y + (lateral.y * bias * resolvedSpreadDistance),
            velocityX: rotatedX * forwardMagnitude,
            velocityY: rotatedY * forwardMagnitude,
            velocityZ: resolvedVerticalSpeed + (Math.random() * resolvedVerticalVariance),
            airDrag: resolvedAirDrag
        };
    }

    getDroppedItemsLayer(parent = null) {
        return this.gameMap?.layers?.objects || parent?.canvas?.querySelector('.layer.foreground') || null;
    }

    createDroppedInventoryItem({
        type = null, variant = null, quantity = 1, inventoryType = null,
        inventoryVariant = null, inventoryName = null, description = '', motion = null, motionOptions = {}
    } = {}) {
        const resolvedVariant = ItemRegistry.resolveIdSync(variant) || variant;
        const itemDefinition = ItemRegistry.getItemSync(resolvedVariant);
        const resolvedType = String(inventoryType || type || itemDefinition?.type || 'ITEM').toUpperCase();
        const resolvedMotion = motion ?? this.getItemPopOutMotion(motionOptions);
        const dropped = new DroppedMapItem(this.gameMap, resolvedType, resolvedVariant, resolvedMotion.spawnX, resolvedMotion.spawnY);
        dropped.quantity = Math.max(1, Number(quantity) || 1);
        dropped.inventoryType = resolvedType;
        dropped.inventoryVariant = inventoryVariant || itemDefinition?.id || resolvedVariant;
        dropped.inventoryName = inventoryName || itemDefinition?.name || dropped.inventoryVariant;
        dropped.description = description || itemDefinition?.description || '';
        dropped.velocityX = resolvedMotion.velocityX ?? 0;
        dropped.velocityY = resolvedMotion.velocityY ?? 0;
        dropped.velocityZ = resolvedMotion.velocityZ ?? 0;
        dropped.airDrag = resolvedMotion.airDrag ?? dropped.airDrag ?? 0.86;
        return dropped;
    }

    spawnDroppedInventoryItem(itemConfig = {}, { parent = null, layer = null, localCollection = null } = {}) {
        const foregroundLayer = layer || this.getDroppedItemsLayer(parent);
        if (!foregroundLayer) return null;
        const dropped = this.createDroppedInventoryItem(itemConfig);
        if (!dropped?.element) return null;
        foregroundLayer.appendChild(dropped.element);
        if (Array.isArray(localCollection)) localCollection.push(dropped);
        if (!this.gameMap?.droppedItems?.includes(dropped)) this.gameMap?.droppedItems?.push(dropped);
        return dropped;
    }

    spawnDroppedInventoryItems(itemConfigs = [], { parent = null, layer = null, localCollection = null, motionOptions = {} } = {}) {
        const entries = Array.isArray(itemConfigs) ? itemConfigs.filter(Boolean) : [itemConfigs].filter(Boolean);
        const totalCount = entries.length;
        return entries.map((itemConfig, index) => this.spawnDroppedInventoryItem({
            ...itemConfig,
            motionOptions: { ...motionOptions, ...(itemConfig?.motionOptions ?? {}), spreadIndex: index, spreadCount: totalCount }
        }, { parent, layer, localCollection })).filter(Boolean);
    }

    pruneDroppedItemCollection(collection = []) {
        if (!Array.isArray(collection)) return [];
        return collection.filter(item => !!item && item.active && !item.collected);
    }

    // Rolls a weighted drop table. dropTable entries: { type, variant, quantity, chance }
    _rollDrops(dropTable, minYield, maxYield) {
        if (!dropTable?.length) return [];
        const quantity = Utility.randomInt(minYield, maxYield);
        const results = [];
        for (let i = 0; i < quantity; i++) {
            const roll = Math.random();
            let cumulative = 0;
            for (const drop of dropTable) {
                cumulative += drop.chance ?? 1 / dropTable.length;
                if (roll <= cumulative) {
                    results.push({ type: drop.type, variant: drop.variant, quantity: drop.quantity ?? 1 });
                    break;
                }
            }
        }
        return results;
    }
};

// ── withPickup ────────────────────────────────────────────────────────
// Mixin for map objects that can be picked up and carried by a Myte.
// Overrides the thin stubs on MapObject with full implementations.
// Apply: class Foo extends withPickup(BaseClass) { ... }
const withPickup = (Base) => class extends Base {
    getPickupRange(myte) {
        const explicitRange = this.getConfig('pickupRange', null);
        if (Number.isFinite(explicitRange)) return explicitRange;
        const myteReach = Math.max(myte?.collider?.width ?? 0, myte?.collider?.height ?? 0) * 0.5;
        const pickupRect = this.getPickupRect() || this.getRegionRect('collider');
        const objectReach = Math.max(pickupRect?.width ?? 0, pickupRect?.height ?? 0) * 0.5;
        return Math.max(24, myteReach + objectReach + 8);
    }

    canBePickedUpBy(myte) {
        return !!myte?.isActive &&
            this.active &&
            this.getConfig('canPickUp', false) &&
            (!this.isPickedUp || this.carrier === myte);
    }

    isInPickupRange(myte) {
        if (!myte) return false;
        const touchThreshold = this.getConfig('pickupTouchThreshold', 12);
        const myteRect = this.getColliderRectFor(myte);
        const pickupRect = this.getPickupRect() || this.getRegionRect('collider');
        if (pickupRect && myteRect) {
            const gapX = Math.max(0, pickupRect.left - myteRect.right, myteRect.left - pickupRect.right);
            const gapY = Math.max(0, pickupRect.top - myteRect.bottom, myteRect.top - pickupRect.bottom);
            if (Math.hypot(gapX, gapY) <= touchThreshold) return true;
        } else if (this.getColliderGapTo(myte) <= touchThreshold) {
            return true;
        }
        const myteCenter = typeof myte.getCenterPoint === 'function'
            ? myte.getCenterPoint('collider')
            : {
                x: myte.posX + (myte.collider?.offsetX ?? 0) + ((myte.collider?.width ?? myte.size.width) / 2),
                y: myte.posY + (myte.collider?.offsetY ?? 0) + ((myte.collider?.height ?? myte.size.height) / 2)
            };
        const objectCenter = pickupRect
            ? { x: pickupRect.left + (pickupRect.width / 2), y: pickupRect.top + (pickupRect.height / 2) }
            : this.getCenterPoint?.() ?? { x: this.posX + this.size.width / 2, y: this.posY + this.size.height / 2 };
        return Math.hypot(objectCenter.x - myteCenter.x, objectCenter.y - myteCenter.y) <= this.getPickupRange(myte);
    }

    getPickupTargetPoint(myte = null) {
        const pickupRect = this.getPickupRect();
        if (pickupRect) return { x: pickupRect.left + (pickupRect.width / 2), y: pickupRect.top + (pickupRect.height / 2) };
        return this.getCenterPoint?.() ?? { x: this.posX + this.size.width / 2, y: this.posY + this.size.height / 2 };
    }

    getCarriedPosition(carrier) {
        return carrier?.getCarriedItemPosition?.(this.size) || { x: this.posX, y: this.posY };
    }

    pickup(myte) {
        if (!this.canBePickedUpBy(myte)) return false;

        const attachment = this.container?.attachments?.attach?.(myte, this, 'carry.item');
        if (this.container?.attachments && !attachment) return false;

        this.isPickedUp = true;
        this.carrier = myte;
        this.pendingPickup = false;
        if (!attachment) {
            this.container?.relationships?.set?.('carrying', myte, this);
        }
        this.element?.classList.add('picked-up');
        this.syncRenderLayer();
        this.wake();
        this.container?.ui?.setSelected?.(this);
        this.playConfiguredSound?.('pickup');
        return true;
    }

    drop(vx = 0, vy = 0) {
        const attachment = this.container?.attachments?.getAttachment?.(this);
        if (attachment) {
            this.container.attachments.detach(this);
        } else if (this.carrier) {
            this.container?.relationships?.clear?.('carrying', this.carrier, this);
        }
        this.isPickedUp = false;
        this.carrier = null;
        this.pendingPickup = false;
        this.element?.classList.remove('picked-up');
        this.syncRenderLayer();
        this.gameMap?.gridSystem?.updateObjectPosition(this);
        this.playConfiguredSound?.('drop');
        return { vx, vy };
    }
};

// ── withFlightSounds ───────────────────────────────────────────────────
// Mixin for airborne ambient creatures that play land/flight sounds.
// Reads from `flightSound` config key (set in constructor mergedConfig or types.json):
//   landSound, landVolume, flySound, flyVolumeBase, flyVolumeScale, flyVolumeMin,
//   flyVolumeMax, speedThreshold, cooldownMin, cooldownVariance
// Optional `flapSyncAnimations: [names]` switches flySound from the default
// speed-based retrigger to animation-loop cues. Both paths share the cooldown;
// a fast wing animation must not create an unbounded stream of audio voices.
// Apply: class Foo extends withFlightSounds(BaseClass) { ... }
const withFlightSounds = (Base) => class extends Base {
    constructor(...args) {
        super(...args);
        const cfg = this.getConfig('flightSound', {});
        this._flightSoundCooldown = (cfg.cooldownMin ?? 300) + Math.random() * (cfg.cooldownVariance ?? 400);
    }

    playAnimation(animationName, onComplete) {
        const cfg = this.getConfig('flightSound', null);
        if (cfg?.flapSyncAnimations?.includes(animationName)) {
            super.playAnimation(animationName, () => {
                this._playFlapSound(cfg);
                onComplete?.();
            });
            return;
        }
        super.playAnimation(animationName, onComplete);
    }

    _playFlapSound(cfg) {
        const soundManager = this.gameMap?.soundManager;
        if (!soundManager || !cfg.flySound || this._flightSoundCooldown > 0) return;
        const currentSpeed = Math.hypot(this.velocity?.x ?? 0, this.velocity?.y ?? 0);
        const speedRatio = currentSpeed / Math.max(this.speed, 0.01);
        const volume = Utility.clamp(
            (cfg.flyVolumeBase ?? 0.35) + speedRatio * (cfg.flyVolumeScale ?? 0.13),
            cfg.flyVolumeMin ?? 0.3,
            cfg.flyVolumeMax ?? 0.5
        );
        soundManager.play(cfg.flySound, { volume, source: this });
        this._flightSoundCooldown = (cfg.cooldownMin ?? 300) + Math.random() * (cfg.cooldownVariance ?? 400);
    }

    tickUpdate(tickDelta) {
        const wasRestingOnTarget = this.isRestingOnTarget;
        super.tickUpdate(tickDelta);
        this._updateFlightSound(tickDelta, wasRestingOnTarget);
    }

    _updateFlightSound(tickDelta, wasRestingOnTarget) {
        this._flightSoundCooldown = Math.max(0, this._flightSoundCooldown - tickDelta);
        const cfg = this.getConfig('flightSound', null);
        if (!cfg) return;
        const soundManager = this.gameMap?.soundManager;
        if (!soundManager) return;

        if (!wasRestingOnTarget && this.isRestingOnTarget) {
            if (cfg.landSound) soundManager.play(cfg.landSound, {
                volume: cfg.landVolume ?? 0.5,
                source: this
            });
            return;
        }

        // Flap-synced creatures get their flySound from the animation loop
        // instead (see playAnimation above), not from this speed-based retrigger.
        if (cfg.flapSyncAnimations) return;

        const currentSpeed = Math.hypot(this.velocity?.x ?? 0, this.velocity?.y ?? 0);
        if (!this.isIdle && !this.isRestingOnTarget && currentSpeed > (cfg.speedThreshold ?? 0.18) && this._flightSoundCooldown <= 0 && cfg.flySound) {
            const speedRatio = currentSpeed / Math.max(this.speed, 0.01);
            const volume = Utility.clamp(
                (cfg.flyVolumeBase ?? 0.35) + speedRatio * (cfg.flyVolumeScale ?? 0.13),
                cfg.flyVolumeMin ?? 0.3,
                cfg.flyVolumeMax ?? 0.5
            );
            soundManager.play(cfg.flySound, { volume, source: this });
            this._flightSoundCooldown = (cfg.cooldownMin ?? 300) + Math.random() * (cfg.cooldownVariance ?? 400);
        }
    }
};
;
/* -- js/Map/MapObjects/Interactive/FountainMapObject.js -- */
class FountainMapObject extends withAura(ToggleableMapObject) {
    getApproachMode() {
        return 'adjacent';
    }

    isAuraActive() {
        return this.isEnabled();
    }

    getAuraExpression() {
        return 'happy';
    }

    getAuraExpressionChance() {
        return 0.1;
    }

    press(parent) {
        if (!this.active) return false;
        return this.runInteractionWhenInRange(() => this.toggleState());
    }

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('fountain');
        return element;
    }

}
;
/* -- js/Map/MapObjects/Interactive/LightMapObject.js -- */
class LightMapObject extends withAura(ToggleableMapObject) {
    // isAuraActive() defaults to this.isEnabled() via the mixin — no override needed.

    press(parent) {
        if (!this.active) return false;
        return this.runInteractionWhenInRange(() => {
            this.playAnimation('flicker', () => this.toggleLight(parent));
        });
    }

    toggleLight(parent) {
        this.toggleState({
            afterChange: () => this.applyEffects(parent)
        });
    }

    applyEffects(parent) {
        if (this.isEnabled() && this.activeMyte) {
            this.activeMyte.buffs?.applyBuff?.(
                this.getConfig('interactionBuffDefinition', null) ??
                this.getConfig('interactionBuffId', 'light_switch_delight'),
                {
                    source: 'interaction',
                    payload: { objectType: this.type, objectId: this.id }
                }
            );
        }
    }

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('light-object');
        return element;
    }

    getAiAffordances(context = {}, actor = null) {
        return super.getAiAffordances(context, actor).filter(a =>
            !(a.actionId === 'interact_object' && a.purpose === 'toggle')
        );
    }
}

class MusicBoxMapObject extends withAura(InteractiveMapObject) {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);
        this.isPlayingState = options.initialState ?? this.getConfig('defaultPlaying', false);
    }

    isAuraActive() {
        return this.isPlayingState;
    }

    serializeState() {
        return {
            isPlaying: this.isPlayingState,
            inventoryItemId: this.getConfig('inventoryItemId', null)
        };
    }

    restoreState(state = {}) {
        this.isPlayingState = state.isPlaying === true;
        if (state.inventoryItemId) this.config.inventoryItemId = state.inventoryItemId;
        this.updatePlaybackState();
    }

    getAuraExpression() {
        return 'happy';
    }

    getAuraExpressionChance() {
        return 0.12;
    }

    press(parent) {
        if (!this.active) return false;
        return this.runInteractionWhenInRange(() => this.togglePlayback(parent));
    }

    togglePlayback(parent) {
        this.isPlayingState = !this.isPlayingState;
        this.updatePlaybackState();
        this.playConfiguredSound(this.isPlayingState ? 'on' : 'off');

        if (this.isPlayingState && this.activeMyte) {
            this.activeMyte.buffs?.applyBuff?.(
                this.getConfig('startBuffDefinition', null) ??
                this.getConfig('startBuffId', 'music_delight'),
                {
                    source: 'interaction',
                    payload: { objectType: this.type, objectId: this.id }
                }
            );
            this.activeMyte.queue.addExpression('happy', 45, 1);
        }
    }

    handleDoubleClick(event) {
        event?.originalEvent?.preventDefault?.();
        this.togglePlayback(this.container ?? this.parent);
        this.selectInUi();
    }

    updatePlaybackState() {
        if (!this.element) return;
        this.element.setAttribute('data-playing', this.isPlayingState ? 'true' : 'false');
        this.element.classList.toggle('is-playing', this.isPlayingState);
    }

    isMusicSource() {
        return true;
    }

    isActiveMusicSource() {
        return this.isPlayingState;
    }

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('music-box');
        this.updatePlaybackState();
        return element;
    }
}
;
/* -- js/Map/MapObjects/Interactive/TreasureChestMapObject.js -- */
class TreasureChestMapObject extends withItemDrops(MultiStateMapObject) {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);
        this.items = [];
        this.droppedItems = [];
        this.canClose = this.getConfig('canClose', false);

        // Add initial items if provided
        this.addItems(options.items ?? this.getConfig('items', []));
    }

    getStateClassNames() {
        return ['closed', 'opening', 'opened', 'closing'];
    }

    addItems(items) {
        this.items = this.normalizeItems(items);
    }

    getChestStateLabel() {
        return this.humanizeLabelToken(this.state || 'closed');
    }

    hasLoot() {
        return this.normalizeItems(this.items).length > 0;
    }

    getContainedLootSummary(maxEntries = 3) {
        const items = this.normalizeItems(this.items);
        if (!items.length) {
            return 'Empty';
        }

        const summary = items.slice(0, maxEntries).map(item => {
            const itemDefinition = ItemRegistry.getItemSync(item.variant);
            const label = itemDefinition?.name ||
                this.humanizeLabelToken(item.variant || item.type || 'Loot');
            const quantity = this.formatDisplayQuantity(item.quantity);
            const probability = Number(item.probability);
            const parts = [label];

            if (quantity && quantity !== '1') {
                parts.push(`x${quantity}`);
            }

            if (Number.isFinite(probability) && probability > 0 && probability < 1) {
                parts.push(`(${Math.round(probability * 100)}%)`);
            }

            return parts.join(' ');
        });

        if (items.length > maxEntries) {
            summary.push(`+${items.length - maxEntries} more`);
        }

        return summary.join(', ');
    }

    applyRuntimeProperties(properties = {}) {
        if (Object.prototype.hasOwnProperty.call(properties, 'items')) {
            this.items = this.normalizeItems(properties.items);
        }

        if (Object.prototype.hasOwnProperty.call(properties, 'canClose')) {
            this.canClose = !!properties.canClose;
        }
    }

    normalizeItems(items) {
        if (items == null) return [];

        if (Array.isArray(items)) {
            return items
                .flatMap(item => this.normalizeItems(item))
                .filter(Boolean);
        }

        if (typeof items === 'string') {
            const trimmed = items.trim();
            if (!trimmed) return [];

            if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
                try {
                    return this.normalizeItems(JSON.parse(trimmed));
                } catch (error) {
                    return this.parseItemDefinitionString(trimmed);
                }
            }

            return this.parseItemDefinitionString(trimmed);
        }

        if (typeof items === 'object') {
            if ('type' in items) {
                const normalizedItem = this.normalizeItemDefinition(items);
                return normalizedItem ? [normalizedItem] : [];
            }

            return Object.values(items)
                .flatMap(item => this.normalizeItems(item))
                .filter(Boolean);
        }

        return [];
    }

    parseItemDefinitionString(str) {
        const cleanString = str.trim().replace(/\n/g, '');
        if (!cleanString) return [];

        const itemStrings = cleanString.includes('{')
            ? cleanString.split(/,(?=\s*{)/)
            : [cleanString];

        return itemStrings
            .map(itemStr => {
                const parts = itemStr
                    .replace(/^\[|\]$/g, '')
                    .replace(/[{}]/g, '')
                    .split(',')
                    .map(part => this._sanitizeItemToken(part))
                    .filter(part => part.length > 0);

                if (!parts.length) return null;

                return this.normalizeItemDefinition({
                    type: parts[0],
                    variant: parts[1] ?? 'default',
                    quantity: parts.length > 2 ? parts[2] : undefined,
                    probability: parts.length > 3 ? parts[3] : undefined
                });
            })
            .filter(Boolean);
    }

    normalizeItemDefinition(item) {
        if (!item || typeof item !== 'object' || !item.type) return null;

        const parseRangeValue = (value) => {
            if (Array.isArray(value)) {
                return value.map(Number);
            }

            if (typeof value === 'string' && /^\d+\s*-\s*\d+$/.test(value)) {
                const [min, max] = value.split('-').map(part => Number(part.trim()));
                return [min, max];
            }

            const numericValue = Number(value);
            return Number.isFinite(numericValue) ? numericValue : value;
        };

        const normalizedType = this._sanitizeItemToken(item.type).toUpperCase();
        let variant = this._sanitizeItemToken(item.variant ?? 'default');
        let quantity = parseRangeValue(this._sanitizeItemToken(item.quantity ?? 1));
        const probability = Number(this._sanitizeItemToken(item.probability ?? 1));
        const parsedVariant = parseRangeValue(variant);

        if (!normalizedType) {
            console.warn('[TreasureChestMapObject] Ignoring item with empty type:', item);
            return null;
        }

        // Chest shorthand like {COIN, 100} or {HEALTH, 10} — second slot is the amount, not a variant.
        if ((normalizedType === 'COIN' || normalizedType === 'HEALTH') &&
            (typeof parsedVariant === 'number' || Array.isArray(parsedVariant)) &&
            (item.quantity === undefined || item.quantity === null)) {
            quantity = parsedVariant;
            variant = normalizedType === 'COIN' ? 'coin' : 'health_orb';
        }

        if (typeof variant === 'string') {
            variant = ItemRegistry.resolveIdSync(variant) || variant;
        }

        const resolvedItemDefinition = typeof variant === 'string'
            ? ItemRegistry.getItemSync(variant)
            : null;
        const supportedSpecialTypes = new Set(['COIN', 'HEALTH']);
        const supportedInventoryTypes = new Set(['ITEM', 'FOOD', 'TOY', 'CROP', 'MEDICINE']);
        const normalizedInventoryType = resolvedItemDefinition?.type
            ? String(resolvedItemDefinition.type).toUpperCase()
            : null;

        if (supportedInventoryTypes.has(normalizedType) && !resolvedItemDefinition) {
            console.warn('[TreasureChestMapObject] Ignoring chest item with unknown inventory variant:', item);
            return null;
        }

        if (!supportedSpecialTypes.has(normalizedType) &&
            !supportedInventoryTypes.has(normalizedType) &&
            !MapObjectFactory.hasType(normalizedType)) {
            console.warn('[TreasureChestMapObject] Ignoring chest item with unsupported type:', item);
            return null;
        }

        if (supportedInventoryTypes.has(normalizedType) && normalizedInventoryType) {
            variant = resolvedItemDefinition.id;
        }

        if (!Number.isFinite(probability) || probability <= 0) {
            console.warn('[TreasureChestMapObject] Ignoring chest item with invalid probability:', item);
            return null;
        }

        return {
            type: supportedInventoryTypes.has(normalizedType) && normalizedInventoryType
                ? normalizedInventoryType
                : normalizedType,
            variant,
            quantity,
            probability
        };
    }

    getSidebarStatusRows() {
        return [
            { label: 'State', value: this.getChestStateLabel() },
            ...super.getSidebarStatusRows()
        ];
    }

    getSidebarDetailRows() {
        return [
            { label: 'Contents', value: this.hasLoot() ? 'Has Loot' : 'Empty' },
            ...super.getSidebarDetailRows()
        ];
    }

    _sanitizeItemToken(value) {
        if (value == null) return value;
        if (Array.isArray(value)) {
            return value.map(entry => this._sanitizeItemToken(entry));
        }
        if (typeof value !== 'string') {
            return value;
        }

        const trimmed = value.trim();
        return trimmed.replace(/^['"]+|['"]+$/g, '');
    }

    /**
     * Whether the chest can take a deposit right now. An open chest has already
     * spilled what it held, so putting something in would either vanish or need
     * a second spill — closing it first is the honest answer.
     */
    canAcceptDeposit() {
        return this.active && this.state === 'closed';
    }

    // Copy for the refusal, so the caller does not have to guess why.
    getDepositRefusal() {
        if (!this.active) return 'This chest is not ready.';
        if (this.state !== 'closed') return 'Close the chest first.';
        return null;
    }

    /**
     * Put an inventory item into the chest.
     *
     * Contents are stored as loot definitions rather than live objects, which
     * is the same shape authored loot already uses — so a deposited item spills
     * out the same way when a Myte pries the chest open, and rides through
     * `serializeState` with no extra persistence of its own.
     */
    depositItem({ variant, type, quantity = 1 } = {}) {
        if (!this.canAcceptDeposit()) return false;

        const definition = ItemRegistry.getItemSync(variant);
        const entry = this.normalizeItemDefinition({
            type: this._chestTypeForItem(definition, type),
            variant: definition?.id || variant,
            quantity: Math.max(1, Number(quantity) || 1)
        });
        if (!entry) return false;

        // A deposit is a certainty, not a drop chance, so it merges only with
        // other certainties — folding it into an authored 30% roll would make
        // the player's own item a coin flip.
        const existing = this.items.find(item =>
            item.type === entry.type &&
            item.variant === entry.variant &&
            item.probability === 1 &&
            Number.isFinite(item.quantity));

        if (existing) existing.quantity += entry.quantity;
        else this.items.push(entry);

        this.playConfiguredSound('drop');
        this.gameMap?.particleSystem?.burstEffectAtObject(this, 'SPARKLE', { count: 8, spread: 30 });
        return true;
    }

    // Coins and health orbs are chest shorthand types rather than inventory
    // types; everything else deposits under its registry type.
    _chestTypeForItem(definition, fallbackType) {
        const id = definition?.id;
        if (id === 'coin') return 'COIN';
        if (id === 'health_orb') return 'HEALTH';
        return String(definition?.type || fallbackType || 'item').toUpperCase();
    }

    // Storing the chest itself keeps the box and drops the contents on the
    // floor of the inventory — which is to say, loses them.
    getStorageResetWarning() {
        return this.hasLoot()
            ? 'Packing this chest away empties it. Open it first if you want what is inside.'
            : null;
    }

    open(parent) {
        if (this.state !== 'closed') return false;
        this.playConfiguredSound('open');

        return this.playStateTransition('opening', 'opened', {
            afterChange: () => {
                this.spawnItems(parent);
            }
        });
    }

    close(parent) {
        if (this.state !== 'opened' || !this.canClose) return false;
        this.playConfiguredSound('close');
        return this.playStateTransition('closing', 'closed');
    }

    isWithinChestInteractionRange(myte = this.activeMyte) {
        if (!myte) return false;
        return this.getColliderGapTo(myte) <= this.getConfig('interactionTouchThreshold', 12);
    }

    runChestInteraction(action, myte = this.activeMyte, options = {}) {
        if (!this.active || !myte || typeof action !== 'function') return false;

        this.selectInUi?.();

        const { postActionIdleDuration = 0, ...approachOptions } = options;
        const wrappedAction = (m) => {
            action(m);
            if (postActionIdleDuration > 0) {
                m?.queue?.addIdle(postActionIdleDuration);
            }
        };

        if (this.isWithinChestInteractionRange(myte)) {
            wrappedAction(myte);
            return true;
        }

        return this.enqueueApproach(myte, () => {
            if (this.isWithinChestInteractionRange(myte)) {
                wrappedAction(myte);
            }
        }, approachOptions);
    }

    press(parent, actor = this.activeMyte) {
        const myte = actor;
        if (!this.active || !myte) return false;

        if (this.state === 'closed') {
            return this.runChestInteraction(() => {
                this.open(parent);
            }, myte, {
                queueVerb: 'Open Chest',
                userInitiated: true,
                postActionIdleDuration: 350
            });
        }

        if (this.state === 'opened' && this.canClose) {
            return this.runChestInteraction(() => {
                this.close(parent);
            }, myte, {
                queueVerb: 'Close Chest',
                userInitiated: true,
                postActionIdleDuration: 400
            });
        }

        return false;
    }

    runDebugDirectInteraction(parent = this.container ?? this.parent) {
        if (!this.active) return false;

        this.selectInUi?.();

        if (this.state === 'closed') {
            return this.open(parent);
        }

        if (this.state === 'opened' && this.canClose) {
            return this.close(parent);
        }

        return false;
    }
    
    spawnItems(parent) {
        const itemsToSpawn = this.normalizeItems(this.items);
        if (!itemsToSpawn.length) return;

        const itemConfigs = itemsToSpawn.map(item => this.createDroppedItemConfig(item));
        this.spawnDroppedInventoryItems(
            itemConfigs,
            {
                parent,
                localCollection: this.droppedItems
            }
        );

        this.playConfiguredSound('drop');
        this.gameMap?.particleSystem?.burstEffectAtObject(this, 'SPARKLE', { count: 24, spread: 70 });
        this.gameMap?.eventManager?.emit(EVENTS.CHEST_OPENED, { chest: this, items: itemConfigs });

        this.items = [];
    }

    createDroppedItemConfig(item) {
        const resolvedQuantity = Array.isArray(item.quantity)
            ? Utility.randomInt(item.quantity[0], item.quantity[1])
            : Math.max(1, Number(item.quantity) || 1);
        const itemDefinition = ItemRegistry.getItemSync(item.variant);
        if (!itemDefinition) {
            console.warn(`[TreasureChestMapObject] Spawning dropped item with no registry entry: "${item.variant}"`);
        }

        return {
            type: item.type,
            variant: item.variant,
            quantity: resolvedQuantity
        };
    }

    update(deltaTime) {
        super.update(deltaTime);
        this.droppedItems = this.pruneDroppedItemCollection(this.droppedItems);
    }

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('treasure-chest', this.state);
        return element;
    }

    serializeState() {
        return { state: this.state, items: Utility.deepClone(this.items) };
    }

    restoreState(data = {}) {
        this.state = data.state ?? this.state;
        this.items = this.normalizeItems(data.items ?? this.items);
        this.updateElementState();
    }





    


      getAiAffordances(context = {}, actor = null) {
        const affordances = super.getAiAffordances(context, actor).filter(affordance => {
          if ((affordance.actionId === 'inspect' || affordance.actionId === 'deep_inspect') &&
              (this.state !== 'closed' || this.items.length === 0)) {
            return false;
          }
          return true;
        });

        if (this.state === 'closed' && this.hasLoot()) {
          affordances.push({ actionId: 'open_chest', purpose: 'open' });
        }

        return affordances;
      }







}
;
/* -- js/Map/MapObjects/Interactive/PortalMapObject.js -- */
class PortalMapObject extends InteractiveMapObject {
	hasGeneratedVisual() {
		return this.usesFallbackVisual === true;
	}

    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);

        this.targetMap = options.targetMap ?? this.getConfig('targetMap', null);
        this.targetSpawnPoint = options.targetSpawnPoint ?? this.getConfig('targetSpawnPoint', null);
        this.targetPortalId = options.targetPortalId ?? this.getConfig('targetPortalId', null);
        this.portalId = String(
            options.portalId ??
            this.getConfig('portalId', options.id ?? `${type}_${variant}_${posX}_${posY}`)
        );
        this.isActive = options.isActive ?? this.getConfig('isActive', true);
        this.activationRadius = options.activationRadius ?? this.getConfig('activationRadius', 75);
        this.transitionDuration = options.transitionDuration ?? this.getConfig('transitionDuration', 1000);

        this.isAnimating = false;
        this.particleSystem = null;
        this.usesFallbackVisual = false;

        this.applyFallbackPortalVisualConfig();

        this.initializePortalEffects();
    }

    applyFallbackPortalVisualConfig() {
        const spriteSheetUrl = this.getVisualSpriteSheet()?.url || '';
        if (!spriteSheetUrl) {
            this.usesFallbackVisual = true;
            return;
        }

        if (!spriteSheetUrl.includes('portal.png')) {
            return;
        }

        if (this.config?.visual?.spriteSheet) {
            this.config.visual.spriteSheet.url = '';
        }

        if (this.config?.spriteConfig?.spriteSheet) {
            this.config.spriteConfig.spriteSheet.url = '';
        }

        this.usesFallbackVisual = true;
    }

    getApproachActionId() {
        return 'go_to_object';
    }

    getApproachMode() {
        return 'center';
    }

    getInteractionRadius() {
        return this.activationRadius;
    }

    getPortalCooldownDuration() {
        return this.getConfig('portalCooldownDuration', 1500);
    }

    canTransitionMyte(myte) {
        if (!myte) return false;
        if (myte.isDragging) return false;
        return (myte.portalCooldownUntil || 0) <= SimClock.now();
    }

    getPortalReferenceId() {
        return String(this.portalId || this.id || '');
    }

    getResolvedTargetMapId() {
        if (this.targetMap) {
            return this.targetMap;
        }

        if (this.targetPortalId || this.targetSpawnPoint) {
            return this.gameMap?.id || null;
        }

        return null;
    }

    hasTransitionDestination() {
        return !!(this.targetMap || this.targetSpawnPoint || this.targetPortalId);
    }

    getTransitionRect(alignTo = 'sprite') {
        if (alignTo === 'collider' && this.collider) {
            return {
                x: this.posX + (this.collider.offsetX || 0),
                y: this.posY + (this.collider.offsetY || 0),
                width: this.collider.width || this.size.width,
                height: this.collider.height || this.size.height
            };
        }

        return {
            x: this.posX,
            y: this.posY,
            width: this.size.width,
            height: this.size.height
        };
    }

    getPortalCenter(alignTo = 'sprite') {
        const rect = this.getTransitionRect(alignTo);
        return {
            x: rect.x + rect.width / 2,
            y: rect.y + rect.height / 2
        };
    }

    getCenteredPositionFor(myte, alignTo = 'sprite') {
        const center = this.getPortalCenter(alignTo);
        return {
            x: center.x - ((myte?.size?.width || 0) / 2),
            y: center.y - ((myte?.size?.height || 0) / 2)
        };
    }

    getExitPositionFor(myte) {
        return this.getCenteredPositionFor(myte, this.getConfig('transitionAlignTo', 'sprite'));
    }

    initializePortalEffects() {
        if (this.gameMap?.particleSystem && this.getConfig('particleEffects', true)) {
            const particleConfig = this.getConfig('particleConfig', {});
            const effectName = particleConfig.particleEffect || 'GLOW';

            this.particleSystem = this.gameMap.particleSystem.addEffect(this, effectName, {
                ...particleConfig,
                colors: [
                    this.getConfig('particleStartColor', '#8A2BE2'),
                    this.getConfig('particleEndColor', '#4B0082')
                ],
                count: this.isActive ? 1 : 0,
                randomizePosition: true,
                randomizeFactor: 20
            });
        }
    }

    playPortalSound(type) {
        const soundEffect = this.getConfig(`soundEffects.${type}`);
        if (soundEffect && this.gameMap?.soundManager) {
            this.gameMap.soundManager.play(soundEffect, { source: this });
        }
    }

    press(parent) {
        if (!this.active || this.isAnimating || !this.isActive || !this.hasTransitionDestination()) return false;

        const myte = this.activeMyte;
        if (!myte || !this.canTransitionMyte(myte)) return false;

        return this.runInteractionWhenInRange(() => {
            this.beginTransition(myte);
        }, myte);
    }

    runDebugDirectInteraction() {
        if (!this.active || this.isAnimating || !this.isActive || !this.hasTransitionDestination()) {
            return false;
        }

        this.selectInUi?.();
        this.beginTransition(null);
        return true;
    }

    checkProximityActivation(myte) {
        if (!this.isActive || !myte || !this.hasTransitionDestination() || this.isAnimating || !this.canTransitionMyte(myte)) return;

        if (this.isInInteractionRange(myte, this.activationRadius)) {
            this.beginTransition(myte);
        }
    }

    beginTransition(myte) {
        const targetMapId = this.getResolvedTargetMapId();
        if (this.isAnimating || !this.isActive || !targetMapId) return;

        this.isAnimating = true;
        this.isActive = false;
        if (myte) {
            myte.portalCooldownUntil = SimClock.now() + this.transitionDuration + this.getPortalCooldownDuration();
        }

        this.playPortalSound('depart');

        if (this.hasAnimation('activate')) {
            this.playAnimation('activate');
        }

        const container = this.container;
        const transitionCopy = this.getPortalTransitionCopy();

        if (container.transitionManager) {
            container.transitionManager.startTransition({
                targetMap: targetMapId,
                targetSpawnPoint: this.targetSpawnPoint,
                targetPortalId: this.targetPortalId,
                sourceMapId: this.gameMap?.id ?? null,
                sourcePortalId: this.getPortalReferenceId(),
                duration: this.transitionDuration,
                message: transitionCopy.message,
                transitionTitle: transitionCopy.title,
                transitionDescription: transitionCopy.description,
                myte,
                sourcePortal: this,
                onComplete: () => {
                    this.isAnimating = false;
                    this.isActive = true;
                }
            });
            return;
        }

        container.loadMap(targetMapId).then(() => {
            this.isAnimating = false;
            this.isActive = true;

            if (myte && container.gameMap) {
                const portalPosition = this.targetPortalId
                    ? container.gameMap.objects.find(obj =>
                        obj instanceof PortalMapObject &&
                        obj.getPortalReferenceId?.() === String(this.targetPortalId)
                    )?.getCenteredPositionFor?.(myte)
                    : null;
                const spawnPoint = this.targetSpawnPoint
                    ? container.gameMap.getSpawnPoint(this.targetSpawnPoint)
                    : container.gameMap.getSpawnPoint('myte');
                const position = portalPosition || spawnPoint;

                if (position) {
                    myte.setPosition(position.x, position.y);
                    myte.setTarget(position.x, position.y);
                    myte.setSpritePosition(position.x, position.y);
                }
            }
        });
    }

    handleDoubleClick(event) {
        if (!this.activeMyte) {
            if (!this.active || this.isAnimating || !this.isActive || !this.hasTransitionDestination()) {
                return;
            }

            event?.originalEvent?.preventDefault?.();
            this.selectInUi?.();
            this.beginTransition(null);
            return;
        }

        super.handleDoubleClick(event);
    }

    getPortalWindowTitle() {
        return this.getDisplayName();
    }

    getAffordanceTooltipTitle() {
        const destination = this.getPortalWindowTitle();
        return destination.toLowerCase().startsWith('portal')
            ? destination
            : `Portal to ${destination}`;
    }

    getFallbackAffordanceTooltipAction() {
        return this.getActionConfig?.('interact_object')?.label ?? 'Use Portal';
    }

    getDisplayName() {
        if (this.targetMap) {
            const mapLoader = this.core?.mapLoader;
            return mapLoader?.getCachedMapDisplayName?.(this.targetMap) ||
                mapLoader?.humanizeMapId?.(this.targetMap) ||
                String(this.targetMap);
        }

        const explicitName = this.getConfig('label', null);
        if (typeof explicitName === 'string' && explicitName.trim()) {
            return explicitName.trim();
        }

        const fallback = super.getDisplayName?.();
        if (fallback && fallback !== 'Default') {
            return fallback;
        }

        return 'Portal';
    }

    getPortalTransitionMessage() {
        return `Traveling to ${this.getPortalWindowTitle()}...`;
    }

    getPortalTransitionDescription() {
        return this.targetMap
            ? `Traveling to ${this.getPortalWindowTitle()}...`
            : 'Traveling...';
    }

    getPortalTransitionCopy() {
        return {
            title: this.getPortalWindowTitle(),
            message: this.getPortalTransitionMessage(),
            description: this.getPortalTransitionDescription()
        };
    }

    updatePortalStateClasses() {
        if (!this.element) return;
        this.element.classList.toggle('active', this.isActive);
        this.element.classList.toggle('inactive', !this.isActive);
    }

    syncPortalWindowTitle() {
        const titleElement = this.element?.querySelector('.portal-window .portal-panel__title');
        if (!titleElement) return;

        const nextTitle = this.getPortalWindowTitle();
        if (titleElement.textContent !== nextTitle) {
            titleElement.textContent = nextTitle;
        }
        titleElement.title = this.areInteractionHintsEnabled() ? this.getInteractionHint() : '';
    }

    getInteractionHint() {
        const destination = this.getPortalWindowTitle();
        const activeMyte = this.activeMyte;
        return activeMyte
            ? `Double-click to send ${activeMyte.name} to ${destination}.`
            : `Double-click to open ${destination}.`;
    }

    syncInteractionHint() {
        if (!this.element) return;
        const hint = this.getInteractionHint();
        this.element.title = this.areInteractionHintsEnabled() ? hint : '';
        this.element.setAttribute('aria-label', hint);
        this.element.dataset.userNavigable = String(!this.activeMyte);
    }

    updatePortalDom({ refreshTitle = false } = {}) {
        if (!this.element) return;

        this.element.classList.add('portal');
        this.updatePortalStateClasses();
        this.ensurePortalWindow();
        this.syncPortalWindowTitle();
        this.syncInteractionHint();

        if (this.targetMap) {
            this.element.dataset.targetMap = this.targetMap;
        } else {
            delete this.element.dataset.targetMap;
        }

        if (refreshTitle) {
            this.refreshPortalWindowTitle();
        }
    }

    ensurePortalWindow() {
        if (!this.element || this.element.querySelector('.portal-window')) return;

        const portal = document.createElement('div');
        portal.className = 'portal-window';

        const title = document.createElement('div');
        title.className = 'portal-panel__title';
        title.textContent = this.getPortalWindowTitle();
        title.title = this.areInteractionHintsEnabled() ? this.getPortalWindowTitle() : '';

        const content = document.createElement('div');
        content.className = 'content portal-panel__content';
        const portalWindowBackground = this.getConfig('portalWindowBackground', '');
        if (portalWindowBackground) {
            content.style.backgroundImage = `url(${portalWindowBackground})`;
        } else {
            // content.style.backgroundImage = 'radial-gradient(circle at center, rgba(255,255,255,0.35), rgba(138,43,226,0.65) 45%, rgba(75,0,130,0.92) 100%)';
        }

        portal.appendChild(title);
        portal.appendChild(content);
        this.element.appendChild(portal);
        this.refreshPortalWindowTitle();
    }

    refreshPortalWindowTitle() {
        this.syncPortalWindowTitle();

        if (!this.targetMap || !this.core?.mapLoader?.getMapDisplayName) {
            return;
        }

        this.core.mapLoader.getMapDisplayName(this.targetMap).then(displayName => {
            if (!displayName) return;

            const liveTitleElement = this.element?.querySelector('.portal-window .portal-panel__title');
            if (!liveTitleElement) return;

            liveTitleElement.textContent = displayName;
            liveTitleElement.title = this.areInteractionHintsEnabled() ? this.getInteractionHint() : '';
        }).catch(error => {
            Utility.warnDebug(`[PortalMapObject] Failed to refresh portal title for ${this.targetMap}:`, error);
        });
    }

    render(container, parent) {
        const element = super.render(container, parent);

        if (this.usesFallbackVisual) {
            const spriteElement = element.querySelector('.sprite');
            if (spriteElement) {
                // spriteElement.style.backgroundImage = 'radial-gradient(circle at center, rgba(255,255,255,0.6) 0%, rgba(173,216,230,0.55) 20%, rgba(138,43,226,0.9) 55%, rgba(75,0,130,0.95) 100%)';
                // spriteElement.style.borderRadius = '50%';
                // spriteElement.style.boxShadow = '0 0 28px rgba(138, 43, 226, 0.55), inset 0 0 18px rgba(255,255,255,0.28)';
            }
        }

        this.updatePortalDom({ refreshTitle: true });

        return element;
    }

    tickUpdate(tickDelta) {
        super.tickUpdate(tickDelta);

        if (this.isActive && !this.getConfig('interactionOnly', false) && this.activeMyte) {
            this.checkProximityActivation(this.activeMyte);
        }
    }

    update(deltaTime) {
        super.update(deltaTime);
        this.updatePortalDom();

        if (this.particleSystem?.setEnabled) {
            this.particleSystem.setEnabled(this.isActive);
        } else if (this.particleSystem) {
            this.particleSystem.active = this.isActive;
        }
    }

    remove() {
        if (this.particleSystem) {
            if (typeof this.particleSystem.destroy === 'function') {
                this.particleSystem.dispose();
            } else {
                this.particleSystem.active = false;
            }
            this.particleSystem = null;
        }

        super.remove();
    }

    wake() {
        super.wake();
        this.updatePortalDom();
    }
}
