/* -- js/Map/MapObjects/Barrier/WallOpeningPlacement.js -- */
const withWallOpeningPlacement = BaseClass => class extends BaseClass {
    getRenderZIndex() {
        if (Number.isFinite(this._attachmentRenderZIndex)) return super.getRenderZIndex();
        return this.gameMap?.wallBuilder?.getOpeningRenderZIndex(this, this.posX, this.posY) ??
            super.getRenderZIndex();
    }

    getGridOccupancyBounds(x = this.posX, y = this.posY) {
        return this.gameMap?.wallBuilder?.getOpeningPlacementBounds(this, x, y) || null;
    }

    /**
     * Culling has to use the sprite, not the footprint. An opening occupies one
     * cell row but its art stands the full height of the wall above it, so
     * culling on the footprint drops the sprite as soon as that thin band
     * leaves the camera — while most of the window is still on screen.
     */
    getCullingBounds(x = this.posX, y = this.posY) {
        const frame = this.getVisualFrameSize?.() || null;
        const width = Math.max(this.size.width, Number(frame?.width) || 0);
        const height = Math.max(this.size.height, Number(frame?.height) || 0);
        const sprite = { x, y: y - (height - this.size.height), width, height };
        const footprint = this.getGridOccupancyBounds(x, y);
        if (!footprint) return sprite;

        const left = Math.min(sprite.x, footprint.x);
        const top = Math.min(sprite.y, footprint.y);
        return {
            x: left,
            y: top,
            width: Math.max(sprite.x + sprite.width, footprint.x + footprint.width) - left,
            height: Math.max(sprite.y + sprite.height, footprint.y + footprint.height) - top
        };
    }

    clampPlacementPosition(x, y) {
        return this.gameMap?.wallBuilder?.resolveOpeningPlacement(this, x, y)?.position || { x, y };
    }

    checkDropValidity(x, y) {
        return this.gameMap?.wallBuilder?.canPlaceOpeningObject(this, x, y) === true;
    }

    restoreInvalidDropToOrigin() {
        return true;
    }

    onPlacementDragStart() {
        this.gameMap?.wallBuilder?.beginOpeningMove(this);
    }

    onPlacementDragMove() {
        this.gameMap?.wallBuilder?.refreshMovingObjectReveal(this);
    }

    onPlacementDragEnd() {
        return this.gameMap?.wallBuilder?.finishOpeningMove(this) === true;
    }

    // Dropped into the inventory rather than back onto a wall: the opening is
    // gone for good, so just let go of it.
    onPlacementStored() {
        this.gameMap?.wallBuilder?.cancelOpeningMove(this);
    }

    // Leaving the map by any route — stored from the action sidebar, discarded
    // because placement failed — must fill the hole back in. An opening whose
    // object is gone is a cutout nothing sits in and nothing can be placed
    // over, and it persists into the save.
    remove() {
        this.gameMap?.wallBuilder?.releaseObject(this);
        super.remove();
    }

    /**
     * Presentation contract with the wall that hosts this opening.
     *
     * A door or window is a thing in its own right, not decoration painted on
     * the wall, so lowering the wall must not delete it — you still need to see
     * where the room's exits are. It therefore keeps drawing at full size; the
     * hook stays so a construction whose openings really are wall-height can
     * clip them later. Collision, walkability and line of sight are untouched
     * either way.
     */
    applyWallCut() {
        if (this.element) this.element.style.clipPath = '';
    }
};
;
/* -- js/Map/MapObjects/Barrier/WallFixturePlacement.js -- */
/**
 * Placement behaviour for objects that hang on a wall's face — paintings and
 * anything else mounted flat against a wall rather than cut through it.
 *
 * The counterpart to `withWallOpeningPlacement`: an opening occupies wall cells
 * and interrupts the wall, a fixture occupies none and merely rides on it. So
 * where an opening snaps to a cell footprint, a fixture snaps to a point on a
 * face — free along the wall, free up and down it, but never off it.
 */
const withWallFixturePlacement = BaseClass => class extends BaseClass {
    getWallBuilder() {
        return this.gameMap?.wallBuilder || null;
    }

    // Deliberately the candidate rather than the resolved placement: a fixture
    // dragged over an occupied patch of wall is still in front of that wall.
    // Sorting an invalid position by the floor rule instead drops it behind the
    // wall art, so the painting blinks out mid-drag and returns on release.
    getRenderZIndex() {
        if (Number.isFinite(this._attachmentRenderZIndex)) return super.getRenderZIndex();
        const placement = this.getWallBuilder()?.getFixturePlacementCandidate(this, this.posX, this.posY);
        return placement
            ? this.gameMap.getDepthZIndex(placement.piece.baseline) + 1
            : super.getRenderZIndex();
    }

    // A fixture is mounted on a wall, not standing on the floor: it occupies no
    // grid cell and must never take part in collision or pathfinding.
    getGridOccupancyBounds() {
        return null;
    }

    getCullingBounds(x = this.posX, y = this.posY) {
        return { x, y, width: this.size.width, height: this.size.height };
    }

    clampPlacementPosition(x, y) {
        return this.getWallBuilder()?.resolveFixturePlacement(this, x, y)?.position || { x, y };
    }

    checkDropValidity(x, y) {
        return this.getWallBuilder()?.canPlaceFixtureObject(this, x, y) === true;
    }

    restoreInvalidDropToOrigin() {
        return true;
    }

    onPlacementDragStart() {
        this.getWallBuilder()?.beginFixtureMove(this);
    }

    onPlacementDragMove() {
        this.getWallBuilder()?.refreshMovingObjectReveal(this);
    }

    onPlacementDragEnd() {
        return this.getWallBuilder()?.finishFixtureMove(this) === true;
    }

    // Dropped into the inventory rather than back onto a wall.
    onPlacementStored() {
        this.getWallBuilder()?.cancelFixtureMove(this);
    }

    // Leaving the map by any route — stored from the action sidebar, discarded
    // because placement failed — must hand the patch of wall back, or it stays
    // reserved for an object that no longer exists.
    remove() {
        this.getWallBuilder()?.releaseObject(this);
        super.remove();
    }

    // Presentation contract with the wall behind it: the SAME rule the authored
    // decorations use, so the two paths cannot drift apart again. The record,
    // the socket attachment and the authored u/v are untouched - only what is
    // drawn changes.
    applyWallCut(cutY) {
        WallBuilder.applyFixtureCut(this.element, cutY, this.posY, this.size?.height ?? 0);
    }
};

class WallFixtureMapObject extends withWallFixturePlacement(MapObject) {
    getBaseCssClass() {
        return 'wall-fixture';
    }
}
;
/* -- js/Map/MapObjects/Barrier/FencePostPlacement.js -- */
/**
 * withFencePostPlacement — placement behaviour for a thing that drops into a
 * fence line: a gate.
 *
 * The counterpart to the wall-opening mixin. A gate snaps to the fence grid,
 * may land on a cell that already holds a fence (that fence is the thing it
 * replaces), and on release hands off to FenceBuilder.settlePost to pull the
 * replaced fence into the inventory and re-point the neighbours.
 *
 * Undo of the drag itself is the ordinary map-object move command; the fence it
 * displaced is restored by settlePost's own history entry sitting under it.
 */
const withFencePostPlacement = BaseClass => class extends BaseClass {
    get fenceBuilder() {
        return this.gameMap?.fenceBuilder || null;
    }

    _fenceCell(x = this.posX, y = this.posY) {
        return this.fenceBuilder?.cellForObject(this, x, y) || null;
    }

    clampPlacementPosition(x, y) {
        const builder = this.fenceBuilder;
        if (!builder) return { x, y };
        const cell = builder.cellForObject(this, x, y);
        return builder.worldPosForObject(this, cell.x, cell.y);
    }

    getGridOccupancyBounds(x = this.posX, y = this.posY) {
        const builder = this.fenceBuilder;
        if (!builder) {
            return super.getGridOccupancyBounds?.(x, y) ?? null;
        }
        const cs = builder.cellSize;
        const cell = builder.cellForObject(this, x, y);
        return { x: cell.x * cs, y: cell.y * cs, width: cs, height: cs };
    }

    checkDropValidity(x, y) {
        const builder = this.fenceBuilder;
        if (!builder) return super.checkDropValidity ? super.checkDropValidity(x, y) : true;
        const cell = builder.cellForObject(this, x, y);
        return builder.canHostPost(cell.x, cell.y, this) === true;
    }

    restoreInvalidDropToOrigin() {
        return true;
    }

    // Also the inventory placement path: Inventory.placeInventoryItem creates
    // the object and then trusts onPlacementDragEnd's verdict, without a
    // clampPlacementPosition or checkDropValidity call of its own.
    onPlacementDragEnd() {
        const builder = this.fenceBuilder;
        if (!builder) return super.onPlacementDragEnd ? super.onPlacementDragEnd() : true;

        const snapped = this.clampPlacementPosition(this.posX, this.posY);
        this.posX = snapped.x;
        this.posY = snapped.y;
        this.updatePosition?.();

        const cell = builder.cellForObject(this);
        if (!builder.canHostPost(cell.x, cell.y, this)) return false;
        builder.settlePost(this, cell);
        return true;
    }

    // Whatever route it leaves by, the fences it was connecting need to redraw.
    remove() {
        this._notifyFenceNeighbors?.();
        super.remove();
    }
};
