/* -- js/Map/MapObjects/GrowingPlant/TreeMapObject.js -- */
class TreeMapObject extends GrowingPlantMapObject {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);

        // Override growth stages for trees
        this.stages = ['seed', 'sprout', 'half_grown', 'grown'];

        // Shake-to-harvest state
        this.shakeCooldown = this.getConfig('shakeConfig.cooldown', 30000);
        this._shakeElapsed = Number.isFinite(options._shakeElapsed) ? options._shakeElapsed : this.shakeCooldown;
        this.shakeItemDrops = this.getConfig('shakeConfig.drops', []);
        this.minShakeYield = this.getConfig('shakeConfig.yield.min', 1);
        this.maxShakeYield = this.getConfig('shakeConfig.yield.max', 3);

        // Chop state
        this.chopItemDrops = this.getConfig('chopConfig.drops', []);
        this.minChopYield = this.getConfig('chopConfig.yield.min', 2);
        this.maxChopYield = this.getConfig('chopConfig.yield.max', 5);
    }

    // ── capability checks ────────────────────────────────────────────────────

    isGrown() {
        return this.growthStage === 'grown' && !this.fullyGrown === false;
    }

    canShake() {
        return this.growthStage === 'grown' && this._shakeElapsed >= this.shakeCooldown;
    }

    canChop() {
        return this.growthStage === 'grown';
    }

    // ── actions ──────────────────────────────────────────────────────────────

    shake() {
        if (!this.canShake()) return false;

        this._shakeElapsed = 0;
        this.playAnimation('shake', () => this.playAnimation('grown'));

        const drops = this._rollDrops(this.shakeItemDrops, this.minShakeYield, this.maxShakeYield);
        drops.forEach(drop => this.spawnDroppedInventoryItem(drop, { parent: this.container ?? this.parent }));
        this.playConfiguredSound?.('shake');

        return true;
    }

    chop() {
        if (!this.canChop()) return false;

        this.playAnimation('chop', () => this._transformToStump());
        this.playConfiguredSound?.('chop');

        return true;
    }

    _transformToStump() {
        const map = this.gameMap ?? this.parent;
        if (!map) return;

        const stump = MapObjectFactory.create(
            'TREE_STUMP',
            this.variant ? `${this.variant}_stump` : 'stump',
            this.posX,
            this.posY,
            map,
            { configOverrides: this.getConfig('chopConfig.stumpConfig', {}) }
        );

        if (stump) {
            // Drop chop items before removing the tree
            const drops = this._rollDrops(this.chopItemDrops, this.minChopYield, this.maxChopYield);
            drops.forEach(drop => this.spawnDroppedInventoryItem(drop, { parent: this.container ?? this.parent }));

            map.addObject(stump);
        }

        this.remove();
    }

    // ── time skip ────────────────────────────────────────────────────────────

    onTimeSkip(realMs) {
        super.onTimeSkip(realMs);
        this._shakeElapsed = Math.min(this._shakeElapsed + realMs, this.shakeCooldown);
    }

    // ── tick ─────────────────────────────────────────────────────────────────

    tickUpdate(tickDelta) {
        super.tickUpdate(tickDelta);

        if (this.growthStage === 'grown' && this._shakeElapsed < this.shakeCooldown) {
            this._shakeElapsed = Math.min(this._shakeElapsed + tickDelta, this.shakeCooldown);
        }
    }

    // ── interaction ──────────────────────────────────────────────────────────

    press(parent) {
        const myte = this.activeMyte;
        if (!myte) return false;

        if (this.growthStage !== 'grown') {
            if (!this.canWater()) return false;
            return this.runInteractionWhenInRange(() => this.water(), myte, {
                queueVerb: 'Water Tree',
                userInitiated: true
            });
        }

        if (this.canShake()) {
            return this.runInteractionWhenInRange(() => this.shake(), myte, {
                queueVerb: 'Shake Tree',
                userInitiated: true,
                postActionIdleDuration: 1200
            });
        }

        return false;
    }

    handleDoubleClick(event) {
        const myte = this.activeMyte;
        if (!myte || !this.canChop()) return false;

        return this.runInteractionWhenInRange(() => this.chop(), myte, {
            queueVerb: 'Chop Tree',
            userInitiated: true,
            postActionIdleDuration: 1200
        });
    }

    runDebugDirectInteraction(parent = this.container ?? this.parent) {
        if (!this.active) return false;
        this.selectInUi?.();

        if (this.growthStage !== 'grown') {
            if (this.canWater()) { this.water(); return true; }
            return false;
        }

        if (this.canShake()) return this.shake();
        return false;
    }

    // ── render ───────────────────────────────────────────────────────────────

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('tree');
        element.dataset.treeStage = this.growthStage;
        return element;
    }

    getSaveData() {
        return { ...super.getSaveData(), _shakeElapsed: this._shakeElapsed };
    }

    restoreFromSaveData(data = {}) {
        super.restoreFromSaveData(data);
        if (Number.isFinite(data._shakeElapsed)) this._shakeElapsed = data._shakeElapsed;
    }

    // ── info ─────────────────────────────────────────────────────────────────

    getSidebarDetailRows() {
        const rows = [...(super.getSidebarDetailRows?.() ?? [])];

        if (this.growthStage === 'grown') {
            const cooldownRemaining = Math.max(0, this.shakeCooldown - this._shakeElapsed);
            rows.push({ label: 'Shake Ready', value: cooldownRemaining <= 0 ? 'Yes' : `${Math.ceil(cooldownRemaining / 1000)}s` });
        }

        return rows;
    }
}
;
/* -- js/Map/MapObjects/GrowingPlant/FruitTreeMapObject.js -- */
class FruitTreeMapObject extends TreeMapObject {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);

        this.hasFruit = false;
        this._fruitRegrowthElapsed = 0;
        this.fruitRegrowthTime = this.getConfig('fruitConfig.regrowthTime', 300000);
        this.readyOnFirstGrown = this.getConfig('fruitConfig.readyOnFirstGrown', true);
        this.fruitDrops = this.getConfig('fruitConfig.drops', this.shakeItemDrops);
        this.minFruitYield = this.getConfig('fruitConfig.yield.min', this.minShakeYield);
        this.maxFruitYield = this.getConfig('fruitConfig.yield.max', this.maxShakeYield);

        // Fruit readiness is tracked via hasFruit — disable the base shake cooldown
        this.shakeCooldown = 0;
        this._shakeElapsed = 0;
    }

    // ── capability checks ────────────────────────────────────────────────────

    canShake() {
        return this.growthStage === 'grown' && this.hasFruit;
    }

    serializeState() {
        return {
            ...super.serializeState(),
            hasFruit: this.hasFruit,
            fruitRegrowthElapsed: this._fruitRegrowthElapsed
        };
    }

    restoreState(data = {}) {
        super.restoreState(data);
        this.hasFruit = data.hasFruit === true;
        this._fruitRegrowthElapsed = Utility.clamp(
            Number(data.fruitRegrowthElapsed) || 0,
            0,
            this.fruitRegrowthTime
        );
        this._updateFruitVisuals();
    }

    // ── growth callback ──────────────────────────────────────────────────────

    onGrowthStageComplete(stage) {
        if (stage === 'grown' && this.readyOnFirstGrown) {
            this.hasFruit = true;
            this._fruitRegrowthElapsed = this.fruitRegrowthTime;
            this._updateFruitVisuals();
        }
    }

    // ── actions ──────────────────────────────────────────────────────────────

    shake() {
        if (!this.canShake()) return false;

        this.hasFruit = false;
        this._fruitRegrowthElapsed = 0;
        this._updateFruitVisuals();

        this.playAnimation('shake', () => this.playAnimation('grown'));

        const drops = this._rollDrops(this.fruitDrops, this.minFruitYield, this.maxFruitYield);
        drops.forEach(drop => this.spawnDroppedInventoryItem(drop, { parent: this.container ?? this.parent }));
        this.playConfiguredSound?.('shake');

        return true;
    }

    // ── fruit regrowth ───────────────────────────────────────────────────────

    _advanceFruitTimer(deltaMs) {
        if (this.growthStage !== 'grown' || this.hasFruit) return;

        this._fruitRegrowthElapsed = Math.min(
            this._fruitRegrowthElapsed + deltaMs,
            this.fruitRegrowthTime
        );

        if (this._fruitRegrowthElapsed >= this.fruitRegrowthTime) {
            this.hasFruit = true;
            this._updateFruitVisuals();
        }
    }

    _updateFruitVisuals() {
        if (!this.element) return;
        this.element.classList.toggle('has-fruit', this.hasFruit);
    }

    // ── time ─────────────────────────────────────────────────────────────────

    onTimeSkip(realMs) {
        super.onTimeSkip(realMs);
        this._advanceFruitTimer(realMs);
    }

    tickUpdate(tickDelta) {
        super.tickUpdate(tickDelta);
        this._advanceFruitTimer(tickDelta);
    }

    // ── render ───────────────────────────────────────────────────────────────

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('fruit-tree');
        if (this.hasFruit) element.classList.add('has-fruit');
        return element;
    }

    // ── info ─────────────────────────────────────────────────────────────────

    getSidebarDetailRows() {
        const rows = [];

        if (this.growthStage === 'grown') {
            if (this.hasFruit) {
                rows.push({ label: 'Fruit', value: 'Ready to pick' });
            } else {
                const remaining = Math.max(0, this.fruitRegrowthTime - this._fruitRegrowthElapsed);
                rows.push({ label: 'Fruit regrows in', value: `${Math.ceil(remaining / 1000)}s` });
            }
        }

        return rows;
    }
}
;
/* -- js/Map/MapObjects/GrowingPlant/TreeStumpMapObject.js -- */
class TreeStumpMapObject extends MapObject {
    constructor(parent, type, variant, posX, posY, config = {}, options = {}) {
        super(parent, type, variant, posX, posY, config, options);

        this.removeItemDrops = this.getConfig('removeConfig.drops', []);
        this.minRemoveYield = this.getConfig('removeConfig.yield.min', 1);
        this.maxRemoveYield = this.getConfig('removeConfig.yield.max', 2);
    }

    canRemoveStump() {
        return true;
    }

    removeStump() {
        if (!this.canRemoveStump()) return false;

        this.playAnimation('remove', () => this._finishRemoval());
        this.playConfiguredSound?.('remove');

        return true;
    }

    _finishRemoval() {
        const drops = this._rollDrops(this.removeItemDrops, this.minRemoveYield, this.maxRemoveYield);
        drops.forEach(drop => this.spawnDroppedInventoryItem(drop, { parent: this.container ?? this.parent }));
        this.remove();
    }

    press(parent) {
        const myte = this.activeMyte;
        if (!myte || !this.canRemoveStump()) return false;

        return this.runInteractionWhenInRange(() => this.removeStump(), myte, {
            queueVerb: 'Remove Stump',
            userInitiated: true,
            postActionIdleDuration: 1200
        });
    }

    runDebugDirectInteraction(parent = this.container ?? this.parent) {
        if (!this.active) return false;
        this.selectInUi?.();
        return this.removeStump();
    }

    render(container, parent) {
        const element = super.render(container, parent);
        element.classList.add('tree-stump');
        return element;
    }
}
