            objects: new Set(),
            tileWalkable: true,
            objectWalkable: true,
            walkable: true,
            swimmable: false,
            conditionallyWalkable: false,
            conditionType: null,
            conditionId: null,
            wallBlocksLineOfSight: false,
            terrainType: GridSystem.defaultTerrain,
            originalTerrainType: GridSystem.defaultTerrain,
            posX: x * this.config.cellSize,
            posY: y * this.config.cellSize,
