        if (!this.grid[gridX][gridY].originalTerrainType) {
            this.grid[gridX][gridY].originalTerrainType = this.grid[gridX][gridY].terrainType;
        }

        // Update the terrain type
        this.grid[gridX][gridY].terrainType = terrainType;

