/* -- js/UI/Map/OffscreenMyteIndicatorManager.js -- */
class OffscreenMyteIndicatorManager extends UIComponent {
    constructor(parent) {
        super(parent);
        this.overlay = null;
        this.markers = new Map();
        this.edgePadding = 14;
        this.preferredGap = 18;
        this._elapsed = 0;
    }

    init() {
        const containerElement = this.parent.parent?.element;
        if (!containerElement) return;

        this.overlay = document.createElement('div');
        this.overlay.className = 'myte-offscreen-indicators';
        this.overlay.setAttribute('aria-hidden', 'true');
        containerElement.appendChild(this.overlay);

        this.boundMarkerClick = (event) => this.handleMarkerClick(event);
        this.overlay.addEventListener('click', this.boundMarkerClick);
    }

    getMarker(myte) {
        const markerId = String(myte?.id ?? '');
        if (!markerId || !this.overlay) return null;

        if (!this.markers.has(markerId)) {
            const marker = document.createElement('div');
            marker.className = 'myte-offscreen-indicator is-hidden';
            marker.dataset.myteId = markerId;
            this.overlay.appendChild(marker);
            this.markers.set(markerId, marker);
        }

        return this.markers.get(markerId);
    }

    hideMarker(marker) {
        if (!marker) return;
        marker.classList.add('is-hidden');
    }

    hideAllMarkers() {
        this.markers.forEach(marker => this.hideMarker(marker));
    }

    /**
     * The slice of the world the player can currently see, in world coordinates.
     *
     * The render offset matters: walls reserve a strip above the map for their
     * height, and every other world↔screen conversion subtracts it. This read it
     * off `this.parent` — the UserInterface, which has no `gameMap` — so it was
     * silently zero, and the whole visible band was wrong by the wall overhang.
     * That is why a myte you could plainly see got a marker and one off the
     * bottom edge did not. The container is the thing that owns the offset, and
     * it is the same object the caller already has in hand.
     */
    getViewportWorldBounds(container, camera, viewportWidth, viewportHeight) {
        const safeZoom = Number.isFinite(camera?.zoomLevel) && camera.zoomLevel > 0
            ? camera.zoomLevel
            : 1;
        const renderOffset = container?.getRenderOffset?.() || { x: 0, y: 0 };
        const left = (Number.isFinite(camera?.posX) ? -camera.posX : 0) - renderOffset.x;
        const top = (Number.isFinite(camera?.posY) ? -camera.posY : 0) - renderOffset.y;
        const width = viewportWidth / safeZoom;
        const height = viewportHeight / safeZoom;

        return {
            left,
            top,
            right: left + width,
            bottom: top + height,
            width,
            height
        };
    }

    projectWorldPointToViewport(point, viewportBounds, viewportWidth, viewportHeight) {
        const normalizedX = viewportBounds.width > 0
            ? (point.x - viewportBounds.left) / viewportBounds.width
            : 0.5;
        const normalizedY = viewportBounds.height > 0
            ? (point.y - viewportBounds.top) / viewportBounds.height
            : 0.5;

        return {
            x: normalizedX * viewportWidth,
            y: normalizedY * viewportHeight
        };
    }

    isPointInsideViewport(point, viewportBounds) {
        return (
            point.x >= viewportBounds.left &&
            point.x <= viewportBounds.right &&
            point.y >= viewportBounds.top &&
            point.y <= viewportBounds.bottom
        );
    }

    getMarkerEdge(x, y, viewportWidth, viewportHeight) {
        const touchesTop = y <= this.edgePadding;
        const touchesBottom = y >= viewportHeight - this.edgePadding;
        const touchesLeft = x <= this.edgePadding;
        const touchesRight = x >= viewportWidth - this.edgePadding;

        if (touchesTop && touchesLeft) return 'top-left';
        if (touchesTop && touchesRight) return 'top-right';
        if (touchesBottom && touchesLeft) return 'bottom-left';
        if (touchesBottom && touchesRight) return 'bottom-right';
        if (touchesTop) return 'top';
        if (touchesBottom) return 'bottom';
        if (touchesLeft) return 'left';
        if (touchesRight) return 'right';
        return 'inside';
    }

    resolveEdgeOverlap(markers, axis, min, max) {
        if (!Array.isArray(markers) || markers.length <= 1) return;

        markers.sort((a, b) => a[axis] - b[axis]);

        const availableSpace = Math.max(0, max - min);
        const gap = Math.max(
            0,
            Math.min(
                this.preferredGap,
                markers.length > 1 ? availableSpace / (markers.length - 1) : this.preferredGap
            )
        );

        let nextPosition = min;
        markers.forEach(marker => {
            marker[axis] = Math.max(marker[axis], nextPosition);
            nextPosition = marker[axis] + gap;
        });

        markers[markers.length - 1][axis] = Math.min(markers[markers.length - 1][axis], max);

        for (let i = markers.length - 2; i >= 0; i -= 1) {
            markers[i][axis] = Math.min(markers[i][axis], markers[i + 1][axis] - gap);
        }

        for (let i = 0; i < markers.length; i += 1) {
            markers[i][axis] = Utility.clamp(markers[i][axis], min, max);
        }

        for (let i = 1; i < markers.length; i += 1) {
            markers[i][axis] = Math.max(markers[i][axis], markers[i - 1][axis] + gap);
            markers[i][axis] = Utility.clamp(markers[i][axis], min, max);
        }
    }

    /**
     * The box markers are allowed to sit in, and where it starts relative to the
     * stage. CSS owns the inset — see `.myte-offscreen-indicators` — because the
     * thing it has to clear is the chips, which CSS also places.
     */
    getMarkerBand(viewport) {
        const rect = this.overlay?.getBoundingClientRect?.();
        if (!rect?.width || !rect?.height) {
            return { offsetX: 0, offsetY: 0, width: viewport.width, height: viewport.height };
        }
        return {
            offsetX: rect.left - viewport.left,
            offsetY: rect.top - viewport.top,
            width: rect.width,
            height: rect.height
        };
    }

    /**
     * How far outside the view a point is, as 0–1 against a full viewport's
     * worth of distance. A dot right past the edge and one three screens away
     * were identical before, which is half of "a general idea of where it is".
     */
    distanceOutside(point, viewportBounds) {
        const dx = Math.max(viewportBounds.left - point.x, point.x - viewportBounds.right, 0);
        const dy = Math.max(viewportBounds.top - point.y, point.y - viewportBounds.bottom, 0);
        const reference = Math.max(1, Math.hypot(viewportBounds.width, viewportBounds.height));
        return Utility.clamp(Math.hypot(dx, dy) / reference, 0, 1);
    }

    updateMarker(markerData, activeMyte) {
        const marker = this.getMarker(markerData.myte);
        if (!marker) return;

        marker.classList.remove('is-hidden');
        marker.classList.toggle('active-myte', markerData.myte === activeMyte);
        marker.dataset.edge = markerData.edge;
        marker.dataset.myteId = String(markerData.myte?.id ?? '');
        marker.title = `${markerData.myte?.name || 'Myte'} — click to look`;
        marker.style.left = `${Math.round(markerData.x)}px`;
        marker.style.top = `${Math.round(markerData.y)}px`;
        // Near dots are full size and opaque, far ones shrink and fade. Read as
        // custom properties so the whole treatment stays in CSS.
        marker.style.setProperty('--marker-distance', markerData.distance.toFixed(3));
    }

    /**
     * Clicking a marker looks at the myte it stands for. The dot already knows
     * which myte and roughly where — following it is the obvious next thing to
     * want, and it saves hunting the roster for a name you cannot see.
     */
    handleMarkerClick(event) {
        const markerId = event.target?.closest?.('.myte-offscreen-indicator')?.dataset?.myteId;
        if (!markerId) return;

        event.preventDefault();
        event.stopPropagation();

        const myte = (this.parent.getMytes() || []).find(m => String(m.id) === markerId);
        if (!myte) return;

        this.parent.parent?.camera?.centerToPosition?.(myte.posX, myte.posY, myte.size, false);
        this.parent.setSelected?.(myte);
    }

    update() {
        if (!this.overlay) return;
        if (++this._elapsed % 4 !== 0) return; // throttle to ~15fps

        const container = this.parent.parent;
        const viewport = container?.getContainerRect?.();
        const camera = container?.camera;

        if (!camera || !viewport?.width || !viewport?.height) {
            this.hideAllMarkers();
            return;
        }

        const viewportWidth = viewport.width;
        const viewportHeight = viewport.height;
        const viewportBounds = this.getViewportWorldBounds(container, camera, viewportWidth, viewportHeight);
        // The overlay is inset from the stage so the dots clear the chips. Its
        // box is where markers may sit; the projection below is still in stage
        // coordinates, so the offset converts between the two.
        const band = this.getMarkerBand(viewport);
        const activeMyte = this.parent.getActiveMyte();
        const markerData = [];
        const visibleMarkerIds = new Set();

        (this.parent.getMytes() || []).forEach(myte => {
            const marker = this.getMarker(myte);

            if (!myte?.isActive) {
                this.hideMarker(marker);
                return;
            }

            const worldCenter = {
                x: (Number.isFinite(myte.posX) ? myte.posX : 0) + ((myte.size?.width || 0) / 2),
                y: (Number.isFinite(myte.posY) ? myte.posY : 0) + ((myte.size?.height || 0) / 2)
            };

            if (this.isPointInsideViewport(worldCenter, viewportBounds)) {
                this.hideMarker(marker);
                return;
            }

            const projectedCenter = this.projectWorldPointToViewport(
                worldCenter,
                viewportBounds,
                viewportWidth,
                viewportHeight
            );

            let x = Utility.clamp(
                projectedCenter.x - band.offsetX,
                this.edgePadding,
                Math.max(this.edgePadding, band.width - this.edgePadding)
            );
            let y = Utility.clamp(
                projectedCenter.y - band.offsetY,
                this.edgePadding,
                Math.max(this.edgePadding, band.height - this.edgePadding)
            );
            const edge = this.getMarkerEdge(x, y, band.width, band.height);

            visibleMarkerIds.add(String(myte.id));
            markerData.push({
                myte,
                edge,
                x,
                y,
                distance: this.distanceOutside(worldCenter, viewportBounds)
            });
        });

        markerData.forEach(marker => this.updateMarker(marker, activeMyte));

        this.markers.forEach((marker, markerId) => {
            if (!visibleMarkerIds.has(markerId)) {
                this.hideMarker(marker);
            }
        });
    }

    dispose() {
        if (this.overlay && this.boundMarkerClick) {
            this.overlay.removeEventListener('click', this.boundMarkerClick);
        }
        this.boundMarkerClick = null;
        this.markers.forEach(marker => marker.remove());
        this.markers.clear();
        this.overlay?.remove();
        this.overlay = null;
    }
}
;
/* -- js/UI/Container/ScreenManager.js -- */
class ScreenManager extends UIComponent {
    constructor(parent) {
        super(parent);
        this.headerElement = this.parent.containerWrapper.querySelector('.header');
        this.fullscreenButton = this.parent.containerWrapper.querySelector('.fullscreen-btn');
        this.userTextElement = this.headerElement?.querySelector('.username .username__text') || null;
        this.listenerCleanup = [];
    }

    init() {
        this.initializeButtons();
        this.initializeHeaderState();
    }

    static STORAGE_KEY = 'neko_fullscreen';

    initializeButtons() {
        if (this.fullscreenButton) {
            this.handleFullscreenClick = () => {
                this.toggleFullscreen();
            };
            this.fullscreenButton.addEventListener("click", this.handleFullscreenClick);
            this.listenerCleanup.push(() => this.fullscreenButton?.removeEventListener('click', this.handleFullscreenClick));
        }

        if (localStorage.getItem(ScreenManager.STORAGE_KEY) === '1') {
            this.setFullscreen(true);
        }
    }

    toggleFullscreen() {
        this.setFullscreen(!this.parent.containerWrapper.classList.contains('is-fullscreen'));
    }

    // Re-framing the camera is left to the container's ResizeObserver: the class
    // change is what resizes the stage, and the observer already reacts to that.
    setFullscreen(isFullscreen) {
        this.parent.containerWrapper.classList.toggle('is-fullscreen', isFullscreen);
        this.fullscreenButton?.classList.toggle('active', isFullscreen);
        localStorage.setItem(ScreenManager.STORAGE_KEY, isFullscreen ? '1' : '0');
    }

    initializeHeaderState() {
        const user = this.parent.parent?.core?.user;

        // The name is ours to write; opening the profile is UserProfilePanel's,
        // which claims this button as its trigger and marks it active while the
        // window is open.
        if (this.userTextElement) {
            this.userTextElement.textContent = user?.username || 'Guest';
        }
    }

    dispose() {
        this.listenerCleanup.forEach(cleanup => cleanup());
        this.listenerCleanup = [];
    }
}
;
/* -- js/UI/core/UserInterface.js -- */
class UserInterface {
    constructor(parent) {
        this.parent = parent;
        this.containerWrapper = parent.containerWrapper;
        this.debugOverlay = new DebugOverlayUI(parent);
        this.debug = this.debugOverlay;
        this.isActive = false;
		this.lastSoundHour = null;
		this.boundControlClickSound = this.handleControlClickSound.bind(this);
		this.boundTimeMilestoneSound = this.handleTimeMilestoneSound.bind(this);

        // Initialize all UI components
        this.toolManager = new ToolManager(this);
        this.selectionManager = new SelectionManager(this);
        this.buildMarqueeSelection = new BuildMarqueeSelection(this);
        this.queueTargetManager = new QueueTargetManager(this);
        this.actionSidebarManager = new ActionSidebarManager(this);
        this.myteListManager = new MyteListManager(this);
        this.hudManager = new HUDManager(this);
        this.buffOverlayUI = new BuffOverlayUI(this, {
            element: document.getElementById('myte_buff_overlay')
        });
        this.offscreenMyteIndicatorManager = new OffscreenMyteIndicatorManager(this);
        this.screenManager = new ScreenManager(this);
        this.cursorManager = new CursorManager(this);
        this.compactQueueUI = new CompactQueueUI(this, {
            element: document.getElementById('myte_queue_overlay')
        });
        this.buildModeUI = new BuildModeUI(this);
        this.buildPlacement = new MyteBuildPlacement(this);
        this.hintNotes = new HintNotes(this);
        this.stageChips = new StageChips(this);
        this.stageViewBar = new StageViewBar(this);
    }

    init() {
        // Initialize all components
        this.toolManager.init();
        this.selectionManager.init();
        this.buildMarqueeSelection.init();
        this.actionSidebarManager.init();
        this.myteListManager.init();
        this.hudManager.init();
        this.offscreenMyteIndicatorManager.init();
        this.screenManager.init();

        // The Options window owns the shared modal its four tab controllers
        // bind into, so it has to exist before any of them.
        this.optionsPanel = new OptionsPanel(this);
        this.soundPanel = new SoundPanel(this);
        this.settingsPanel = new SettingsPanel(this);
        this.surfaceCustomizePanel = new SurfaceCustomizePanel(this);
        this.wallBuildPanel = new WallBuildPanel(this);
        this.fenceBuildPanel = new FenceBuildPanel(this);
        this.roomPanel = new RoomPanel(this);
        this.terrainPaintPanel = new TerrainPaintPanel(this);
        this.viewPanel = new ViewPanel(this);
        this.worldMapPanel = new WorldMapPanel(this);
        this.calendarPanel = new CalendarPanel(this);
        this.debugPanel = new DebugPanel(this);
        this.myteInfoPanel = new MyteInfoPanel(this);
        this.userProfilePanel = new UserProfilePanel(this);
        this.shopPanel = new ShopPanel(this);
        this.gameLogManager = new GameLogManager(this);
        this.buildModeUI.init();
        this.buildPlacement.init();
        // After the panels, because it decorates their markup and hangs its
        // toggle in their title bars.
        this.hintNotes.init();
        this.stageChips.init();
        this.stageViewBar.init();

		document.addEventListener('click', this.boundControlClickSound);
		const gameTime = this.parent.core?.gameTime;
		this.lastSoundHour = gameTime?.getCurrentHour?.() ?? null;
		gameTime?.subscribe?.('hour', this.boundTimeMilestoneSound);
        this.soundMenu = this.soundPanel;
        this.settingsMenu = this.settingsPanel;
        this.viewMenu = this.viewPanel;
        this.debugMenu = this.debugPanel;
    }

    /**
     * What the pointer is over, in the one word every build tool has to say.
     *
     * Each tool used to own its own answer, and between them they said almost
     * nothing: the Wall and Room tools showed a crosshair over the whole stage,
     * including the grey outside the map where a click does nothing, and the
     * Surface tool said nothing at all until the target was locked. Three tools
     * with three vocabularies is three things to learn; this is one.
     *
     *   null       nothing here this tool can act on — plain arrow
     *   'ready'    a click would do the thing (which thing is the tool's own
     *              cursor: a grid square for Wall and Room, a pick for Surface)
     *   'grab'     a drag would move what is under the pointer
     *   'refused'  there is something here, and the answer is no
     */
    setBuildCursor(state = null) {
        if (state) document.body.dataset.buildCursor = state;
        else delete document.body.dataset.buildCursor;
    }

    // Methods for component communication
    onToolModeChanged(mode) {
        // Clear selection when tool mode changes
        this.selectionManager.setSelected(null);
        this.buildMarqueeSelection?.clearSelection?.();
        // A gesture belongs to the tool that started it: leaving Move mid-drag
        // would otherwise leave a myte wherever the cursor happened to be.
        this.buildPlacement?.cancel();

        // Notify action manager to update UI
        this.actionSidebarManager.updateActions(null);
        this.surfaceCustomizePanel?.handleToolModeChanged(mode);
        this.wallBuildPanel?.handleToolModeChanged(mode);
        this.fenceBuildPanel?.handleToolModeChanged(mode);
        this.roomPanel?.handleToolModeChanged(mode);
        this.terrainPaintPanel?.handleToolModeChanged(mode);
    }

    onSelectionChanged(selectedObject) {
        // Update action panel based on selection
        this.actionSidebarManager.updateActions(selectedObject);
    }

    // Proxy methods to parent for components to use
    getMytes() {
        return this.parent.mytes;
    }

    getActiveMyte() {
        return this.parent.activeMyte;
    }

    setActiveMyte(myte) {
        this.parent.setActiveMyte(myte);
        this.myteListManager.updateMytesList(myte);
        this.hudManager.update();
        this.viewPanel?.updateButtonStates();
    }

    playSound(sound) {
        this.parent.core.soundManager.playUISound(sound);
    }

	handleControlClickSound(event) {
		const control = event.target.closest?.('button, [role="button"]');
		if (!control || !document.body.contains(control)) return;
		if (control.disabled || event.defaultPrevented) return;
		if (control.dataset.modalTrigger === 'true') return;
		if (control.closest('.window-panel__controls, #sound-settings-panel')) return;

		this.parent.core?.soundManager?.playWhenReady?.(SiteConfig.ui.interactionSounds.click);
	}

	handleTimeMilestoneSound(timeData = {}) {
		const hour = Number(timeData.hour);
		if (!Number.isFinite(hour) || hour === this.lastSoundHour) return;
		this.lastSoundHour = hour;

		const sounds = SiteConfig.ui.interactionSounds;
		const cue = sounds.timeMilestones[hour];
		if (!cue) return;
		this.parent.core?.soundManager?.playWhenReady?.(sounds.timeMilestone, cue);
	}

    // Public methods
    setSelected(obj) {
        if (!obj) this.buildMarqueeSelection?.clearSelection?.();
        this.selectionManager.setSelected(obj);
    }

    getSelected() {
        return this.selectionManager.getSelectedObject();
    }

    getSelectedObjects() {
        return this.selectionManager.getSelectedObjects();
    }

    setToolMode(mode) {
        this.toolManager.setToolMode(mode);
    }

    isTool(mode) {
        return this.toolManager.isTool(mode);
    }

    changeToolMode(mode) {
        return this.toolManager.changeToolMode(mode);
    }

    /** Two fingers always borrow the map, so abandon any one-finger build preview. */
    cancelBuildGesturesForCamera() {
        this.wallBuildPanel?.cancelDrag?.();
        this.fenceBuildPanel?.cancelDrag?.();
        this.roomPanel?.cancelDrag?.();
        this.terrainPaintPanel?.abortStroke?.();
        this.buildMarqueeSelection?.cancelDrag?.();
        this.buildPlacement?.cancel?.();
    }

    /**
     * Writes the walls standing on this map back into its .tmx.
     *
     * Deliberately a manual, explicit action rather than something that rides
     * along with the autosave: it edits a source file that Tiled may also have
     * open, and the conflict check can only protect a write the author asked
     * for at a moment they know about.
     *
     * It lives here because two controls offer it — the Debug panel's button
     * and the build bar's shortcut — and neither of them should be the one that
     * knows how it works.
     */
    async exportMapToTiled(button = null) {
        const gameMap = this.parent?.gameMap;
        const toasts = this.parent?.core?.toastManager;
        if (typeof WallTiledExporter === 'undefined') return;
        if (!WallTiledExporter.isAvailable(gameMap)) {
            toasts?.show?.({
                type: 'warning',
                title: 'Export unavailable',
                content: 'Needs the local editor API and a map whose tileset authors the wall wang set.'
            });
            return;
        }

        // This overwrites a source .tmx on disk — the one authoring path for
        // the map — so it asks first. Nothing else in the debug panel writes
        // outside the save.
        const path = gameMap?.sourcePath || 'the map source';
        if (!window.confirm(
            `Overwrite ${path} with the walls currently standing?

` +
            'This rewrites the Tiled source file. Close the map in Tiled first, ' +
            'and make sure any edits there are saved.'
        )) return;

        if (button) button.disabled = true;
        try {
            // Ground first, walls second. Both patch the same file and each
            // re-reads it, so they must not overlap — and doing terrain first
            // means the wall pass hashes a file that already has the ground in
            // it rather than losing the race to its own sibling.
            await this.exportTerrainToTiled(gameMap, toasts);

            const result = await WallTiledExporter.exportMap(gameMap);
            if (!result.ok) {
                toasts?.show?.({
                    type: result.code === 'conflict' ? 'warning' : 'error',
                    title: 'Export failed',
                    content: result.message
                });
                console.warn('[WallTiledExporter]', result.code, result.message);
                return;
            }
            const { cells, layers, objectsAdded, objectsUpdated, objectsRemoved } = result.stats;
            toasts?.show?.({
                type: 'success',
                title: 'Walls exported to Tiled',
                content: `${cells} cells across ${layers} layer${layers === 1 ? '' : 's'} → ${result.path}. ` +
                    `Objects: ${objectsAdded} added, ${objectsUpdated} updated, ${objectsRemoved} removed.`
            });
            for (const warning of result.warnings) {
                toasts?.show?.({ type: 'warning', title: 'Export warning', content: warning });
                console.warn('[WallTiledExporter]', warning);
            }
        } finally {
            if (button) button.disabled = false;
        }
    }

    /**
     * Painted ground, written back into the same .tmx. Quiet when the map has
     * none: terrain is optional, and a map with no painted ground should not
     * make the wall export report a failure it did not have.
     */
    async exportTerrainToTiled(gameMap = this.parent?.gameMap, toasts = this.parent?.core?.toastManager) {
        if (typeof TerrainTiledExporter === 'undefined') return null;
        if (!TerrainTiledExporter.isAvailable(gameMap)) return null;

        const result = await TerrainTiledExporter.exportMap(gameMap);
        if (!result.ok) {
            toasts?.show?.({
                type: result.code === 'conflict' ? 'warning' : 'error',
                title: 'Ground export failed',
                content: result.message
            });
            console.warn('[TerrainTiledExporter]', result.code, result.message);
            return result;
        }
        const { cells, layers, layersAdded, layersRemoved } = result.stats;
        const changes = [
            layersAdded > 0 ? `${layersAdded} new` : null,
            layersRemoved > 0 ? `${layersRemoved} removed` : null
        ].filter(Boolean);
        toasts?.show?.({
            type: 'success',
            title: 'Ground exported to Tiled',
            content: `${cells} tiles across ${layers} layer${layers === 1 ? '' : 's'}` +
                `${changes.length ? ` (${changes.join(', ')})` : ''} → ${result.path}.`
        });
        for (const warning of result.warnings) {
            toasts?.show?.({ type: 'warning', title: 'Ground export warning', content: warning });
            console.warn('[TerrainTiledExporter]', warning);
        }
        return result;
    }

    showMessage(message, type = 'info', title = '') {
        const toastManager = this.parent?.core?.toastManager;
        if (!toastManager || !message) {
            return;
        }

        const method = typeof toastManager[type] === 'function' ? type : 'info';
        toastManager[method](String(message), title || undefined);
    }

    // Update method called every frame
    update() {
        this.debugOverlay.update();
        this.cursorManager.update();
        this.queueTargetManager.update();
        this.hudManager.update();
        this.buffOverlayUI.update();
        this.offscreenMyteIndicatorManager.update();
        this.compactQueueUI?.update?.();
        this.myteInfoPanel?.update?.();
        this.buildModeUI?.update?.();
    }

    get gameMode() {
        return this.parent?.gameMode || null;
    }

    dispose() {
		document.removeEventListener('click', this.boundControlClickSound);
		this.parent.core?.gameTime?.unsubscribe?.('hour', this.boundTimeMilestoneSound);
        this.debugOverlay?.dispose?.();
        this.debugOverlay = null;
        this.debug = null;
        this.debugPanel?.dispose?.();
        this.debugPanel = null;
        this.debugMenu = null;
        this.myteInfoPanel?.dispose?.();
        this.myteInfoPanel = null;
        this.userProfilePanel?.dispose?.();
        this.userProfilePanel = null;
        this.calendarPanel?.dispose?.();
        this.calendarPanel = null;
        this.shopPanel?.dispose?.();
        this.shopPanel = null;
        this.settingsPanel?.dispose?.();
        this.settingsPanel = null;
        this.settingsMenu = null;
        this.surfaceCustomizePanel?.dispose?.();
        this.surfaceCustomizePanel = null;
        this.wallBuildPanel?.dispose?.();
        this.wallBuildPanel = null;
        this.fenceBuildPanel?.dispose?.();
        this.fenceBuildPanel = null;
        this.roomPanel?.dispose?.();
        this.roomPanel = null;
        this.terrainPaintPanel?.dispose?.();
        this.terrainPaintPanel = null;
        this.soundPanel?.dispose?.();
        this.soundPanel = null;
        this.soundMenu = null;
        this.viewPanel?.dispose?.();
        this.viewPanel = null;
        this.viewMenu = null;
        this.worldMapPanel?.dispose?.();
        this.worldMapPanel = null;
        this.optionsPanel?.dispose?.();
        this.optionsPanel = null;
        this.buildModeUI?.dispose?.();
        this.buildModeUI = null;
        this.stageViewBar?.dispose?.();
        this.stageViewBar = null;
        this.stageChips?.dispose?.();
        this.stageChips = null;

        this.screenManager?.dispose?.();
        this.toolManager?.dispose?.();
        this.cursorManager?.dispose?.();
        this.queueTargetManager?.dispose?.();
        this.offscreenMyteIndicatorManager?.dispose?.();
        this.selectionManager?.dispose?.();
        this.buildMarqueeSelection?.dispose?.();
        this.hudManager?.dispose?.();
        this.buffOverlayUI?.dispose?.();
        this.actionSidebarManager?.dispose?.();
        this.myteListManager?.dispose?.();

        this.screenManager = null;
        this.toolManager = null;
        this.cursorManager = null;
        this.queueTargetManager = null;
        this.offscreenMyteIndicatorManager = null;
        this.selectionManager = null;
        this.hudManager = null;
        this.buffOverlayUI = null;
        this.actionSidebarManager = null;
        this.myteListManager = null;
        this.compactQueueUI?.dispose?.();
        this.compactQueueUI = null;
		this.boundControlClickSound = null;
		this.boundTimeMilestoneSound = null;
    }
}
;
/* -- js/UI/core/ModalWindow.js -- */
class ModalWindow {

	static activeWindows = [];
	static allowMultipleWindows = false;

constructor(parent, options = {}) {
    this.parent = parent;
    this.container = parent.container;
    this.config = parent.config;

    // Default options
    this.options = Object.assign({
        id: null,                  // ID of the modal element
		floating: true, 			// if it's fixed
		buttonId: null,
		title: 'Modal',            // Title of the modal
        closeOnOutsideClick: true, // Close when clicking outside the modal
        autoInit: false,           // Subclasses must call this.init() explicitly after their own state is ready
        animationDuration: 300,    // Animation duration in ms
        position: 'center',        // center, top-right, bottom-left, etc.
        draggable: false,          // Allow dragging the modal
        resizable: false,          // Allow resizing the modal
        fullscreen: null,          // true creates a maximize control; null uses authored markup
        onOpen: null,              // Callback when modal opens
        onClose: null,             // Callback when modal closes
        onMinimize: null,          // Callback when modal is minimized
        onMaximize: null,          // Callback when modal is maximized
		
        closeButtonSelector: '.modal-close-btn', // Selector for close button
		minimizeButtonSelector: '.modal-minimize-btn', // Selector for minimize button
		fullscreenButtonSelector: '.modal-fullscreen-btn', // Selector for maximize button
        
        rememberPosition: true,    // Remember the position when reopening
        allowMultipleWindows: false, // Allow multiple windows to be open at once
        snapToEdges: true,         // Snap windows to screen edges when dragging
        dragBoundsElement: null    // Optional element (or getter) that bounds relative-positioned windows
    }, options);

    // Element references
    this.modalElement = null;
    this.closeButton = null;
    this.minimizeButton = null;
    this.fullscreenButton = null;
    this.headerElement = null;

    // State
    this.isVisible = false;
    this.isDragging = false;
    this.isFullscreen = false;
    this.isMinimized = false;
    this.dragOffset = { x: 0, y: 0 };
    this.position = { x: 0, y: 0 };  // Track current position
    this.originalSize = { width: 0, height: 0 }; // Store original size for restoring
    this.lastClickTime = 0; // For double-click detection
    this.dragPointerId = null;
	this.tabBinding = null;
	this.previouslyFocusedElement = null;

    // Bind methods to maintain correct 'this' context
    this.open = this.open.bind(this);
    this.close = this.close.bind(this);
    this.toggle = this.toggle.bind(this);
    this.handleOutsideClick = this.handleOutsideClick.bind(this);
    this.handleDragStart = this.handleDragStart.bind(this);
    this.handleDragMove = this.handleDragMove.bind(this);
    this.handleDragEnd = this.handleDragEnd.bind(this);
    this.toggleFullscreen = this.toggleFullscreen.bind(this);
    this.toggleMinimize = this.toggleMinimize.bind(this);
    this.handleHeaderDoubleClick = this.handleHeaderDoubleClick.bind(this);

    // Initialize if autoInit is true
    if (this.options.autoInit) {
        this.init();
    }
}

	/**
	 * Initialize the modal window
	 */
	init() {
		// Find modal element
		if (this.options.id) {
			this.modalElement = document.getElementById(this.options.id);

			if (!this.modalElement) {
				Utility.warnDebug(`Modal element with id '${this.options.id}' not found`);
				return;
			}

			if(this.options.floating) {
				this.modalElement.classList.add('is-floating');
			}

			this.modalElement.inert = true;
			this.modalElement.setAttribute('aria-hidden', 'true');

			if(this.options.buttonId) {
				this.buttonElement = document.getElementById(this.options.buttonId);

				if (!this.buttonElement) {
					Utility.warnDebug(`Button with id '${this.options.id}' for modal element with id '${this.options.id}' not found`);
					return;
				}

				// Clear any existing listeners
				this.buttonElement.onclick = null;
				this.buttonElement.oncontextmenu = null;

				this.buttonElement.oncontextmenu = (e) => {
					this.buttonRightClick(e);
				};
		
				this.buttonElement.onclick = (e) => {
					this.buttonLeftClick(e);
				};
				this.buttonElement.dataset.modalTrigger = 'true';
			}

			// Find or create window controls
			this.headerElement = this.modalElement.querySelector('.window-panel__header');
			if (this.options.fullscreen === true) {
				this.ensureFullscreenButton();
			}
			this.closeButton = this.modalElement.querySelector(this.options.closeButtonSelector);
			this.minimizeButton = this.modalElement.querySelector(this.options.minimizeButtonSelector);
			this.fullscreenButton = this.modalElement.querySelector(this.options.fullscreenButtonSelector);

			// Store original size for restoring from fullscreen/minimize
			const rect = this.modalElement.getBoundingClientRect();
			this.originalSize = {
				width: rect.width,
				height: rect.height
			};

			// Set up event listeners
			this.setupEventListeners();

			// Apply initial positioning
			this.applyPosition();
		} else {
			Utility.warnDebug('No modal ID provided');
		}
	}

	// A window's trigger button toggles it. Every panel wanted exactly this and
	// wrote it out again, so it is the default — override only for a button that
	// means something else.
	buttonLeftClick(e) {
		e.preventDefault();
		e.stopPropagation();
		this.toggle();
		return false;
	}

	buttonRightClick(e) {
		this.buttonLeftClick(e);
	}
	
	/**
	 * Set up event listeners for the modal
	 */
	setupEventListeners() {
		// Close button click handler
		if (this.closeButton) {
			this.closeButton.onclick = () => this.close();
		}

		// Minimize button click handler
		if (this.minimizeButton) {
			this.minimizeButton.onclick = this.toggleMinimize;
		}

		// Fullscreen button click handler
		if (this.fullscreenButton) {
			this.fullscreenButton.onclick = this.toggleFullscreen;
		}

		// Header double-click handler
		if (this.headerElement) {
			this.headerElement.ondblclick = this.handleHeaderDoubleClick;
		}

		// Escape is not handled here. Every window listening for it on its own
		// meant two answers to one keypress: the window closed itself while the
		// layered handler, seeing no window it recognised, went on to undo the
		// next thing down. ContainerInputManager.handleEscape is the only
		// authority, and it closes `ModalWindow.frontMost()`.

		// Outside click handler (will be added/removed when modal opens/closes)
		if (this.options.closeOnOutsideClick) {
			// We'll add this when the modal opens
		}

		// Draggable setup
		if (this.options.draggable && this.modalElement) {
			const header = this.modalElement.querySelector('.window-panel__header') || this.modalElement;
			header.style.cursor = 'move';
			header.style.touchAction = 'none';
			header.addEventListener('pointerdown', this.handleDragStart);
		}
	}

	/**
	 * Handle header double-click event
	 * @param {MouseEvent} e - Mouse event
	 */
	handleHeaderDoubleClick(e) {
		// A title bar should only advertise maximize-by-double-click when the
		// window actually exposes a maximize control.
		if (!this.fullscreenButton) return;

		// If minimized, restore to normal
		if (this.isMinimized) {
			this.toggleMinimize();
		}
		// If normal, go to fullscreen
		else if (!this.isFullscreen) {
			this.toggleFullscreen();
		}
		// If fullscreen, restore to normal
		else {
			this.toggleFullscreen();
		}
	}

	/**
	 * The open window nearest the front, or null when none are open.
	 *
	 * Stacking order is the only sensible reading of "the window I meant" —
	 * it is the one the eye is on and the one a click would reach first.
	 */
	static frontMost() {
		let front = null;
		let frontZ = -Infinity;
		for (const window of ModalWindow.activeWindows) {
			if (!window.isVisible || !window.modalElement) continue;
			const z = parseInt(window.modalElement.style.zIndex) || 0;
			if (z >= frontZ) {
				frontZ = z;
				front = window;
			}
		}
		return front;
	}

	/**
	 * Check if this window is the front-most active window
	 * @returns {boolean} True if this is the front-most window
	 */
	isFrontMost() {
		if (!this.modalElement || !this.isVisible) return false;
		return ModalWindow.frontMost() === this;
	}

	/**
	 * Toggle fullscreen state
	 */
	toggleFullscreen() {
		if (!this.modalElement) return;

		// Toggle fullscreen class
		if (this.isFullscreen) {
			this.modalElement.classList.remove('is-fullscreen');
			this.isFullscreen = false;

			// Restore original position if we had one
			if (this.options.rememberPosition && this.position.x !== 0 && this.position.y !== 0) {
				this.modalElement.style.left = `${this.position.x}px`;
				this.modalElement.style.top = `${this.position.y}px`;
			}

			// Callback
			if (typeof this.options.onMaximize === 'function') {
				this.options.onMaximize(false); // false = exited fullscreen
			}
		} else {
			// Save current position before going fullscreen
			if (!this.isFullscreen && !this.isMinimized) {
				const rect = this.modalElement.getBoundingClientRect();
				this.position = {
					x: rect.left,
					y: rect.top
				};
			}

			this.modalElement.classList.add('is-fullscreen');

			// When going fullscreen, ensure we're not minimized
			if (this.isMinimized) {
				this.modalElement.classList.remove('is-minimized');
				this.isMinimized = false;
			}
			
			this.isFullscreen = true;
			
			// Callback
			if (typeof this.options.onMaximize === 'function') {
				this.options.onMaximize(true); // true = entered fullscreen
			}
		}

		// Play UI sound
		this.playSound('click');
	}

	/**
	 * Toggle minimize state
	 */
	toggleMinimize() {
		if (!this.modalElement) return;

		// Toggle minimize class
		if (this.isMinimized) {
			this.modalElement.classList.remove('is-minimized');
			this.isMinimized = false;

			// Restore original position if we had one
			if (this.options.rememberPosition && this.position.x !== 0 && this.position.y !== 0) {
				this.modalElement.style.left = `${this.position.x}px`;
				this.modalElement.style.top = `${this.position.y}px`;
			}

			// Callback
			if (typeof this.options.onMinimize === 'function') {
				this.options.onMinimize(false); // false = unminimized
			}
		} else {
			// Save current position before minimizing
			if (!this.isFullscreen && !this.isMinimized) {
				const rect = this.modalElement.getBoundingClientRect();
				this.position = {
					x: rect.left,
					y: rect.top
				};
			}

			this.modalElement.classList.add('is-minimized');

			// When minimizing, ensure we're not fullscreen
			if (this.isFullscreen) {
				this.modalElement.classList.remove('is-fullscreen');
				this.isFullscreen = false;
			}
			
			this.isMinimized = true;
			
			// Callback
			if (typeof this.options.onMinimize === 'function') {
				this.options.onMinimize(true); // true = minimized
			}
		}

		// Play UI sound
		this.playSound('click');
	}

	/**
	 * Handle drag start event
	 * @param {MouseEvent} e - Mouse event
	 */
	handleDragStart(e) {
		// Don't allow dragging in fullscreen mode
		if (!this.options.draggable || this.isFullscreen) return;
		if (e.button !== 0 || e.target.closest('button, input, select, textarea, a, .window-panel__controls')) return;

		this.isDragging = true;
		this.dragPointerId = e.pointerId;

		// Calculate offset relative to the modal element
		const rect = this.modalElement.getBoundingClientRect();
		this.dragOffset = {
			x: e.clientX - rect.left,
			y: e.clientY - rect.top
		};
		
		// Store current modal position
		this.position = {
			x: rect.left,
			y: rect.top
		};

		// Convert CSS-positioned windows to explicit viewport coordinates before
		// moving them. This prevents the centering transform from transitioning
		// against the first left/top update and producing a top-left jump.
		this.modalElement.classList.add('is-dragging');
		this.modalElement.classList.remove('position-center', 'position-top-right',
			'position-top-left', 'position-bottom-right', 'position-bottom-left');
		this.modalElement.style.transform = 'none';
		const isViewportPositioned = getComputedStyle(this.modalElement).position === 'fixed';
		const offsetRect = isViewportPositioned
			? { left: 0, top: 0 }
			: this.modalElement.offsetParent?.getBoundingClientRect?.() ?? { left: 0, top: 0 };
		this.modalElement.style.left = `${rect.left - offsetRect.left}px`;
		this.modalElement.style.top = `${rect.top - offsetRect.top}px`;
	
		this.headerElement?.setPointerCapture?.(e.pointerId);
		this.headerElement?.addEventListener('pointermove', this.handleDragMove);
		this.headerElement?.addEventListener('pointerup', this.handleDragEnd);
		this.headerElement?.addEventListener('pointercancel', this.handleDragEnd);
	
		// Prevent text selection during drag
		e.preventDefault();
		
		// Bring this window to the front
		this.bringToFront();
	}
	
	/**
	 * Bring this window to the front of other windows
	 */
	bringToFront() {
		const base = AppConfig?.ui?.modalBaseZIndex ?? 9999;
		let highestZIndex = base;
		ModalWindow.activeWindows.forEach(window => {
			const zIndex = parseInt(window.modalElement.style.zIndex) || 0;
			if (zIndex > highestZIndex) highestZIndex = zIndex;
		});
		this.modalElement.style.zIndex = `${highestZIndex + 1}`;
	}
	
	/**
	 * Handle drag move event
	 */
	handleDragMove(e) {
		if (!this.isDragging || e.pointerId !== this.dragPointerId) return;

		const configuredBounds = typeof this.options.dragBoundsElement === 'function'
			? this.options.dragBoundsElement()
			: this.options.dragBoundsElement;
		const boundsRect = configuredBounds?.getBoundingClientRect?.() || {
			left: 0,
			top: 0,
			width: window.innerWidth,
			height: window.innerHeight
		};
		const isViewportPositioned = getComputedStyle(this.modalElement).position === 'fixed';
		const minX = isViewportPositioned ? boundsRect.left : 0;
		const minY = isViewportPositioned ? boundsRect.top : 0;
		const modalRect = this.modalElement.getBoundingClientRect();
		const maxX = Math.max(minX, minX + boundsRect.width - modalRect.width);
		const maxY = Math.max(minY, minY + boundsRect.height - modalRect.height);

		// Calculate new position based on mouse movement and initial offset
		let x = e.clientX - this.dragOffset.x - (isViewportPositioned ? 0 : boundsRect.left);
		let y = e.clientY - this.dragOffset.y - (isViewportPositioned ? 0 : boundsRect.top);

		// Apply snapping if enabled
		if (this.options.snapToEdges) {
			const snapDistance = 15; // Pixels to trigger snapping

			// Snap to left edge
			if (x < minX + snapDistance) x = minX;

			// Snap to right edge
			if (x > maxX - snapDistance) {
				x = maxX;
			}

			// Snap to top edge
			if (y < minY + snapDistance) y = minY;

			// Snap to bottom edge
			if (y > maxY - snapDistance) {
				y = maxY;
			}
		}
		x = Math.min(maxX, Math.max(minX, x));
		y = Math.min(maxY, Math.max(minY, y));

		// Apply new position with inline styles (necessary for dragging)
		this.modalElement.style.left = `${x}px`;
		this.modalElement.style.top = `${y}px`;
		
		// Remove position classes when manually dragging
		this.modalElement.classList.remove('position-center', 'position-top-right', 
			'position-top-left', 'position-bottom-right', 'position-bottom-left');
		
		// Remove center transform if it exists
		if (this.modalElement.style.transform) {
			this.modalElement.style.transform = '';
		}
		
		// Update stored position
		this.position = { x, y };
	
		e.preventDefault();
	}

	/**
	 * Handle drag end event
	 */
	handleDragEnd(event) {
		if (event?.pointerId !== undefined && event.pointerId !== this.dragPointerId) return;
		if (this.dragPointerId !== null && this.headerElement?.hasPointerCapture?.(this.dragPointerId)) {
			this.headerElement.releasePointerCapture(this.dragPointerId);
		}
		this.isDragging = false;
		this.dragPointerId = null;
		this.modalElement?.classList.remove('is-dragging');

		this.headerElement?.removeEventListener('pointermove', this.handleDragMove);
		this.headerElement?.removeEventListener('pointerup', this.handleDragEnd);
		this.headerElement?.removeEventListener('pointercancel', this.handleDragEnd);
	}

	/**
	 * Apply position to the modal based on options
	 */
	applyPosition() {
		if (!this.modalElement) return;

		const position = this.options.position;

		// Remove all position classes first
		this.modalElement.classList.remove('position-center', 'position-top-right', 'position-top-left', 'position-bottom-right', 'position-bottom-left');

		// Apply position class based on option
		this.modalElement.classList.add(`position-${position}`);
	}

	/**
	 * Handle clicks outside the modal
	 * @param {MouseEvent} e - Mouse event
	 */
	handleOutsideClick(e) {
		// Ignore the click that triggered open() — its event fires after the listener attaches
		if (e.timeStamp < this._openTime + 16) return;
		if (this.isVisible &&
			this.modalElement &&
			!this.modalElement.contains(e.target) &&
			e.target.id !== this.options.triggerElementId) {
			this.close();
		}
	}

	/**
	 * Open the modal
	 */
	open() {
		if (!this.modalElement || this.isVisible) return;
		this.previouslyFocusedElement = document.activeElement instanceof HTMLElement
			? document.activeElement
			: null;
		this.modalElement.inert = false;
		this.modalElement.setAttribute('aria-hidden', 'false');
	
		// Close other windows if multiple windows aren't allowed
		if (!this.options.allowMultipleWindows) {
			ModalWindow.activeWindows.forEach(window => {
				if (window !== this && window.isVisible) {
					window.close();
				}
			});
		}
	
		// Add this window to active windows array
		if (!ModalWindow.activeWindows.includes(this)) {
			ModalWindow.activeWindows.push(this);
		}
		
		// Reset window state to normal before showing
		// (ensures we don't have remnants of previous minimize/fullscreen state)
		this.modalElement.classList.remove('is-fullscreen', 'is-minimized');
		this.isFullscreen = false;
		this.isMinimized = false;

		// Add visible class to show the modal
		this.modalElement.classList.add('is-visible');
		this.isVisible = true;
		this._openTime = performance.now();

		// Add document click listener for outside clicks
		if (this.options.closeOnOutsideClick) {
			document.addEventListener('click', this.handleOutsideClick);
		}
	
		// Call onOpen callback if provided
		if (typeof this.options.onOpen === 'function') {
			this.options.onOpen();
		}

		if(this.buttonElement){
			this.buttonElement.classList.add('active');
		}
		
		// Bring this window to the front
		this.bringToFront();
	
		// Play sound if sound manager is available
		this.playSound('open');
	}

	/**
	 * Close the modal
	 */
	close() {
		if (!this.modalElement || !this.isVisible) return;
		this.handleDragEnd();
		this.restoreFocusBeforeClose();

		// Save the current state for tracking
		const wasFullscreen = this.isFullscreen;
		const wasMinimized = this.isMinimized;
		
		// Update state flags
		this.isVisible = false;
		this.isFullscreen = false;
		this.isMinimized = false;
		
		// Remove visible class to hide the modal (keeping fullscreen/minimize classes for animation)
		this.modalElement.classList.remove('is-visible');
		this.modalElement.inert = true;
		this.modalElement.setAttribute('aria-hidden', 'true');
		
		// Set up a delayed removal of state classes after animation completes
		if (wasFullscreen || wasMinimized) {
			setTimeout(() => {
				// Only remove classes if the modal is still not visible
				if (!this.isVisible) {
					this.modalElement.classList.remove('is-fullscreen', 'is-minimized');
				}
			}, this.options.animationDuration);
		}
	
		// Remove document click listener
		if (this.options.closeOnOutsideClick) {
			document.removeEventListener('click', this.handleOutsideClick);
		}
	
		// Call onClose callback if provided
		if (typeof this.options.onClose === 'function') {
			this.options.onClose();
		}
	
		// Play sound if sound manager is available
		this.playSound('close');

		if(this.buttonElement){
			this.buttonElement.classList.remove('active');
		}
		
		// Remove from active windows array
		const index = ModalWindow.activeWindows.indexOf(this);
		if (index !== -1) {
			ModalWindow.activeWindows.splice(index, 1);
		}
	}

	restoreFocusBeforeClose() {
		const activeElement = document.activeElement;
		if (!(activeElement instanceof HTMLElement) || !this.modalElement.contains(activeElement)) return;

		const candidates = [this.previouslyFocusedElement, this.buttonElement];
		for (const candidate of candidates) {
			if (!(candidate instanceof HTMLElement) ||
				!candidate.isConnected ||
				candidate.closest('[inert]') ||
				candidate.disabled) continue;
			candidate.focus({ preventScroll: true });
			if (document.activeElement === candidate) break;
		}
		if (this.modalElement.contains(document.activeElement)) {
			activeElement.blur();
		}
	}

	/**
	 * Toggle the modal visibility
	 */
	toggle() {
		if (this.isVisible) {
			this.close();
		} else {
			this.open();
		}
	}

	ensureFullscreenButton() {
		if (!this.headerElement || this.modalElement.querySelector(this.options.fullscreenButtonSelector)) return;
		const controls = this.headerElement.querySelector('.window-panel__controls');
		if (!controls) return;

		const button = document.createElement('button');
		button.type = 'button';
		button.className = this.options.fullscreenButtonSelector.replace(/^\./, '');
		button.setAttribute('aria-label', 'Maximize');
		button.appendChild(Utility.createIcon('maximize'));
		const closeButton = controls.querySelector(this.options.closeButtonSelector);
		controls.insertBefore(button, closeButton);
	}

	setupTabs(options = {}) {
		this.disposeTabs();
		if (!options.element) return;
		this.tabBinding = new TabController(options).init();
	}

	syncTabs(activeId) {
		const binding = this.tabBinding;
		if (!binding) return;
		binding.sync(activeId);
	}

	disposeTabs() {
		if (!this.tabBinding) return;
		this.tabBinding.dispose();
		this.tabBinding = null;
	}

	/**
	 * Play a UI sound if sound manager is available
	 * @param {string} soundType - Type of sound to play (open, close, etc.)
	 */
	playSound(soundType) {
		const soundManager = this.getSoundManager();
		const sounds = SiteConfig.ui.interactionSounds;
		const soundId = soundType === 'open'
			? sounds.modalOpen
			: soundType === 'close'
				? sounds.modalClose
				: sounds.click;

		soundManager?.playWhenReady?.(soundId);
	}

	/**
	 * Get the sound manager from the parent hierarchy
	 * @returns {object|null} Sound manager object or null if not found
	 */
	getSoundManager() {
		// Navigate up the parent chain to find the core sound manager
		let current = this.parent;
		while (current) {
			if (current.core?.soundManager) {
				return current.core.soundManager;
			}
			if (current.parent) {
				current = current.parent;
			} else {
				break;
			}
		}
		return null;
	}

	/**
	 * Clean up event listeners when the modal is no longer needed
	 */
	dispose() {
		this.disposeTabs();
		// Remove all event listeners
		if (this.closeButton) {
			this.closeButton.onclick = null;
		}
		
		if (this.minimizeButton) {
			this.minimizeButton.onclick = null;
		}
		
		if (this.fullscreenButton) {
			this.fullscreenButton.onclick = null;
		}
		
		if (this.headerElement) {
			this.headerElement.ondblclick = null;
		}

		if (this.buttonElement) {
			this.buttonElement.onclick = null;
			this.buttonElement.oncontextmenu = null;
			delete this.buttonElement.dataset.modalTrigger;
		}

		document.removeEventListener('click', this.handleOutsideClick);

		if (this.options.draggable && this.modalElement) {
			const header = this.modalElement.querySelector('.window-panel__header') || this.modalElement;
			header.removeEventListener('pointerdown', this.handleDragStart);
		}

		this.handleDragEnd();
		
		// Remove from active windows array
		const index = ModalWindow.activeWindows.indexOf(this);
		if (index !== -1) {
			ModalWindow.activeWindows.splice(index, 1);
		}
	}
}
