/* -- js/UI/core/SegmentControl.js -- */
/**
 * SegmentControl — one row of buttons where exactly one is down.
 *
 * The build panels were reaching for radio inputs to express "pick one of
 * these", which in a 300px tool window costs a stacked row and a label per
 * option for a choice that is two words wide. A segment says the same thing on
 * one line, and it is already the shape the wall-view control uses — so this is
 * that control, generalized, rather than a second way of doing it.
 *
 * Markup: a root carrying `.segment-control` whose buttons carry `.segment-btn`
 * and a `data-value`. The DOM is the state; there is no shadow copy to drift.
 */
class SegmentControl {
    constructor(root, options = {}) {
        this.root = root || null;
        this.onChange = options.onChange || null;
        this.handleClick = this.handleClick.bind(this);
        this.root?.addEventListener('click', this.handleClick);
        if (options.value) this.value = options.value;
    }

    get buttons() {
        return [...(this.root?.querySelectorAll('.segment-btn') || [])];
    }

    get value() {
        return this.root?.querySelector('.segment-btn.active')?.dataset.value ?? null;
    }

    set value(next) {
        for (const button of this.buttons) {
            const selected = button.dataset.value === next;
            button.classList.toggle('active', selected);
            button.setAttribute('aria-pressed', String(selected));
        }
    }

    get values() {
        return this.buttons.map(button => button.dataset.value);
    }

    handleClick(event) {
        const button = event.target.closest('.segment-btn');
        if (!button || !this.root.contains(button)) return;
        event.preventDefault();
        this.select(button.dataset.value);
    }

    select(value) {
        if (value === null || value === undefined) return false;
        if (!this.values.includes(value)) return false;
        this.value = value;
        this.onChange?.(value);
        return true;
    }

    /** Walk the row by `direction`, wrapping — what Home/End bind to. */
    step(direction) {
        const values = this.values;
        if (values.length === 0) return false;
        const current = values.indexOf(this.value);
        const next = ((current < 0 ? 0 : current) + direction + values.length) % values.length;
        return this.select(values[next]);
    }

    setDisabled(flag) {
        for (const button of this.buttons) button.disabled = flag === true;
    }

    dispose() {
        this.root?.removeEventListener('click', this.handleClick);
        this.root = null;
        this.onChange = null;
    }
}
;
/* -- js/UI/core/BuildSettingToggle.js -- */
/**
 * BuildSettingToggle — a checkbox bound to one piece of build state.
 *
 * The state lives on the container, not on the control: the checkbox writes it
 * through the container's setter, and the keyboard drives that same setter, so
 * the two can never hold different answers. `sync()` is how the control catches
 * up after the keyboard moved it.
 */
class BuildSettingToggle {
    /**
     * @param {object} owner    the panel or component mounting this
     * @param {Element} root    the element to search for the checkbox
     * @param {object} config   { selector, setting, setter }
     */
    constructor(owner, root, config) {
        this.owner = owner;
        this.config = config;
        this.element = root?.querySelector(config.selector) || null;
        this.handleChange = () => this.container?.[config.setter]?.(this.element.checked);
        this.element?.addEventListener('change', this.handleChange);
    }

    // See WallViewControl: panels resolve the container through the UI, a
    // UIComponent has it directly.
    get container() {
        return this.owner?.container ?? this.owner?.parent?.parent ?? null;
    }

    sync() {
        if (this.element) {
            this.element.checked = this.container?.settings?.[this.config.setting] !== false;
        }
    }

    dispose() {
        this.element?.removeEventListener('change', this.handleChange);
        this.element = null;
        this.owner = null;
    }
}

/** The grid overlay. Also driven by the `G` key. */
class BuildGridToggle extends BuildSettingToggle {
    constructor(owner, root) {
        super(owner, root, {
            selector: '.build-grid-toggle',
            setting: 'buildGrid',
            setter: 'setBuildGridEnabled'
        });
    }
}

/** Whether dragged objects land on grid cells. `Ctrl` inverts it per drag. */
class BuildSnapToggle extends BuildSettingToggle {
    constructor(owner, root) {
        super(owner, root, {
            selector: '.build-snap-toggle',
            setting: 'buildSnap',
            setter: 'setBuildSnapEnabled'
        });
    }
}
;
/* -- js/UI/core/WallViewControl.js -- */
/**
 * WallViewControl — the Up / Cutaway / Down / Hidden segmented control.
 *
 * Build mode used to force walls up, which made the floor behind a south wall
 * unreachable in a small room. The presentation is the player's to pick, in
 * either mode; the control lives on the stage bar so it is one click away
 * while playing as well as while building.
 *
 * The row itself is a plain `SegmentControl` — including the Home/End walk,
 * since the buttons are already authored in order of how much wall you see.
 * What lives here is the part that is about walls: reading the builder's
 * current presentation, and writing a choice back to it.
 */
class WallViewControl {
    constructor(owner, root) {
        this.owner = owner;
        this.root = root || null;
        this.segment = new SegmentControl(
            this.root?.querySelector('.segment-control') || null,
            { onChange: (mode) => this.apply(mode) }
        );
    }

    // Mounted either on a panel (whose own `container` is unset — see
    // ModalWindow) or on a UIComponent, which has one.
    get container() {
        return this.owner?.container ?? this.owner?.parent?.parent ?? null;
    }

    get builder() {
        return this.container?.gameMap?.wallBuilder || null;
    }

    apply(mode) {
        if (!SiteConfig.wallSystem.presentationModes.includes(mode)) return false;
        const container = this.container;
        if (!container) return false;
        container.buildPresentation = mode;
        this.builder?.setUserPresentationMode(mode);
        return true;
    }

    select(mode) {
        return this.segment.select(mode);
    }

    // Home walks toward "more wall", End toward "less" — Sims muscle memory.
    step(direction) {
        return this.segment.step(direction);
    }

    /**
     * The builder is the truth while there is one: it is what build mode's
     * entry environment writes to, and what a freshly loaded map reports. The
     * remembered choice only answers for the gap before a map has walls.
     */
    sync() {
        this.segment.value = this.builder?.presentation ?? this.container?.buildPresentation ?? null;
        this.segment.setDisabled(!this.builder);
        if (this.root) this.root.hidden = SiteConfig.wallSystem?.enabled !== true;
    }

    dispose() {
        this.segment?.dispose();
        this.segment = null;
        this.root = null;
        this.owner = null;
    }
}
;
/* -- js/UI/core/PanelSection.js -- */
/**
 * PanelSection — a controller for one tab inside a shared window.
 *
 * Sound, View and Debug used to each own a window of their own and a sidebar
 * button to open it. They are now tabs of the Options window, but their
 * controllers are unchanged: this gives them the small slice of ModalWindow
 * they actually used (`modalElement`, `open`/`close`/`toggle`, `playSound`)
 * and points open/close at the owning window's tab instead of a window of
 * their own.
 */
class PanelSection {
    constructor(parent, options = {}) {
        this.parent = parent;
        this.options = { tab: null, owner: 'optionsPanel', ...options };
        this.modalElement = null;
        this.sectionElement = null;
        // Sections have no sidebar button of their own; the owner has one.
        this.buttonElement = null;
    }

    get owner() {
        return this.parent?.[this.options.owner] || null;
    }

    get isVisible() {
        return this.owner?.isVisible === true && this.owner?.activeTab === this.options.tab;
    }

    init() {
        this.modalElement = this.owner?.modalElement || null;
        this.sectionElement = this.modalElement?.querySelector(`[data-tab-panel="${this.options.tab}"]`) || null;
        if (!this.modalElement) {
            Utility.warnDebug(`[PanelSection] Options window missing for tab '${this.options.tab}'`);
        }
    }

    open() {
        this.owner?.openTab(this.options.tab);
    }

    close() {
        this.owner?.close();
    }

    toggle() {
        this.owner?.toggleTab(this.options.tab);
    }

    // Called by the owner when this section's tab becomes visible, so a section
    // can refresh values it only reads while on screen.
    onSectionShown() {}

    getSoundManager() {
        return this.parent?.parent?.core?.soundManager || null;
    }

    playSound(soundType) {
        const sounds = SiteConfig.ui.interactionSounds;
        const soundId = soundType === 'open'
            ? sounds.modalOpen
            : soundType === 'close'
                ? sounds.modalClose
                : sounds.click;
        this.getSoundManager()?.playWhenReady?.(soundId);
    }

    setupTabs() {}

    syncTabs() {}

    dispose() {
        this.modalElement = null;
        this.sectionElement = null;
        this.parent = null;
    }
}
;
/* -- js/UI/core/DetailRows.js -- */
// ─────────────────────────────────────────────────────────────────────────────
// DetailRows — the label/value list that shows up wherever a panel has to state
// a handful of facts: the world map's map details, the keyboard legends in
// Options, the calendar's day summary.
//
// Every one of those had its own markup and its own label-column width, so
// "Points of interest" and "Distance" started their values in different places
// and three legends under three headings each sized their key column
// separately. One `<dl>` with a shared column definition fixes both: within a
// list, every label shares the widest label's width.
//
// Two column strategies, because there are two situations:
//
//   default   the list sizes its own label column to its longest label. Right
//             for a list standing on its own.
//   subgrid   the list borrows its parent's columns, so several lists side by
//             side or stacked under separate headings still line up with each
//             other. Right for the legends inside a settings group.
// ─────────────────────────────────────────────────────────────────────────────

class DetailRows {
    /**
     * @param {Array} rows  `[label, value]` pairs, or `{ label, value, modifier }`
     *                      objects. A row with a null/undefined value is skipped,
     *                      so callers can list optional facts inline.
     * @param {Object} options
     * @param {boolean} options.subgrid  borrow the parent grid's columns.
     * @param {string} options.className extra classes for the list element.
     */
    static build(rows = [], options = {}) {
        const list = document.createElement('dl');
        list.className = ['detail-rows', options.subgrid ? 'detail-rows--subgrid' : '', options.className ?? '']
            .filter(Boolean).join(' ');

        for (const row of rows) {
            const { label, value, modifier } = Array.isArray(row)
                ? { label: row[0], value: row[1] }
                : row ?? {};
            if (value == null) continue;

            const term = document.createElement('dt');
            term.className = 'detail-row__label';
            term.textContent = label ?? '';

            const detail = document.createElement('dd');
            detail.className = ['detail-row__value', modifier].filter(Boolean).join(' ');
            // A value may be pre-built markup (a chip, a list of nodes) or plain
            // text; text goes in as text so save data can never become markup.
            if (value instanceof Node) detail.appendChild(value);
            else detail.textContent = String(value);

            list.append(term, detail);
        }

        return list;
    }

    /** Build and hand back as the sole content of `container`. */
    static render(container, rows = [], options = {}) {
        if (!container) return null;
        const list = this.build(rows, options);
        container.replaceChildren(list);
        return list;
    }
}
;
/* -- js/UI/core/WorldModal.js -- */
class WorldModal extends ModalWindow {
    constructor(parent, options = {}) {
        const worldOptions = {
            id: null,
            title: '',
            icon: '',
            closeOnBackdrop: true,
            draggable: true,
            ...options
        };

        super(parent, {
            id: worldOptions.id,
            title: worldOptions.title,
            floating: true,
            position: 'center',
            draggable: worldOptions.draggable,
            closeOnOutsideClick: false,
            allowMultipleWindows: true,
            rememberPosition: true,
            autoInit: false
        });

        this.worldOptions = worldOptions;
        this.hasManualPosition = false;
        this.options.dragBoundsElement = () => this.layerElement;
        this.boundSyncBounds = this.syncBounds.bind(this);
        this.build();
        this.init();
    }

    build() {
        const stage = this.parent?.parent?.element;
        if (!stage || !this.worldOptions.id) return;
        this.stageElement = stage;

        this.layerElement = document.createElement('div');
        this.layerElement.className = 'world-modal-layer ignore';
        this.layerElement.id = `${this.worldOptions.id}-layer`;
        this.layerElement.hidden = true;

        this.modalElement = document.createElement('section');
        this.modalElement.className = 'window-panel world-modal';
        this.modalElement.id = this.worldOptions.id;
        this.modalElement.setAttribute('role', 'dialog');
        this.modalElement.setAttribute('aria-modal', 'true');

        const header = document.createElement('header');
        header.className = 'window-panel__header world-modal__header';
        const title = document.createElement('h2');
        title.className = 'window-panel__title world-modal__title';
        this.iconElement = Utility.createIcon('');
        this.titleTextElement = document.createElement('span');
        this.titleTextElement.className = 'text';
        title.append(this.iconElement, this.titleTextElement);

        const controls = document.createElement('div');
        controls.className = 'window-panel__controls';
        const closeButton = document.createElement('button');
        closeButton.className = 'modal-close-btn world-modal__close';
        closeButton.type = 'button';
        closeButton.setAttribute('aria-label', 'Close');
        closeButton.textContent = '×';
        controls.appendChild(closeButton);
        header.append(title, controls);

        this.bodyElement = document.createElement('div');
        this.bodyElement.className = 'window-panel__content world-modal__body';
        this.modalElement.append(header, this.bodyElement);
        this.layerElement.appendChild(this.modalElement);
        document.body.appendChild(this.layerElement);

        this.setTitle(this.worldOptions.title);
        this.setIcon(this.worldOptions.icon);
        this.resizeObserver = typeof ResizeObserver === 'function'
            ? new ResizeObserver(this.boundSyncBounds)
            : null;
        this.resizeObserver?.observe(stage);
        window.addEventListener('resize', this.boundSyncBounds);
        window.addEventListener('scroll', this.boundSyncBounds, { passive: true });

        this.layerElement.addEventListener('pointerdown', event => {
            event.stopPropagation();
            if (this.worldOptions.closeOnBackdrop && event.target === this.layerElement) this.close();
        });
        this.modalElement.addEventListener('click', event => event.stopPropagation());
    }

    setTitle(title) {
        if (this.titleTextElement) this.titleTextElement.textContent = String(title || '');
    }

    // `icon` is a sprite symbol name from the #icon-sprite block in index.html.
    setIcon(icon) {
        if (!this.iconElement) return;
        Utility.setIcon(this.iconElement, icon);
        this.iconElement.hidden = !icon;
    }

    setContent(content) {
        if (!this.bodyElement) return;
        this.bodyElement.replaceChildren();
        if (content) this.bodyElement.appendChild(content);
    }

    syncBounds() {
        if (!this.layerElement || !this.stageElement) return;
        const rect = this.stageElement.getBoundingClientRect();
        this.layerElement.style.left = `${rect.left}px`;
        this.layerElement.style.top = `${rect.top}px`;
        this.layerElement.style.width = `${rect.width}px`;
        this.layerElement.style.height = `${rect.height}px`;
        if (this.isVisible && !this.hasManualPosition) this.centerInStage();
    }

    centerInStage() {
        if (!this.modalElement || !this.stageElement) return;
        const stageRect = this.stageElement.getBoundingClientRect();
        const modalRect = this.modalElement.getBoundingClientRect();
        this.modalElement.classList.remove(
            'position-center',
            'position-top-right',
            'position-top-left',
            'position-bottom-right',
            'position-bottom-left'
        );
        this.modalElement.style.left = `${stageRect.left + ((stageRect.width - modalRect.width) / 2)}px`;
        this.modalElement.style.top = `${stageRect.top + ((stageRect.height - modalRect.height) / 2)}px`;
        this.modalElement.style.transform = '';
    }

    handleDragStart(event) {
        super.handleDragStart(event);
        if (this.isDragging) this.hasManualPosition = true;
    }

    open() {
        if (!this.layerElement || this.isVisible) return;
        const needsInitialPlacement = !this.hasManualPosition && !this.modalElement.style.left;
        if (needsInitialPlacement) this.modalElement.classList.add('is-positioning');
        this.layerElement.hidden = false;
        this.syncBounds();
        if (!this.hasManualPosition) this.centerInStage();
        if (needsInitialPlacement) {
            void this.modalElement.offsetWidth;
            this.modalElement.classList.remove('is-positioning');
        }
        super.open();
        this.modalElement.querySelector('button, [href], input, select, textarea')?.focus();
    }

    close() {
        if (!this.layerElement || !this.isVisible) return;
        super.close();
        this.layerElement.hidden = true;
    }

    dispose() {
        this.resizeObserver?.disconnect();
        window.removeEventListener('resize', this.boundSyncBounds);
        window.removeEventListener('scroll', this.boundSyncBounds);
        super.dispose();
        this.layerElement?.remove();
        this.resizeObserver = null;
        this.stageElement = null;
        this.layerElement = null;
        this.modalElement = null;
        this.titleTextElement = null;
        this.iconElement = null;
        this.bodyElement = null;
    }
}
;
/* -- js/UI/panels/MyteInfoPanel.js -- */
class MyteInfoPanel extends ModalWindow {
    static GENERAL_FIELDS = Object.freeze([
        Object.freeze({ key: 'status', label: 'Status' }),
        Object.freeze({ key: 'species', label: 'Species' }),
        Object.freeze({ key: 'level', label: 'Level' }),
        Object.freeze({ key: 'mood', label: 'Mood' }),
        Object.freeze({ key: 'action', label: 'Current Action' }),
        Object.freeze({ key: 'slot', label: 'Home Slot' }),
        Object.freeze({ key: 'id', label: 'File ID' })
    ]);

    static STAT_FIELDS = Object.freeze([
        Object.freeze({ key: 'health', label: 'Health', minKey: 'minHealth', maxKey: 'maxHealth' }),
        Object.freeze({ key: 'energy', label: 'Energy', minKey: 'minEnergy', maxKey: 'maxEnergy' }),
        Object.freeze({ key: 'fun', label: 'Fun', minKey: 'minFun', maxKey: 'maxFun' }),
        Object.freeze({ key: 'social', label: 'Social', minKey: 'minSocial', maxKey: 'maxSocial' }),
        Object.freeze({ key: 'satiety', label: 'Satiety', minKey: 'minSatiety', maxKey: 'maxSatiety' }),
        Object.freeze({ key: 'comfort', label: 'Comfort', minKey: 'minComfort', maxKey: 'maxComfort' }),
        Object.freeze({
            key: 'confidence',
            label: 'Confidence',
            minKey: 'minConfidence',
            maxKey: 'maxConfidence',
            displayScale: 100
        })
    ]);

    static TRAIT_FIELDS = Object.freeze([
        Object.freeze({ key: 'boldness', label: 'Boldness', lowPole: 'Timid', highPole: 'Reckless' }),
        Object.freeze({ key: 'curiosity', label: 'Curiosity', lowPole: 'Contented', highPole: 'Obsessive' }),
        Object.freeze({ key: 'activity', label: 'Activity', lowPole: 'Lethargic', highPole: 'Frantic' }),
        Object.freeze({ key: 'sociability', label: 'Sociability', lowPole: 'Reclusive', highPole: 'Clingy' })
    ]);

    static DRIVE_LABELS = Object.freeze({
        eatDrive: 'Hunger',
        restDrive: 'Rest',
        playDrive: 'Play',
        socialDrive: 'Social',
        exploreDrive: 'Explore',
        comfortDrive: 'Comfort',
        safetyDrive: 'Safety'
    });

    constructor(parent) {
        super(parent, {
            id: 'myte-info-panel',
            closeOnOutsideClick: false,
            position: 'center',
            draggable: true,
            allowMultipleWindows: true,
            autoInit: false
        });

        this.myte = null;
        this.activeTab = 'general';
        this.debugEditing = false;
        this.renderedMyteId = null;
        this.renderedTab = null;
        this.valueElements = new Map();
        this.lastValues = new Map();
        this.lastSyncAt = 0;
        this.init();
    }

    init() {
        super.init();
        if (!this.modalElement) return;

        this.titleElement = this.modalElement.querySelector('.window-panel__title .text');
        this.portraitElement = this.modalElement.querySelector('.myte-info__portrait');
        this.nameElement = this.modalElement.querySelector('.myte-info__name');
        this.speciesElement = this.modalElement.querySelector('.myte-info__species');
        this.bodyElement = this.modalElement.querySelector('.myte-info__body');
        this.tabsElement = this.modalElement.querySelector('.myte-info__tabs');

        this.setupTabs({
            element: this.tabsElement,
            buttonSelector: '[data-myte-info-tab]',
            getTabId: (tab) => tab.dataset.myteInfoTab,
            onChange: (tabId) => this.setActiveTab(tabId)
        });
    }

    openFor(myte) {
        if (!myte) return;
        const changedMyte = String(this.myte?.id) !== String(myte.id);
        this.myte = myte;
        if (changedMyte) {
            this.renderedMyteId = null;
            this.renderedTab = null;
        }
        this.renderShell();
        this.renderTab();
        this.syncDynamicValues(true);
        if (!this.isVisible) super.open();
    }

    setActiveTab(tabId) {
        const nextTab = tabId === 'debug' && !this.debugEditing ? 'general' : tabId;
        if (!['general', 'needs', 'behavior', 'drives', 'debug'].includes(nextTab)) return;
        if (this.activeTab === nextTab && this.renderedTab === nextTab) return;
        this.activeTab = nextTab;
        this.renderTab();
        this.syncDynamicValues(true);
    }

    setDebugEditing(enabled) {
        const nextValue = enabled === true;
        if (this.debugEditing === nextValue) return;
        this.debugEditing = nextValue;
        if (!this.debugEditing && this.activeTab === 'debug') this.activeTab = 'general';
        this.renderShell();
        this.renderTab();
        this.syncDynamicValues(true);
    }

    isDebugEditing() {
        return this.debugEditing;
    }

    renderShell() {
        if (!this.myte || !this.modalElement) return;

        const myteId = String(this.myte.id);
        if (this.renderedMyteId !== myteId) {
            this.titleElement.textContent = `${this.myte.name}.myte`;
            this.nameElement.textContent = this.myte.name;
            this.speciesElement.textContent = this.getSpeciesLabel();
            this.renderPortrait();
            this.renderedMyteId = myteId;
        }

        this.tabsElement.querySelectorAll('[data-myte-info-tab]').forEach((tab) => {
            const isDebugTab = tab.dataset.myteInfoTab === 'debug';
            tab.hidden = isDebugTab && !this.debugEditing;
        });
        this.syncTabs(this.activeTab);
        const activeTab = this.tabsElement.querySelector(`[data-myte-info-tab="${this.activeTab}"]`);
        if (activeTab?.id) this.bodyElement.setAttribute('aria-labelledby', activeTab.id);
    }

    renderTab() {
        if (!this.myte || !this.bodyElement) return;
        this.renderShell();
        if (this.renderedTab === this.activeTab) return;

        this.valueElements.clear();
        this.lastValues.clear();
        this.bodyElement.dataset.activeTab = this.activeTab;
        this.bodyElement.replaceChildren(this.buildActiveTab());
        this.renderedTab = this.activeTab;
    }

    buildActiveTab() {
        if (this.activeTab === 'needs') return this.buildNeedsTab();
        if (this.activeTab === 'behavior') return this.buildBehaviorTab();
        if (this.activeTab === 'drives') return this.buildDrivesTab();
        if (this.activeTab === 'debug' && this.debugEditing) return this.buildDebugTab();
        return this.buildGeneralTab();
    }

    buildGeneralTab() {
        const rows = this.createRowsContainer();
        MyteInfoPanel.GENERAL_FIELDS.forEach((field) => {
            const value = document.createElement('span');
            value.className = 'myte-info__text-value';
            this.valueElements.set(field.key, value);
            rows.appendChild(this.createInfoRow(field.label, value));
        });
        return rows;
    }

    buildNeedsTab() {
        const rows = this.createRowsContainer();
        MyteInfoPanel.STAT_FIELDS
            .filter((field) => field.key !== 'confidence')
            .forEach((field) => rows.appendChild(this.createInfoRow(
                field.label,
                this.createMeterValue(field.key)
            )));
        return rows;
    }

    buildBehaviorTab() {
        const dashboard = this.createRowsContainer();
        dashboard.classList.add('myte-info__dashboard');

        const status = this.createInfoSection('Current Behavior', 'myte-info__section--status');
        [
            ['behavior:mood', 'Mood'],
            ['behavior:mode', 'Behavior'],
            ['behavior:detail', 'Behavior Detail'],
            ['behavior:activity', 'Activity'],
            ['behavior:decision', 'Last AI Choice']
        ].forEach(([key, label]) => {
            const value = document.createElement('span');
            value.className = 'myte-info__text-value';
            this.valueElements.set(key, value);
            status.body.appendChild(this.createInfoRow(label, value));
        });

        const personality = this.createInfoSection('Personality');
        personality.body.appendChild(this.createInfoRow(
            'Confidence',
            this.createMeterValue('personality:confidence')
        ));
        MyteInfoPanel.TRAIT_FIELDS.forEach((field) => {
            personality.body.appendChild(this.createTraitRow(field));
        });

        dashboard.append(status.section, personality.section);
        return dashboard;
    }

    buildDrivesTab() {
        const page = this.createRowsContainer();
        const summary = document.createElement('p');
        summary.className = 'myte-info__page-description';
        summary.textContent = 'Drives show what the AI currently feels most compelled to do.';
        page.appendChild(summary);

        Object.entries(MyteInfoPanel.DRIVE_LABELS).forEach(([key, label]) => {
            page.appendChild(this.createInfoRow(
                label,
                this.createMeterValue(`drive:${key}`, 'is-urgency')
            ));
        });
        return page;
    }

    createInfoSection(title, className = '') {
        const section = document.createElement('section');
        section.className = `myte-info__section ${className}`.trim();
        const heading = document.createElement('h3');
        heading.className = 'myte-info__section-title';
        heading.textContent = title;
        const body = document.createElement('div');
        body.className = 'myte-info__section-body';
        section.append(heading, body);
        return { section, body };
    }

    createMeterValue(key, className = '') {
        const valueWrap = document.createElement('div');
        valueWrap.className = `myte-info__need-value ${className}`.trim();
        const meter = document.createElement('div');
        meter.className = 'myte-info__meter';
        meter.setAttribute('role', 'progressbar');
        meter.setAttribute('aria-valuemin', '0');
        meter.setAttribute('aria-valuemax', '100');
        const fill = document.createElement('span');
        meter.appendChild(fill);
        const output = document.createElement('output');
        valueWrap.append(meter, output);
        this.valueElements.set(key, { fill, output, meter });
        return valueWrap;
    }

    createTraitRow(field) {
        const valueWrap = document.createElement('div');
        valueWrap.className = 'myte-info__trait-value';
        const low = document.createElement('span');
        low.textContent = field.lowPole;
        const track = document.createElement('span');
        track.className = 'myte-info__trait-track';
		track.setAttribute('role', 'progressbar');
		track.setAttribute('aria-valuemin', '0');
		track.setAttribute('aria-valuemax', '100');
        const marker = document.createElement('span');
        marker.className = 'myte-info__trait-marker';
        track.appendChild(marker);
        const high = document.createElement('span');
        high.textContent = field.highPole;
        valueWrap.append(low, track, high);
        this.valueElements.set(`trait:${field.key}`, { marker, track });
        return this.createInfoRow(field.label, valueWrap);
    }

    buildDebugTab() {
        const editor = this.createRowsContainer();

        const nameInput = document.createElement('input');
        nameInput.type = 'text';
        nameInput.value = this.myte.name;
        nameInput.maxLength = 30;
        const applyName = document.createElement('button');
        applyName.type = 'button';
        applyName.textContent = 'Apply';
        applyName.addEventListener('click', () => this.renameMyte(nameInput.value));
        const nameControls = document.createElement('div');
        nameControls.className = 'myte-info__name-controls';
        nameControls.append(nameInput, applyName);
        editor.appendChild(this.createInfoRow('Display Name', nameControls));

        MyteInfoPanel.STAT_FIELDS.forEach((field) => {
            const controls = document.createElement('div');
            controls.className = 'myte-info__stat-controls';
            const minus = document.createElement('button');
            minus.type = 'button';
            minus.textContent = '−';
            const output = document.createElement('output');
            const plus = document.createElement('button');
            plus.type = 'button';
            plus.textContent = '+';
            minus.addEventListener('click', () => this.adjustStat(field, -SiteConfig.debug.statStep));
            plus.addEventListener('click', () => this.adjustStat(field, SiteConfig.debug.statStep));
            controls.append(minus, output, plus);
            this.valueElements.set(field.key, output);
            editor.appendChild(this.createInfoRow(field.label, controls));
        });

        return editor;
    }

    createRowsContainer() {
        const rows = document.createElement('div');
        rows.className = 'info-list myte-info__page myte-info__rows';
        rows.setAttribute('role', 'tabpanel');
        rows.setAttribute('aria-label', `${this.activeTab} information`);
        return rows;
    }

    createInfoRow(labelText, valueElement) {
        const row = document.createElement('div');
        row.className = 'info-row myte-info__row';
        const label = document.createElement('span');
        label.className = 'info-row__label myte-info__row-label';
        label.textContent = labelText;
        const value = document.createElement('div');
        value.className = 'info-row__value myte-info__row-value';
        value.appendChild(valueElement);
        row.append(label, value);
        return row;
    }

    getGeneralValues() {
        const action = this.myte.queue?.getCurrentAction?.();
        return {
            status: this.getStatusLabel(),
            species: this.getSpeciesLabel(),
            level: String(this.myte.stats?.level ?? 1),
            mood: this.myte.stats?.getDerivedMood?.() ?? 'Neutral',
            action: action?.constructor?.metadata?.label || action?.constructor?.metadata?.id || 'Idle',
            slot: this.myte.elements?.wrapper?.querySelector?.('.myte-home-label .name')?.textContent || 'None',
            id: String(this.myte.id)
        };
    }

    getStatSnapshot(field) {
        const value = Number(this.myte.stats?.[field.key]) || 0;
        const min = Number(this.myte.stats?.[field.minKey]) || 0;
        const max = Number(this.myte.stats?.[field.maxKey]) || 100;
        const percentage = Math.round(Utility.clamp((value - min) / Math.max(1, max - min), 0, 1) * 100);
        return {
            percentage,
            display: Math.round(value * (field.displayScale || 1))
        };
    }

    syncDynamicValues(force = false) {
        if (!this.myte || !this.isVisible && !force) return;

        if (this.activeTab === 'general') {
            const values = this.getGeneralValues();
            Object.entries(values).forEach(([key, value]) => this.updateTextValue(key, value, force));
        } else if (this.activeTab === 'needs') {
            MyteInfoPanel.STAT_FIELDS.filter((field) => field.key !== 'confidence').forEach((field) => {
                const snapshot = this.getStatSnapshot(field);
                this.updateMeterValue(field.key, snapshot.percentage, force);
            });
        } else if (this.activeTab === 'behavior') {
            this.syncBehaviorValues(force);
        } else if (this.activeTab === 'drives') {
            this.syncDriveValues(force);
        } else if (this.activeTab === 'debug') {
            MyteInfoPanel.STAT_FIELDS.forEach((field) => {
                const snapshot = this.getStatSnapshot(field);
                this.updateTextValue(field.key, String(snapshot.display), force);
            });
        }

        this.lastSyncAt = performance.now();
    }

    syncBehaviorValues(force = false) {
        const snapshot = this.myte.ai?.getNeedsSnapshot?.({ live: true }) ?? {};
        const sidebar = this.parent.actionSidebarManager;
        const detail = sidebar?.getMyteBehaviorDetail?.(this.myte);
        const behaviorValues = {
            'behavior:mood': this.myte.stats?.getDerivedMood?.() ?? 'Neutral',
            'behavior:mode': sidebar?.getMyteBehaviorLabel?.(this.myte) ?? this.getStatusLabel(),
            'behavior:detail': detail?.value ?? 'Standard',
            'behavior:activity': sidebar?.getMyteActivityLabel?.(this.myte) ?? 'Idle',
            'behavior:decision': snapshot.lastDecisionLabel ?? 'No decision yet'
        };
        Object.entries(behaviorValues).forEach(([key, value]) => this.updateTextValue(key, value, force));

        this.updateMeterValue('personality:confidence', snapshot.vitals?.confidence ?? 0, force);
        MyteInfoPanel.TRAIT_FIELDS.forEach((field) => {
            const percentage = Math.round((this.myte.stats?.getTraitNormalized?.(field.key) ?? 0.5) * 100);
            this.updateTraitValue(`trait:${field.key}`, percentage, force);
        });

    }

    syncDriveValues(force = false) {
        const snapshot = this.myte.ai?.getNeedsSnapshot?.({ live: true }) ?? {};
        const needs = new Map((snapshot.needs ?? []).map((need) => [need.id, need.percent ?? 0]));
        Object.keys(MyteInfoPanel.DRIVE_LABELS).forEach((key) => {
            this.updateMeterValue(`drive:${key}`, needs.get(key) ?? 0, force);
        });
    }

    updateMeterValue(key, percentage, force = false) {
        const normalized = Math.round(Utility.clamp(Number(percentage) || 0, 0, 100));
        if (!force && this.lastValues.get(key) === normalized) return;
        const elements = this.valueElements.get(key);
        if (!elements) return;
        elements.fill.style.width = `${normalized}%`;
        elements.output.textContent = `${normalized}%`;
        elements.meter?.setAttribute('aria-valuenow', String(normalized));
        this.lastValues.set(key, normalized);
    }

    updateTraitValue(key, percentage, force = false) {
        const normalized = Math.round(Utility.clamp(Number(percentage) || 0, 0, 100));
        if (!force && this.lastValues.get(key) === normalized) return;
        const elements = this.valueElements.get(key);
        if (!elements) return;
        elements.marker.style.left = `${normalized}%`;
		elements.track.setAttribute('aria-valuenow', String(normalized));
        this.lastValues.set(key, normalized);
    }

    updateTextValue(key, value, force = false) {
        const normalized = String(value);
        if (!force && this.lastValues.get(key) === normalized) return;
        const element = this.valueElements.get(key);
        if (element) element.textContent = normalized;
        this.lastValues.set(key, normalized);
    }

    renderPortrait() {
        this.portraitElement.replaceChildren();
        const sprite = document.createElement('span');
        sprite.className = 'myte-info__portrait-sprite';
        const inner = document.createElement('span');
        inner.className = 'myte-info__portrait-sprite-inner';
        sprite.appendChild(inner);
        this.portraitElement.appendChild(sprite);
        this.parent.myteListManager?.applyThumbnailVisuals?.(sprite, inner, this.myte);
    }

    getSpeciesLabel() {
        return this.myte.definition?.label || this.myte.species || 'Myte';
    }

    getStatusLabel() {
        if (!this.myte.isActive) return 'In Home Slot';
        if (this.myte === this.parent.getActiveMyte()) return 'Following';
        if (this.myte.goal === MOVE_TYPES.FREEROAM) return 'Free Roam';
        return 'Deployed';
    }

    adjustStat(field, displayDelta) {
        const stats = this.myte.stats;
        if (!stats) return;
        const scale = field.displayScale || 1;
        const min = Number(stats[field.minKey]) || 0;
        const max = Number(stats[field.maxKey]) || 100;
        stats[field.key] = Utility.clamp(stats[field.key] + (displayDelta / scale), min, max);
        stats.updateBatteryDisplay?.();
        this.parent.parent.core?.user?._scheduleSave?.();
        this.parent.hudManager?.update?.(true);
        this.syncDynamicValues();
    }

    renameMyte(rawName) {
        const name = String(rawName || '').trim();
        if (!name) return;
        const rosterEntry = MyteRosterSchema.normalizeEntry({
            ...MyteRosterSchema.serializeMyte(this.myte),
            name
        });
        MyteRosterSchema.applyToMyte(this.myte, rosterEntry);
        this.parent.myteListManager?.initMytesList?.();
        this.parent.hudManager?.update?.(true);
        this.parent.parent.core?.user?._scheduleSave?.();
        this.renderedMyteId = null;
        this.renderShell();
    }

    update() {
        if (!this.isVisible) return;
        if (performance.now() - this.lastSyncAt < SiteConfig.ui.hud.updateIntervalMs) return;
        this.syncDynamicValues();
    }

    dispose() {
        super.dispose();
        this.valueElements.clear();
        this.lastValues.clear();
        this.myte = null;
        this.titleElement = null;
        this.portraitElement = null;
        this.nameElement = null;
        this.speciesElement = null;
        this.bodyElement = null;
        this.tabsElement = null;
    }
}
;
/* -- js/UI/panels/UserProfilePanel.js -- */
class UserProfilePanel extends ModalWindow {
    constructor(parent) {
        super(parent, {
            id: 'user-profile-panel',
            // The header's name plate is this window's trigger.
            buttonId: 'header-user-button',
            closeOnOutsideClick: false,
            position: 'center',
            draggable: true,
            fullscreen: true,
            allowMultipleWindows: true,
            autoInit: false
        });
        this.activeTab = 'account';
        this.init();
    }

    init() {
        super.init();
        if (!this.modalElement) return;

        this.avatarElement = this.modalElement.querySelector('.user-profile__avatar');
        this.nameElement = this.modalElement.querySelector('.user-profile__name');
        this.idElement = this.modalElement.querySelector('.user-profile__id');
        this.tabsElement = this.modalElement.querySelector('.user-profile__tabs');
        this.bodyElement = this.modalElement.querySelector('.user-profile__body');
        this.setupTabs({
            element: this.tabsElement,
            buttonSelector: '[data-user-profile-tab]',
            getTabId: (tab) => tab.dataset.userProfileTab,
            onChange: (tabId) => this.setActiveTab(tabId)
        });
        this.syncTabs(this.activeTab);
    }

    open() {
        this.render();
        super.open();
    }

    setActiveTab(tabId) {
        if (!['account', 'progress'].includes(tabId)) return;
        this.activeTab = tabId;
        this.renderTab();
    }

    render() {
        const user = this.getUser();
        if (!user || !this.bodyElement) return;

        const username = user.username || 'Guest';
        this.avatarElement.textContent = username.trim().charAt(0).toUpperCase() || 'G';
        this.nameElement.textContent = username;
        this.idElement.textContent = `User ID: ${user.userId || 'default'}`;
        this.renderTab();
        this.syncTabs(this.activeTab);
    }

    renderTab() {
        const user = this.getUser();
        if (!user || !this.bodyElement) return;
        this.bodyElement.dataset.activeTab = this.activeTab;
        this.bodyElement.replaceChildren(
            this.activeTab === 'progress'
                ? this.buildRows(this.getProgressEntries(user))
                : this.buildRows(this.getAccountEntries(user))
        );
    }

    getUser() {
        return this.parent.parent?.core?.user || null;
    }

    getAccountEntries(user) {
        return [
            ['Username', user.username || 'Guest'],
            ['User ID', user.userId || 'default'],
            ['Member since', this.formatDate(user.dateCreated)],
            ['Last login', this.formatDate(user.lastLogin)],
            ['Current map', user.currentMapId || 'Unknown']
        ];
    }

    getProgressEntries(user) {
        const playTime = user.getPlayTimeStats?.() ?? { totalHours: 0, totalMinutes: 0 };
        const inventory = user.inventory?.items ?? user.items ?? [];
        const itemCount = inventory.reduce((total, item) => total + (Number(item.quantity) || 0), 0);
        return [
            ['Play time', `${Utility.formatNumber(playTime.totalHours)}h ${Utility.formatNumber(playTime.totalMinutes)}m`],
            ['Mytes', user.activeMytes?.length ?? 0],
            ['Items', itemCount],
            ['Coins', Utility.formatCurrency('coins', user.currency?.coins ?? 0)],
            ['Gems', user.currency?.gems ?? 0],
            ['Mytes hatched', user.stats?.mytesHatched ?? 0],
            ['Achievements', user.stats?.achievementsUnlocked ?? user.achievements?.size ?? 0]
        ];
    }

    buildRows(entries) {
        const list = document.createElement('dl');
        list.className = 'info-list user-profile__stats';
        entries.forEach(([label, value]) => {
            const row = document.createElement('div');
            row.className = 'info-row user-profile__stat';
            const term = document.createElement('dt');
            term.className = 'info-row__label';
            term.textContent = label;
            const description = document.createElement('dd');
            description.className = 'info-row__value';
            description.textContent = typeof value === 'number'
                ? Utility.formatNumber(value)
                : String(value);
            row.append(term, description);
            list.appendChild(row);
        });
        return list;
    }

    formatDate(value) {
        if (!value) return 'Unknown';
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return 'Unknown';
        return new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(date);
    }
}
;
/* -- js/UI/panels/ShopPanel.js -- */
class ShopPanel extends WorldModal {
    constructor(parent) {
        super(parent, {
            id: 'world-shop-panel',
            title: 'Shop',
            icon: 'shop',
            closeOnBackdrop: true,
            draggable: true
        });
        this.shop = null;
        this.shopkeeper = null;
        this.itemRows = new Map();
        this.lastDialogueChoices = new Map();
    }

    openFor(shopkeeper, shopId) {
        const shop = ShopRegistry.getShop(shopId);
        if (!shop) {
            console.warn(`[ShopPanel] Unknown shop "${shopId}".`);
            return;
        }

        this.shopkeeper = shopkeeper || null;
        this.shop = shop;
        this.setTitle(shop.name);
        this.renderShop();
        this.setDialogue('welcome');
        super.open();
    }

    renderShop() {
        this.itemRows.clear();
        const content = document.createElement('div');
        content.className = 'shop-panel';

        const shopkeeper = document.createElement('div');
        shopkeeper.className = 'shop-panel__shopkeeper';
        const identity = document.createElement('div');
        identity.className = 'shop-panel__identity';
        const name = document.createElement('strong');
        name.textContent = this.shop.shopkeeper.name || 'Shopkeeper';
        const title = document.createElement('span');
        title.textContent = this.shop.shopkeeper.title || '';
        identity.append(name, title);
        this.dialogueElement = document.createElement('p');
        this.dialogueElement.className = 'shop-panel__dialogue';
        this.dialogueElement.setAttribute('aria-live', 'polite');
        shopkeeper.append(identity, this.dialogueElement);

        const itemList = document.createElement('div');
        itemList.className = 'shop-panel__items';
        if (this.shop.items.length === 0) {
            const emptyState = document.createElement('div');
            emptyState.className = 'window-empty-state';
            emptyState.textContent = 'Nothing is for sale right now. Check back later.';
            itemList.appendChild(emptyState);
        } else {
            this.shop.items.forEach(entry => itemList.appendChild(this.buildItemRow(entry)));
        }

        content.append(shopkeeper, itemList);
        this.setContent(content);
    }

    buildItemRow(entry) {
        const item = ItemRegistry.getItemSync(entry.itemId);
        const row = document.createElement('article');
        row.className = 'shop-item';
        row.dataset.itemId = item.id;

        const image = document.createElement('span');
        image.className = `shop-item__image item ${item.type} ${item.id}`;
        image.setAttribute('role', 'img');
        image.setAttribute('aria-label', item.name);
        ItemRegistry.applySpriteStyles(image, item.id);

        const details = document.createElement('div');
        details.className = 'shop-item__details';
        const heading = document.createElement('div');
        heading.className = 'shop-item__heading';
        const name = document.createElement('strong');
        name.className = 'shop-item__name';
        name.textContent = item.name;
        const stock = document.createElement('span');
        stock.className = 'shop-item__stock';
        heading.append(name, stock);
        const description = document.createElement('span');
        description.className = 'shop-item__description';
        description.textContent = item.description;
        details.append(heading, description);

        const purchase = document.createElement('div');
        purchase.className = 'shop-item__purchase';
        const button = document.createElement('button');
        button.type = 'button';
        button.addEventListener('click', () => this.purchase(entry.itemId));
        purchase.appendChild(button);
        row.append(image, details, purchase);

        this.itemRows.set(item.id, { stock, button, entry, image });
        this.syncStock(entry.itemId);
        return row;
    }

    purchase(itemId) {
        if (!this.shop) return;
        const container = this.parent.parent;
        const result = ShopRegistry.purchase(
            this.shop.id,
            itemId,
            container.core?.user,
            container.inventory
        );
        this.syncStock(itemId);
        this.setDialogue(result.reason, result);

        if (result.ok) {
            const row = this.itemRows.get(ItemRegistry.resolveIdSync(itemId));
            container.inventory?.playAcquisition(result.item.id, row?.image ?? null);
        }
    }

    setDialogue(reason, result = {}) {
        if (!this.dialogueElement || !this.shop) return;
        const item = result.item || ItemRegistry.getItemSync(result.entry?.itemId);
        const previousIndex = this.lastDialogueChoices.get(reason) ?? -1;
        const choice = ShopRegistry.chooseDialogue(
            this.shop.dialogue[reason] || this.shop.dialogue.welcome,
            previousIndex
        );
        this.lastDialogueChoices.set(reason, choice.index);
        this.dialogueElement.textContent = ShopRegistry.formatDialogue(
            choice.text,
            {
                item: item?.name || 'that item',
                price: result.entry?.price ?? 0,
                stock: result.stock ?? 0
            }
        );
    }

    syncStock(itemId) {
        const controls = this.itemRows.get(ItemRegistry.resolveIdSync(itemId));
        if (!controls || !this.shop) return;
        const stock = ShopRegistry.getStock(this.shop.id, itemId);
        const stockText = stock > 0 ? `× ${stock}` : 'Sold out';
        if (controls.stock.textContent !== stockText) controls.stock.textContent = stockText;
        controls.button.disabled = stock <= 0;
        controls.button.textContent = stock > 0
            ? `Buy 1× for ${Utility.formatCurrency(this.shop.currency, controls.entry.price)}`
            : 'Sold out';
    }

    close() {
        super.close();
        this.shopkeeper = null;
    }

    dispose() {
        this.itemRows.clear();
        this.lastDialogueChoices.clear();
        this.shop = null;
        this.shopkeeper = null;
        super.dispose();
    }
}
;
/* -- js/UI/debug/DebugOverlayUI.js -- */
class DebugOverlayUI {
    static PERSIST_KEY = 'neko.debug';
    static FLOATING_MARGIN = 8;
    static MIN_VISIBLE_WIDTH = 120;
    static MIN_VISIBLE_HEIGHT = 40;

    constructor(parent) {
        this.parent = parent;
        this.debug = document.querySelector('.debug-panel');
        this.cameraEnabled = false;
        this.camera = null;
        this.wasDebugEnabled = false;

        // Per-section drag + collapse state (keyed by sectionKey + 'queue')
        this.debugSectionState = {
            system:   { x: null, y: null, open: true, groups: {} },
            myte:     { x: null, y: null, open: true, groups: {} },
            overlays: { x: null, y: null, open: true, groups: {} },
            queue:    { x: null, y: null }
        };
        this._initializeFloatingStateMetadata();

        this.overlayState = {
            colliders:   true,
            interaction: false,
            hit:         false,
            select:      false,
            pickup:      false,
            anchors:     false
        };
        this.directWorldInteractionEnabled = false;

        this.debugDomRefs = new Map();
        this.debugOverlaySetup = false;

        // Drag tracking (shared for debug sections + queue panel)
        this.dragState = null;
        this.handleDebugPointerDown   = this.onDebugPointerDown.bind(this);
        this.handleDebugPointerMove   = this.onDebugPointerMove.bind(this);
        this.handleDebugPointerUp     = this.onDebugPointerUp.bind(this);
        this.handleDebugSummaryClick  = this.onDebugSummaryClick.bind(this);
        this.handleQueuePointerDown   = this.onQueuePointerDown.bind(this);
        this.handleWindowResize       = this.onWindowResize.bind(this);

        this.queueUI = new QueueUI(parent);
        this.lastDebugUpdate = 0;
        this.debugUpdateInterval = 100;
        this.gridBootstrapAttempts = 0;
        this.lastBootstrappedGridSystem = null;

        this._mountFloatingPanels();

        // Load persisted state and apply
        this._applyPersistedState();
        window.addEventListener('resize', this.handleWindowResize);
    }

    // ─── persistence helpers ─────────────────────────────────────────────────

    _mountFloatingPanels() {
        const queueEl = this.queueUI?.queue;
        if (!this.debug || !queueEl || queueEl.parentElement === this.debug) return;
        this.debug.appendChild(queueEl);
    }

    _initializeFloatingStateMetadata() {
        Object.values(this.debugSectionState).forEach(state => {
            if (!state || typeof state !== 'object') return;
            state.groups ??= {};
            state._hasSavedPosition = false;
            state._hasSavedOpen = false;
            state._hasSavedCollapsed = false;
            state._responsiveStateResolved = false;
        });
    }

    _loadState() {
        try {
            return JSON.parse(localStorage.getItem(DebugOverlayUI.PERSIST_KEY) || '{}');
        } catch {
            return {};
        }
    }

    _saveState(patch) {
        try {
            const state = this._loadState();
            Object.assign(state, patch);
            localStorage.setItem(DebugOverlayUI.PERSIST_KEY, JSON.stringify(state));
        } catch {}
    }

    _saveSectionState(key) {
        const s = this.debugSectionState[key];
        if (!s) return;
        const state = this._loadState();
        if (!state.sections) state.sections = {};
        state.sections[key] = {
            x: s.x,
            y: s.y,
            open: s.open,
            groups: { ...(s.groups || {}) }
        };
        try { localStorage.setItem(DebugOverlayUI.PERSIST_KEY, JSON.stringify(state)); } catch {}
    }

    _saveQueueState() {
        const q = this.debugSectionState.queue;
        const state = this._loadState();
        state.queue = { x: q.x, y: q.y, collapsed: this.queueUI?.isCollapsed ?? false };
        try { localStorage.setItem(DebugOverlayUI.PERSIST_KEY, JSON.stringify(state)); } catch {}
    }

    _saveOverlayState() {
        this._saveState({ overlays: { ...this.overlayState } });
    }

    _saveDebugEnabledState(enabled = document.body.classList.contains('debug')) {
        this._saveState({ debugEnabled: !!enabled });
    }

    setDirectWorldInteractionEnabled(enabled) {
        this.directWorldInteractionEnabled = !!enabled;
        this._saveState({
            interactionModes: {
                directWorldInteraction: this.directWorldInteractionEnabled
            }
        });
        this.parent?.ui?.debugPanel?.updateButton?.('directWorldInteraction');
    }

    isDirectWorldInteractionEnabled() {
        return this.directWorldInteractionEnabled;
    }

    getEnabledOverlayDebugLabels() {
        const labels = [];
        if (this.overlayState.colliders) labels.push('Colliders');
        if (this.overlayState.interaction) labels.push('Interaction');
        if (this.overlayState.hit) labels.push('Hit');
        if (this.overlayState.select) labels.push('Select');
        if (this.overlayState.pickup) labels.push('Pickup');
        if (this.overlayState.anchors) labels.push('Anchors');
        return labels;
    }

    _saveGridOverlays() {
        const flags = this.parent?.gameMap?.gridSystem?.overlayFlags;
        if (!flags) return;
        const state = this._loadState();
        state.gridOverlays = { ...flags };
        try { localStorage.setItem(DebugOverlayUI.PERSIST_KEY, JSON.stringify(state)); } catch {}
    }

    _applyGridOverlays(gridSystem) {
        const state = this._loadState();
        if (!state.gridOverlays) return;
        for (const [key, value] of Object.entries(state.gridOverlays)) {
            gridSystem.setOverlayFlag(key, value);
        }
    }

    _applyPersistedState() {
        const state = this._loadState();

        // Debug sections
        if (state.sections) {
            for (const [key, saved] of Object.entries(state.sections)) {
                if (this.debugSectionState[key]) {
                    this.debugSectionState[key].x    = saved.x    ?? null;
                    this.debugSectionState[key].y    = saved.y    ?? null;
                    this.debugSectionState[key].open = saved.open ?? true;
                    this.debugSectionState[key].groups =
                        saved.groups && typeof saved.groups === 'object'
                            ? { ...saved.groups }
                            : {};
                    this.debugSectionState[key]._hasSavedPosition =
                        Number.isFinite(saved.x) && Number.isFinite(saved.y);
                    this.debugSectionState[key]._hasSavedOpen =
                        typeof saved.open === 'boolean';
                    this.debugSectionState[key]._responsiveStateResolved =
                        this.debugSectionState[key]._hasSavedOpen;
                }
            }
        }

        // Queue position + collapse
        if (state.queue) {
            const q = this.debugSectionState.queue;
            q.x = state.queue.x ?? null;
            q.y = state.queue.y ?? null;
            q._hasSavedPosition = Number.isFinite(state.queue.x) && Number.isFinite(state.queue.y);
            q._hasSavedCollapsed = typeof state.queue.collapsed === 'boolean';
            q._responsiveStateResolved = q._hasSavedCollapsed;
            if (state.queue.collapsed != null && this.queueUI) {
                this.queueUI.setCollapsed(state.queue.collapsed);
            }
        }

        // Overlay flags
        if (state.overlays) {
            Object.assign(this.overlayState, state.overlays);
        }

        if (state.interactionModes) {
            this.directWorldInteractionEnabled = !!state.interactionModes.directWorldInteraction;
        }

        // Restore visual debug body class
        if (typeof state.debugEnabled === 'boolean') {
            document.body.classList.toggle('debug', state.debugEnabled);
        }

        this._mountFloatingPanels();

        // Apply queue panel position
        this._applyQueuePosition();
    }

    _applyQueuePosition() {
        const queueEl = this.queueUI?.queue;
        if (!queueEl) return;
        const q = this.debugSectionState.queue;
        this._mountFloatingPanels();
        queueEl.style.right = 'auto';
        queueEl.style.bottom = 'auto';
        queueEl.style.transform = 'none';
        queueEl.style.position = 'absolute';
        this._applyFloatingPosition(queueEl, q, () => this._getDefaultQueuePosition(), {
            handle: this.queueUI?.panelSummary
        });
    }

    _getDefaultQueuePosition() {
        const margin = DebugOverlayUI.FLOATING_MARGIN;
        return { x: margin, y: Math.max(margin, window.innerHeight - 300) };
    }

    _getStoredFloatingPosition(state, getDefaultPosition) {
        if (state && Number.isFinite(state.x) && Number.isFinite(state.y)) {
            return { x: state.x, y: state.y };
        }

        const fallback = getDefaultPosition();
        if (state) {
            state.x = Math.round(fallback.x);
            state.y = Math.round(fallback.y);
        }

        return fallback;
    }

    _getFloatingConstraintOptions(handle = null) {
        const handleHeight = handle ? Math.ceil(handle.getBoundingClientRect().height || 0) : 0;
        return {
            margin: DebugOverlayUI.FLOATING_MARGIN,
            minVisibleWidth: DebugOverlayUI.MIN_VISIBLE_WIDTH,
            minVisibleHeight: Math.max(DebugOverlayUI.MIN_VISIBLE_HEIGHT, handleHeight || 0)
        };
    }

    _getFloatingBounds(element, options = {}) {
        const margin = options.margin ?? DebugOverlayUI.FLOATING_MARGIN;
        const rect = element.getBoundingClientRect();
        const width = Math.max(0, rect.width || element.offsetWidth || 0);
        const height = Math.max(0, rect.height || element.offsetHeight || 0);
        const maxVisibleWidth = Math.max(24, window.innerWidth - (margin * 2));
        const maxVisibleHeight = Math.max(24, window.innerHeight - (margin * 2));
        const minVisibleWidth = Math.min(options.minVisibleWidth ?? DebugOverlayUI.MIN_VISIBLE_WIDTH, width || maxVisibleWidth, maxVisibleWidth);
        const minVisibleHeight = Math.min(options.minVisibleHeight ?? DebugOverlayUI.MIN_VISIBLE_HEIGHT, height || maxVisibleHeight, maxVisibleHeight);
        const minLeft = Math.round(margin + minVisibleWidth - width);
        const maxLeft = Math.round(window.innerWidth - margin - minVisibleWidth);
        const minTop = margin;
        const maxTop = Math.round(window.innerHeight - margin - minVisibleHeight);

        return {
            minLeft: Math.min(minLeft, maxLeft),
            maxLeft: Math.max(minLeft, maxLeft),
            minTop: Math.min(minTop, maxTop),
            maxTop: Math.max(minTop, maxTop)
        };
    }

    _clampFloatingPosition(element, position, options = {}) {
        const bounds = this._getFloatingBounds(element, options);
        return {
            x: Math.min(Math.max(position.x, bounds.minLeft), bounds.maxLeft),
            y: Math.min(Math.max(position.y, bounds.minTop), bounds.maxTop)
        };
    }

    _applyFloatingPosition(element, state, getDefaultPosition, options = {}) {
        if (!element) return null;

        const rawPosition = this._getStoredFloatingPosition(state, getDefaultPosition);
        const safePosition = this._clampFloatingPosition(
            element,
            rawPosition,
            this._getFloatingConstraintOptions(options.handle)
        );

        element.style.left = `${Math.round(safePosition.x)}px`;
        element.style.top = `${Math.round(safePosition.y)}px`;

        return safePosition;
    }

    _applySectionPosition(sectionKey) {
        const refs = this.debugDomRefs.get(sectionKey);
        const state = this.debugSectionState[sectionKey];
        if (!refs?.sectionEl || !state) return;

        const handle = refs.sectionEl.querySelector(':scope > summary');
        this._applyFloatingPosition(refs.sectionEl, state, () => this.getDefaultSectionPosition(sectionKey), {
            handle
        });
    }

    _shouldStartCollapsed(element, handle = null) {
        if (!element) return false;

        const margin = DebugOverlayUI.FLOATING_MARGIN * 2;
        const viewportWidth = Math.max(200, window.innerWidth - margin);
        const viewportHeight = Math.max(160, window.innerHeight - margin);
        const handleHeight = Math.ceil(handle?.getBoundingClientRect?.().height || 0);
        const rect = element.getBoundingClientRect();
        const fullWidth = Math.max(rect.width || 0, element.scrollWidth || 0);
        const fullHeight = Math.max(rect.height || 0, element.scrollHeight || 0);

        return fullWidth > viewportWidth || fullHeight > Math.max(handleHeight + 48, viewportHeight);
    }

    _maybeApplyResponsiveSectionState(sectionKey) {
        const refs = this.debugDomRefs.get(sectionKey);
        const state = this.debugSectionState[sectionKey];
        if (!refs?.sectionEl || !state || state._responsiveStateResolved) return;

        const handle = refs.sectionEl.querySelector(':scope > summary');
        const shouldCollapse = this._shouldStartCollapsed(refs.sectionEl, handle);
        refs.sectionEl.open = !shouldCollapse;
        state.open = refs.sectionEl.open;
        state._responsiveStateResolved = true;
    }

    _maybeApplyResponsiveQueueState() {
        const queueEl = this.queueUI?.queue;
        const queueState = this.debugSectionState.queue;
        if (!queueEl || !queueState || queueState._responsiveStateResolved) return;

        const shouldCollapse = this._shouldStartCollapsed(queueEl, this.queueUI?.panelSummary);
        this.queueUI?.setCollapsed?.(shouldCollapse);
        queueState._responsiveStateResolved = true;
        this._applyQueuePosition();
    }

    _refreshFloatingPositions() {
        this.debugDomRefs.forEach((refs, sectionKey) => {
            if (refs?.sectionEl) {
                this._applySectionPosition(sectionKey);
            }
        });

        this._applyQueuePosition();
    }

    onWindowResize() {
        this._refreshFloatingPositions();
    }

    // ─── debug section DOM ───────────────────────────────────────────────────

    getDebugSections(debugGroups) {
        return [
            {
                key: 'system',
                title: 'Debug – System',
                groups: debugGroups.filter(g => ['System', 'Input', 'Time', 'Map', 'Camera', 'Sound'].includes(g.name))
            },
            {
                key: 'myte',
                title: 'Debug – Myte',
                groups: [
                    { name: 'Overview', messages: this.getMyteSummaryMessages() },
                    ...debugGroups.filter(g => ['Myte', 'Myte Stats', 'Myte AI'].includes(g.name))
                ]
            }
        ];
    }

    getMyteSummaryMessages() {
        const mytes  = this.parent.mytes || [];
        const active = mytes.filter(m => m?.isActive);
        const inactive = mytes.filter(m => m && !m.isActive);
        const messages = [
            { label: 'Total',    value: mytes.length },
            { label: 'Active',   value: active.length },
            { label: 'Inactive', value: inactive.length }
        ];
        if (active.length > 0) {
            messages.push({ label: 'Selected', value: this.parent.activeMyte?.name || '—' });
        }
        return messages;
    }

    groupCssClass(groupName) {
        return groupName.toLowerCase().replace(/\s+/g, '-');
    }

    reconcileSection(sectionKey, title, groupsData) {
        if (!this.debug) return;

        let refs = this.debugDomRefs.get(sectionKey);
        if (!refs) {
            const sectionEl = document.createElement('details');
            sectionEl.className = `debug-section ${sectionKey}`;
            sectionEl.dataset.sectionKey = sectionKey;

            const state = this.debugSectionState[sectionKey];
            sectionEl.open = state?.open ?? true;

            const summary = document.createElement('summary');
            summary.textContent = title;
            sectionEl.appendChild(summary);

            const body = document.createElement('div');
            body.className = 'debug-section-body';
            sectionEl.appendChild(body);

            this.debug.appendChild(sectionEl);

            refs = { sectionEl, bodyEl: body, groupMap: new Map() };
            this.debugDomRefs.set(sectionKey, refs);
        }

        const activeGroups = new Set();

        for (const { name, messages } of groupsData) {
            const hasData = messages.length > 0;
            let groupRefs = refs.groupMap.get(name);

            if (!groupRefs) {
                const groupEl = document.createElement('details');
                groupEl.className = `debug-group ${this.groupCssClass(name)}`;
                groupEl.open = refs.sectionEl
                    ? (this.debugSectionState[sectionKey]?.groups?.[name] ?? true)
                    : true;

                const summary = document.createElement('summary');
                summary.className = 'debug-group-summary';
                summary.textContent = name;
                groupEl.appendChild(summary);

                const table = document.createElement('table');
                table.className = 'debug-table';
                groupEl.appendChild(table);

                refs.bodyEl.appendChild(groupEl);
                groupEl.addEventListener('toggle', () => {
                    const sectionState = this.debugSectionState[sectionKey];
                    if (!sectionState) return;
                    sectionState.groups ??= {};
                    sectionState.groups[name] = groupEl.open;
                    this._saveSectionState(sectionKey);
                });
                groupRefs = { groupEl, tableEl: table, rowMap: new Map() };
                refs.groupMap.set(name, groupRefs);
            }

            groupRefs.groupEl.style.display = hasData ? '' : 'none';
            if (!hasData) continue;

            activeGroups.add(name);
            const activeLabels = new Set();

            for (const item of messages) {
                const { label, value } = item;
                const labelClean = item.labelClean ?? label;

                activeLabels.add(label);
                let valueCell = groupRefs.rowMap.get(label);

                if (!valueCell) {
                    const tr = document.createElement('tr');
                    const labelCell = document.createElement('td');
                    labelCell.className = 'debug-label';
                    labelCell.innerHTML = label;
                    labelCell.title = labelClean;
                    tr.appendChild(labelCell);

                    valueCell = document.createElement('td');
                    valueCell.className = 'debug-value';
                    tr.appendChild(valueCell);

                    groupRefs.tableEl.appendChild(tr);
                    groupRefs.rowMap.set(label, valueCell);
                }

                const str = String(value ?? 'N/A');
                if (valueCell.textContent !== str) valueCell.textContent = str;
            }

            for (const [label, valueCell] of groupRefs.rowMap) {
                if (!activeLabels.has(label)) {
                    valueCell.closest('tr')?.remove();
                    groupRefs.rowMap.delete(label);
                }
            }
        }

        this._maybeApplyResponsiveSectionState(sectionKey);
        this._applySectionPosition(sectionKey);
    }

    getDefaultSectionPosition(key) {
        const margin    = DebugOverlayUI.FLOATING_MARGIN;
        const panelWidth = 350;
        if (key === 'myte') {
            return { x: Math.max(margin, window.innerWidth - panelWidth - margin), y: 60 };
        }
        if (key === 'overlays') {
            return { x: margin, y: 320 };
        }
        return { x: margin, y: 60 };
    }

    // ─── drag: debug sections ────────────────────────────────────────────────

    ensureDebugOverlaySetup() {
        if (!this.debug || this.debugOverlaySetup) return;

        this._mountFloatingPanels();
        this.debug.addEventListener('pointerdown', this.handleDebugPointerDown);
        this.debug.addEventListener('click', this.handleDebugSummaryClick, true);
        this.debugOverlaySetup = true;

        // Wire up queue panel dragging once
        const queueEl = this.queueUI?.queue;
        const summary = this.queueUI?.panelSummary;
        if (queueEl && summary) {
            summary.addEventListener('click', this.handleDebugSummaryClick, true);
            summary.addEventListener('pointerdown', this.handleQueuePointerDown);
        }
    }

    onDebugSummaryClick(event) {
        const summary = event.target.closest('.debug-section > summary, .queue-panel-shell > summary');
        const isDebugSummary = summary && this.debug?.contains(summary);
        const isQueueSummary = summary === this.queueUI?.panelSummary;
        if (!summary || (!isDebugSummary && !isQueueSummary)) return;
        event.preventDefault();
    }

    onDebugPointerDown(event) {
        if (event.button !== 0) return;

        const summary = event.target.closest('.debug-section > summary');
        if (!summary || !this.debug?.contains(summary)) return;

        const section    = summary.closest('.debug-section[data-section-key]');
        if (!section) return;

        const sectionKey = section.dataset.sectionKey;
        const rect = section.getBoundingClientRect();

        this.dragState = {
            type: 'section',
            sectionKey,
            pointerId:   event.pointerId,
            startX:      event.clientX,
            startY:      event.clientY,
            originLeft:  rect.left,
            originTop:   rect.top,
            moved: false
        };

        window.addEventListener('pointermove', this.handleDebugPointerMove);
        window.addEventListener('pointerup',   this.handleDebugPointerUp);
        window.addEventListener('pointercancel', this.handleDebugPointerUp);
    }

    // ─── drag: queue panel ───────────────────────────────────────────────────

    onQueuePointerDown(event) {
        if (event.button !== 0) return;

        const queueEl = this.queueUI?.queue;
        if (!queueEl) return;

        const rect = queueEl.getBoundingClientRect();

        this.dragState = {
            type: 'queue',
            pointerId:  event.pointerId,
            startX:     event.clientX,
            startY:     event.clientY,
            originLeft: rect.left,
            originTop:  rect.top,
            moved: false
        };

        window.addEventListener('pointermove', this.handleDebugPointerMove);
        window.addEventListener('pointerup',   this.handleDebugPointerUp);
        window.addEventListener('pointercancel', this.handleDebugPointerUp);

        event.preventDefault();
    }

    // ─── drag: shared move / up ──────────────────────────────────────────────

    onDebugPointerMove(event) {
        if (!this.dragState || event.pointerId !== this.dragState.pointerId) return;

        const deltaX = event.clientX - this.dragState.startX;
        const deltaY = event.clientY - this.dragState.startY;

        if (!this.dragState.moved && Math.abs(deltaX) < 4 && Math.abs(deltaY) < 4) return;

        this.dragState.moved = true;
        event.preventDefault();

        if (this.dragState.type === 'section') {
            const section = this.debug?.querySelector(
                `.debug-section[data-section-key="${this.dragState.sectionKey}"]`
            );
            if (!section) return;

            section.classList.add('dragging');

            const handle = section.querySelector(':scope > summary');
            const nextPosition = this._clampFloatingPosition(
                section,
                {
                    x: this.dragState.originLeft + deltaX,
                    y: this.dragState.originTop + deltaY
                },
                this._getFloatingConstraintOptions(handle)
            );

            section.style.left = `${Math.round(nextPosition.x)}px`;
            section.style.top  = `${Math.round(nextPosition.y)}px`;

            const state = this.debugSectionState[this.dragState.sectionKey];
            if (state) {
                state.x = Math.round(nextPosition.x);
                state.y = Math.round(nextPosition.y);
            }

        } else if (this.dragState.type === 'queue') {
            const queueEl = this.queueUI?.queue;
            const queueShell = this.queueUI?.panelShell;
            if (!queueEl || !queueShell) return;

            queueShell.classList.add('dragging');

            const nextPosition = this._clampFloatingPosition(
                queueEl,
                {
                    x: this.dragState.originLeft + deltaX,
                    y: this.dragState.originTop + deltaY
                },
                this._getFloatingConstraintOptions(this.queueUI?.panelSummary)
            );

            queueEl.style.left = `${Math.round(nextPosition.x)}px`;
            queueEl.style.top  = `${Math.round(nextPosition.y)}px`;

            this.debugSectionState.queue.x = Math.round(nextPosition.x);
            this.debugSectionState.queue.y = Math.round(nextPosition.y);
        }
    }

    onDebugPointerUp(event) {
        if (!this.dragState || event.pointerId !== this.dragState.pointerId) return;

        const moved = this.dragState.moved;

        if (this.dragState.type === 'section') {
            const section = this.debug?.querySelector(
                `.debug-section[data-section-key="${this.dragState.sectionKey}"]`
            );
            if (moved) {
                section?.classList.remove('dragging');
                this._saveSectionState(this.dragState.sectionKey);
            } else if (section) {
                section.open = !section.open;
                const state = this.debugSectionState[this.dragState.sectionKey];
                if (state) state.open = section.open;
                this._saveSectionState(this.dragState.sectionKey);
            }
        } else if (this.dragState.type === 'queue') {
            const queueShell = this.queueUI?.panelShell;
            queueShell?.classList.remove('dragging');
            if (moved) {
                this._saveQueueState();
            } else {
                this.queueUI?.setCollapsed(!this.queueUI?.isCollapsed);
                this._saveQueueState();
            }
        }

        this.dragState = null;
        window.removeEventListener('pointermove', this.handleDebugPointerMove);
        window.removeEventListener('pointerup',   this.handleDebugPointerUp);
        window.removeEventListener('pointercancel', this.handleDebugPointerUp);
    }

    // ─── debug data ──────────────────────────────────────────────────────────

    getSystemMessages() {
        return [
            { label: 'FPS',              value: this.parent.core.currentFPS.toFixed(2) },
            { label: 'Memory Usage',     value: this.getMemoryUsage() },
            { label: 'Active Entities',  value: this.getActiveEntitiesCount() }
        ];
    }

    getInputMessages() {
        const lastInputTime =
            this.parent.inputHandler?.inputSystem?.state?.lastActivityTime ??
            this.parent.inputHandler?.lastActiveTime ??
            null;

        const localMouse = this.parent.inputHandler.getMouseWorldPosition();
        const localTile  = this.pixelToTile(localMouse.x, localMouse.y);
        const mouseTile  = this.pixelToTile(this.parent.mousePosX, this.parent.mousePosY);

        return [
            { label: 'User Active',     value: this.parent.userIsActive },
            { label: 'Direct Interact', value: this.directWorldInteractionEnabled ? 'On' : 'Off' },
            { label: 'Local Mouse',     value: `${localMouse.x.toFixed(2)}px, ${localMouse.y.toFixed(2)}px` },
            { label: 'Local Mouse Tile', value: localTile ? `[${localTile.x}, ${localTile.y}]` : 'N/A' },
            { label: 'Mouse',           value: `${this.parent.mousePosX.toFixed(2)}px, ${this.parent.mousePosY.toFixed(2)}px` },
            { label: 'Mouse Tile',      value: mouseTile ? `[${mouseTile.x}, ${mouseTile.y}]` : 'N/A' },
            {
                label: 'Last Input Time',
                value: Number.isFinite(lastInputTime)
                    ? new Date(lastInputTime).toLocaleTimeString()
                    : 'N/A'
            }
        ];
    }

    getTimeMessages() {
        const timeData = this.parent.timeManager.getTimeData();
        return [
            { label: 'Time',                    value: timeData.formattedTime },
            { label: 'Date',                    value: timeData.formattedDate },
            { label: 'Time of Day',             value: timeData.timeOfDay },
            { label: 'Light Level',             value: timeData.lightLevel.toFixed(2) },
            { label: 'Moon Phase',              value: timeData.moonPhase },
            { label: 'Moon Illumination',       value: timeData.moonIllumination.toFixed(2) },
            { label: 'Moon Growth Multiplier',  value: timeData.moonGrowthMultiplier.toFixed(2) }
        ];
    }

    getMapMessages() {
        const messages = [];

        if (this.parent?.gameMap) {
            const gm = this.parent.gameMap;
            messages.push({ label: 'Map ID',   value: gm.id });
            messages.push({ label: 'Map Name', value: gm.displayName || 'Unknown' });

            const cellSize = gm.gridSystem?.config?.cellSize;
            if (cellSize) messages.push({ label: 'Tile Size', value: `${cellSize}px` });

            if (gm.dimensions) {
                const { width, height } = gm.dimensions;
                messages.push({ label: 'Size', value: `${width} × ${height}px` });
                if (cellSize) {
                    messages.push({ label: 'Size (tiles)', value: `${Math.floor(width / cellSize)} × ${Math.floor(height / cellSize)}` });
                }
            }

            messages.push({ label: 'Objects', value: gm.objects?.length || 0 });
            messages.push({ label: 'Visual Debug', value: document.body.classList.contains('debug') ? 'On' : 'Off' });

            const enabledOverlays = this.getEnabledOverlayDebugLabels();
            messages.push({
                label: 'Active Overlays',
                value: enabledOverlays.length > 0 ? enabledOverlays.join(', ') : 'None'
            });

            const cullingStats = gm.gridSystem?.getCullingDebugStats?.();
            if (cullingStats) {
                messages.push({ label: 'Visible Cells',  value: cullingStats.visibleCells });
                messages.push({ label: 'Active Objects', value: cullingStats.activeObjects });
                messages.push({ label: 'Total Cells',    value: cullingStats.totalCells });
                messages.push({ label: 'Culling Ratio',  value: `${cullingStats.cullingRatio}%` });
            }

            if (gm.particleSystem) {
                const particleStats = gm.particleSystem.getDebugStats?.() || null;
                if (particleStats) {
                    messages.push({ label: 'Particle Effects',  value: particleStats.effectsEnabled ? 'On' : 'Off' });
                    messages.push({ label: 'Particles',         value: `${particleStats.activeParticles} active / ${particleStats.pooledParticles} pooled` });
                    messages.push({ label: 'Particle Emitters', value: `${particleStats.activeEmitters}` });
                    messages.push({ label: 'Particle Bindings', value: `${particleStats.objectBindings || 0}` });
                    messages.push({ label: 'Particle Culling',  value: `${particleStats.culledThisFrame} culled` });
                } else {
                    messages.push({ label: 'Particles',         value: `${gm.particleSystem.particles?.length || 0}` });
                    messages.push({ label: 'Particle Emitters', value: `${gm.particleSystem.emitters?.length || 0}` });
                }
            }
        }

        if (this.parent?.gameMap?.zoneManager?.zones?.size > 0) {
            messages.push(...this.getZoneDebugMessages());
        }

        return messages;
    }

    getZoneDebugMessages() {
        const messages = [];
        const zoneManager = this.parent?.gameMap?.zoneManager;
        if (!zoneManager?.zones) return messages;

        try {
            zoneManager.zones.forEach((zone, zoneId) => {
                if (!zone?.mytesInZone) return;
                try {
                    const names = Array.from(zone.mytesInZone)
                        .map(id => this.parent.mytes?.find(m => m && m.id === id))
                        .filter(Boolean)
                        .map(m => m.name)
                        .join(', ');
                    const type = zone.type || 'zone';
                    const displayName = zone.displayName || type;
                    messages.push({
                        label: `<span class="badge ${type}">${displayName}</span> ${zoneId}`,
                        labelClean: `${displayName} ${zoneId}`,
                        value: names || '—'
                    });
                } catch {
                    messages.push({ label: `Zone ${zoneId}`, value: 'Error' });
                }
            });
        } catch {}

        return messages;
    }

    getCameraMessages() {
        if (!this.parent.camera) return [];

        const cam  = this.parent.camera;
        const zoom = cam.zoomLevel;
        const vp   = this.parent.getContainerRect?.();
        const vpW  = vp?.width  ?? 0;
        const vpH  = vp?.height ?? 0;

        const worldLeft   = -cam.posX;
        const worldTop    = -cam.posY;
        const worldRight  = vpW / zoom - cam.posX;
        const worldBottom = vpH / zoom - cam.posY;

        const tl   = this.pixelToTile(worldLeft, worldTop);
        const br   = this.pixelToTile(worldRight, worldBottom);
        const visW = tl && br ? br.x - tl.x + 1 : null;
        const visH = tl && br ? br.y - tl.y + 1 : null;

        return [
            { label: 'Camera Position', value: `${cam.posX.toFixed(2)}px, ${cam.posY.toFixed(2)}px` },
            { label: 'Zoom Level',      value: zoom.toFixed(2) },
            { label: 'Follow Mode',     value: cam.followMode },
            { label: 'Viewport Size',   value: `${vpW.toFixed(0)}×${vpH.toFixed(0)}px` },
            { label: 'Visible World',   value: `${worldLeft.toFixed(0)},${worldTop.toFixed(0)} → ${worldRight.toFixed(0)},${worldBottom.toFixed(0)}px` },
            { label: 'Visible Tiles',   value: tl && br ? `(${tl.x},${tl.y}) → (${br.x},${br.y}) [${visW}×${visH}]` : 'N/A' }
        ];
    }

    getMyteMessages() {
        const activeMyte = this.parent.activeMyte;
        if (!activeMyte) return [];

        const posTile    = this.pixelToTile(activeMyte.posX, activeMyte.posY);
        const targetTile = this.pixelToTile(activeMyte.targetX, activeMyte.targetY);

        return [
            { label: 'State',           value: activeMyte.stateMachine.currentState },
            { label: 'State Duration',  value: `${(activeMyte.stateMachine.getStateDuration() / 1000).toFixed(1)}s` },
            { label: 'Goal',            value: activeMyte.getMoveType(activeMyte.goal) },
            { label: 'Previous Goal',   value: activeMyte.getMoveType(activeMyte.previousGoal) },
            { label: 'Follow Goal',     value: activeMyte.getMoveFollowType(activeMyte.followGoal) },
            { label: 'AI Goal',         value: activeMyte.getMoveAutonomyType(activeMyte.autonomyGoal) },
            { label: 'Active',          value: activeMyte.isActive },
            { label: 'Deployed',        value: activeMyte.isDeployed },
            { label: 'In Slot',         value: activeMyte.isInSlot },
            { label: 'Controlled',      value: activeMyte.isActiveMyte },
            { label: 'Position',        value: `${activeMyte.posX.toFixed(2)}px, ${activeMyte.posY.toFixed(2)}px` },
            { label: 'Position Tile',   value: posTile ? `[${posTile.x}, ${posTile.y}]` : 'N/A' },
            { label: 'Target',          value: `${activeMyte.targetX.toFixed(2)}px, ${activeMyte.targetY.toFixed(2)}px` },
            { label: 'Target Tile',     value: targetTile ? `[${targetTile.x}, ${targetTile.y}]` : 'N/A' },
            { label: 'Direction',       value: activeMyte.direction },
            { label: 'Distance to Target', value: `${activeMyte.distanceFromTarget}px` },
            { label: 'Distance from Mouse', value: `${activeMyte.distanceFromMouse}px` },
            { label: 'Falling',         value: activeMyte.isFalling },
            { label: 'Jumping',         value: activeMyte.isJumping },
            { label: 'Velocity',        value: activeMyte.physics.velocity.toFixed(3) },
            { label: 'Sort Y',          value: Number.isFinite(activeMyte.renderer?.getSortY?.()) ? `${activeMyte.renderer.getSortY().toFixed(2)}px` : 'N/A' },
            { label: 'Z-Index',         value: activeMyte.duplicate.style.zIndex },
            { label: 'Queue Items',     value: activeMyte.queue.count() }
        ];
    }

    getMyteStats() {
        const activeMyte = this.parent.activeMyte;
        if (!activeMyte) return [];

        const status = activeMyte.stats.getStatus();
        return [
            { label: 'Mood',        value: activeMyte.stats.getDerivedMood() },
            { label: 'Fun',         value: activeMyte.stats.fun.toFixed(1) },
            { label: 'Social',      value: activeMyte.stats.social.toFixed(1) },
            { label: 'Fullness',    value: activeMyte.stats.satiety.toFixed(1) },
            { label: 'Comfort',     value: activeMyte.stats.comfort.toFixed(1) },
            { label: 'Confidence',  value: activeMyte.stats.confidence.toFixed(1) },
            { label: 'Speed',       value: activeMyte.stats.getSpeed() },
            { label: 'Health',      value: status.health },
            { label: 'Energy',      value: status.energy.current.toFixed(1) },
            { label: 'Level',       value: status.level },
            { label: 'Experience',  value: status.experience },
            { label: 'Personality', value: status.personality.description }
        ];
    }

    prettifyAiToken(token) {
        return String(token || '')
            .replace(/[_-]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .replace(/\b\w/g, char => char.toUpperCase());
    }

    prettifyAiPath(path) {
        return String(path || '')
            .split(':')
            .filter(Boolean)
            .map(segment => this.prettifyAiToken(segment))
            .join(' / ');
    }

    formatAiCandidate(candidate, index) {
        const rawLabel = String(candidate?.label || 'candidate');
        const segments = rawLabel.split(':').filter(Boolean);
        const primary  = this.prettifyAiToken(segments.shift() || rawLabel);
        const detail   = segments.map(segment => this.prettifyAiToken(segment)).join(' / ');
        return {
            label: `#${index + 1} ${primary}`,
            value: detail ? `${detail} · ${Number(candidate?.score ?? 0).toFixed(2)}` : Number(candidate?.score ?? 0).toFixed(2)
        };
    }

    getMyteAiMessages() {
        const activeMyte = this.parent.activeMyte;
        const aiState    = activeMyte?.ai?.getDebugState?.();
        if (!activeMyte || !aiState) return [];

        const drives = aiState.context?.drives || {};
        const fmt    = v => (v == null ? 'N/A' : Number(v).toFixed(2));

        const candidateRows = (aiState.candidates || [])
            .slice(0, 5)
            .map((candidate, index) => this.formatAiCandidate(candidate, index));

        return [
            { label: 'Decision',    value: aiState.lastDecisionLabel ? this.prettifyAiPath(aiState.lastDecisionLabel) : 'N/A' },
            { label: 'Rest',        value: fmt(drives.restDrive) },
            { label: 'Eat',         value: fmt(drives.eatDrive) },
            { label: 'Play',        value: fmt(drives.playDrive) },
            { label: 'Social',      value: fmt(drives.socialDrive) },
            { label: 'Explore',     value: fmt(drives.exploreDrive) },
            { label: 'Comfort',     value: fmt(drives.comfortDrive) },
            { label: 'Safety',      value: fmt(drives.safetyDrive) },
            { label: 'Light need',  value: fmt(aiState.context?.lightNeed) },
            { label: 'Music need',  value: fmt(aiState.context?.musicNeed) },
            { label: 'Local light', value: fmt(aiState.context?.localLightLevel) },
            ...candidateRows
        ];
    }

    getSoundMessages() {
        const sm = this.parent.core?.soundManager;
        if (!sm) return [{ label: 'Audio', value: 'SoundManager unavailable' }];

        const messages = [];

        if (!sm.initialized) {
            messages.push({ label: 'Audio', value: 'Not initialized' });
            return messages;
        }

        // Global state
        messages.push({ label: 'Sound',   value: sm.soundEnabled   ? 'On' : 'Off' });
        messages.push({ label: 'Music',   value: sm.musicEnabled   ? 'On' : 'Off' });
        messages.push({ label: 'Ambient', value: sm.ambientEnabled ? 'On' : 'Off' });
        messages.push({ label: 'SFX',     value: sm.sfxEnabled     ? 'On' : 'Off' });
        messages.push({ label: 'UI',      value: sm.uiEnabled      ? 'On' : 'Off' });

        // Map context
        const ctx = sm._mapContext;
        if (ctx) {
            messages.push({ label: 'Location', value: ctx.location ?? '—' });
            if (ctx.musicOverride)   messages.push({ label: 'Music Override',   value: ctx.musicOverride });
            if (ctx.ambientOverride?.length) {
                messages.push({ label: 'Ambient Override', value: ctx.ambientOverride.join(', ') });
            }
        }

        // Active music track
        messages.push({ label: 'Music Track', value: sm.currentMusicSynth ?? '—' });

        // Active ambient sounds — check synths not loops; noise-based ambient sounds
        // (wind, indoor, water) are in synths only; only pattern-based (birds, crickets) use loops
        const ambientLoops = [];
        sm.synths.forEach((_sound, id) => {
            const preset = sm.synthPresets[id];
            if (preset?.type === 'ambient' && !(sm._proximitySounds?.has(id))) {
                ambientLoops.push(id);
            }
        });
        messages.push({
            label: 'Ambient Loops',
            value: ambientLoops.length ? ambientLoops.join(', ') : '—'
        });

        // Proximity sounds — shown with their current volume so distance-fade is visible
        const proxIds = sm._proximitySounds ? [...sm._proximitySounds] : [];
        if (proxIds.length) {
            proxIds.forEach(id => {
                const sound = sm.synths.get(id);
                const vol = sound?.currentVolume != null
                    ? ` (${(sound.currentVolume * 100).toFixed(0)}%)`
                    : '';
                messages.push({ label: `Proximity: ${id}`, value: `active${vol}` });
            });
        } else {
            messages.push({ label: 'Proximity', value: '—' });
        }

        // Active SFX/machine loops (non-ambient, non-music — e.g. fountains)
        const machineLoops = [];
        sm.loops.forEach((_loop, id) => {
            const preset = sm.synthPresets[id];
            if (preset && preset.type !== 'ambient' && preset.type !== 'music') {
                machineLoops.push(id);
            }
        });
        if (machineLoops.length) {
            messages.push({ label: 'Object Loops', value: machineLoops.join(', ') });
        }

        // Proximity diagnostics — directly inspect the grid near the myte so we can
        // confirm whether water cells are present even when the sound isn't triggering
        const gm = this.parent.gameMap;
        const myte = this.parent.activeMyte;
        if (gm && myte) {
            const gs = gm.gridSystem;
            if (gs?.grid) {
                const cs  = gs.config.cellSize;
                // Use collider ground-center, matching what proximity scan uses
                const ox  = myte.collider?.offsetX ?? 0;
                const oy  = myte.collider?.offsetY ?? 0;
                const cw  = myte.collider?.width  ?? myte.size?.width  ?? 0;
                const ch  = myte.collider?.height ?? myte.size?.height ?? 0;
                const cx  = Math.floor((myte.posX + ox + cw / 2) / cs);
                const cy  = Math.floor((myte.posY + oy + ch)     / cs);
                const RADIUS = 192;
                const gr  = Math.ceil(RADIUS / cs);
                const terrainCounts = {};
                for (let gx = Math.max(0, cx - gr); gx <= Math.min(gs.gridWidth - 1, cx + gr); gx++) {
                    for (let gy = Math.max(0, cy - gr); gy <= Math.min(gs.gridHeight - 1, cy + gr); gy++) {
                        const t = gs.grid[gx]?.[gy]?.terrainType;
                        if (t && t !== 'ground') terrainCounts[t] = (terrainCounts[t] || 0) + 1;
                    }
                }
                const nearby = Object.entries(terrainCounts).map(([t, n]) => `${t}×${n}`).join(', ');
                messages.push({ label: 'Nearby Terrain', value: nearby || 'ground only' });
                messages.push({ label: 'Myte Grid', value: `[${cx}, ${cy}]` });
            } else {
                messages.push({ label: 'Nearby Terrain', value: 'no grid' });
            }
        }

        return messages;
    }

    // ─── utility ─────────────────────────────────────────────────────────────

    pixelToTile(px, py) {
        const cellSize = this.parent.gameMap?.gridSystem?.config?.cellSize;
        if (!cellSize) return null;
        return { x: Math.floor(px / cellSize), y: Math.floor(py / cellSize) };
    }

    getActiveEntitiesCount() {
        return this.parent.mytes?.filter(myte => myte.isActive).length || 0;
    }

    getMemoryUsage() {
        if (window.performance?.memory) {
            return `${(window.performance.memory.usedJSHeapSize / (1024 * 1024)).toFixed(2)} MB`;
        }
        return 'N/A';
    }

    // ─── collider / region visualization ────────────────────────────────────

    _appendRegionBox(layer, bounds, ...cssClasses) {
        if (!bounds) return;
        const el = document.createElement('div');
        el.classList.add('debug-collider', ...cssClasses);
        el.style.position = 'absolute';
        el.style.left   = `${bounds.left}px`;
        el.style.top    = `${bounds.top}px`;
        el.style.width  = `${bounds.right !== undefined ? bounds.right - bounds.left : bounds.width}px`;
        el.style.height = `${bounds.bottom !== undefined ? bounds.bottom - bounds.top : bounds.height}px`;
        layer.appendChild(el);
    }

    _appendAnchorDot(layer, x, y, label) {
        const r = 4;
        const el = document.createElement('div');
        el.classList.add('debug-collider', 'debug-anchor');
        el.style.position = 'absolute';
        el.style.left  = `${x - r}px`;
        el.style.top   = `${y - r}px`;
        el.title = label ?? '';
        layer.appendChild(el);
    }

    drawDebugColliders() {
        if (!this.parent?.gameMap) return;
        if (!this.parent.gameMap.layers?.debug) return;

        const layer = this.parent.gameMap.layers.debug;
        layer.querySelectorAll('.debug-collider').forEach(c => c.remove());

        const anyEnabled = Object.values(this.overlayState).some(Boolean);
        if (!anyEnabled) return;

        const mytes   = this.parent.mytes ?? [];
        const objects = [...(this.parent.gameMap.gridSystem?.activeObjects ?? [])];

        mytes.forEach(myte => {
            if (!myte) return;
            // Skip mytes in their home slot — their coordinates are relative to the slot
            // element, not the map, so debug boxes would render at the wrong position.
            if (!myte.isActive) return;
            try {
                if (this.overlayState.colliders) {
                    this._appendRegionBox(layer, myte.parent.getEntityColliderBounds(myte), 'myte-collider');
                }
                if (this.overlayState.interaction) {
                    const rect = myte.getRegionRect?.('interaction');
                    if (!rect && !myte._debugRegionWarned) {
                        myte._debugRegionWarned = true;
                        Utility.warnDebug('[DebugUI] myte interaction region is null. species:', myte.species,
                            '| spatial.regions:', myte.definition?.spatial?.regions,
                            '| posX:', myte.posX, 'posY:', myte.posY);
                    }
                    this._appendRegionBox(layer, rect, 'debug-region-interaction');
                }
                if (this.overlayState.hit) {
                    this._appendRegionBox(layer, myte.getRegionRect?.('hit'), 'debug-region-hit');
                }
                if (this.overlayState.select) {
                    this._appendRegionBox(layer, myte.getRegionRect?.('select'), 'debug-region-select');
                }
                if (this.overlayState.pickup) {
                    this._appendRegionBox(layer, myte.getRegionRect?.('pickup'), 'debug-region-pickup');
                }
                if (this.overlayState.anchors) {
                    const anchors = myte.definition?.spatial?.anchors ?? {};
                    Object.keys(anchors).forEach((id) => {
                        const anchorDirection = myte.getResolvedAnchorDirection?.() ?? myte.direction;
                        const anchor = MyteDefinitionRegistry.getSpatialAnchor?.(myte.definition, id, anchorDirection) ?? anchors[id];
                        if (!anchor) return;
                        this._appendAnchorDot(layer, myte.posX + (anchor.x ?? 0), myte.posY + (anchor.y ?? 0), id);
                    });
                }
            } catch (e) {
                console.error('[DebugUI] myte collider draw error:', e);
            }
        });

        try {
            objects.forEach(obj => {
                if (!obj || obj instanceof Myte) return;
                try {
                    if (this.overlayState.colliders) {
                        const bounds = this.parent.getEntityColliderBounds(obj);
                        const css = ['object-collider', ...(obj.config?.physics?.walkable ? ['walkable-object'] : [])];
                        this._appendRegionBox(layer, bounds, ...css);

                        const slotConfig = obj.getActionConfig?.('use_surface_slot');
                        if (slotConfig) {
                            (obj.getActionSlotDefinitions?.('use_surface_slot') ?? []).forEach(slot => {
                                if (!slot?.restPosition) return;
                                const cb = this.parent.getEntityColliderBounds(obj);
                                const sx = cb.left + (cb.right - cb.left) * (slot.restPosition.xFactor ?? 0.5);
                                const sy = cb.top  + (cb.bottom - cb.top) * (slot.restPosition.yFactor ?? 0.5);
                                const dot = document.createElement('div');
                                dot.classList.add('debug-collider', 'slot-marker');
                                dot.style.position = 'absolute';
                                dot.style.left   = `${sx - 4}px`;
                                dot.style.top    = `${sy - 4}px`;
                                dot.style.width  = '8px';
                                dot.style.height = '8px';
                                layer.appendChild(dot);
                            });
                        }
                    }
                    if (this.overlayState.interaction) {
                        this._appendRegionBox(layer, obj.getRegionRect?.('interaction'), 'debug-region-interaction');
                    }
                    if (this.overlayState.hit) {
                        this._appendRegionBox(layer, obj.getRegionRect?.('hit'), 'debug-region-hit');
                    }
                    if (this.overlayState.select) {
                        this._appendRegionBox(layer, obj.getRegionRect?.('select'), 'debug-region-select');
                    }
                    if (this.overlayState.pickup) {
                        this._appendRegionBox(layer, obj.getRegionRect?.('pickup'), 'debug-region-pickup');
                    }
                } catch {}
            });
        } catch {}
    }

    reconcileOverlayControls() {
        if (!this.debug) return;

        let refs = this.debugDomRefs.get('overlays');
        if (!refs) {
            const sectionEl = document.createElement('details');
            sectionEl.className = 'debug-section overlays';
            sectionEl.dataset.sectionKey = 'overlays';
            const state = this.debugSectionState.overlays;
            sectionEl.open = state?.open ?? true;

            const summary = document.createElement('summary');
            summary.textContent = 'Debug – Overlays';
            sectionEl.appendChild(summary);

            const body = document.createElement('div');
            body.className = 'debug-section-body debug-overlay-controls';

            const defs = [
                { key: 'colliders',   label: 'Colliders',    css: 'myte-collider'           },
                { key: 'interaction', label: 'Interaction',   css: 'debug-region-interaction' },
                { key: 'hit',         label: 'Hit',           css: 'debug-region-hit'         },
                { key: 'select',      label: 'Select',        css: 'debug-region-select'      },
                { key: 'pickup',      label: 'Pickup',        css: 'debug-region-pickup'      },
                { key: 'anchors',     label: 'Anchors',       css: 'debug-anchor'             }
            ];

            const controlMap = new Map();
            for (const { key, label, css } of defs) {
                const row = document.createElement('label');
                row.className = 'debug-overlay-row';

                const swatch = document.createElement('span');
                swatch.className = `debug-overlay-swatch debug-collider ${css}`;
                row.appendChild(swatch);

                const cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.checked = this.overlayState[key] ?? false;
                cb.addEventListener('change', () => {
                    this.overlayState[key] = cb.checked;
                    this._saveOverlayState();
                });
                row.appendChild(cb);
                row.append(` ${label}`);
                body.appendChild(row);
                controlMap.set(key, {
                    input: cb,
                    getValue: () => this.overlayState[key] ?? false
                });
            }

            const directInteractRow = document.createElement('label');
            directInteractRow.className = 'debug-overlay-row';

            const directInteractSwatch = document.createElement('span');
            directInteractSwatch.className = 'debug-overlay-swatch';
            directInteractRow.appendChild(directInteractSwatch);

            const directInteractInput = document.createElement('input');
            directInteractInput.type = 'checkbox';
            directInteractInput.checked = this.isDirectWorldInteractionEnabled();
            directInteractInput.addEventListener('change', () => {
                this.setDirectWorldInteractionEnabled(directInteractInput.checked);
            });
            directInteractRow.appendChild(directInteractInput);
            directInteractRow.append(' Direct Interact');
            body.appendChild(directInteractRow);
            controlMap.set('directWorldInteraction', {
                input: directInteractInput,
                getValue: () => this.isDirectWorldInteractionEnabled()
            });

            sectionEl.appendChild(body);
            this.debug.appendChild(sectionEl);
            refs = { sectionEl, controlMap };
            this.debugDomRefs.set('overlays', refs);
        }

        for (const { input, getValue } of refs.controlMap.values()) {
            const current = !!getValue();
            if (input.checked !== current) input.checked = current;
        }

        this._maybeApplyResponsiveSectionState('overlays');
        this._applySectionPosition('overlays');
    }

    // ─── main update ─────────────────────────────────────────────────────────

    updateDebug() {
        const debugGroups = [
            { name: 'System',    messages: this.getSystemMessages() },
            { name: 'Input',     messages: this.getInputMessages() },
            { name: 'Time',      messages: this.getTimeMessages() },
            { name: 'Map',       messages: this.getMapMessages() },
            { name: 'Camera',    messages: this.getCameraMessages() },
            { name: 'Sound',     messages: this.getSoundMessages() },
            { name: 'Myte',      messages: this.getMyteMessages() },
            { name: 'Myte Stats', messages: this.getMyteStats() },
            { name: 'Myte AI',   messages: this.getMyteAiMessages() }
        ];

        this.parent.activeMyte?.queue?.getCurrentAction?.()?.refreshDebugVisualization?.();

        for (const { key, title, groups } of this.getDebugSections(debugGroups)) {
            this.reconcileSection(key, title, groups);
        }

        this.ensureDebugOverlaySetup();
    }

    clearDebugVisuals() {
        if (this.debug) {
            this.debugDomRefs.forEach(refs => refs.sectionEl?.remove());
            this.debugDomRefs.clear();
        }

        const debugLayer = this.parent?.gameMap?.layers?.debug;
        if (debugLayer) {
            debugLayer.querySelectorAll('.debug-collider, .pathfinder-node').forEach(node => node.remove());
        }
    }

    update() {
        const debugEnabled = document.body.classList.contains('debug');
        const gridSystem   = this.parent?.gameMap?.gridSystem;
        const camera = this.parent?.camera;

        if (gridSystem !== this.lastBootstrappedGridSystem) {
            this.lastBootstrappedGridSystem = gridSystem;
            this.gridBootstrapAttempts = 0;
        }

        if (debugEnabled && gridSystem && !gridSystem.debugMode) {
            gridSystem.toggleDebug();
            this._applyGridOverlays(gridSystem);
        }

        if (!debugEnabled) {
            this.gridBootstrapAttempts = 0;
        } else if (
            gridSystem &&
            camera &&
            gridSystem.debugMode &&
            this.gridBootstrapAttempts < 3
        ) {
            const canvasVisibility = this.parent?.canvas
                ? window.getComputedStyle(this.parent.canvas).visibility
                : 'visible';

            if (canvasVisibility !== 'hidden') {
                gridSystem.forceDebugRefresh?.(camera);
                this.gridBootstrapAttempts += 1;
            }
        }

        if (debugEnabled && this.debug) {
            // Overlay boxes run every frame so they track moving entities without lag
            this.drawDebugColliders();

            const now = performance.now();
            if (now - this.lastDebugUpdate < this.debugUpdateInterval) return;
            this.lastDebugUpdate = now;
            try {
                this.updateDebug();
                this.wasDebugEnabled = true;
            } catch (error) {
                Utility.warnDebug('Debug UI update error:', error);
            }
        } else if (this.wasDebugEnabled) {
            this.clearDebugVisuals();
            this.wasDebugEnabled = false;
        }

        if (this.queueUI) {
            try {
                this.queueUI.update();
                this._maybeApplyResponsiveQueueState();
            } catch {}
        }
    }

    dispose() {
        this.clearDebugVisuals();

        if (this.debugOverlaySetup && this.debug) {
            this.debug.removeEventListener('pointerdown', this.handleDebugPointerDown);
            this.debug.removeEventListener('click', this.handleDebugSummaryClick, true);
        }

        const summary = this.queueUI?.panelSummary;
        if (summary) {
            summary.removeEventListener('click', this.handleDebugSummaryClick, true);
            summary.removeEventListener('pointerdown', this.handleQueuePointerDown);
        }

        window.removeEventListener('pointermove', this.handleDebugPointerMove);
        window.removeEventListener('pointerup',   this.handleDebugPointerUp);
        window.removeEventListener('pointercancel', this.handleDebugPointerUp);
        window.removeEventListener('resize', this.handleWindowResize);

        this.debugOverlaySetup = false;
        this.dragState = null;
        this.queueUI?.dispose?.();
        this.queueUI = null;
    }
}
;
/* -- js/UI/debug/AuditHarness.js -- */
// AuditHarness — console tooling that records current behavior as JSON so the
// refactor phases (docs/ARCHITECTURE_AUDIT_2026-07.md) have mechanical
// before/after acceptance instead of opinions.
//
// Usage from DevTools console:
//   __audit.dumpDepth()                     // T2 acceptance — depth/z for every object + myte
//   __audit.dumpAffordances()               // T7 acceptance — affordances for every map object
//   const rec = __audit.recordCandidates(); // T4 acceptance — AI candidate stream
//   ...let mytes roam...
//   rec.stop(); __audit.download('candidates', rec.entries);
//   __audit.download('depth-before', __audit.dumpDepth());
//
// Workflow: dump BEFORE a migration task starts, commit the JSON under
// docs/audit-baselines/, dump again after, diff. Zero diff = accepted.

const AuditHarness = {
	_activeAutoplay: null,

	_container() {
		const container = MyteCore.instance?.getFirstContainer?.();
		if (!container) throw new Error('[AuditHarness] Game not initialized');
		return container;
	},

	// ── T2: depth/z snapshot ─────────────────────────────────────────────────
	// One row per object and per active myte, sorted by id for stable diffs.
	dumpDepth() {
		const container = this._container();
		const rows = [];

		for (const obj of container.gameMap?.objects ?? []) {
			rows.push({
				id: String(obj.id),
				type: obj.type,
				variant: obj.variant ?? null,
				sortY: Math.round(obj.getSortY() * 100) / 100,
				depthOffset: Math.round(obj.resolveDepthOffset() * 100) / 100,
				depthPriority: obj.getDepthPriority?.() ?? 0,
				zIndex: obj.getRenderZIndex(),
				renderLayer: obj.getRenderLayerKey?.() ?? 'objects'
			});
		}

		for (const myte of container.mytes ?? []) {
			if (!myte.renderer) continue;
			rows.push({
				id: `myte_${myte.id}`,
				type: 'MYTE',
				variant: myte.species,
				sortY: Math.round(myte.renderer.getSortY() * 100) / 100,
				depthOffset: Math.round(myte.renderer.resolveDepthOffset() * 100) / 100,
				depthPriority: myte.renderer.getDepthPriority?.() ?? 0,
				zIndex: myte.renderer.getZIndex(myte.posY),
				renderLayer: 'myte'
			});
		}

		rows.sort((a, b) => a.id.localeCompare(b.id));
		return rows;
	},

	// ── T7: affordance snapshot ──────────────────────────────────────────────
	// Fixed synthetic context so output is deterministic regardless of live
	// stats. Actor defaults to null (no carrying/occupancy exclusions from a
	// live myte leaking into the recording).
	syntheticAffordanceContext() {
		return {
			energy: 0.5,
			fun: 0.5,
			curiosity: 0.8,
			getNoveltyScore: () => 0.6
		};
	},

	dumpAffordances(actor = null, context = this.syntheticAffordanceContext()) {
		const container = this._container();
		const rows = [];

		for (const obj of container.gameMap?.objects ?? []) {
			if (typeof obj.getAiAffordances !== 'function') continue;
			rows.push({
				id: String(obj.id),
				type: obj.type,
				variant: obj.variant ?? null,
				affordances: obj.getAiAffordances(context, actor)
					.map(a => `${a.actionId}:${a.purpose ?? ''}${a.chain ? ':chain' : ''}`)
					.sort()
			});
		}

		rows.sort((a, b) => a.id.localeCompare(b.id));
		return rows;
	},

	// ── T4: AI candidate stream recorder ─────────────────────────────────────
	// Wraps planNextAction on every myte (or one), capturing the context and
	// candidate snapshots MyteAI already maintains. stop() restores the
	// original methods.
	recordCandidates(target = null) {
		const container = this._container();
		const mytes = target ? [target] : (container.mytes ?? []);
		const entries = [];
		const restorers = [];

		for (const myte of mytes) {
			if (!myte.ai) continue;
			const original = myte.ai.planNextAction.bind(myte.ai);
			myte.ai.planNextAction = () => {
				original();
				entries.push({
					t: Math.round(SimClock.now()),
					myte: myte.id,
					decision: myte.ai.lastDecisionLabel,
					context: myte.ai.lastContextSnapshot,
					candidates: myte.ai.lastCandidateSnapshot
				});
			};
			restorers.push(() => { myte.ai.planNextAction = original; });
		}

		return {
			entries,
			stop() { restorers.forEach(fn => fn()); }
		};
	},

	// ── Invariant sweeper ────────────────────────────────────────────────────
	// Cross-checks the world registry, grid index, and relationships against
	// the population arrays. Returns [] when clean; run after despawn cycles,
	// map transitions, and at the end of any registry/relationship task.
	invariants() {
		const container = this._container();
		const issues = [];
		const registry = container.worldRegistry;
		const gameMap = container.gameMap;

		if (!registry) return ['worldRegistry missing on container'];

		// 1. Registry counts match population arrays.
		const stats = registry.stats();
		if (stats.myte !== (container.mytes?.length ?? 0)) {
			issues.push(`registry mytes=${stats.myte} vs container.mytes=${container.mytes?.length}`);
		}
		if (stats.object !== (gameMap?.objects?.length ?? 0)) {
			issues.push(`registry objects=${stats.object} vs gameMap.objects=${gameMap?.objects?.length}`);
		}
		if (stats.item !== (gameMap?.droppedItems?.length ?? 0)) {
			issues.push(`registry items=${stats.item} vs droppedItems=${gameMap?.droppedItems?.length}`);
		}

		// 2. Every registered entity resolves back to itself by worldId.
		for (const entity of registry.all()) {
			if (registry.byId(entity.worldId) !== entity) {
				issues.push(`byId round-trip failed for ${entity.worldId}`);
			}
		}

		// 3. Population members are registered.
		for (const myte of container.mytes ?? []) {
			if (!myte.worldId || registry.byId(myte.worldId) !== myte) {
				issues.push(`myte ${myte.id} not registered`);
			}
		}
		for (const obj of gameMap?.objects ?? []) {
			if (!obj.worldId || registry.byId(obj.worldId) !== obj) {
				issues.push(`object ${obj.id} (${obj.type}) not registered`);
			}
		}
		for (const item of gameMap?.droppedItems ?? []) {
			if (!item.worldId || registry.byId(item.worldId) !== item) {
				issues.push(`dropped item ${item.id} not registered`);
			}
		}

		// 4. Deployed mytes are grid-indexed in the CURRENT gridSystem
		//    (self-healing runs at 8 fps — a mismatch right after a map
		//    transition resolves within ~125 ms; re-run before trusting it).
		for (const myte of container.mytes ?? []) {
			if (myte.isActive && gameMap?.gridSystem && myte._gridRegistered !== gameMap.gridSystem) {
				issues.push(`deployed myte ${myte.id} not registered in current gridSystem (may resolve within 125ms)`);
			}
			if (!myte.isActive && myte._gridRegistered) {
				issues.push(`inactive myte ${myte.id} still grid-registered`);
			}
		}

		// 5. Mytes never poison walkability or collider lists.
		for (const myte of container.mytes ?? []) {
			if (!myte.isActive || !gameMap?.gridSystem) continue;
			const colliders = gameMap.gridSystem.getPotentialCollidersForArea(
				myte.posX, myte.posY, myte.size.width, myte.size.height
			);
			if (colliders.includes(myte)) {
				issues.push(`myte ${myte.id} appears as a collider`);
			}
		}

		// 6. Relationship endpoints are registered entities.
		if (container.relationships) {
			for (const pair of container.relationships.serialize()) {
				if (!registry.byId(pair.a)) issues.push(`relation ${pair.type}: dangling a=${pair.a}`);
				if (!registry.byId(pair.b)) issues.push(`relation ${pair.type}: dangling b=${pair.b}`);
				const entityA = registry.byId(pair.a);
				const entityB = registry.byId(pair.b);
				if (entityA && entityA.active === false) issues.push(`relation ${pair.type}: inactive a=${pair.a}`);
				if (entityB && entityB.active === false) issues.push(`relation ${pair.type}: inactive b=${pair.b}`);
			}

			for (const obj of gameMap?.objects ?? []) {
				const relatedCarrier = container.relationships.get('carriedBy', obj);
				if (obj.isPickedUp && !relatedCarrier) {
					issues.push(`picked-up object ${obj.id} missing carriedBy relation`);
				}
				if (!obj.isPickedUp && relatedCarrier) {
					issues.push(`object ${obj.id} has carriedBy relation while not picked up`);
				}
				if (obj.carrier && relatedCarrier !== obj.carrier) {
					issues.push(`object ${obj.id} carrier field mismatches carriedBy relation`);
				}
			}
		}

		// 7. Attachments, socket occupancy, and their semantic relations agree.
		if (container.attachments) {
			for (const record of container.attachments.serialize()) {
				const parent = registry.byId(record.parentId);
				const child = registry.byId(record.childId);
				if (!parent) issues.push(`attachment ${record.socketId}: dangling parent=${record.parentId}`);
				if (!child) issues.push(`attachment ${record.socketId}: dangling child=${record.childId}`);
				if (!parent || !child) continue;

				const attachment = container.attachments.getAttachment(child);
				if (attachment?.parent !== parent || attachment?.socketId !== record.socketId) {
					issues.push(`attachment ${record.childId}: lookup disagrees with serialized record`);
				}
				const socket = parent.sockets?.get?.(record.socketId);
				if (!socket) {
					issues.push(`attachment ${record.childId}: missing socket ${record.socketId}`);
					continue;
				}
				if (!parent.sockets.occupantsOf(record.socketId).includes(child)) {
					issues.push(`attachment ${record.childId}: absent from socket ${record.socketId} occupancy`);
				}
				const relationType = socket.kind === 'hold'
					? 'carrying'
					: socket.kind === 'mount' ? 'riding' : 'occupying';
				if (!container.relationships?.has?.(relationType, parent, child)) {
					issues.push(`attachment ${record.childId}: missing ${relationType} relation`);
				}
			}

			for (const parent of registry.all()) {
				for (const socket of parent.sockets?.list?.() ?? []) {
					for (const child of parent.sockets.occupantsOf(socket.id)) {
						if (!child.worldId || registry.byId(child.worldId) !== child) {
							issues.push(`socket ${parent.worldId}:${socket.id} contains unregistered occupant`);
							continue;
						}
						const attachment = container.attachments.getAttachment(child);
						if (attachment?.parent !== parent || attachment?.socketId !== socket.id) {
							const action = child.queue?.getCurrentAction?.();
							const isReservedApproach = action?._reserved === true &&
								action.target === parent &&
								action._selectedSlotId === socket.id &&
								(action.phase === 'approach' || action.phase === 'settle');
							if (!isReservedApproach) {
								issues.push(`socket ${parent.worldId}:${socket.id} occupant ${child.worldId} lacks matching attachment`);
							}
						}
					}
				}
			}
		}

		return issues;
	},

	// ── Shared: save any dump as a JSON file ─────────────────────────────────
	// Runs the game's normal autonomous AI while sampling invariants on
	// simulation time. Hidden tabs do not consume the requested duration.
	// Returns a controller immediately; await controller.promise for the report.
	autoplay({ durationMs = 5 * 60 * 1000, sampleIntervalMs = 5000 } = {}) {
		if (this._activeAutoplay) {
			throw new Error('[AuditHarness] An autoplay run is already active');
		}
		if (!Number.isFinite(durationMs) || durationMs <= 0) {
			throw new Error('[AuditHarness] durationMs must be a positive finite number');
		}
		if (!Number.isFinite(sampleIntervalMs) || sampleIntervalMs <= 0) {
			throw new Error('[AuditHarness] sampleIntervalMs must be a positive finite number');
		}

		const container = this._container();
		const samples = [];
		let elapsedMs = 0;
		let lastSimTime = SimClock.now();
		let nextSampleAt = 0;
		let frameHandle = null;
		let resolveReport;
		let controller;
		const promise = new Promise(resolve => { resolveReport = resolve; });

		const sample = () => {
			let issues;
			try {
				issues = this.invariants();
			} catch (error) {
				issues = [`invariant sweep threw: ${error?.message ?? String(error)}`];
			}
			samples.push({
				elapsedMs: Math.round(elapsedMs),
				simTime: Math.round(SimClock.now()),
				issues,
				registry: container.worldRegistry?.stats?.() ?? null
			});
		};

		const finish = reason => {
			if (this._activeAutoplay !== controller) return null;
			if (frameHandle !== null) cancelAnimationFrame(frameHandle);
			if (samples.at(-1)?.elapsedMs !== Math.round(elapsedMs)) sample();
			const issueSamples = samples.filter(entry => entry.issues.length > 0);
			const report = {
				reason,
				passed: reason === 'completed' && issueSamples.length === 0,
				durationMs: Math.round(elapsedMs),
				requestedDurationMs: durationMs,
				sampleIntervalMs,
				sampleCount: samples.length,
				issueSampleCount: issueSamples.length,
				uniqueIssues: [...new Set(issueSamples.flatMap(entry => entry.issues))],
				samples
			};
			this._activeAutoplay = null;
			resolveReport(report);
			return report;
		};

		const tick = () => {
			const now = SimClock.now();
			if (now >= lastSimTime) elapsedMs += now - lastSimTime;
			lastSimTime = now;

			if (elapsedMs >= nextSampleAt) {
				sample();
				nextSampleAt = elapsedMs + sampleIntervalMs;
			}
			if (elapsedMs >= durationMs) {
				finish('completed');
				return;
			}
			frameHandle = requestAnimationFrame(tick);
		};

		controller = {
			promise,
			stop: () => finish('stopped'),
			get samples() { return samples; }
		};
		this._activeAutoplay = controller;
		sample();
		nextSampleAt = sampleIntervalMs;
		frameHandle = requestAnimationFrame(tick);
		return controller;
	},

	download(name, data) {
		const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
		const url = URL.createObjectURL(blob);
		const a = document.createElement('a');
		a.href = url;
		a.download = `${name}-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}.json`;
		a.click();
		URL.revokeObjectURL(url);
	}
};

window.__audit = AuditHarness;
window.__invariants = () => AuditHarness.invariants();
;
/* -- js/UI/debug/SurfaceDebug.js -- */
// SurfaceDebug — console tooling for the two systems that answer "which room
// owns this piece of the world": wall paint surfaces and room floors.
//
// Both are made of slices smaller than a cell — a junction cell draws up to
// four wall surfaces, and a floor stops on the CENTRELINE of the wall beside
// it — so "what colour is cell 12,3" is not a question either system can be
// asked from the outside. This asks it from the inside.
//
// Usage from DevTools console:
//   __surfaces.cell(12, 3)          // wall: mask, faces, and every painted slice
//   __surfaces.floor(14, 0)         // floor: which room owns each quarter of a cell
//   __surfaces.stretch(12, 3, 4)    // what one paint stroke at that pixel would cover
//   __surfaces.audit()              // every quarter-cell two rooms both claim, or neither
//   __surfaces.overlay()            // draw all of the above ON the map
//   __surfaces.overlay(false)       // take it back off
//   __surfaces.pick()               // click a bad floor edge; copies its report
//   __surfaces.download()           // the whole lot as JSON, for a bug report
//
// Coordinates are CELLS everywhere (x, y), never pixels — that is how the wall
// data, the room tilemasks and the Tiled map all index the world.

const SurfaceDebug = {
	// Quarter of a cell: the finest slice either system produces, since a wall's
	// half-cell post and a floor's half-cell bleed both land on a 16px line.
	QUARTER: 4,

	_map() {
		const map = MyteCore.instance?.getFirstContainer?.()?.gameMap;
		if (!map) throw new Error('[SurfaceDebug] Game not initialized');
		return map;
	},

	_walls() {
		const builder = this._map().wallBuilder;
		if (!builder) throw new Error('[SurfaceDebug] This map has no walls');
		return builder;
	},

	get cellSize() {
		return this._map().gridSystem?.config?.cellSize || 32;
	},

	// ── Walls ────────────────────────────────────────────────────────────────

	/**
	 * One wall cell, as the renderer sees it: the neighbour mask, the room each
	 * of its four faces looks into, and the slices it actually draws.
	 *
	 * `slices` is the answer to "why is that quarter the wrong colour": each one
	 * names the pixels it covers, whether it is the head-on band of an east-west
	 * wall or the post of a north-south one, and which room's paint it is
	 * wearing.
	 */
	cell(x, y) {
		const builder = this._walls();
		const raw = builder.cells.get(`${x},${y}`);
		if (!raw) return { cell: `${x},${y}`, wall: false };

		const mask = builder.computeMask(raw);
		const faces = builder.assignFaces(raw);
		const piece = builder.findPieceForCell(x, y);
		return {
			cell: `${x},${y}`,
			wall: true,
			mask,
			connections: SurfaceDebug.maskName(mask),
			piece: piece?.id ?? null,
			construction: raw.constructionId,
			finish: raw.finishId,
			opening: raw.opening?.type ?? null,
			faces: Object.fromEntries(Object.entries(faces).map(([name, face]) => [
				name,
				`${face.roomId || '(outside)'} ${face.materialId}`
			])),
			slices: builder.getCellSurfaces(raw).map(surface => ({
				px: `${surface.from}-${surface.to}`,
				part: surface.axis === 'horizontal' ? 'band' : 'post',
				face: surface.face,
				room: surface.roomId || '(outside)',
				finish: surface.finishId
			}))
		};
	},

	/** Every cell of one rendered piece, in the order it draws them. */
	piece(id) {
		const piece = this._walls().findPieceById(id);
		if (!piece) return null;
		return {
			id: piece.id,
			cells: piece.cells.map(cell => this.cell(cell.x, cell.y))
		};
	},

	/**
	 * What one paint stroke would cover, clicking `offset` pixels into the cell.
	 *
	 * The offset matters and is not optional: clicking the left quarter of a
	 * junction and the right quarter of the same cell select two different
	 * walls, which is the whole point of the slices.
	 */
	stretch(x, y, offset = 0) {
		const builder = this._walls();
		const raw = builder.cells.get(`${x},${y}`);
		if (!raw) return { cell: `${x},${y}`, wall: false };

		const clicked = builder.getCellSurfaces(raw)
			.filter(surface => offset >= surface.from && offset < surface.to)
			.pop();
		if (!clicked) return { cell: `${x},${y}`, slice: null, covers: [] };

		return {
			cell: `${x},${y}`,
			slice: `${clicked.from}-${clicked.to} ${clicked.face}`,
			room: clicked.roomId || '(outside)',
			finish: clicked.finishId,
			covers: builder.getPaintStretchSurfaces(clicked)
				.map(surface => `${surface.cell.x},${surface.cell.y} [${surface.from}-${surface.to}] ${surface.finishId}`)
				.sort()
		};
	},

	/** Every wall cell that draws a slice of the given room's paint. */
	roomWalls(roomId) {
		const builder = this._walls();
		const rows = [];
		for (const cell of builder.cells.values()) {
			for (const surface of builder.getCellSurfaces(cell)) {
				if (surface.roomId !== roomId) continue;
				rows.push(`${cell.x},${cell.y} [${surface.from}-${surface.to}] ${surface.face} ${surface.finishId}`);
			}
		}
		return rows.sort();
	},

	// ── Floors ───────────────────────────────────────────────────────────────

	/**
	 * Which room's floor is painted on each quarter of a cell.
	 *
	 * A room's floor runs half a cell past its own edge so it ends under the
	 * middle of the wall beside it, which means the four quarters of one cell
	 * can honestly belong to four different rooms. Two rooms on one quarter is
	 * a bug — they are drawn on separate canvases, so which one you see is
	 * whichever happened to be appended last.
	 */
	floor(x, y) {
		const size = this.cellSize;
		const quarter = size / this.QUARTER;
		const rows = {};
		for (let row = 0; row < 2; row++) {
			for (let column = 0; column < 2; column++) {
				const name = `${row === 0 ? 'top' : 'bottom'}-${column === 0 ? 'left' : 'right'}`;
				rows[name] = this.floorOwnersAt(
					(x * size) + (column * size / 2) + quarter,
					(y * size) + (row * size / 2) + quarter
				);
			}
		}
		return {
			cell: `${x},${y}`,
			wall: this._map().wallBuilder?.cells?.has(`${x},${y}`) ?? false,
			room: this._map().regionManager?.innermostAt?.(
				(x + 0.5) * size, (y + 0.5) * size, 'room', size
			)?.id ?? null,
			quarters: Object.fromEntries(Object.entries(rows).map(([name, owners]) => [
				name,
				owners.length === 0 ? '(bare ground)' : owners.join(' + ')
			]))
		};
	},

	_floorPlanOwners() {
		const map = this._map();
		const ownership = map.floorBuilder?.computeOwnership?.() ?? new Map();
		const ownerByBlock = new Map();
		for (const [roomId, blocks] of ownership) {
			for (const [blockX, blockY] of blocks) ownerByBlock.set(`${blockX},${blockY}`, roomId);
		}
		return ownerByBlock;
	},

	/** The ownership plan before it is rasterized into separate room canvases. */
	floorPlan(x, y, ownerByBlock = this._floorPlanOwners()) {
		const perCell = FloorBuilder.BLOCKS_PER_CELL;
		const quarters = {};
		for (let row = 0; row < perCell; row++) {
			for (let column = 0; column < perCell; column++) {
				const name = `${row === 0 ? 'top' : 'bottom'}-${column === 0 ? 'left' : 'right'}`;
				const blockX = (x * perCell) + column;
				const blockY = (y * perCell) + row;
				quarters[name] = ownerByBlock.get(`${blockX},${blockY}`) ?? '(bare ground)';
			}
		}
		return quarters;
	},

	/** Everything needed to explain the four floor quarters of one cell. */
	inspectFloor(x, y) {
		const map = this._map();
		const size = this.cellSize;
		const wall = map.wallBuilder?.cells?.get(`${x},${y}`) ?? null;
		const rooms = map.regionManager?.all?.('room') ?? [];
		const planOwners = this._floorPlanOwners();
		const roomsAt = (column, row) => {
			const mapX = (x + (column === 0 ? 0.25 : 0.75)) * size;
			const mapY = (y + (row === 0 ? 0.25 : 0.75)) * size;
			return rooms.filter(room => room.contains(mapX, mapY)).map(room => room.id);
		};
		return {
			cell: `${x},${y}`,
			rendered: this.floor(x, y).quarters,
			planned: this.floorPlan(x, y, planOwners),
			containingRooms: {
				'top-left': roomsAt(0, 0),
				'top-right': roomsAt(1, 0),
				'bottom-left': roomsAt(0, 1),
				'bottom-right': roomsAt(1, 1)
			},
			wall: wall ? this.cell(x, y) : { wall: false },
			neighbours: Object.fromEntries(WallBuilder.DIRECTIONS.map(direction => {
				const nextX = x + direction.dx;
				const nextY = y + direction.dy;
				return [direction.name, {
					cell: `${nextX},${nextY}`,
					wall: map.wallBuilder?.cells?.has(`${nextX},${nextY}`) ?? false,
					planned: this.floorPlan(nextX, nextY, planOwners)
				}];
			}))
		};
	},

	/** Arm one click on the map and copy a focused floor ownership report. */
	pick() {
		const container = MyteCore.instance?.getFirstContainer?.();
		const input = container?.inputHandler;
		if (!input?.screenToWorldCoordinates) {
			throw new Error('[SurfaceDebug] Container input is not ready');
		}
		const handler = event => {
			const point = input.screenToWorldCoordinates(event.pageX, event.pageY);
			const x = Math.floor(point.x / this.cellSize);
			const y = Math.floor(point.y / this.cellSize);
			const report = this.inspectFloor(x, y);
			this.lastPick = report;
			console.log('[SurfaceDebug] floor pick', JSON.stringify(report, null, 2));
			navigator.clipboard?.writeText(JSON.stringify(report, null, 2)).catch(() => {});
			event.preventDefault();
			event.stopImmediatePropagation();
		};
		document.addEventListener('pointerdown', handler, { capture: true, once: true });
		return 'picker armed — click a bad floor quarter; its report will be logged and copied';
	},

	/** Every room whose floor canvas has a pixel at this point in map space. */
	floorOwnersAt(mapX, mapY) {
		const owners = [];
		for (const [roomId, surface] of this._map().floorBuilder?.surfaces ?? []) {
			const canvas = surface.canvas;
			const x = Math.floor(mapX - parseFloat(canvas.style.left));
			const y = Math.floor(mapY - parseFloat(canvas.style.top));
			if (x < 0 || y < 0 || x >= canvas.width || y >= canvas.height) continue;
			if (canvas.getContext('2d').getImageData(x, y, 1, 1).data[3] > 0) {
				owners.push(`${roomId}:${surface.finishId}`);
			}
		}
		return owners;
	},

	/**
	 * Every quarter-cell two rooms both claim, and every one a room should have
	 * painted and did not.
	 *
	 * Overlaps are the flat defect — two canvases fighting over the same pixels,
	 * so which one you see is whichever was appended last. Gaps are the other
	 * half of the same question and are listed apart from them, because a bare
	 * quarter inside a room that HAS a floor is a hole while a room with no
	 * finish at all is opted out on purpose and shows the map as authored;
	 * those rooms are named once in `noFloor` instead of a line per quarter.
	 *
	 * `wallGaps` is the third list and the one this tool used to be blind to. A
	 * wall cell is not inside any room, so it was skipped outright — which
	 * excluded the exact ground the edge bleed EXISTS to cover, and let a bare
	 * sliver beside a wall pass an audit that reported nothing wrong.
	 *
	 * What separates a hole from the outdoors is not proximity to a floor —
	 * every exterior wall has floor on its inner half — but whether you could
	 * walk to it from off the map without crossing one. So the bare quarters are
	 * flooded from the map edge, and only the ones that fill cannot reach are
	 * reported: those are enclosed by floor on every side, which is the
	 * definition of a hole in it.
	 */
	audit() {
		const map = this._map();
		const size = this.cellSize;
		const quarter = size / this.QUARTER;
		const width = (map.gridSystem?.gridWidth || 0) * 2;
		const height = (map.gridSystem?.gridHeight || 0) * 2;
		const surfaces = map.floorBuilder?.surfaces;
		const overlaps = [];
		const gaps = [];
		const wallGaps = [];
		const noFloor = new Set();
		const bare = new Map();

		for (let row = 0; row < height; row++) {
			for (let column = 0; column < width; column++) {
				const x = Math.floor(column / 2);
				const y = Math.floor(row / 2);
				const owners = this.floorOwnersAt(
					(column * size / 2) + quarter,
					(row * size / 2) + quarter
				);
				const where = `${x},${y} ${row % 2 === 0 ? 'top' : 'bottom'}-${column % 2 === 0 ? 'left' : 'right'}`;
				if (owners.length > 1) { overlaps.push(`${where}: ${owners.join(' + ')}`); continue; }
				if (owners.length > 0) continue;

				const inRoom = map.regionManager?.innermostAt?.(
					(x + 0.5) * size, (y + 0.5) * size, 'room', size
				);
				if (inRoom && !surfaces?.has(inRoom.id)) noFloor.add(inRoom.id);
				const wall = map.wallBuilder?.cells?.has(`${x},${y}`) ?? false;
				if (inRoom && surfaces?.has(inRoom.id) && !wall) gaps.push(`${where}: inside ${inRoom.id}`);
				else bare.set(`${column},${row}`, where);
			}
		}

		const outdoors = new Set();
		const queue = [];
		const reach = (column, row) => {
			const key = `${column},${row}`;
			if (column < 0 || row < 0 || column >= width || row >= height) return;
			if (!bare.has(key) || outdoors.has(key)) return;
			outdoors.add(key);
			queue.push([column, row]);
		};
		for (let column = 0; column < width; column++) { reach(column, 0); reach(column, height - 1); }
		for (let row = 0; row < height; row++) { reach(0, row); reach(width - 1, row); }
		for (let index = 0; index < queue.length; index++) {
			const [column, row] = queue[index];
			reach(column - 1, row); reach(column + 1, row);
			reach(column, row - 1); reach(column, row + 1);
		}
		for (const [key, where] of bare) if (!outdoors.has(key)) wallGaps.push(where);

		return { overlaps, gaps, wallGaps, noFloor: [...noFloor] };
	},

	/** Rooms as both systems read them: shape, size, and the two finishes. */
	rooms() {
		const size = this.cellSize;
		return (this._map().regionManager?.all('room') ?? []).map(room => ({
			id: room.id,
			name: room.properties?.displayName ?? null,
			shape: room.shape?.kind,
			cells: room.areaInCells(size),
			bounds: room.bounds,
			wallFinish: room.properties?.wallFinishId ?? null,
			floorFinish: room.properties?.floorFinishId ?? null,
			autoDetected: room.properties?.autoDetected === true
		}));
	},

	// ── Overlay ──────────────────────────────────────────────────────────────

	/**
	 * The same answers, drawn on the map instead of printed.
	 *
	 * Floors tint by owning room, walls draw one bar per painted slice in the
	 * colour of the room that slice belongs to, and anything two rooms both
	 * claim is hatched red. A quarter-tile in the wrong colour is a thing you
	 * SEE, so the tool that explains it should be too.
	 */
	overlay(show = true) {
		this._overlay?.remove();
		this._overlay = null;
		if (!show) return 'overlay off';

		const map = this._map();
		const layer = map.layers?.objects;
		if (!layer) throw new Error('[SurfaceDebug] No object layer to draw on');
		const size = this.cellSize;
		const width = map.dimensions?.width || 0;
		const height = map.dimensions?.height || 0;

		const canvas = document.createElement('canvas');
		canvas.width = width;
		canvas.height = height;
		canvas.className = 'surface-debug-overlay';
		Object.assign(canvas.style, {
			position: 'absolute', left: '0', top: '0', pointerEvents: 'none',
			zIndex: '2000000', imageRendering: 'pixelated'
		});
		const context = canvas.getContext('2d');

		const quarter = size / this.QUARTER;
		for (let y = 0; y < height / size; y++) {
			for (let x = 0; x < width / size; x++) {
				for (let row = 0; row < 2; row++) {
					for (let column = 0; column < 2; column++) {
						const px = (x * size) + (column * size / 2);
						const py = (y * size) + (row * size / 2);
						const owners = this.floorOwnersAt(px + quarter, py + quarter);
						if (owners.length === 0) continue;
						context.fillStyle = owners.length > 1
							? 'rgba(255, 0, 0, 0.55)'
							: SurfaceDebug.roomColor(owners[0].split(':')[0], 0.28);
						context.fillRect(px, py, size / 2, size / 2);
					}
				}
			}
		}

		// Wall slices sit on the cell's own footprint, not on the sprite that
		// rises above it — the sprite is 6 cells tall and would bury the floor
		// this is drawn to explain.
		const builder = map.wallBuilder;
		for (const cell of builder?.cells?.values() ?? []) {
			for (const surface of builder.getCellSurfaces(cell)) {
				context.fillStyle = SurfaceDebug.roomColor(surface.roomId, 0.95);
				context.fillRect(
					(cell.x * size) + surface.from,
					(cell.y * size) + (surface.axis === 'horizontal' ? size - 8 : 0),
					surface.to - surface.from,
					surface.axis === 'horizontal' ? 8 : size
				);
			}
		}

		layer.appendChild(canvas);
		this._overlay = canvas;
		return 'overlay on — floors tinted by room, wall slices barred, conflicts red';
	},

	// A stable colour per room id, so the same room reads the same on every
	// redraw and two rooms never come out indistinguishable by accident.
	roomColor(roomId, alpha) {
		if (!roomId) return `rgba(120, 120, 120, ${alpha})`;
		let hash = 0;
		for (let index = 0; index < roomId.length; index++) {
			hash = ((hash << 5) - hash + roomId.charCodeAt(index)) | 0;
		}
		return `hsla(${Math.abs(hash) % 360}, 75%, 55%, ${alpha})`;
	},

	maskName(mask) {
		const names = ['N', 'E', 'S', 'W'].filter((_, index) => (mask & (1 << index)) !== 0);
		return names.length > 0 ? names.join('+') : 'isolated';
	},

	// ── Bug reports ──────────────────────────────────────────────────────────

	/** Every wall cell and every room, as JSON — the whole surface state. */
	dump() {
		const builder = this._map().wallBuilder;
		return {
			mapId: this._map().id,
			rooms: this.rooms(),
			cells: [...(builder?.cells?.values() ?? [])]
				.sort((a, b) => a.y - b.y || a.x - b.x)
				.map(cell => this.cell(cell.x, cell.y)),
			floors: this.audit()
		};
	},

	download() {
		AuditHarness.download('surfaces', this.dump());
	}
};

window.__surfaces = SurfaceDebug;
;
/* -- js/UI/debug/QueueUI.js -- */
class QueueUI {
    constructor(parent, options = {}) {
        this.parent = parent;
        this.mode = options.mode || 'debug';
        this.queue = options.element || document.querySelector('.action-queue-panel');
        this.elements = new Map();
        this.previousValues = new Map();
        this.allowControls = options.allowControls ?? this.mode !== 'compact';
        this.maxItems = Number.isFinite(options.maxItems) ? options.maxItems : Infinity;
        this.holdDelay = Number.isFinite(options.holdDelay) ? options.holdDelay : 550;
        this.panelShell = null;
        this.panelSummary = null;
        this.itemsHost = this.queue;
        this.isCollapsed = false;
        this.lastQueueSignature = null;

        if (this.mode === 'debug' && this.queue) {
            this._buildPanelShell();
        }
    }

    _buildPanelShell() {
        this.panelShell = document.createElement('details');
        this.panelShell.className = 'queue-panel-shell';
        this.panelShell.open = true;

        this.panelSummary = document.createElement('summary');
        this.panelSummary.textContent = 'Debug - Action Queue';

        this.itemsHost = document.createElement('div');
        this.itemsHost.className = 'queue-panel-body';

        this._emptyState = document.createElement('div');
        this._emptyState.className = 'queue-empty-state';
        this._emptyState.textContent = 'No active myte';

        this.panelShell.appendChild(this.panelSummary);
        this.panelShell.appendChild(this.itemsHost);
        this.panelShell.appendChild(this._emptyState);
        this.queue.replaceChildren(this.panelShell);
    }

    setEmptyStateMessage(message) {
        if (this._emptyState) {
            this._emptyState.textContent = message;
        }
    }

    clearItems() {
        this.elements.forEach(el => el.remove());
        this.elements.clear();
        this.previousValues.clear();
        this.lastQueueSignature = null;
    }

    setCollapsed(collapsed) {
        this.isCollapsed = collapsed;
        if (this.panelShell) {
            this.panelShell.open = !collapsed;
        }
    }

    createQueueItem(item) {
        if (this.mode === 'compact') {
            return this.createCompactQueueItem();
        }

        const element = document.createElement('div');
        element.className = 'queue-item';

        const content = document.createElement('div');
        content.className = 'content';

        const number = document.createElement('span');
        number.className = 'number';
        content.appendChild(number);

        const information = document.createElement('div');
        information.className = 'information';

        const title = document.createElement('div');
        title.className = 'title';

        const name = document.createElement('span');
        name.className = 'name';

        let controls = null;
        let skipBtn = null;
        let removeBtn = null;

        if (this.allowControls) {
            controls = document.createElement('div');
            controls.className = 'controls';

            skipBtn = document.createElement('button');
            skipBtn.className = 'skip';
            skipBtn.textContent = '>>';
            skipBtn.title = 'Skip action';

            removeBtn = document.createElement('button');
            removeBtn.className = 'remove';
            removeBtn.textContent = 'X';
            removeBtn.title = 'Remove action';

            skipBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                const index = Number(element.dataset.index);
                if (index === 0) {
                    this.parent.activeMyte?.queue?.removeCurrentAction?.();
                }
            });

            removeBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                const index = Number(element.dataset.index);
                if (!Number.isFinite(index)) return;
                if (index === 0) {
                    this.parent.activeMyte?.queue?.removeCurrentAction?.();
                } else {
                    this.parent.activeMyte?.queue?.queue?.splice(index, 1);
                }
            });

            controls.appendChild(skipBtn);
            controls.appendChild(removeBtn);
            title.appendChild(controls);
        }

        title.insertBefore(name, title.firstChild);
        information.appendChild(title);

        const description = document.createElement('div');
        description.className = 'description';
        information.appendChild(description);
        content.appendChild(information);

        let progress = null;
        let bar = null;
        if ((item.duration && item.duration > 0) || typeof item.getProgress === 'function') {
            progress = document.createElement('div');
            progress.className = 'progress';
            bar = document.createElement('div');
            bar.className = 'bar';
            progress.appendChild(bar);
            content.appendChild(progress);
        }

        element.appendChild(content);
        element._refs = {
            number,
            name,
            description,
            controls,
            skipBtn,
            removeBtn,
            progress,
            bar,
            status: null
        };

        return element;
    }

    createCompactQueueItem() {
        const element = document.createElement('button');
        element.className = 'queue-item compact';
        element.type = 'button';

        const tooltipSystem = TooltipSystem.getInstance();
        const icon = document.createElement('span');
        icon.className = 'queue-icon';

        const order = document.createElement('span');
        order.className = 'queue-order';

        element.appendChild(order);
        element.appendChild(icon);
        element._holdTimer = null;
        element._holdTriggered = false;

        const showTooltip = (autoHideMs = 0) => {
            const text = element.dataset.tooltip;
            if (!text) return;

            tooltipSystem.show({
                anchor: element,
                text,
                autoHideMs
            });
        };

        const hideTooltip = () => {
            if (tooltipSystem.isVisibleFor(element)) {
                tooltipSystem.hide();
            }
        };

        const clearHoldTimer = () => {
            if (element._holdTimer) {
                clearTimeout(element._holdTimer);
                element._holdTimer = null;
            }

            if (!element._holdTriggered) {
                element.classList.remove('holding');
            }
        };

        const cancelQueuedAction = () => {
            const index = Number(element.dataset.index);
            if (!Number.isFinite(index)) return;

            const activeMyte = this.parent.activeMyte;
            if (!activeMyte?.queue) return;

            if (index === 0) {
                activeMyte.queue.removeCurrentAction?.();
            } else if (Array.isArray(activeMyte.queue.queue)) {
                activeMyte.queue.queue.splice(index, 1);
            }
        };

        element.addEventListener('pointerdown', (event) => {
            event.preventDefault();
            element._holdTriggered = false;
            hideTooltip();
            clearHoldTimer();
            element.classList.add('holding');
            element._holdTimer = setTimeout(() => {
                element._holdTriggered = true;
                element.classList.remove('holding');
                cancelQueuedAction();
            }, this.holdDelay);
        });

        ['pointerup', 'pointerleave', 'pointercancel', 'lostpointercapture'].forEach((eventName) => {
            element.addEventListener(eventName, clearHoldTimer);
        });

        element.addEventListener('mouseenter', () => showTooltip());
        element.addEventListener('mouseleave', hideTooltip);
        element.addEventListener('focus', () => showTooltip());
        element.addEventListener('blur', hideTooltip);

        element.addEventListener('click', (event) => {
            if (element._holdTriggered) {
                event.preventDefault();
                event.stopPropagation();
                element._holdTriggered = false;
                return;
            }

            tooltipSystem.toggle({
                anchor: element,
                text: element.dataset.tooltip || '',
                autoHideMs: 1500
            });
        });

        element._refs = { icon, order };
        return element;
    }

    getTargetIdentifier(target) {
        if (!target) return null;

        if (target.type && target.variant) {
            return `${target.type}-${target.variant}-${target.posX?.toFixed(0) || 0}-${target.posY?.toFixed(0) || 0}`;
        }

        return target.constructor?.name || 'Unknown';
    }

    getQueueTitle(item) {
        return item.getQueueTitle?.() || item.constructor.metadata?.label || item.constructor.name.replace('Action', '');
    }

    getQueueDescription(item) {
        return item.getQueueDescription?.() || '';
    }

    getCompactLabel(item) {
        const title = this.getQueueTitle(item);
        const words = String(title)
            .trim()
            .split(/[^a-zA-Z0-9]+/)
            .filter(Boolean);

        if (words.length === 0) return 'Q';
        if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
        return `${words[0][0]}${words[1][0]}`.toUpperCase();
    }

    getQueueSignature(activeMyte, queueItems) {
        return JSON.stringify({
            mode: this.mode,
            activeMyteId: activeMyte?.id ?? null,
            controls: this.allowControls,
            items: queueItems.map((item, index) => ({
                index,
                action: item.constructor?.name || '',
                category: item.constructor?.metadata?.category || '',
                title: this.getQueueTitle(item),
                description: this.getQueueDescription(item),
                repeat: item.repeat ?? null,
                expressionType: item.type || null,
                targetId: this.getTargetIdentifier(item.target),
                isCurrent: index === 0
            }))
        });
    }

    updateCurrentProgress(item) {
        const currentElement = this.elements.get('queue-0');
        if (!currentElement?._refs || !item) return;

        const refs = currentElement._refs;
        if (!refs.progress) return;

        const hasProgress = !!((item.duration && item.duration > 0) || typeof item.getProgress === 'function');
        refs.progress.classList.toggle('has-progress', hasProgress);
        if (hasProgress) {
            const percentage = this.calculateProgress(item);
            if (refs.bar) refs.bar.style.width = `${percentage}%`;
            if (refs.status) refs.status.textContent = `${percentage}%`;
        } else {
            if (refs.status) refs.status.textContent = 'in progress';
        }
    }

    updateQueueItem(element, item, index) {
        if (this.mode === 'compact') {
            this.updateCompactQueueItem(element, item, index);
            return;
        }

        const key = `queue-${index}`;
        const refs = element._refs;
        element.dataset.index = String(index);

        const targetId = this.getTargetIdentifier(item.target);
        const simplifiedValue = {
            targetId,
            repeat: item.repeat,
            name: item.constructor.name,
            queueTitle: this.getQueueTitle(item),
            queueDescription: this.getQueueDescription(item),
            isCurrent: index === 0,
            hasProgress: !!(item.duration && item.duration > 0),
            expressionType: item.type || null
        };
        const currentValue = JSON.stringify(simplifiedValue);

        if (this.previousValues.get(key) !== currentValue) {
            element.className = `queue-item ${item.constructor.metadata?.category || ''}${index === 0 ? ' is-current' : ''}`;

            refs.number.textContent = `#${index + 1}`;
            const icon = item.constructor?.metadata?.icon;
            refs.name.textContent = icon ? `${icon} ${this.getQueueTitle(item)}` : this.getQueueTitle(item);
            refs.description.innerHTML = '';
            refs.status = null;

            const queueDescription = this.getQueueDescription(item);
            if (queueDescription) {
                const detail = document.createElement('span');
                detail.className = 'target';
                detail.textContent = queueDescription;
                refs.description.appendChild(detail);
            }

            if (item.constructor.name === 'ExpressionAction') {
                const type = document.createElement('span');
                type.className = 'target';
                type.textContent = `[${item.type}]`;
                refs.description.appendChild(type);
            }

            if (item.repeat && item.repeat > 1) {
                const repeats = document.createElement('span');
                repeats.className = 'repeats';
                repeats.textContent = `x${item.repeat}`;
                refs.description.appendChild(repeats);
            }

            if (index === 0) {
                const status = document.createElement('span');
                status.className = 'status';
                status.textContent = item.duration && item.duration > 0
                    ? `${this.calculateProgress(item)}%`
                    : 'in progress';
                refs.description.appendChild(status);
                refs.status = status;
            }

            this.previousValues.set(key, currentValue);
        }

        if (this.allowControls && refs.skipBtn) {
            refs.skipBtn.classList.toggle('is-visible', index === 0);
        }

        if (refs.progress) {
            const hasProgress = index === 0 && ((item.duration && item.duration > 0) || typeof item.getProgress === 'function');
            refs.progress.classList.toggle('has-progress', hasProgress);
            if (hasProgress) {
                const percentage = this.calculateProgress(item);
                if (refs.bar) refs.bar.style.width = `${percentage}%`;
                if (refs.status) refs.status.textContent = `${percentage}%`;
            }
        }
    }

    updateCompactQueueItem(element, item, index) {
        const refs = element._refs;
        const title = this.getQueueTitle(item);
        const description = this.getQueueDescription(item);
        const tooltipParts = [title];

        if (description) {
            tooltipParts.push(description);
        }

        tooltipParts.push(`Hold to cancel${index === 0 ? ' current action' : ''}.`);

        element.className = `queue-item compact ${item.constructor.metadata?.category || ''}${index === 0 ? ' is-current' : ''}`;
        element.dataset.index = String(index);
        element.dataset.queueTitle = title;
        element.dataset.queueDescription = description;
        element.dataset.queueState = index === 0 ? 'now' : 'next';
        element.dataset.tooltip = tooltipParts.join(' - ');
        element.setAttribute('aria-label', element.dataset.tooltip);
        refs.icon.textContent = this.getCompactLabel(item);
    }

    calculateProgress(item) {
        if (typeof item.getProgress === 'function') {
            return Math.round(item.getProgress() * 100);
        }
        if (item.currentDuration === -1) return 0;
        return Math.round(100 - (item.currentDuration / item.duration * 100));
    }

    update() {
        if (!this.queue) return;

        const activeMyte = this.parent.activeMyte;
        const queueItems = activeMyte?.queue?.queue
            ? activeMyte.queue.queue.slice(0, this.maxItems)
            : [];
        const queueSignature = this.getQueueSignature(activeMyte, queueItems);

        this.setEmptyStateMessage(activeMyte ? 'No actions queued' : 'No active myte');
        this.queue.classList.toggle('has-items', queueItems.length > 0);
        if (this._emptyState) this._emptyState.classList.toggle('is-visible', queueItems.length === 0);

        if (!activeMyte) {
            this.clearItems();
            return;
        }

        if (this.lastQueueSignature === queueSignature) {
            if (this.mode !== 'compact' && queueItems[0]) {
                this.updateCurrentProgress(queueItems[0]);
            }
            return;
        }

        this.lastQueueSignature = queueSignature;

        while (this.elements.size > queueItems.length) {
            const key = `queue-${this.elements.size - 1}`;
            const element = this.elements.get(key);
            element.remove();
            this.elements.delete(key);
            this.previousValues.delete(key);
        }

        queueItems.forEach((item, index) => {
            const key = `queue-${index}`;
            let element = this.elements.get(key);

            if (!element) {
                element = this.createQueueItem(item);
                this.elements.set(key, element);
                this.itemsHost.appendChild(element);
            }

            this.updateQueueItem(element, item, index);
        });

        if (this.mode !== 'compact' && queueItems[0]) {
            this.updateCurrentProgress(queueItems[0]);
        }
    }

    setControlsEnabled(enabled) {
        this.allowControls = enabled;
        this.lastQueueSignature = null;
        this.update();
    }

    dispose() {
        this.elements.forEach(el => el.remove());
        this.elements.clear();
        this.previousValues.clear();
        this.lastQueueSignature = null;
        this.panelShell?.remove();
        this.panelShell = null;
        this.panelSummary = null;
        this.itemsHost = this.queue;
    }
}
